window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["24844990"]={"book":{"id":24844990,"title":"说话的力量","author":"孙路弘","translator":"","publisher":"浙江人民出版社","pubdate":"2013-7-1","isbn":"9787213055492","tags":["沟通","沟通技巧","口才","演讲与口才","说话","职场","孙路弘","销售"],"memCount":20},"np":1,"pb":[38],"idx":[{"i":19230,"t":"垫子：创造一来一往舒适的说话氛围","l":"TF2-2","c":"此念","g":1,"p":1},{"i":16654,"t":"共情，创造沟通同频","l":"TF2-4","c":"长大的石榴","g":1,"p":1},{"i":16468,"t":"晋级","l":"TF3-2","c":"王礼界","g":1,"p":1},{"i":16289,"t":"倾听回应4+3","l":"TF2-4","c":"开心1314","g":1,"p":1},{"i":16115,"t":"说话的力量-讨论与汇报","l":"TF3-3","c":"长大的石榴","g":1,"p":1},{"i":16032,"t":"说话的力量","l":"","c":"王礼界","g":1,"p":1},{"i":15879,"t":"解释","l":"TF2-3","c":"开心1314","g":1,"p":1},{"i":15367,"t":"解释概念，争取对方听懂我","l":"TF3-2","c":"王礼界","g":0,"p":1},{"i":15310,"t":" 解释","l":"TF2-2","c":"开心1314","g":1,"p":1},{"i":15225,"t":"解释","l":"TF2-1","c":"开心1314","g":1,"p":1},{"i":14038,"t":"说话的力量","l":"TF2-3","c":"立慧","g":1,"p":1},{"i":12559,"t":"合格汇报的三大要素","l":"TF2-2","c":"秋香","g":1,"p":1},{"i":11922,"t":"3步说到对方心坎里","l":"TF3-1","c":"余盛莲","g":1,"p":1},{"i":11330,"t":"如何汇报","l":"TF2-2","c":"陈羽西","g":1,"p":1},{"i":11150,"t":"你真的听懂了吗","l":"TF2-3","c":"余盛莲","g":1,"p":1},{"i":10800,"t":"表达时的受众分析","l":"TF1-1","c":"于潇潇","g":1,"p":1},{"i":8207,"t":"用迎合的技巧建立信任","l":"TF3-3","c":"郭宏江","g":0,"p":1},{"i":8206,"t":"用迎合技巧建立信任","l":"TF3-3","c":"郭宏江","g":0,"p":1},{"i":6585,"t":"解释是一种说话技能","l":"TF2-3","c":"慎蓓","g":1,"p":1},{"i":6403,"t":"解释也是一种说话技能","l":"TF2-3","c":"慎蓓","g":1,"p":1},{"i":6354,"t":"如何用触动人心的事实传达观点","l":"TF1-2","c":"绿竹","g":1,"p":1},{"i":6306,"t":"三个铺垫方法，沟通更顺畅","l":"TF2-2","c":"扫地僧  王伟","g":0,"p":1},{"i":6236,"t":"如何让自己的表达更具有影响力","l":"TF3-3","c":"王文元","g":1,"p":1},{"i":5773,"t":"让人舒心的解释","l":"TF2-3","c":"冬夜读书YHY","g":1,"p":1},{"i":5388,"t":"把握四要素，让你的汇报清晰，准确，高效","l":"TF1-2","c":"魏世英","g":1,"p":1},{"i":5335,"t":"不是教你“说假话”，而是教你“有选择的说实话”","l":"TF3-3","c":"思蓓","g":1,"p":1},{"i":3867,"t":"影响力是“演”出来的","l":"TF2-1","c":"空林文子","g":1,"p":1},{"i":3805,"t":"迎合，共情","l":"TF1-2","c":"梅砸","g":1,"p":1},{"i":3804,"t":"表达沟通","l":"TF1-1","c":"梅砸","g":1,"p":1},{"i":3747,"t":"掌握合理汇报三要素","l":"TF2-1","c":"郑娇","g":1,"p":1},{"i":3410,"t":"受众分析","l":"TF2-1","c":"空林文子","g":1,"p":1},{"i":2867,"t":"迎合三步骤","l":"TF3-1","c":"李杏梅","g":1,"p":1},{"i":2009,"t":"用迎合为你的人际关系加分","l":"TF3-2","c":"空林文子","g":1,"p":1},{"i":2005,"t":"创造一来一往舒适的说话氛围","l":"TF2-2","c":"空林文子","g":1,"p":1},{"i":2004,"t":"台上一分钟，台下十年功","l":"TF2-1","c":"空林文子","g":1,"p":1},{"i":2003,"t":"用触动人心的事实传达观点","l":"TF1-2","c":"空林文子","g":1,"p":1},{"i":163,"t":"发言引人入胜并具有说服力的技巧","l":"TF1-2","c":"喜羊羊","g":0,"p":1},{"i":138,"t":"说话的力量","l":"TF1-1","c":"喜羊羊","g":1,"p":1}],"ms":[{"id":19230,"topic":"垫子：创造一来一往舒适的说话氛围","learn_goal":"","remark":"你有没有这样的时候，领导让你汇报某一项工作的进展，感觉领导不太满意，甚至还可能让领导质疑你的能力。你不知道该如何汇报，才能达成领导满意的目的，气氛一时显得很僵很尴尬。接下来的这个拆页片段所讲述的垫子三个技巧，将提高你的汇报水平，达到事半功倍的效果","level":"TF2-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"此念","city":"宁波市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>简单介绍一下自己，我是来自台州玉环的此念。我的三个标签分别是独抚妈妈、文化传媒创业者和婚姻家庭辅导师。\u003c/p>\u003cp>今天我带大家学习的是来自《说话的力量》拆页片段P149-150【垫子：创造一来一往舒适的说话氛围】。\u003c/p>\u003cp>\u003cstrong>F特征\u003c/strong>：作者孙路弘毕业于美国麻省理工学院，曾在通用电气工作，具备扎实的理工科背景和丰富的商业沟通经验，《说话的力量》构建了完整的说话技巧体系，内容贴近生活和工作实际，提供大量案例和具体模板，读者可以直接应用到日常沟通中。\u003c/p>\u003cp>\u003cstrong>A优势\u003c/strong>：通过真实或虚构的案例，生动展示说话技巧的应用，让读者更直观地理解和掌握。和其他沟通类的书籍比较，这本书提供的说话技巧简单易懂，可操作性强，读者可以快速应用到实际沟通中。\u003c/p>\u003cp>\u003cstrong>B利益\u003c/strong>：\u003c/p>\u003cp>B1（本书）：你在和孩子谈话时是不是常常遇到沟通不顺让你大发雷霆？你在和同事工作交流中解释说明不到位而产生工作分歧？如果你确实遇到过以上的问题不妨跟这本书学习一下说话的技巧，让你与其他人沟通时更高效更顺畅，工作也事半功倍。\u003c/p>\u003cp>B2（拆页）：你有没有这样的时候，领导让你汇报某一项工作的进展，感觉领导不太满意，甚至还可能让领导质疑你的能力。你不知道该如何汇报，才能达成领导满意的目的，气氛一时显得很僵很尴尬。接下来的这个拆页片段所讲述的垫子三个技巧，将提高你的汇报水平，达到事半功倍的效果。\u003c/p>\u003cp>\u003cstrong>学习目标\u003c/strong>：在跟随我完成本次RIA学习后，学习者能在遇到类似的问题和矛盾时，熟练运用“垫子”三技巧，为下一步的沟通缓和了气氛。\u003c/p>\u003cp>过渡：现在给大家3分钟的时间，请大家阅读屏幕里的拆页，阅读完的小伙伴扣1。\u003c/p>","ratings_count":1,"texts":[{"id":23586,"quote":"\u003cp>垫子的3种类型\u003c/p>\u003cp>垫子主要有三种类型，在这三种类型的基础上，可以根据具体语境衍生出不同的变形。但就像学剑要先练剑谱一样，掌握最基本的三种垫子，是掌握垫子技巧的关键。\u003c/p>\u003cp>第一种垫子，赞扬问问题的人，简单地说就是夸他的问题问得太好了。\u003c/p>\u003cp>有位客户买了一台车，提走车后第二天早晨就送回来了，说:“你看看车顶，我昨天拿的车，车顶上有一个这么明显的刮痕，这是怎么回事?”如果你急于说:“这不是我们的问题。”那就是推卸责任了，沟通立刻就陷入了僵局。\u003c/p>\u003cp>如果你会使用垫子，就会说:“哎呀，您可真细心啊!您是什么时候发现这个划痕的?昨天晚上提车的时候有没有看到?”当你对他的问题予以肯定的时候，他就会给你更多信息，而不是立刻进入你问我答的境地。\u003c/p>\u003cp>如果只是简单地直接回答问题，一旦你的回答不符合对方的期待，关系就容易僵化。而垫子可以有效地促进提问一方对自己的问题进行解释，一旦解释了，就会讲出更多的信息。\u003c/p>\u003cp>在回答问题前，先对对方的问题给予肯定和赞许，赞许的结果是可以赢得对方好感，降低提问的挑战性。加垫子还有一个好处，那就是表示你的思考位置是在提问者之上，可以超越提问者的。\u003c/p>\u003cp>◆第二种垫子，说他的问题很普遍，很有代表性，比如说这个向题最近很多人都在问。\u003c/p>\u003cp>第二个垫子的功效特点是把问题普遍化。“你一问我这个问题，我想起来了，清华大学一个工程系的教授也问过这个问题”，“你这个问题问得真是好，当年孔子也问过这个问题”。可以换位思考一下，当你听到别人这样对你说的时候，你的心理状态会发生什么变化?\u003c/p>\u003cp>比如客户说:“这部手机外形真漂亮，用的什么材料啊?”销售人员回答:“哎呀，无独有偶，当年苹果公司的首席执行官乔布斯，他拿到员工设计的手机的时候，也问了刚才你问的这个问题:这个表面用了什么材质啊?”销售人员这样回答以后，对方会觉得你是有想法的，而且会很高兴:这个问题乔布斯也问过，那自己问这个问题还是挺值得骄傲的。也就是说销售人员加这个垫子的时候，已经让客户感受到对他的赞扬了，客户觉得自己的问题是有价值的，后面问题的挑衅性就会下降。\u003c/p>\u003cp>但是这种垫子也要看具体情况，比如女友问男友你爱我吗?男友用第一种垫子:“哎呀，你这个问题问得太好了。”是可以的。但是套用第二种垫子:“很多人都问过我这个问题。”可就麻烦了!女友会想，那还有谁问过你啊?这时候男友要把谈话主题引导到另外一个方向一-我是受欢迎的，而不要陷入对方引导的方向。\u003c/p>\u003cp>◆第三种垫子，在回答问题前，将自己的处境讲出来。\u003c/p>\u003cp>在回答问题之前，先将自己的处境讲出来，从而赢得对方的好感，并降低对方对答案的质疑。要养成这样的习惯并不容易，因为要养成这个习惯，你就要学会示弱。示弱并不等于自己真的很弱小，恰恰只有真正强大的人才肯承认自己的弱小。一旦学会这个的技巧，你与他人的沟通过程就会更加流畅，更加自然和顺利。\u003c/p>\u003cp>比如领导问你:“能在下周一之前做出方案吗?”你是不是要马上回答能或者不能?不，你要加个垫子，讲出自己的处境:“这个周末确实有好几个方案等着做，但我一定优先做您的。”\u003c/p>","explains":"\u003cp>\u003cstrong>【What】\u003c/strong>垫子，通俗来讲就是在直接表达容易产生矛盾和冲突地时候，我们需要用委婉地方式去铺垫，起到一个缓冲的作用。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>我们在工作和生活中有时候难免会遇见一些刁难和别有用心地提问，如果正面回应容易激发矛盾，或者使彼此关系变紧张。这个时候会说话地人（或者说“有眼力见”）就会使用铺垫也就是俗称“垫子”来起到缓和气氛的作用，沟通过程也会更加流畅顺利。\u003c/p>\u003cp>如果不使用“垫子”，面对严肃的或者矛盾一触即发的场面，有可能会使结果推向不可逆转的对立关系。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>掌握垫子的三种方法，是铺垫技巧的关键。第一种是赞美垫，赞美别人问得好。我对女儿提的问题竖起来大拇指：“你提的问题很专业，看得出来你是经过分析和思考的，我要向你学习！”赞美法适用于晚辈或下级等关系。\u003c/p>\u003cp>第二种垫子是代表垫，指出这个问题很有代表性。客户气冲冲地提着刚买的虾干要退货，她说：“我问你买5斤虾干，结果回家称了只有3.5斤，你做生意怎么这么不诚信的？虾干我也不要了，退钱”。这时我给她竖起了大拇指，夸她：“您这个问题提到点子上了，其实很多人有这个疑问但是没有都提出来，导致我想当然地以为大家都明白这个行情。今天正好借这个机会，我做个解释，也提醒自己下次一定要提前和客户说清楚。是这样的，这个虾干呢市场上是按活虾价格来算的，实际煮熟晾晒后到手是7两。我要是当时就解释，也就不用耽误您时间精力来回跑一趟了，实在对不起！”这个时候客户也就释怀了。这个垫子适合彼此之间的平等关系和合作关系等。\u003c/p>\u003cp>第三种是示弱垫，回答问题前先做示弱的铺垫。比如我对领导的提问会这么说：“我得跟您坦白一下，我这人在逻辑思维方面比较弱，看问题常常太感性不能抓住问题关键。这方面的短板我要多请教学习，努力改进。”这个垫子适合上级和长辈等关系。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>可能你会说，这种垫子用得不好会显得非常刻意不自然，反而引起对方反感，让矛盾不可调和。所以这里需要我们平时有意识地多多练习，到真正需要使用的时候就会不着痕迹，很自然地就过渡了。\u003c/p>\u003cp>也有人会问，使用垫子能解决问题吗？其实很多问题和矛盾并不是一定要解决的，可能就是情绪上来了的一句气话，对方需要的是你的尊重，有了垫子这个台阶，情绪满足了，问题自然也就迎刃而解了。\u003c/p>","interaction":"\u003cp>A2催化应用（步骤一）\u003c/p>\u003cp> 想象一下未来一周或一个月内，你可能会遇到被家人、同事或者客户质问的事情，可能是故意刁难也可能是比较棘手，让你一下子不知道怎么回答? 请注意设想大致的时间、地点、人物、事件、问题要表述清楚注意。2分钟时间，晚上只有5位伙伴我们就不在另外分组了，大家思考后写在纸上。\u003c/p>\u003cp> 参考场景：“讲解产品、指导下属、教育儿女、劝说他人……你在工作和生活中会涉及哪个情境？”\u003c/p>\u003cp>2分钟到了，有哪位伙伴愿意主动分享，我们欢迎。\u003c/p>\u003cp> 学习者Echo：我来吧，我想了一下可能明天会被质问，就是我今天太忙了，我的新闻稿还没写。那可能明天我的同事就会过来问我，你的稿子呢，为什么稿子还没写完？这是我可能会碰到被质问的事情。\u003c/p>\u003cp> 学习者周舟：这个周末，我老公可能会质问我，为什么把麦麸撒到花盘上面，搞得阳台上飞得到处都是。\u003c/p>\u003cp>A2催化应用（步骤二）\u003c/p>\u003cp> 刚刚我们对未来可能发生的问题邀请了两个小伙伴做了分享，现在结合学到的三个垫子铺垫法来实际应用。你觉得你会碰到的这个问题用我们学到的哪个垫子最合适？也是2分钟时间，我们请小伙伴主动分享。\u003c/p>\u003cp> 学习者Echo：我来吧，我会选择使用示弱垫，确实（没完成新闻稿）这个事情是有点理亏，忙归忙工作还是要完成的。面对质问，我可能会说：“对对对，确实这个报道还没赶出来，这个新闻时效性还是很重要的。我还是要反思一下，虽然今天比较忙所以没有及时完成，但是我还是要努力改进，避免以后再出现类似的情形”。\u003c/p>\u003cp> 学习者周舟：“我也觉得用示弱垫比较合适，我跟我老公说，我把麦麸洒在花盘上，确实把阳台弄得挺脏的，有劳你先打扫一下，等我把拆书稿写完了，我再来解决掉这个事儿”。\u003c/p>\u003cp>总结和回顾：\u003c/p>\u003cp> 生活和工作中碰到因为对方刁难或者事情的严重性导致气氛很僵硬严肃等等，这样的例子不胜枚举。学会应用三种垫子的方法，可以在日常问题中起到四两拨千斤的作用，轻风化雨就把矛盾消散了。希望今晚我们学到的知识能让帮助您解决实际生活里的诸多问题！感谢大家的参与，今晚的分享到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1755523125000,"updated_at":1755587960000,"ria":true},{"id":16654,"topic":"共情，创造沟通同频","learn_goal":"","remark":"迎合，说话的力量八大主题之一","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"长大的石榴","city":"南京市"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>\u003cstrong>迎合，创造共振的场\u003c/strong> \u003c/p>\u003cp>\u003cstrong>【开场】开始录音\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍\u003c/strong> \u003cstrong>】\u003c/strong>\u003c/p>\u003cp>各位伙伴们大家好。我叫沈洁。我用三个标签介绍一下我自己：\u003c/p>\u003cp>第一个标签：二十年助力贸易顺差的外贸人。\u003c/p>\u003cp>第二个标签：企业内训师。\u003c/p>\u003cp>第三个标签：个性十足小女生的妈妈。\u003c/p>\u003cp>很荣幸有这样一个机会，以拆书家的身份，和在场的伙伴一起，进行此次《说话的力量》RIA拆书的活动。\u003c/p>\u003cp>\u003cstrong>【分组\u003c/strong> \u003cstrong>】\u003c/strong>\u003c/p>\u003cp>今天是我TF2-4的第五次定级，我来分下组，以迪哥为中心，左手边为一组，右手边为一组。\u003c/p>\u003cp>希望伙伴们都积极参加到互动环节中来。 \u003c/p>\u003cp>\u003cstrong>一、图书介绍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【用FAB法介绍图书 】\u003c/strong>\u003c/p>\u003cp>今天的两个拆页，分别来自于《说话的力量》P164-165和P171-172。\u003c/p>\u003cp>我刚刚已经将两个原书拆页发给大家了，人手一份。本次拆解预计需要60分钟左右。\u003c/p>\u003cp>\u003cstrong>F: \u003c/strong>这本书的作者是孙路弘。本书是作者倾其25年营销、销售经验的精华之作。书中大量、丰富的案例都是作者多年来经历过的真实事件。通过这些案例，我们能更形象、更具体理解说话的技巧、方法和工具。\u003c/p>\u003cp>\u003cstrong>A: \u003c/strong>这本书是国内首部系统学习说话的实战指南，豆瓣评分7.9。相比市面上其他沟通类书籍，本书不仅有大量案例分析，同时各章结尾部分还为读者设置了“练兵场”，通过实用的练习题融会贯通每章的内容，帮助读者快速、有效地掌握每章的核心对话技能。\u003c/p>\u003cp>\u003cstrong>B1: \u003c/strong>你有没有在沟通中，接不上对方话的时候？有没有在和对方表达诉求和解决方案时，一直得不到对方的认可，最后不欢而散的情况？这些工作生活中常常遇到的沟通问题，本书中都有案例和对应的方法。\u003c/p>\u003cp>\u003cstrong>B2: \u003c/strong>今天的拆页来自于这本书中关于“迎合”的部分。我们在日常工作和生活中，会遇到一些突发事件或是十万火急的棘手问题。这时，通过“迎合”的沟通技巧，我们适时表达共情，安抚住当事人的情绪，进而得到对方的认可。\u003c/p>\u003cp>\u003cstrong>【学习总目标】\u003c/strong>\u003c/p>\u003cp>在完成今天的RIA现场学习后，学习者能够使用“表达共情”和“巧妙迎合”两种方法，在沟通中能够倾听对方，换位思考，表达理解引发对方情感共鸣，缓和矛盾同时，获得对方的认可与好感。\u003c/p>\u003cp>\u003cstrong>【片段关系】\u003c/strong>\u003c/p>\u003cp>两个片段讲的是不同的“迎合方式”：片段一是\u003cstrong>通过情感传递的方式\u003c/strong>，片段二是\u003cstrong>按照逻辑分析的方式\u003c/strong>。通过两种不同方式的“迎合”，获得对方认可。两个片段呈\u003cstrong>并列关系\u003c/strong>。\u003c/p>\u003cp>\u003cstrong>第一个RIA “表达共情”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>二、学习目标1：\u003c/strong>\u003c/p>\u003cp>今天的学习内容主要分为两个片段，片段1的主要内容是“表达共情”，在完成这个片段的学习后，学习者能够在处理矛盾时认真倾听，让对方完整地叙述出事件原委和表达出情绪，并学会使用肯定的语言尝试理解对方的立场与感受，获得对方认可。\u003c/p>","ratings_count":3,"texts":[{"id":20766,"quote":"\u003cp>三、\u003cstrong>【R】阅读原书拆页\u003c/strong>\u003c/p>\u003cp>接下来咱们用两分钟的时间，阅读一下原文，读完的小伙伴可以举手示意我一下。《说话的力量》P164-165\u003c/p>\u003cp>\u003cem>迎合不是吹牛、拍马屁，也不是奉承，而是表达共情，获得对方认同。共情，是指在人际交往过程中，\u003cstrong>能够体会他人的情绪和想法，理解他人的立场和感受，\u003c/strong>并站在他人的角度思考和处理问题的能力，又叫做换位思考、移情。迎合是快速\u003cstrong>将共情用说话的方式表达出来\u003c/strong>，让对方直接、快速、明了地\u003cstrong>感受到这个人跟他自己一样，跟他有一样的逻辑，有一样的经验和体会，\u003c/strong>什么都跟他一样，双方就容易相互接近了。\u003c/em>\u003c/p>\u003cp>\u003cem>在交谈中表达共情，对方听完你的话会觉得一拍即合：哎呀，我怎么没早认识你呢？咱俩想法太一致了，你简直是我的\u003cstrong>知音\u003c/strong>。如果他真的有这样的感觉和体会，你就可以让双方有一种相见恨晚的感觉，谈话投机、滔滔不绝，自然建立了一个共振的场。\u003c/em>\u003c/p>\u003cp>\u003cem>迎合的前提就是，使用共情，\u003cstrong>创造谈话的共振场\u003c/strong>。在沟通时学会使用迎合，就可以创造良好的人际氛围。迎合是将心比心的具体落实，\u003cstrong>通过说话来拉近彼此的距离\u003c/strong>，它不是奉承、套话和吹捧。\u003c/em>\u003c/p>\u003cp>\u003cem>比如一家银行，早晨刚开门就进来一位小伙子，急急忙忙到柜台前，着急地说：“我昨天在你们这儿开了一个账户，存了3万元钱。你们给我开了网上银行功能，但是昨天晚上回家我在网上一查，账户里只剩30元钱了。”这时候要怎么表达共情？\u003c/em>\u003c/p>\u003cp>\u003cem>首先要想对方现在的心情是怎样的。钱查不到了当然很担忧，很紧张。有的营业员自以为有经验，上去就说：“小伙子您先别急，冷静一点。”小伙子一听肯定会说：“我能不紧张吗？我能冷静吗？这事儿跟你没关系你当然冷静了。”这样的回答不叫迎合，对于解决问题只会火上浇油。应该表达的不是告诉他别紧张，这样会让他觉得你说他紧张是不对的，他紧张当然是对的，他着急也是对的，他怎么可能冷静？换成是你，你能冷静吗？\u003c/em>\u003c/p>\u003cp>\u003cem>所以要这样迎合：“怎么会这样呢？这太不正常了！这种情况是无论如何不该出现的，要是真有这种情况，不仅我们银行不能容忍，我也不能容忍。”你一说出这番话，他会觉得至少你跟他是有同样感受的。接着你再说：“我来帮您看下，昨天您办理存款手续时的收据小条带来了吗？身份证带来了吗？我立刻帮您查，这件事是不应该发生的。”\u003c/em>\u003c/p>","explains":"\u003cp>四、\u003cstrong>【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>看到大部分伙伴都举手示意原文看完了，接下来我们对这段原文进行一下解读。\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>这个片段主要表述的是，在对话中要表达共情，尤其在处理特殊事件时，运用“共情”能更好地缓解冲突。\u003c/p>\u003cp>共情，是指在人际交往过程中，能够体会他人的情绪和想法，理解他人的立场和感受，并站在他人的角度思考和处理问题的能力，又叫做换位思考、移情。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>将共情用说话的方式表达出来，让对方直接、快速、明了地感受到这个人跟他自己一样，跟他有一样的逻辑，有一样的经验和体会，什么都跟他一样，双方就容易相互接近了。\u003c/p>\u003cp>\u003cstrong>【通常的做法】\u003c/strong>\u003c/p>\u003cp>共情确实能给交流带来好处。但是，我们通常做法是给对方建议而不是共情。比如家里人在一些事情上发牢骚抱怨的时候，我们通常不是安抚对方的情绪，而是直接给建议，按照自己的经验应该这样或那样做，导致对方不仅不领情，反而更加激发对方的负面情绪。\u003c/p>\u003cp>\u003cstrong>【反例】\u003c/strong>\u003c/p>\u003cp>前两天，女儿回家后一直嘟着小脸，说她再也不参加滑板社团了。她说有同学嫌她速度慢，跟不上团体动作。作为家长的我，听到这儿，直接打断她，脱口而出：“你怎么那么傻啊？他们排挤你，你不会告诉老师呀？”想了想，觉得好像说重了，又改口：“没关系，咱们不想不参加就不参加了，妈妈最爱你了！”女儿抬头望了望我，叹了口气，不再说话了。我的两个回复，似乎都不合格，按照原文中的方法，如果我做了以下几个步骤，可能结果会完全不一样。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>细化原文的步骤：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、体（提）会对方的情绪和想法，让对方倾诉彻底。\u003c/strong>\u003c/p>\u003cp> 1）在说话前，体会到对方此刻的情绪是不冷静的，会说一些气话。\u003c/p>\u003cp> 2） 给对方时间，让TA说完整个过程，慢慢平复心情。\u003c/p>\u003cp>\u003cstrong>2、理（荔）解对方的立场和感受，说出来让对方知道。\u003c/strong>\u003c/p>\u003cp> 1）理解对方在现有的境遇中，一定是不舒服甚至是难过的，至少短时间内无法自愈。\u003c/p>\u003cp> 2）把这种理解和感受，一定要说出来告诉TA。\u003c/p>\u003cp>\u003cstrong>3、成为对方的知（枝）音，用说话的方式创造共振场。\u003c/strong>\u003c/p>\u003cp> 1）让对方感受到，你跟TA有一样的想法、逻辑、一样的经验、体会，自然靠近，成为知音。\u003c/p>\u003cp> 2）通过说话来拉近彼此的距离，再开启理性的谈话，力所能及给予对方问题解决方案或是建议。\u003c/p>\u003cp>\u003cstrong>【正例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果我再遇到同样的情况，我该如何运用“表达共情”呢？“提荔枝”三步骤：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：体（提\u003c/strong> \u003cstrong>）会对方的情绪和想法，让对方倾诉彻底。\u003c/strong>\u003c/p>\u003cp> 1）在说话前，体会到对方此刻的情绪是不冷静的，会说一些气话。\u003c/p>\u003cp> 2）给对方时间，让TA说完整个过程，慢慢平复心情。\u003c/p>\u003cp>1）在说话前，体会到女儿的情绪是悲伤和委屈的。她说再也不去上课，有赌气的成分。\u003c/p>\u003cp>2）我和她靠近地坐在一起，给她时间，耐心地听她把今天的遭遇讲完，慢慢平复心情。\u003c/p>\u003cp>\u003cstrong>第二步：理（荔\u003c/strong> \u003cstrong>）解对方的立场和感受，说出来让对方知道。\u003c/strong>\u003c/p>\u003cp>1）理解对方在现有的境遇中，一定是不舒服甚至是难过的，至少短时间内无法自愈。\u003c/p>\u003cp>2）把这种理解和感受，一定要说出来告诉TA。\u003c/p>\u003cp>1） 理解女儿在滑板课上受到同学排挤，一定是很难过的，且短时间无法自我消化和遗忘。\u003c/p>\u003cp>2） 我把我对她的理解，告诉她：”同学上课排挤你，你觉得很伤心难过，妈妈非常理解你现在的感受。”\u003c/p>\u003cp>\u003cstrong>第三步：成为对方的知（枝\u003c/strong> \u003cstrong>）音，用说话的方式创造共振场。\u003c/strong>\u003c/p>\u003cp>1）让对方感受到，你跟TA有一样的想法、逻辑、一样的经验、体会，自然靠近，成为知音。\u003c/p>\u003cp>2）拉近彼此的距离后，再开启理性的谈话，力所能及给予对方问题解决方案或是建议。\u003c/p>\u003cp>1）让女儿感受到，我和她有一样的想法、逻辑、经验和体会，对她说：“刚刚听你讲了你在滑板课遇到的不愉快，如果换作是我，我一定伤心和委屈极了！”让她听完我的话，自然靠近，成为知音。\u003c/p>\u003cp>2）观察女儿情绪逐渐平和，对话中有配合性点头等肢体动作，认可我说的内容，拉近彼此距离后，再开启理性的谈话，提出了建议：“我也曾在少年时代遇到过类似的事件，如果再遇到这样的事情，我有个解决的办法，你愿意听听我的建议吗？”\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>有的小伙伴可能会说，遇到事情，我可以等对方冷静后再沟通也是一样的呀，没必要非要特意去表达“共情”，反有溜须拍马之嫌。并不是这样哈！你想，如果你能在最短的时间，通过“表达共情”的方式避免一场“家庭风波”，一家人都开开心心的多好；如果你能在最短时间，运用“表达共情”解决客户痛点或是工作难题，你的老板必定对你另眼相看。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>“表达共情”这种方法，适用于缓解、解决冲突的对抗情境中，尤其是在服务客户方面。目标是快速获得对方认可，以便推进下一步行动。如果是一些大型的人数众多的冲突矛盾，想要解决问题，单用“共情”就未必能妥善解决了，则需要更多其他的工具。\u003c/p>","interaction":"\u003cp>五、\u003cstrong>【A1】激活经验\u003c/strong>\u003c/p>\u003cp>【A1】技能点的环节提问和指令清晰，学习者能根据提问中的场景联系自己\u003cstrong>过往的具体经验\u003c/strong>，加工出假如再遇到同等情况，可以如何做。\u003c/p>\u003cp>以上是关于“表达共情”的讲解部分，下面让我们一起来实际操练一下。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计1：\u003c/strong>\u003c/p>\u003cp>在过去的工作生活中，你一定遇到过或者见过，在沟通中表达诉求和解决方案时，一直得不到对方的认可，最后不欢而散的情况。请伙伴们回顾一下，自己或者身边人最近一段时间内，有没有经历过因为在沟通时没有“表达共情”而失败，甚至是激化矛盾冲突的？\u003c/p>\u003cp>\u003cstrong>【案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者庆如分享：\u003c/strong>\u003c/p>\u003cp>上周我的同事小李请年休假带父母去旅游。但是因为部门有个项目特别紧急，我不得不布置了一些任务需要她在休假期间完成，小李在微信上生气地拒绝了我。我打电话给她，但在沟通时没有“表达共情”，结果更糟了，她在电话那头说想要离职。\u003c/p>\u003cp>\u003cstrong>拆书家回应：\u003c/strong>\u003c/p>\u003cp>好的，谢谢庆如的分享。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计2：\u003c/strong>\u003c/p>\u003cp>如果时光倒流，再给你一次机会，就刚才小组内讨论的案例，运用我在片段讲解中表达共情“提荔枝”的三个步骤，可以怎样改写你与对方之前的场景对话呢？请大家组内讨论，一会儿我们派小组代表来分享。\u003c/p>\u003cp>好，时间到了，有哪位小伙伴愿意主动站到抬上来分享一下自己的经历呢？好，有请庆如。\u003c/p>\u003cp>\u003cstrong>【A1-反例变正例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者庆如分享：\u003c/strong>\u003c/p>\u003cp>如果回到过去，我会运用今天学到的“提荔枝”三步骤来“表达共情”：\u003c/p>\u003cp>\u003cstrong>第一步：体（提\u003c/strong> \u003cstrong>）会对方的情绪和想法，让小李倾诉彻底。\u003c/strong>\u003c/p>\u003cp>1）在说话前，体会到对方此刻的情绪是不冷静的，会说一些气话。\u003c/p>\u003cp>2）给对方时间，让TA说完整个过程，慢慢平复心情。\u003c/p>\u003cp>1）在说话前，体会到小李的情绪是气愤和委屈的。她说要离职，应该也是赌气。\u003c/p>\u003cp>2）我向她表示诚挚的歉意，给她足够的时间，耐心地听她把她身处的境况讲完，慢慢平复心情。小李说她已经出来好几天了，父母很开心，每个景点都想去。每天光徒步，就要走上三万步。天气又热，把她累的够呛，但又生怕影响父母高涨的情绪，只得一直随着父母的意愿。\u003c/p>\u003cp>\u003cstrong>第二步：理（荔\u003c/strong> \u003cstrong>）解对方的立场和感受，说出来让对方知道。\u003c/strong>\u003c/p>\u003cp>1）理解对方在现有的境遇中，一定是不舒服甚至是难过的，至少短时间内无法自愈。\u003c/p>\u003cp>2）把这种理解和感受，一定要说出来告诉TA。\u003c/p>\u003cp>1） 理解小李现在在旅途中身体已透支，一定已经很累很不舒服了。但难得带父母出来，作为女儿，还要时刻关注父母的旅游感受。再听到休假中还要加班，一定很崩溃，至少短时间内无法接受。\u003c/p>\u003cp>2）我把我对她的理解，告诉她：“你难得带老家的父母出来旅游，就想能对父母尽孝。既不想败了他们的兴致，又不想让父母感觉到你休假了还要辛苦加班，让他们担心，我非常理解你现在的感受。”\u003c/p>\u003cp>\u003cstrong>第三步：成为对方的知（枝\u003c/strong> \u003cstrong>）音，用说话的方式创造共振场。\u003c/strong>\u003c/p>\u003cp>1）让对方感受到，你跟TA有一样的想法、逻辑、一样的经验、体会，自然靠近，成为知音。\u003c/p>\u003cp>2）拉近彼此的距离后，再开启理性的谈话，力所能及给予对方问题解决方案或是建议。\u003c/p>\u003cp>1） 让小李感受到，我和她有一样的想法、逻辑、经验和体会，对她说：“听你讲了你带父母出游的不容易，如果换作是我，这么多天，这么热，我可能早就受不了发飙了！”让她听完我的话，自然靠近，成为知音。\u003c/p>\u003cp>2）察觉小李情绪逐渐平和，对话中开始附和并认可我说的内容后，拉近彼此距离后，再开启理性的谈话，提出建议：“我之前带父母和孩子出游和你遇到了和你一样的情况，你愿意听听我的建议吗？”\u003c/p>\u003cp>\u003cstrong>拆书家反馈：\u003c/strong>\u003c/p>\u003cp>感谢庆如的分享，我觉得讲的特别好，非常好地运用了我们的“表达共情”的“提荔枝”三步骤。\u003c/p>\u003cp>第一步，体会对方的情绪和想法，让对方倾诉彻底；第二步，理解对方的立场和感受，说出来让对方知道；第三步，成为对方的知音，创造谈话的共振场。这一套流程下来，自然就建立了一个共振的场，不知不觉中拉近了双方的距离，获得了对方的认可。这时候，你想要再推进下一步行动，无论是请小李帮忙，富有余力的话分担一些工作，还是双方商量出更好的办法，都比之前的境况要好很多。\u003c/p>\u003cp>\u003cstrong>【R1-总结】\u003c/strong>\u003c/p>\u003cp>咱们第一个片段的学习就到这里，相信大家已经学会了表达共情的“提荔枝”三步骤，并且在未来会去运用在生活和工作中。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>刚刚我们学习的片段讲的是在沟通中“表达共情”，通过情感表达来对方获得对方认可，而接下来我们要学习的片段，则是更高级别的，通过逻辑分析输出表达，来获得认同。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":20767,"quote":"\u003cp>\u003cstrong>第二个RIA “巧妙迎合”\u003c/strong>\u003c/p>\u003cp>一、\u003cstrong>学习目标2：\u003c/strong>\u003c/p>\u003cp>片段2主要说的是迎合的三种方法，在完成这个片段的学习后，学习者可以根据与对方对话是事实还是观点给出承接的话语，引发对方共鸣感，进而建立链接，获得对方好感。\u003c/p>\u003cp>二、\u003cstrong>【R】阅读原书拆页\u003c/strong>\u003c/p>\u003cp>接下来咱们用两分钟的时间，阅读一下原文，读完的小伙伴可以举手示意我一下。《说话的力量》P171-172\u003c/p>\u003cp>\u003cem>高超的迎合技巧就是，在对方陈述的是看法和观点时，你提出一些你看到非常符合对方表达的观点的现象；在对方陈述的是事实时，你将对方陈述的事实做一个总结和概括，提炼出一个观点，而这个观点又恰好印证对方所说的事实。这就是最基本的两种迎合的方式。\u003c/em>\u003c/p>\u003cp>\u003cstrong>\u003cem>给观点找事实\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cem>叙述的要求是什么？是讲事实、筛选事实、通过事实证明观点。迎合的原理就在于此。当你听到了对方话语中的事实的时候，或者你听到他给了你一个结论的时候，你能听出他依据的逻辑，这时，你就能跟他产生共鸣。\u003c/em>\u003c/p>\u003cp>\u003cem>\u003cstrong>举一个例子：“今年夏天北京可真够热的。”这句话是事实还是结论？这是一个结论，是个人看法。“地坛公园可真够大的。”这是事实还是结论？这也是一个结论，“大”是与哪里相比？这是你的判断。\u003c/strong>“我认识的一个朋友，他每月挣的钱可真够多的。”在不同人的概念里，“多”的概念都是不同的。我在10个人里面调查过，有人认为1万元就算多了，有人写10万元。\u003cstrong>所以当有人对你说“今年夏天北京可真够热的”时，你要知道，这是一个结论，不是事实。那么怎么去迎合呢？你跟一句：“是啊，43度呢，45年来最高纪录了。”你等于为他的结论提供了一个事实，他就会觉得和你投缘。\u003c/strong>\u003c/em>\u003c/p>\u003cp>\u003cstrong>\u003cem>对方说了他的看法，说了一个结论，而你补充了一个事实，不知不觉中对方就觉得和你说话很投机。所谓“酒逢知己千杯少，话不投机半句多”，只有投机了，对话才容易进行下去。\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>给事实找观点\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cem>那么有没有可能是对方给了事实，你帮他总结出一个观点呢？当然也可以。\u003c/em>\u003c/p>\u003cp>\u003cem>比如，\u003cstrong>对方说“今天刚到这里的长途汽车站，就把手机丢了”，这是事实。你可以补一句：“长途汽车站那里人流量特别大，确实挺乱的。”这也是一种迎合的方法，他说了一个事实，你按照他的事实补充一个结论，他会觉得你理解他的意思。不论是他说事实，你给结论，还是他说结论，你给事实，两者的逻辑是一致的，这样你们俩不知不觉就站在一起了。\u003c/strong>\u003c/em>\u003c/p>\u003cp>\u003cstrong>\u003cem>一个人向你抱怨：“5分钟不到网都断了8次。”他说的是个事实，你怎么迎合？我们可以回答：“是呀，这里的WiFi确实信号不好。”\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>事实和观点都有的情况下，补充自己的细节\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>如果对方说：“上周我去银行办事，人太多了，排队排了一个小时，太耽误事情。”这句话既有事实又有结论，事实是他排了一个小时，结论是太耽误事情。那么你又怎么去迎合？你可以这样回答：“太有同感了！上次我银行卡丢了，让我去支行补办，就这样的业务还要取号排队，结果我等了一个半小时，太耽误时间了。”\u003c/em>\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>三、【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>看到大部分伙伴都举手示意原文看完了，接下来我们对这段原文进行一下解读。\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>这个片段运用了一些案例说明了：当对方给观点，我们就给观点找事实；对方给事实，我们就给事实找观点；观点事实都有，我们就加细节。描述了迎合的三种方法。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>我们在工作生活中也会经常遇到希望和别人产生链接，需要“迎合”来获得对方认可、信任，从而推进下一步行动的情况。在这种情况下，使用“迎合”的方法，能够迅速和对方产生共鸣，建立好感。反之，如果你只会给对方一句：“好好好，是是是，您说得对。”我要是对方，肯定觉得你这人又敷衍又没水平。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>“迎合”的方法，适用于建立链接，承接话语，加强双方了解等情境中，尤其是用在谈判、商业场合等方面。目标是不留痕迹地获得对方认可，以便推进下一步行动。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>细化原文的方法：\u003c/strong>\u003c/p>\u003cp>第一种方法：承接语势，给观点找（\u003cstrong>找\u003c/strong>）事实。提供具体的事实，来印证对方说的观点正确。\u003c/p>\u003cp>第二种方法：逻（\u003cstrong>萝\u003c/strong>）辑分析，给事实找观点。用逻辑一致的观点总结，来印证对方说的非常对。\u003c/p>\u003cp>第三种方法：事实和观点都有的情况下，补（\u003cstrong>卜\u003c/strong>）充自己的细节。补充一个自己的体会，要包括类似的细节，创造出你们是同类的感觉，那你说出的话对方就很受用。\u003c/p>\u003cp>\u003cstrong>【意译案例】\u003c/strong>\u003c/p>\u003cp>我举一个我遇到的情况：\u003c/p>\u003cp>\u003cstrong>新客户A来公司拜访，我负责招待。因为暑期南京是旅游旺季，路上有些堵。在楼下迎接到客户A的时候，刚握了手，就听他说道：“南京的路可真够堵的呀！”这句话是事实还是结论？这是一个结论，是个人看法。“堵”是客户的判断。所以当有人对我说“南京的路可真够堵的”时，我知道，这是一个结论，不是事实。那么怎么去迎合呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我跟一句（找\u003c/strong>\u003cstrong>）\u003c/strong>\u003cstrong>：“谁说不是啊，本来30分钟的路程多出了1个小时呢！”（\u003c/strong>第一种方法：承接语势，给观点找事实\u003cstrong>）”我等于为他的结论提供了一个事实，他就会觉得和我投缘。对方说了他的看法，说了一个结论，而我补充了一个事实，不知不觉中对方就觉得和我说话很投机。所谓“酒逢知己千杯少，话不投机半句多”，只有投机了，对话才容易进行下去。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>紧接着进入大楼的电梯间，A总接着说：“让你久等啦。刚刚办理入住，排队等了20分钟，前面排了10来个人，前台站了4个人在办理都手忙脚乱的。”这是事实。\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 我补一句（萝\u003c/strong>\u003cstrong>）\u003c/strong>\u003cstrong>：“南京今年是旅游网红城市，哪哪都排队，尤其是酒店，家家爆满，办理入住确实要很长时间。（\u003c/strong>第二种方法：逻辑分析，给事实找观点\u003cstrong>）也是一种迎合的方法，他说了一个事实，我按照他的事实补充一个结论，他会觉得我理解他的意思。不论是他说事实，我给结论，还是他说结论，我给事实，两者的逻辑是一致的，这样我们俩不知不觉就站在一起了。他向我抱怨：“排队办理入住，等待时间要1小时以上。”他说的是个事实，我怎么迎合？我可以回答：“是呀，确实等待时间太长了。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>到达会议室坐下，A总环顾了墙面，感叹道：“早就听闻贵公司重视企业文化，刚在一楼大厅就看到墙壁上雕刻着你们公司的愿景、使命、价值观，你们这会议室也挂满了企业文化的经营管理理念和特色文化理念，真让人印象深刻啊！”这句话既有事实又有结论，事实是大厅和会议室都有企业文化宣传版，结论是公司重视企业文化。那么你又怎么去迎合？\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 我这样回答\u003c/strong>（\u003cstrong>卜\u003c/strong>）\u003cstrong>：“太有同感了！我们公司所有员工面试时就要通过价值观考核，进了公司以后逐年都要进行企业文化的研讨营培训和考核，出差没参加的员工还得补考呢！公司非常重视企业文化。\u003c/strong>（第三种方法：事实和观点都有的情况下，补充自己的细节）\u003cstrong>A总，您真是心细如尘、观察入微啊！”\u003c/strong>\u003c/p>\u003cp> 这样沟通下来，每当对方抛出一个新的话题，我都会按照“找萝卜”的三种方法接上。在这样“巧妙迎合”的沟通下，A总每次都点头表示认同，无形中拉近了我们的距离，产生了信任，对我们下一步的合作起到了非常关键的作用。\u003c/p>","interaction":"\u003cp>\u003cstrong>四、【A3】促动参与\u003c/strong>\u003c/p>\u003cp>要求：【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并形成一个解决方案，或是应用知识点进行组内角色扮演。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计\u003c/strong>（拆书家给出具体场景或一个方向，学习者可以根据方向加工出具体的案例）：\u003c/p>\u003cp>我们刚刚又一同拆解了第二个RIA“巧妙迎合”，现在我又要邀请各位伙伴给我一些反馈了。我会给到大家一个具体的场景演练。\u003c/p>\u003cp>\u003cstrong>【R2-A3场景设计】\u003c/strong>\u003c/p>\u003cp>场景如下：你的一位标准黄金单身汉朋友，单身30多年。各项条件都还不错，无奈性格过于内向，还特别不会说话表达。但他发誓今年一定要在双十一前找到女朋友。所以他对在相亲见面，和对方谈话沟通的时候，如何能产生链接，承接上对方的话语，获得对方好感和认可，特来求助于你。希望你能带他模拟演练。\u003c/p>\u003cp>参与要求，要进行角色扮演，一个人扮演你的“朋友”，一个人扮演“假装未来的女朋友（下面都简用“女朋友”代替）”。一定要结合我们刚刚拆解学到的知识点哦。\u003c/p>\u003cp>\u003cstrong>【小组讨论】\u003c/strong>\u003c/p>\u003cp>小伙伴们按照刚才分组的情况进行演练，组内的2位小伙伴分别扮演自“朋友”和“女朋友”，“朋友”怎样运用“巧妙迎合”的方法来和“女朋友”对话，取得“女朋友”的认可呢？小组内演练时间8分钟，8分钟后我们将邀请一组小伙伴上台展示他们的演练成果。希望小伙伴都积极参与，检验一下自己的学习效果。大家可以把演练的步骤写下来，便于分享。还记得“巧妙迎合”的三个方法分别是“找、萝、卜”：\u003c/p>\u003cp>1、承接语势，给观点找（\u003cstrong>找\u003c/strong>）事实；\u003c/p>\u003cp>2、逻（\u003cstrong>萝\u003c/strong>）辑分析，给事实找观点；\u003c/p>\u003cp>3、事实和观点都有的情况下，补（\u003cstrong>卜\u003c/strong>）充自己的细节。演练中，至少要用到其中一种方法哦，当然越多越好。\u003c/p>\u003cp>\u003cstrong>【角色扮演】\u003c/strong>\u003c/p>\u003cp>好的，讨论时间到了。请两位小伙伴表演在这个场景下，要将沟通中“巧妙迎合”的对话过程演示出来~\u003c/p>\u003cp>\u003cstrong>【案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>丽丽组，丽丽+贝贝表演，贝贝扮演朋友，丽丽扮演女朋友。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>女朋友\u003c/strong>：“你好，我是王阿姨介绍的丽丽。”\u003c/p>\u003cp>\u003cstrong>朋友：\u003c/strong>“你好，我是贝贝，很高兴认识你。快请坐！”\u003c/p>\u003cp>\u003cstrong>女朋友\u003c/strong>：“今天天气可真热啊！”\u003c/p>\u003cp>\u003cstrong>朋友：\u003c/strong>“谁说不是呢，南京的秋老虎是出了名的，这一周的气温都在35度以上。”\u003c/p>\u003cp>\u003cstrong>女朋友\u003c/strong>：“听说你就职于一家国企，上班时间朝九晚五，周末加班也不多。”\u003c/p>\u003cp>\u003cstrong>朋友：\u003c/strong>“是啊，我的上班时间地点都很固定，工作也很稳定，这样以后成家了也能顾得上家呢！（笑）\u003c/p>\u003cp>\u003cstrong>女友\u003c/strong>：“哇，这么好，你们公司里难道没有内卷吗？我可听说企业里的竞争非常激烈，KPI有严格考核，年终还有末位淘汰呢！”\u003c/p>\u003cp>\u003cstrong>朋友：“\u003c/strong>当然有啊，企业给部门都有严格的考核，但销售岗位的的绩效考核和淘汰更加激烈。而我是做技术岗位的，考核点更关注系统的迭代和数据更新，当然我也可以移动办公，你刚刚来之前我还在和团队在线沟通呢！这天太热了，你先看看喝点什么？咱们再接着聊！”\u003c/p>\u003cp>\u003cstrong>女朋友\u003c/strong>：“冰咖啡就好，确实太热了，刚刚地铁站走过来这么点路，感觉已经晒化了！”\u003c/p>\u003cp>\u003cstrong>朋友：\u003c/strong>“下次可不让你走过来了，我去接你！”（笑）\u003c/p>\u003cp>\u003cstrong>拆书家反馈：\u003c/strong>\u003c/p>\u003cp>哇！非常感谢丽丽和贝贝的精彩演绎，我提议给他们再鼓鼓掌。真的非常精彩！大家来看看，他们组在扮演的对话中，运用到了哪些我们刚刚拆解的关于“巧妙迎合”的方法呢？\u003c/p>\u003cp>首先用到第一种：女朋友说天热，朋友\u003cstrong>承接语势，给观点找\u003c/strong>（\u003cstrong>找\u003c/strong>）\u003cstrong>事实：\u003c/strong>说南京的秋老虎是出了名的，一周的气温都在35度以上。\u003c/p>\u003cp>然后是第二种：女朋友说，听说他在一家国企，上班时间朝九晚五，周末加班也不多。朋友赶紧说对啊，根据女朋友的\u003cstrong>逻\u003c/strong>（\u003cstrong>萝\u003c/strong>）\u003cstrong>辑分析，给事实找观点。补充观点：\u003c/strong>他的工作时间地点固定，工作稳定。还开玩笑说以后能顾家。\u003c/p>\u003cp>最后，也有第三种：和女朋友讨论企业内部竞争问题时，朋友在\u003cstrong>事实和观点都有的情况下，补\u003c/strong>（\u003cstrong>卜\u003c/strong>）\u003cstrong>充自己的细节\u003c/strong>，既认可了女朋友说的话，还补充说明了自己的工作性质。\u003c/p>\u003cp>谢谢小伙伴的分享，感觉每个方法大家都运用的非常好。这样一段“巧妙迎合”的方法运用下来，作为“女朋友”不说心花怒放，至少也会对你的“朋友”产生好感，对他的话非常受用啦！\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>要求：【A2】技能点指令清晰，至少一个【A2】环节提问中包括情境或场景，有学习者受启发联系到自己的具体应用场景。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计\u003c/strong>（分步催化引导的场景指向未来会遇到的，学习者要加工的是未来那个场景中如何用，提问中包括情境或场景）：\u003c/p>\u003cp>\u003cstrong>【分步催化1】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【提出问题】\u003c/strong>\u003c/p>\u003cp>接下来请大家想一下，自己在未来一周，有哪些情况可能会用到“巧妙迎合”呢？比如：和同事、客户、领导、孩子、对象、父母沟通中，还是可能会与一些从未谋面的客户、邻居打交道？\u003c/p>\u003cp>\u003cstrong>【发出指令】\u003c/strong>\u003c/p>\u003cp>请小伙伴把自己可能会遇到的情况在组内分享交流。给大家2分钟的时间，小组内分享结束后，我将邀请一位小伙伴上台分享。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>好的，时间到了，有哪位小伙伴愿意跟大家分享一下自己可能会遇到的，需要运用“巧妙迎合”的情景呢？\u003c/p>\u003cp>\u003cstrong>【案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者乔阳分享：\u003c/strong>\u003c/p>\u003cp>可能运用的场景: 下周我要去深圳参加企业培训行业会议，可能会遇到有合作意向的培训供应商或团队，可以用迎合的沟通技巧与对方开展交流，可能是甲乙双方合作，也可能未来有机会加入对方团队。\u003c/p>\u003cp>\u003cstrong>【分步催化2】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【发出指令】\u003c/strong>\u003c/p>\u003cp>感谢乔阳的分享。接下来就请大家使用“巧妙迎合”的方法，在这个场景下给对方做一个回应。3分钟后，我将邀请一位小伙伴来分享。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>好的，时间到了，有哪位小伙伴愿意跟大家分享一下自己是如何运用“巧妙迎合”的呢？\u003c/p>\u003cp>\u003cstrong>【案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者乔阳分享：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【背景介绍】\u003c/strong>\u003c/p>\u003cp>下周遇到的可能场景：我是甲方公司代表身份，在会议上寻找乙丙方合作供应商。现在我邀请我的搭档杨柳来扮演潜在合作供应商，进行模拟对话，展示我如何运用“巧妙迎合”的方法。\u003c/p>\u003cp>\u003cstrong>学习者乔阳、杨柳分享：\u003c/strong>\u003c/p>\u003cp>杨柳（潜在合作供应商）：“乔阳，您专程从南京赶到深圳来参加这次行业会议！”\u003c/p>\u003cp>乔阳（甲方机构代表）：“对，这次会议培训杂志主办，其中许多培训主题特别好，结合现在培训行业发展形式，有很多课题是我特别感兴趣的，所以来一趟深圳非常值得。”\u003c/p>\u003cp>杨柳：“哎，可惜现在企业培训市场越来越难做，客户越来越难以搞定”\u003c/p>\u003cp>乔阳：确实是，特别是今年经济下行，很多甲方企业都在砍培训预算，而且客户要求越来越高。\u003c/p>\u003cp>杨柳：目前我们手上就有一个项目，但是专业人手不足。\u003c/p>\u003cp>乔阳：看来你们做的很不错，我了解到很多目前培训团队市场不好做，很多机构都在削减人员编制，你们这边缺人手说明你们干的还挺不错。看看我们有没有机会合作。要不我们来加个微信。\u003c/p>\u003cp>杨柳：好，来加个微信。\u003c/p>\u003cp>\u003cstrong>拆书家反馈：\u003c/strong>\u003c/p>\u003cp>哇！非常感谢乔阳和杨柳的分享，我听到了至少两种“巧妙迎合”的方法：\u003c/p>\u003cp>1、供应商吐糟现在企业培训市场很难做，乔阳扮演的谈意向，先说培训市场很难，并对很难做了解释。（给观点找事实）\u003c/p>\u003cp>2、供应商接了一个项目缺人手，乔阳顺这语势接着说，你们做的很不错的，和对方产生了链接。（给事实找观点）\u003c/p>\u003cp>\u003cstrong>结语\u003c/strong>（强有力的结语）\u003c/p>\u003cp> 经过大家热烈的讨论，相信我们在未来与他人沟通中，通过刻意练习“表达共情”和“巧妙迎合”能够倾听对方，换位思考，表达理解引发对方情感共鸣，进而获得他人的认可与好感。谢谢大家的陪伴，我的拆书到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1695178347000,"updated_at":1696835285000,"ria":true},{"id":16468,"topic":"晋级","learn_goal":"","remark":"晋级","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"王礼界","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>为了方便随后的讨论， 我们进行分组，左边伙伴为1组，右边伙伴为2组。\u003cbr>\u003cbr>大家好！ 我是王礼界， 欢迎大家参加本次拆书活动， 我的三个标签是， 销售员、 新手拆书家、 学习者。\u003cbr>\u003cbr>在跟我完成本次 RIA 现场学习后， 学习者在沟通中， 在不确定对方是否理解，我们表达的概念的意思的时候，学习者能够运用 （ 行为） 让对方听懂我的3个步骤（澄清），来进行沟通， 让对方听懂我， 消除对方误解（界定）\u003cbr>\u003cbr>\u003cbr>\u003cbr>图书介绍（场景介绍法）\u003cbr>\u003cbr>[ 事件场景 ]我相信大家应该有工作的经历吧！在工作中， 几乎每天， 我们都在进行沟通， 可有时候，会出现，对方不理解的情况， 比如， 几年前的一天， 我接到一个同事的电话，他问我，有个门店要的超时赠品， 是给他，还是不给他？我就说给他要这么说， 不给他要那么说。 他听了过后说， 你就说给，还是不给吗， 我就说， 可以给他， 也可以不给他（但要避免下次又问超时赠品的问题），给他要这么说， 不给他要那么说， 回答了三次， 他还是说不明白，过后，我说我这是讲第 4 次了， 他才听懂。\u003cbr>\u003cbr>[ 提问 ] 在过去的生活，或者工作中， 大家有没有遇到过类似的场景，在沟通中， 对方很难理解我们表达的意思的情况， 当时，你是怎么做的呢？结果又怎样呢？\u003cbr>\u003cbr>[ 影响 ] 如果很难让领导听懂我， 那领导的心里肯定会对我们有看法， 如果很难让客户听懂我， 那就很难得到客户的支持， 结果不仅会影响到我们工作的开展， 还会影响到自己职业的发展。\u003cbr>\u003cbr>[ 解决 ] 那如何让对方听懂我呢？ 《说话的力量》这本书中， 就为我们提供了解决问题的思路，那就是，在解释过后，还需要确认对方是否听懂了。\u003cbr>\u003cbr>请大家自测\u003cbr>\u003cbr> 在开始片段拆解前，请大家做下量表自测题，来了解自己在沟通中，争取让对方听懂我的能力。请仔细阅读表上的每一句话， 根据自己的实际情况，来勾选对应的数字，不用去纠结分数， 按照自己的实际情况做出选择， 就可以了。 现在， 请大家用一分钟的时间来完成这个测试。\u003cbr>\u003cbr>自测说明： 请仔细阅读表格中的每句话， 根据自己的实际情况打分。 在这份自测题中 （ “1” 代表完全符合实际情况， “6” 代表完全不符合实际情况； ） 测试完后， 相加勾选的数字， 得出总分。\u003cbr>\u003cbr>1、我总是认为对方能够理解我表达的概念的意思。1 2 3 4 5 6\u003cbr>\u003cbr>2、解释概念的时候，我不知道要讲哪些要点。1 2 3 4 5 6\u003cbr>\u003cbr>3、解释概念的时候，我总是感觉到比较困难。1 2 3 4 5 6\u003cbr>\u003cbr>4、解释概念后，我总是认为对方听懂了我讲的概念的意思。1 2 3 4 5 6\u003cbr>\u003cbr>5、多次解释概念的时候，我会显得不耐烦。1 2 3 4 5 6\u003cbr>\u003cbr>合计分数： \u003cbr>\u003cbr>解释自测题\u003cbr>\u003cbr> 好的，大家完成了这个测试，这个测试一共有5道题目，总分是30分，下面，我们就来看看大家的得分。\u003cbr>\u003cbr>1、总分在20分以上的伙伴，说明在沟通中，你让对方听懂我的能力很强。\u003cbr>\u003cbr>2、总分在10 - 20分之间的伙伴，说明在沟通中，我们让对方听懂我的能力，还有提升空间，通过今天的片段拆解，可以提升让对方听懂我的能力，来消除对方的误解。\u003cbr>\u003cbr>3、总分在10分以下的伙伴。\u003cbr>\u003cbr>我们就更应该要注意，如何让对方听懂我，这个问题。\u003cbr>\u003cbr>当然，这只是一个测试，我们不用去纠结分数的多少，因为，我们今天要拆解的这个片段，就是让对方听懂我的一个案例。下面，我们就来拆解这个片段，请大家用1分钟的时间来阅读拆页，阅读完后，请举手示意我。 \u003c/p>","ratings_count":1,"texts":[{"id":20591,"quote":"\u003cp>《说话的力量》作者： 孙路弘\u003cbr>\u003cbr>下面我们来看一段电影《心灵捕手》中，\u003cbr>\u003cbr>心理学教授西恩向充满困惑的男主人公威尔的发问。 这部电影描写的是一个天赋极高但因童年阴影而止步不前的男孩的故事， 片中充满了睿智的对话。\u003cbr>\u003cbr>西恩： 你有心灵伴侣吗？\u003cbr>\u003cbr>威尔： 我有 …… ？ 说清楚点。\u003cbr>\u003cbr>西恩： 能够和你匹敌的人。\u003cbr>\u003cbr>威尔： 我有查克。\u003cbr>\u003cbr>西恩： 不是， 查克是你的家人， 我讲的是触动你心灵的人 ……\u003cbr>\u003cbr>威尔： 我有 ……\u003cbr>\u003cbr>西恩： 谁？\u003cbr>\u003cbr>威尔： 有很多。\u003cbr>\u003cbr>西恩： 说出来 ……\u003cbr>\u003cbr>威尔： 莎士比亚、 尼采、 福斯特、 奥康纳、 康德、 洛克 ……\u003cbr>\u003cbr>[ 插图 ] 图 7—1\u003cbr>\u003cbr>电影《心灵捕手》截图\u003cbr>\u003cbr>西恩： 很棒， 但他们都死了。\u003cbr>\u003cbr>威尔： 对我而言， 他们没死。\u003cbr>\u003cbr>西恩： 他们当然死了，\u003cbr>\u003cbr>威尔， 你无法和他们对谈， 你无法回应他们。\u003cbr>\u003cbr>威尔： 对啊， 没有法术把他们弄醒超生， 是没办法和他们对谈的。\u003cbr>\u003cbr>西恩： 对， 那就是我所说的。 你只看到这个世界中负面的事， 如果你不踏出这第一步， 就永远不会拥有那种关系。\u003c/p>","explains":"\u003cp>好的， 大家阅读了拆页，大部分伙伴都举手了。\u003cbr>\u003cbr>what ： 片段中有一段对话，说的是，心理学教授西恩，争取让威尔听懂他讲的概念，心灵伴侣的意思。\u003cbr>\u003cbr>下面我们就来看，西恩是如何“让对方听懂我&quot;的。\u003cbr>\u003cbr>理解片段：我们先来看片段中的第1段对话，西恩说，你有心灵伴侣吗？威尔回答，我有，说清楚点，这里，咸尔是不是没有听懂，心灵伴侣的意思？\u003cbr>\u003cbr>伙伴：是的。\u003cbr>\u003cbr>是的，没有听懂，心灵伴侣的意思。\u003cbr>\u003cbr>过后，西恩进行了解释，能够和你匹敌的人，威尔回答，我有查克。西恩又说，不是，查克是你的家人，我讲的是触动你心灵的人，这里，我们来看，他们双方，是不是对心灵伴侣讲的是人，达成了共识？\u003cbr>\u003cbr>伙伴：是的。\u003cbr>\u003cbr>是的，对心灵伴侣讲的是人，达成了共识，同时，西恩又进行了解释，我讲的是触动你心灵的人。\u003cbr>\u003cbr>随后，威尔回答，我有，有很多，在这个时候，西恩问咸尔，谁，并要对方，说出来，\u003cbr>\u003cbr>在威尔说了一连串的人物名称过后，西恩说，很棒，这里，我们来看，他们双方，是不是对心灵伴侣讲的是，触动你心灵的人的理解，达成了共识？\u003cbr>\u003cbr>伙伴：是的。\u003cbr>\u003cbr>是的，对心灵伴侣讲的是，触动你心灵的人的理解，达成了共识。\u003cbr>\u003cbr>why ： 在日常沟通中， 当对方不理解我们表达的意思的时候， 我们就努力 的进行解释， 想让对方听懂我， 来理解我。 多次解释过后， 对方还不明白， 我们就可能会显得不耐烦， 心里面认为自己明明说清楚了， 可是对方还听不懂。 当然， 对方也有可能将没有听懂的原因指向你， 认为是你没有说清楚， 结果很可能就会有人认为， 这么简单的事情还弄不清楚， 是不是有意的， 这样的话， 双方就可能产生误会。\u003cbr>\u003cbr>如果用上让对方听懂我的办法， 先给出一个概念， 然后，进行解释， 直到双方对概念的理解达成共识，就能让对方听懂我表达的意思， 因为， 一步一步解释了对方不理解的部分。\u003cbr>\u003cbr>how ： 那如何让对方听懂我呢？根据刚才，我们对片段的理解来看，可以归纳出以下三个步骤：\u003cbr>\u003cbr>1 、 结出概念。给出一个概念， 比如， 案例中的 “ 心灵伴侣 ” 。\u003cbr>\u003cbr>2 、 解释概念。解释自己给出的这个概念，比如，案例中，西恩说，能够和你匹敌的人，还有，我讲的是触动你心灵的人。\u003cbr>\u003cbr>3 、 达成共识。对概念的理解达成共识。\u003cbr>\u003cbr>共识有2点，①对概念讲的事物类别达成共识，比如，案例中，双方对心灵伴侣讲的是人物，达成了共识，②对概念讲的事物区别于它事物的理解达成共识，比如，案例中，在威尔说了一连串的人物名称过后，双方对心灵伴侣讲的是触动你心灵的人的理解，就达成了共识，因为，共识从人物，具体到了，那个人。\u003cbr>\u003cbr>举例：下面，举个例子，来说明一下，以上三个步骤的具体应用。\u003cbr>\u003cbr>前几天，我和一个朋友讨论，他在网上直播卖书的事情，1我说，你有用户思维吗？他说，什么用户思维，说清楚点。2我说，就是要替用户着想，也就是要替顾客着想，他说，我是在替顾客着想啊①，我推荐的都是一些经典书，很有用的。我说，不是你认为有用的意思，我讲的是要站在用户的角度去思考问题。他说，是这样的呀，3我说，那样的？他说，要去思考，用户有什么想法，用户有什么需求啊②。\u003cbr>\u003cbr>在这个时候，我就认为，他听懂了我讲的用户思维的意思，因为，他讲了，要去思考用户有什么想法，用户有什么需求，这里，就从思考的事情，具体到了，思考那件事情。过后，我说，是的，我们就聊用户的事情了。\u003cbr>\u003cbr>那么，在解释概念的时候，让对方听懂我，我们就可以得出，概念讲的事情，就需要对方具体到那件事情，概念讲的人，或物，就要具体到什么？\u003cbr>\u003cbr>伙伴：那个人，那个物，\u003cbr>\u003cbr>是的，要具体到那个人，或那个物。\u003cbr>\u003cbr>在沟通中，我们给到对方一个概念的时候，有的时候说出来对方就懂了，我们就可以继续后面的谈话内容；有的时候，需要来回进行解释，比如拆页中西恩跟威尔说的概念心灵伴侣，就解释了两次。在日常生活或者工作中，有一些比较复杂的概念，有可能需要来回解释很多次，比如元认知。我们今天讲的三个步骤，是给到大家一种思路，先给出概念，然后，解释概念，最后，达成共识，对概念的理解达成共识过后，我们后面的沟通才会更有效。\u003cbr>\u003cbr>where ： 在日常沟通中， 我们都可以运用， 让对方听懂我的办法， 来进行沟通， 当对方不讲道理的时候， 就不太适用， 因为你的解释对方听不进去。\u003c/p>","interaction":"\u003cp>以上就是我对片段的拆解， 下面我们来进行现场演练，\u003cbr>\u003cbr>场景是这样的，新手拆书家小王， 在准备晋级选片段的时候， 将自己手中的图书翻了又翻， 看了又看， 还是没有找到一个让自己满意的片段， 于是， 小王打算，明天上班，午休的时侯， 在办公室，找同事老张，借实用类图书，\u003cbr>\u003cbr>（问题）现在，请大家思考一下，在明天上班，午休的时候，在办公室， 小王应该怎样运用，让对方听懂我的三个步骤，来进行沟通，让老张听懂小王说的实用类图书？\u003cbr>\u003cbr>（指令）1、下面，请在小组内，每两人一组，一人扮演小王，一人扮演老张，相互协助，先写下解决问题的，双方的对话台词，要求，①小王的对话台词内容，要用上，让对方听懂我的三个步骤，②对话的结果，至少要明确出，那一本实用类图书。\u003cbr>\u003cbr>2、再进行角色扮演，一人扮演小王， 一人扮演老张，按写下的对话台词，先预演一次，5 分钟后， 我们邀请 一组伙伴，按写下的对话台词，进行现场演练分亨。\u003cbr>\u003cbr>处理异议：如果有单独一人，那就请他观摩指导讨论。\u003cbr>\u003cbr>二位伙伴现场分享，\u003cbr>\u003cbr>林同学1扮演小王\u003cbr>\u003cbr>林同学2扮演老张\u003cbr>\u003cbr>小王：老张，你好，给你商量个事。\u003cbr>\u003cbr>老张：什么事，你说。\u003cbr>\u003cbr>小王：我借本实用类图书。\u003cbr>\u003cbr>老张：实用类，图书，说清楚点。\u003cbr>\u003cbr>小王：实用类图书，就是侧重解决实际问题，强调实战的书。\u003cbr>\u003cbr>老张：那些实际问题哦!\u003cbr>\u003cbr>小王：比如，解决沟通问题，还有举例子说明的，\u003cbr>\u003cbr>老张：这样的书，我有。\u003cbr>\u003cbr>小王：说出来，书名是什么？\u003cbr>\u003cbr>老张：《关键对话如何高效能沟通》\u003cbr>\u003cbr>小王：那我就借这本书。\u003cbr>\u003cbr>\u003cbr>\u003cbr>为了学以致用，下面，我们来安排一个作业：\u003cbr>\u003cbr>在接下来的两三周内，在沟通中，我们是否有，不确定对方是否理解我们表达的概念的意思的情况，如果有，请大家用让对方听懂我的办法来进行沟通，让对方听懂我，如果没有，那请大家将这个方法分享给身边的伙伴，然后，请将这个过程记录下来，整理成文字，或者图片私信发给我。\u003cbr>\u003cbr>以上就是我的 TF3-2 的晋级分享，让对方听懂我， 欢迎大家留言指导， 谢谢大家！\u003cbr>\u003cbr>王老师分享：\u003cbr>\u003cbr>背景：活动过后，我收集反馈，微信上，又找王同学要苹果、洋葱，好半天，他才回复，几段文字，我看了过后，就说，收到，谢谢王老师的细心讲述[强]，不多久，他说，细心的意思，我还知道，但讲述的意思是什么啊？你说一下呀。\u003cbr>\u003cbr>1、我说，好的 ，收到，谢谢王老师的细心讲述[强]\u003cbr>\u003cbr>他说，细心，我晓得，讲述是啥子？\u003cbr>\u003cbr>2、我说，讲述就是讲解事情的情况。\u003cbr>\u003cbr>他说，我讲的是，我给的苹果和洋葱哟。\u003cbr>\u003cbr>3、我说，不是说苹果洋葱，我讲的是，给的苹果、洋葱，在客观表述事情，\u003cbr>\u003cbr>他说，是的，事后，收集苹果（写下晋级者表现好的部分）和洋葱（写下晋级者可改善部分）。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1692767616000,"updated_at":1692769330000,"ria":true},{"id":16289,"topic":"倾听回应4+3","learn_goal":"","remark":"倾听解释四步法和有效回应三步骤","level":"TF2-4","duration":50,"status":30,"type":0,"chaishujia":{"username":"开心1314","city":""},"club":{"name":"东京ひかり分舵","city":""},"prologue":"\u003cp>大家好，我是来自日本东京筹备分舵的赵丽。我的三个标签是：家庭主妇，菜农，两个反抗期娃的母亲。\u003cbr>【主题介绍】\u003cbr>今天要和大家分享的内容是倾听回应4+3：\u003cbr>“倾听解释四步法 ”和“有效回应三步骤 ”\u003cbr>【片段关系】\u003cu>技能点1：两个拆页的关系\u003c/u>\u003cbr>这两个片段是递进关系，听懂了对方的解释再加上有效的回应会让矛盾更快的得到解决，并能增进彼此的感情联络。\u003cbr>因为下面有小组讨论和分享环节，那我们先以两两一组的形式分一下组。\u003cbr>【学习目标】\u003cu>技能点2：学习目标，可观测可衡量\u003c/u>\u003cbr>在完成这次RIA现场学习后，当你再遇到与他人沟通中出现问题和矛盾时，能够应用倾听四步法来听取对方的解释。之后再运用回应三步骤来积极做出回应，来表明自己立场获得对方认可。\u003cbr>\u003c/p>\u003cp>【FAB 图书介绍】（1.5分钟）\u003cu>技能点3：图书介绍 — 特征，优势，好处\u003c/u>\u003cbr>F（Feature）\u003cbr>这本《说话的力量》作者是孙路弘，他是一名营销和销售专家。本书讲了如何训练你的说话技巧来提高沟通能力和工作能力。\u003cbr>A（Advantage）,\u003cbr>这本书使用浅显易懂的文字和我们生活中经常遇说话的到的状况作为实例来介绍说话的技巧的，相比其它同样内容的图书更容易上手。其中介绍了8个说话方法，4个说话技巧，2种实战工具。\u003cbr>B1（Benefit）\u003cbr>你在和孩子谈话时是不是常常遇到沟通不顺让你大发雷霆。你在和同事工作交流中解释说明不到位而产生工作分歧。你在面试时是不是不知道如何有逻辑的把自己的特长介绍给面试官而让你面试失败。如果你确实遇到过以上的问题不妨跟这本书学习一下说话的技巧，让你与其他人沟通时更高效更顺畅，工作也事半功倍。\u003cbr>B2 这是一本提高说话能力的书籍。好的说话技巧和方法能让你与他人之间更好的相处，尤其是工作中遇到矛盾和问题时，沟通的能力更是决定你能不能胜任此项工作的关键因素。\u003c/p>","ratings_count":2,"texts":[{"id":20389,"quote":"\u003cp>那我们首先来看第一个拆页吧\u003cbr>【拆页一的学习目标】\u003cbr>学习者能够运用倾听解释4步法进行沟通表达。\u003cbr>\u003cbr>[R阅读拆页一]（1.5分钟）\u003cbr>下面请大家花1分钟看一下我的拆页内容，拆页选自《说话的力量》电子版P186～189\u003cbr>[R]原文片段\u003cbr>解释有一个核心，就是听懂。听到不等于听懂，中国有句老话“锣鼓听声，听话听音”，你真的听懂了吗？\u003cbr>真正的听懂有四个层次：第一个是听懂对方，第二个是让对方知道我听懂了，第三个是争取让对方听懂我，第四个是确认对方听懂我了。这也就是解释的四个层次。\u003c/p>","explains":"\u003cp>我看到小伙伴已经都读完了，下面我们一起来解读这段文字。\u003cbr>what ：这段文字讲了如何使用倾听四步法来听懂对方解释，并讲自己意见反馈给对方的一种方法。出现问题我们会解释原因，如何高效听懂对方的解释是进行下一步交流的关键步骤。\u003cbr>why：\u003cu>技能点4：强调不这么做的坏处\u003c/u>\u003cbr>【一般的做法】一般我们遇到矛盾时容易以自己的 观点来评判对方的对错，上来就质疑对方的解释，不给对方解释的机会或充足的解释时间，这样会错失一场正面沟通的机会。\u003cbr>【不这么做的坏处】我分了三种情况：一， 最糟糕的压根不听解释，直接发脾气来质问。这样根本不能进行下一步沟通，甚至合作终止。二，对方说了一堆理由你根本听不出重点在哪里，问题焦点在哪里。三，因为认知水平不同根本听不懂对方说了什么。\u003cbr>【后果】让事态没有向好的方向发展下去，甚至可能矛盾一直会升级。\u003cbr>【反例】半年前的一天，到了放学时间弟弟还没有回家，我问了好几个朋友都说没看到他，天慢慢黑了，也越来越冷了，我心里开始着急了，害怕他遇到坏人出了什么事。等弟弟回到家我就批头盖脸的骂了一顿：“为什么这么晚回家，为什么不给家里打个电话，是不是又跑到同学家玩儿游戏了”。弟弟想说些什么，看我这样大声骂他他也很生气就摔门进屋了，这样我们有三天没说话。\u003cbr>how细化行动步骤： 那如何准确理解对方的解释呢，具体步骤如下 \u003cbr>\u003cu>技能点5：细化步骤，在原文基础上加工出流程步骤\u003c/u>\u003cbr>第一步：听懂对方\u003cbr>给对方解释机会，看对方是不是带着情绪在说话。他是事实求是还是在找借口开脱。我们可以先开口问：“你说的属实吗？“，”你说的是这个意思吗？”\u003cbr>第二步：有所反馈。\u003cbr>跟对方产生共情，即使不完全接受对方的观点也没必要生气，可以点头来示意在听他的解释，或者可以跟他说：我理解你当时的处境，我也同意你的一些观点...... \u003cbr>第三步：说明观点。\u003cbr>跟孩子讲话不要用难懂的人生大哲理跟他讲通。对一个业务内容门外汉的人不要用专业术语来说服他。所以要以双方都理解的内容作为谈话的基础来表达自己的观点。\u003cbr>第四步：最终确认。\u003cbr>询问对方是否同意自己的意见。可以问：“你能听懂我的说明吗？你觉得我的想法如何，或者你有更好的想法和建议吗”。\u003cbr>【反例加工成正例】学了倾听四步法之后，我改变了我的态度，我想先听他解释。前几天弟弟又回来的很晚，同样的事情发生会有完全不同的效果。\u003cbr>我说：“弟弟，天这么晚了，你没有回家妈妈很担心，你能跟妈妈说说发生什么事情了吗”。\u003cbr>弟弟说：我没有去危险的地方，只是和同学打篮球不巧手机也没电了。(听懂对方)\u003cbr>我耐心倾听他的解释说：我很担心你，怕被坏人拐走或者出了车祸。以后手机没电可以借用同学的手机，一定要通知到家人。(有反馈和建议)\u003cbr>弟弟：好的，那下次妈妈也不能动不动就跟我发脾气了。(再次确认)\u003cbr>【where】\u003cbr> 不论在教育子女和家人沟通或和同事之间有矛盾时，在听取对方解释的时候都可以采用这四个步骤来沟通。\u003c/p>","interaction":"\u003cp>【A1显像提问】（3分钟） \u003cu>技能点6：显像提问，回忆自己经历过的相关情景\u003c/u>\u003cbr>回忆一下过去一周或一个月，你有没有遇到过这样的情况。\u003cbr>比如说你的孩子写作业拖拖拉拉，磨蹭到很晚也没有完成作业，你很生气和孩子发生了争吵。\u003cbr>比如去购物，服务员爱理不理服务态度差，导致发生争执？\u003cbr>等等…\u003cbr>类似的事件你还遇到过哪些，你是怎么做的呢，请各位回忆一下你这方面的经历或经验。\u003cbr>下面给大家时间1分钟时间，想想当时发生的事情你是怎么做的呢。\u003cbr>【学习者分享的案例】\u003c/p>\u003cp>下面请Fuji 分享一下她的经历：\u003c/p>\u003cp>我的孩子是一名初中二年级的孩子，写作业也是写到很晚，每次看到都很生气而且屡教不改。\u003cbr>【回应】\u003cbr>谢谢Fuji 的分享内容。\u003cbr>【A1+反思加工】（3分钟）\u003cbr>\u003cu>技能点7：反思加工，遇到同样情况如何做\u003c/u>\u003cbr>既然我们学习了倾听对方解释的四个步骤，那我们就学以致用，假如时间能倒流，再给你一次机会遇到这种情况你是怎么运用今天所学的解释四步法来处理当时的问题。\u003cbr>给大家1分钟思考时间，接下来请一位小伙伴分享一下。\u003cbr>【学习者分享的案例】\u003c/p>\u003cp>还请Fuji 来给我们分享她学了倾听四步法之后会怎么做呢\u003c/p>\u003cp>分享内容：想先听孩子解释一下为什么这么晚睡，是初二的作业比较多还有和同学的交流也多了，拖延了时间。我会给孩子建议，因为初二的作业难了也多了，要管理好自己的时间，不然会影响身体健康和长个子，最后确认一下儿子能不能解释早睡和早起的建议。\u003cbr>【回应和反馈】\u003cu>技能点8：反馈号召\u003c/u>\u003c/p>\u003cp>谢谢Fuji 的精彩分享，我们给一些掌声鼓励。Fuji 使用今天所学的方法首先听对方的解释，然后对对方的意见进行反馈并说明自己的观点，最终和儿子达成协议，解决以后不会拖拉作业的问题。\u003cbr>\u003cu>到此时间（大约15分钟）\u003c/u>\u003cbr>【关门过度】(1分钟)\u003cbr>\u003cstrong>拆页一我们学习了，在和对方有矛盾或分歧时如何倾听对方的解释。从听懂对方，有所反馈，说明观点，最终确认这四步法来倾听对方，缓解矛盾提高沟通能力。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":20390,"quote":"\u003cp>【拆页二学习目标】学习者需要沟通时，能够运用抓住事实，锁定看法，调整内容这三步来回应对方。\u003cbr>【R阅读拆页二】（3分钟)\u003cbr>选自图书《说话的力量》电子版P215-217，现在给大家3分钟时间看完这个拆页。\u003cbr>解释是单向的，重在向对方澄清事实；而回应的要求比解释高，回应等于陈述加解释，听懂对方的陈述，然后给予解释，你的解释是在对方陈述的基础之上进行的。辩论是训练说话，尤其是回应的好方法，因为在辩论中，我们充分练习了回应的3个步骤：听懂对方的陈述、锁定看法和事实、随时调整讲话内容。\u003cbr>比如我们来看2003年国际大学群英辩论赛上的一段经典辩词。当时的辩题是“爱和被爱哪个更幸福”，正方为中山大学的同学，论点是爱比被爱更幸福；反方是新加坡国立大学的同学，论点是被爱比爱更幸福。以下是盘问环节的一个片段。\u003cbr>正方：今天父母都会很疼爱孩子，可能很多孩子却在很悠闲地看电视，请问哪个比较幸福呢？\u003cbr>（正方抛出一个问题，反方要回应了。）\u003cbr>反方：我认为在这个时候，父母是更幸福的，而孩子如果也想像父母那样幸福的话，就真的应该帮我们的爸爸妈妈捶捶肩、洗洗碗。\u003cbr>正方：好，对方辩友告诉我们洗碗是更幸福的，那你是不是跟你妈妈说，妈你洗碗真幸福，你怎么让我一个人痛苦地在这儿看电视呢？是不是这样子呢？\u003cbr>（抓住对方看法“洗碗更幸福”，调整自己的讲话内容，顺着对方逻辑推出荒谬结论。）\u003cbr>反方：问题是我们的妈妈洗碗的幸福是源自他们对我们的爱，如果我们真的爱他们的话，我们也应该去洗碗，难道对方辩友您不是这样想的吗？\u003cbr>（对于对方的陈述无力反驳，转移了话题）\u003c/p>","explains":"\u003cp>【what】这段文字说的是关于解释的回应，对于对方的解释，如何去回应也是提高沟通能力的一种方法。回应基于解释但要求又高于解释，它是陈述和解释的综合。它包括听懂对方的陈述、锁定看法和事实、随时调整讲话内容。\u003cbr>【Why】（不这么做的坏处）\u003cbr>当我们对于对方的解释不能准确合理的回应时，对方会误认为我们没有听或不赞同他的解释和观点，这样会造成误会或让原有的矛盾升级，而且我们自己的主张也不能及时反馈给对方，这时候积极合理的回应对方会让矛盾缓和或者问题得到解决。\u003cbr>【How行动步骤】那么如何正确回应呢\u003cbr>第一步 听懂对方的陈述\u003cbr>不仅要听事实听看法，还要听里面的层次以及弄清说话人背后的立场。\u003cbr>第二步 锁定看法和事实\u003cbr>甄别他的看法是否符合逻辑，组织自己的话语材料与事实进行对比，。比如：我认为你说的不完全符合逻辑有点片面...。\u003cbr>第三步 调整说话内容\u003cbr>可以运用比喻、举例 、讲述等技巧确保对方尽可能多正确的立即你的全部意思。比如：像上次就是.....来办这件事的，而且取得了很好的效果，我们也可以再试一次。\u003cbr>【意议案例】\u003cbr>\u003cu>技能点9：按原文案例脉络和逻辑讲一个贴近学习者生活或工作的例子\u003c/u>\u003cbr>原文案例是个辩论赛，离我们生活较远，下面分享我家里和孩子的事情：\u003cbr>周一，弟弟早上起晚了，急匆匆扒几口早饭就要出门去上学，我见了即可进行规劝，下面是妈妈和儿子的对话片段\u003cbr>我说：怎么吃这么少，早饭吃不好上课会注意力不集中喔\u003cbr>弟弟说：你非让我吃完再走，难道想让我上学迟到吗。(对方抛出问题，听陈述内容)\u003cbr>我说：是你起床太晚了，今天的早餐和平时的量一样啊。(锁定看法和事实)\u003cbr>弟弟说：那你不能让我睡眠不足吧，这样上课能注意力不集中吗。\u003cbr>我说：是你昨天玩游戏睡得太晚了，看来睡觉比吃饭重要多了，以后早饭都可以不吃了。\u003cbr>(顺着对方逻辑推出荒谬结论)\u003cbr>弟弟说：我可不这样认为。\u003cbr>我说：那你今晚就早点睡吧，和以前一样的作息就不会睡眠不足了，明早妈妈给你做爱吃的三明治。\u003cbr>（对于对方的陈述无力，转移了话题）\u003cbr>【Where】\u003cbr>这种回应更适用于一些有争议的想法，或者和对方保有不同观点时候采用。不适用于那些非争议性的话题。\u003cbr>【异议预防】\u003cu>技能点10：设想异议并讲解\u003c/u>\u003cbr>有的小伙伴会说和那些胡搅蛮缠的歪理面有什么好争辩的，但是基于同一个事实立场不同肯定会想法也不同，如果可以互换立场按照他的立场去思考或许能够理解，但是也要坚持自己的观点传达给对方。\u003cbr>\u003cstrong>学习者拆为己用\u003c/strong>\u003c/p>","interaction":"\u003cp>【A3促动参与】12分钟\u003cbr>我们学习了回应三步骤。下面请大家做一个练习。假设有这样一个场景。\u003cbr>【场景设计】\u003cu>技能点11：交代清楚背景 当事人遇到的问题\u003c/u>\u003cbr>背景：一天小王由于加班很晚忘记去幼儿园接孩子这件事了，等他回到家老婆就开始大吵起来，说他只顾工作不管家和孩子。小王对于老婆的大吵大闹，是如何通过回应三步骤来解决这个争论的呢。\u003cbr>【角色扮演练习】\u003cu>技能点12：角色扮演\u003c/u>\u003cbr>下面以小组为单位讨论：写出小王和老婆的沟通场景。下面以富姬和skyfly一组，时和和香京一组。\u003cbr>提示：尽可能详细写出包括双方语言、肢体、表情和声音的内容，确保有画面感。\u003cbr>【学习者角色扮演】\u003c/p>\u003cp>首先让时和和香京来分享一下，时和扮演小王，香京扮演老婆\u003c/p>\u003cp>香京：你为什么没去接娃。\u003c/p>\u003cp>时和：我今天是太忙了实在是抽不出时间了。\u003c/p>\u003cp>香京：难道工作比孩子重要吗，你是怎么想的啊，你还要不要这个家了。\u003c/p>\u003cp>时和：不工作的话我们怎么办啊，去喝西北风吗，我们不能生活了啊。\u003c/p>\u003cp>香京：我可不这么认为，你就两个不能兼顾吗？\u003c/p>\u003cp>时和：当然，我以后一定会注意的。老婆要不今天就这样算了吧，别生气一起去散个步平复平复心情。\u003c/p>\u003cp>\u003cbr>【反馈】技能点13：简要重复了扮演的过程， 并且号召大家鼓掌\u003cbr>谢谢两位有意思的分享，给他们一些掌声。本来的一场争吵，通过回应三步骤变成恩爱夫妻了\u003cbr>\u003c/p>\u003cp>第二组分享：fuji扮演老婆，skyfly扮演小王\u003c/p>\u003cp>fuji:你今天怎么没有去接孩子\u003c/p>\u003cp>skyfly:诶呀，我忙忘了，今天工作比较多开了一天的会，就没有注意时间。\u003c/p>\u003cp>fuji:那你意思是说工作比我和孩子还重要吧\u003c/p>\u003cp>skyfly:那我不去工作，你们吃什么，我们怎么生活呀，那我明天开始就不去工作了，我天天准时去接孩子。\u003c/p>\u003cp>fuji:我不是这个意思，我的意思是希望你能工作和家庭能兼顾一下，我也能轻松些。\u003c/p>\u003cp>skyfly:那我俩以后互相协调一下，调整一下时间，我也多注意以后多陪陪你和孩子，不生气了我们接上孩子去吃麦当劳好不好。\u003c/p>\u003cp>fuji:嗯，好吧。\u003cbr>【学员的问题与拆书家回应】\u003cu>技能点14：回应，追认确认\u003c/u>\u003cbr>谢谢两位的分享。刚才的四位小伙伴把老婆和小王这两个角色表演的活灵活现的，把回应三步骤：听对方陈述，锁定看法和事实然后调整说话内容应用出来，把本来是矛盾的问题被和谐得解决了。\u003cbr>【A2催化应用】（9分钟）\u003cu>技能点15：分两步，想象一个具体的画面和学习者规划未来如何运用\u003c/u>\u003cbr>【分步催化一】\u003cbr>下面大家想一想，在未来一周或一个月内你有没有可能遇到去如何回应别人的问题呢。\u003cbr>比如，孩子看到他的好朋友有一个很贵的手机他很喜欢，他也想买个一模一样的，但是你认为没必要买这么贵的，于是你和孩子发生了争执。\u003cbr>或者孩子只想玩儿游戏就是不去写作业。\u003cbr>设想一下你遇到这种事情或类似这样的事情你是怎么和孩子沟通的呢，思考一分钟我们请小伙伴来分享。\u003cbr>【学习者分享案例】\u003c/p>\u003cp>请香京来分享一下：我女儿打算在下周买个最新款的苹果手机，但是我觉得一个手机能用就行吧，没必要买最新款的，那么贵万一丢了怎么办，不可避免的会有一场矛盾争执。\u003cbr>【分步催化二】\u003cbr>今天我们学习了回应三步法之后，你怎么运用这种方法来解决刚才的事件呢。\u003cbr>请将你的行动计划写在便签上。写好后在小组内分享。\u003cbr>【学习者案例分享】\u003c/p>\u003cp>请香京来分享：\u003c/p>\u003cp>女儿想要一个最新款手机，她说过她的好朋友新买了一个，她也想要一个一样的。（听陈述）\u003c/p>\u003cp>照她这么说，她朋友有的她都想有，她朋友能考全班第一，她是不是也一样考个第一呢。（锁定看法）\u003c/p>\u003cp>跟女儿商量能不能考虑买一个老款的手机，功能也不差，而且价格便宜很多。（调整内容）\u003cbr>【回应与反馈】\u003c/p>\u003cp>谢谢香京打算用今天学到的回应三步骤去化解和孩子可能发生的矛盾。\u003cbr>\u003cu>拆页二预计用时33分钟\u003c/u>\u003cbr>【关门过渡】0.5分种\u003cbr>通过拆页二的学习和演练，我带领大家了解并体验了回应三步法，听懂陈述，锁定看法，调整内容。相信大家经过演练之后对这种方法也有所领悟。\u003cbr>【结束语】0.5分钟\u003cbr>\u003cu>技能点16：强有力结语，强调了要点\u003c/u>\u003cbr>通过今天的拆页学习，我们在解决矛盾和问题时候不要再感情用事，仅靠主观去判断，要冷静下来用倾听四步法来理解对方和采用回应三步骤来回应对方，让矛盾缓和，工作效率提高，增进同事或家人之间的感情。最后谢谢大家今天精彩的分享。\u003cbr>\u003cu>总时长估计用50分钟\u003c/u>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1690120606000,"updated_at":1690923256000,"ria":true},{"id":16115,"topic":"说话的力量-讨论与汇报","learn_goal":"","remark":"说话的力量","level":"TF3-3","duration":70,"status":30,"type":0,"chaishujia":{"username":"长大的石榴","city":"南京市"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>\u003cstrong>如何在讨论中提问并做一场合格的汇报\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【开场】开始录音\u003c/strong>\u003c/p>\u003cp>\u003cstrong>自我介绍：\u003c/strong>\u003c/p>\u003cp>各位伙伴们大家好。我叫沈洁。我用三个标签介绍一下我自己：\u003c/p>\u003cp>第一个标签：一个二十年助力贸易顺差的外贸人，从事出口业务已遍布世界156个国家。第二个标签：企业认证内训师，课程包括商务礼仪、企业文化、行动学习和复盘等等。\u003c/p>\u003cp>第三个标签：一个十岁且个性十足小女生的妈妈。\u003c/p>\u003cp>很荣幸有这样一个机会，今天以拆书家的身份，和在场的伙伴一起，进行我们此次《说话的力量》RIA拆书的活动。\u003c/p>\u003cp>\u003cstrong>分组：\u003c/strong>\u003c/p>\u003cp>今天是我定级TF3-3，我们分下组，请后面这两位小伙伴和前面两位合并为一组。希望伙伴们都积极参加到互动环节中来。我刚刚已经将两个原书拆页发给大家了，人手一份。\u003c/p>\u003cp>\u003cstrong>第一个RIA “讨论”\u003c/strong>\u003cstrong>（用时\u003c/strong>\u003cstrong>22分钟\u003c/strong>）\u003c/p>\u003cp>一、\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：学习目标中包含学习者要完成行动的具体内容和完成程度，现场学习设计清晰体现了该学习目标。\u003c/strong>\u003c/p>\u003cp>希望通过第一个RIA的拆解学习，能帮助各位伙伴，在“讨论”时，针对一个主题结论，不再用观点互相争辩驳斥，而采用提问的方式，问出事实依据，通过客观事实来论证结论是否正确。从而让双方达成共识，提升“讨论”的效率。\u003c/p>\u003cp>\u003cstrong>二、图书介绍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：选择图书是实用类图书。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：在学习者场景介绍法中，能够清晰辨别出事件提问影响解决4个步骤。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：两个拆页是有逻辑关系的，呈递进关系。\u003c/strong>\u003c/p>\u003cp>图书介绍《说话的力量》，作者孙路弘。\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>开会时，我们很多人聚在一起就一个主题进行讨论着。本想着思想碰撞后，能提出一定的建议。结果还没开始汇报，观点不同的两方就一个问题开始争吵，没完没了。其他人还得痛苦陪会，两小时的会被拖成整整一下午。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>回顾一下你最近参加的会议，是否都是按时间完成讨论和汇报的？是否都达到了预期的效果？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>会议讨论中双方主观臆断，无事实依据支撑的“驳斥”，导致讨论无效。那么你或你方的建议则就根本没办法再汇报了。可想而知，领导会对你/你们的工作成效和工作能力会产生什么样的看法。\u003c/p>\u003cp>\u003cstrong>解决\u003c/strong>：如果你想具备“讨论”和“汇报”这两项职场必备技能，提高开会的效率，那么你一定要读这本书--《说话的力量》。这是一本系统学习说话的实战指南。除了“讨论”和“汇报”，还有“陈述、叙述、表达、解决”等8大说话方法、4大说话技巧和2大说话工具，都是作者孙路弘首创，都是倾其25年的营销、销售经验的精华之作。\u003c/p>","ratings_count":2,"texts":[{"id":20203,"quote":"\u003cp>三、\u003cstrong>【R】阅读原书拆页一\u003c/strong>\u003c/p>\u003cp>下面我们先来阅读第一个片段，给大家两分钟的时间。《说话的力量》\u003c/p>\u003cp>\u003cstrong>技能点：每个拆页未超过2页图书内页，至少有一个拆页不包括HOW的内容。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>片段1    \u003c/strong> \u003cstrong>“讨论  ”              《说话的力量》\u003c/strong>\u003c/p>\u003cp> 这就是讨论，如果你提不出问题来，就无法参与任何有效的讨论。常见的\u003cstrong>发问句式可以是：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>What： 有关这个话题，都包括什么方面的内容呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>When： 什么时候才发现你看到的征兆呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Where：在哪里可以验证你得到的结论呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Who:   谁会受到这个问题的影响呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Why:   你刚才说是阳光灿烂，怎么就突然电闪雷鸣了呢？\u003c/strong>\u003c/p>\u003cp>比如我说“北京的麦当劳不如上海的麦当劳”。你听到我这样说以后，应该问我：“这句话是看法还是事实？”这其实是一种看法，不是事实。那么，你还可以问什么？你可以问我怎么得出这个结论的。当你提问后，讨论就形成了。\u003c/p>\u003cp>“有一天我去了北京的一家麦当劳，旁边一张桌子并没有人坐，但桌子上放着吃剩的东西，而这种情况在上海几乎很少见。”你听完我这句话，有要质疑的吗？还是已经接受了我的看法——北京的麦当劳不如上海的麦当劳？因为我给你提供了一个事实。\u003c/p>\u003cp>其实你还能接着提问：“你在北京看到这个情况，是在一家店、两家店，还是很多家？”甚至问：“北京一共有多少家麦当劳店？上海呢？你在多少家店观察到这种现象？”\u003c/p>\u003cp>如果这几个问题我都回答不出来，那么我的结论是不是站不住脚的？也就是说，讨论真正厉害之处不在于驳斥，而在于让结论不攻自破。如果两个人互相都不同意对方的结论，那就是吵架。日常生活中的骂街吵架是什么？就是只谈看法，我的看法是这样的，你的看法是那样的，两个人激烈冲突。双方都不提供细节，都没有理性追问对方所依据的逻辑。\u003c/p>\u003cp>相反，如果我们能更好地提问，讨论就会更有效率，双方的信息传播就会更容易，因为经过讨论之后，双方都对一个信息、一个事实有共同的理解。\u003c/p>","explains":"\u003cp>\u003cstrong>四、【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：有体现出【I】环节的互动，且拆书家能精准掌控。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：在未包含HOW拆页的【I】环节，涵盖了三级讲解引导的技巧：1）给出清晰的HOW，2）通过对比概念和匹配例子引出知识点逻辑、步骤和边界等。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【互动提问】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>当别人跟你说“北京的麦当劳不如上海的麦当劳”，你听到后如何确认TA说的是不是真的？再比如，当别人在会议上跟你说“你的这份计划书不满足客户的需求”，你听到后如何回复？\u003c/p>\u003cp>\u003cstrong>学习者C姐：\u003c/strong>我会问“你怎么得出这个结论的？”\u003c/p>\u003cp>\u003cstrong>拆书家回应：\u003c/strong>非常好。是的，我要提问“你是怎么得出这个结论的？”我们还可以像书中所说的那样提问：“你说的是事实还是看法？”\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>讨论是一种多人对话的形式。而讨论的核心要点，就在于提问！通过不断地提问得到事实依据，让结论不攻自破。 \u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>片段中，是如何得出结论“北京的麦当劳确实不如上海的麦当劳”的？\u003c/p>\u003cp>\u003cstrong>学习者YLIU：\u003c/strong>“在北京的麦当劳，看见桌子空着，但是桌上留着很多剩下的食物，这种情况在上海几乎见不到。”这是提问“你怎么得出这个结论的？”后，给出的事实依据。\u003c/p>\u003cp>\u003cstrong>拆书家回应：\u003c/strong>是的，非常好。要通过提供事实依据来论证“北京的麦当劳确实不如上海的麦当劳”这个结论。因为，我们在“讨论”中是需要事实依据来支撑观点的；而事实依据的得出，则是通过不断地提问获得。所以，没有好的提问，就得不到事实依据和细节；没有事实依据支撑的信息观点，就无法影响听众。学会在“讨论”中发问，就能获得更多的事实和细节，论证结论、支持观点。双方/多方产生共同的理解，从而让会议更加高效。\u003c/p>\u003cp>\u003cstrong>【概念对比】讨论中驳斥\u003c/strong> \u003cstrong>VS    讨论中提问 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>讨论中驳斥: \u003c/strong>双方互相不同意对方的结论，都不提供事实和细节，只针对结论争辩驳斥。\u003c/p>\u003cp>\u003cstrong>讨论中提问: \u003c/strong>一方提出结论，另一方紧紧围绕结论向做出结论者发问（5W提问，比如：为什么会这样，具体是哪些，与什么人相关，什么时候发生，常见在哪里等等），从提问得到事实，而推断结论是否站得住脚。\u003c/p>\u003cp>\u003cstrong>【举例对比】讨论中驳斥\u003c/strong> \u003cstrong>VS    讨论中提问\u003c/strong>\u003c/p>\u003cp>\u003cstrong>讨论中驳斥，如: \u003c/strong>\u003c/p>\u003cp>A:“北京的麦当劳不如上海的麦当劳”\u003c/p>\u003cp>B: “我不这么认为”\u003c/p>\u003cp>A:“很多人都这么认为”\u003c/p>\u003cp>B: “你的看法很偏激”\u003c/p>\u003cp>\u003cstrong>讨论中提问，如: \u003c/strong>\u003c/p>\u003cp>A:“北京的麦当劳不如上海的麦当劳”\u003c/p>\u003cp>B: “你是怎么得出这个结论的？\u003c/p>\u003cp>A:“在北京的麦当劳，看见桌子空着，但是桌上留着很多剩下的食物，这种情况在上海几乎见不到。”\u003c/p>\u003cp>B: “你在北京看到的这个情况，是一家店？两家店？还是很多家店？”\u003c/p>\u003cp>A:“我公司有两个办事处，分别在朝阳区和北淀区，楼下都有麦当劳，在那儿我都见过这样的情况，甚至连人气最旺的北京火车站的麦当劳，都有这样的情况。”\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>从对比中看到，在“讨论中提问”得到了事实依据，论证了“北京的麦当劳确实不如上海的麦当劳”这个结论。\u003c/p>\u003cp>这就是为什么要在\u003cstrong>讨论中用提问\u003c/strong>的方式。\u003c/p>\u003cp>\u003cstrong>【清晰的步骤HOW】“5W提问”\u003c/strong>\u003c/p>\u003cp>那么如何紧紧围绕主题结论，高质量发问呢？\u003c/p>\u003cp>称它为5W提问！书中给到我们发问的5个句式：\u003c/p>\u003cp>\u003cstrong>1、what发问：有关这个话题，都包括什么方面的内容？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、when发问: 什么时候才发现你看到的征兆呢？\u003c/strong> \u003c/p>\u003cp>\u003cstrong>3、where发问: 在哪里可以验证你得到的结论呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>4、who发问：谁会受到这个问题的影响呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>5、why发问:  你刚才说是阳光灿烂，怎么就突然电闪雷鸣了呢？\u003c/strong>\u003c/p>\u003cp>5W围绕“是什么，什么时候，在哪里，都有谁，到底为什么？”这五个方面提问。为了帮助大家更好地理解和应用这5W提问，下面我以《杜拉拉升职记》中，一个开会场景的经典片段来具体演示讲解，如何运用5W提问来引出结论的客观事实。\u003c/p>\u003cp>\u003cstrong>【案例】《杜拉拉升职记》\u003c/strong>\u003c/p>\u003cp>苏浅唱：“每逢月初，李坤经理都会先和我讲好，当月我能拿到多少费用，我们会讨论好投资计划，我也都是严格按照计划和指示来做的，可是到了月底报销的时候，他总是很细地一笔一笔查问我的费用，即使是非常非常小的数字——这令我感到很不舒服，觉得他就像防贼一样防着我。”\u003c/p>\u003cp>杜拉拉：“你提到的“非常小的数字”，可不可以给个概念，多小？”\u003c/p>\u003cp>\u003cstrong>（\u003c/strong> \u003cstrong>1、what：有关这个话题，都包括什么方面的内容？）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“WHAT”发问：将结论具体且显性地描述出来。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>提问内容：可以朝着量化、数字化、图像化、图表化的方向提问，得到客观的事实数据。\u003c/strong>\u003c/p>\u003cp>苏浅唱：“比如两百多元的餐费。”\u003c/p>\u003cp>\u003cstrong>通过杜拉拉的“WHAT”提问，明确了话题中“非常小的数字”，“非常小”到底是多少。\u003c/strong>\u003c/p>\u003cp>杜拉拉：“关于费用，哪位还有补充？”\u003c/p>\u003cp>\u003cstrong>（\u003c/strong> \u003cstrong>4、who：谁会受到这个问题的影响呢？）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“WHO”发问：针对事件中的相关人员发问。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>提问内容：可以围绕事件中，谁是受益者？谁是受害者？谁主导？谁负责？谁同意？谁不同意？等等。\u003c/strong>\u003c/p>\u003cp>卢秋白：“希望经理在管理中适当授权，每个月希望我做多少指标咱们说清楚，给多少钱办多少事。月初定好费用和指标后，经理就不必管得太细致了。不然我们工作太难了!”\u003c/p>\u003cp>\u003cstrong>通过杜拉拉的“WHO”提问，确定了两个信息：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、受到报销和小额费用困扰的销售团队中，除了苏浅唱还有卢秋白；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、障碍方是经理。\u003c/strong>\u003c/p>\u003cp>杜拉拉：“为什么太难了，难在哪些地方？能具体说一说，什么时候希望经理授权？\u003c/p>\u003cp>\u003cstrong>（\u003c/strong> \u003cstrong>5、why:  你刚才说是阳光灿烂，怎么就突然电闪雷鸣了呢？）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“WHY”发问：问出原因，从表面原因到根本原因，弄清楚到底是什么造成的。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>提问内容：可参考著名的5WHY理论，一直提问为什么，直到找到冰山下的原因。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（\u003c/strong> \u003cstrong>3、where: 在哪里可以验证你得到的结论呢？）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“WHERE”发问：验证结论。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>提问内容：围绕在哪些情况下，具体场景，多一些细节，提问时可以让对方举例说明。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（\u003c/strong> \u003cstrong>2、when: 什么时候才发现你看到的征兆呢？）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“WHEN”发问：验证结论。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>提问内容：围绕“具体在什么时候”OR “哪些时候”，也可以让对方多举例说明。\u003c/strong>\u003c/p>\u003cp>卢秋白：”现在我们花一点小钱都要先打电话请示经理。有时候经理太忙，半天不方便接电话，我又不好意思对客户说，您等一等，等经理批准了，我再请你去吃饭——说实在的，人家肯让我们请客，是给面子了。现在的客户不好伺候，动作慢一点，人家会觉得我们不识趣，说变脸就变脸。这种时候，经理能给一个额度内的授权就不会有这个问题。”\u003c/p>\u003cp>\u003cstrong>杜拉拉的“WHY”、“WHERE”和“WHEN”的提问，确定了销售代表们的难处，在于无论大小，每笔金额都要报批。导致销售代表要请客吃饭时，需要临时现场请示，但又会得不到经理回复的尴尬情况，还可能因此流失掉客户。销售员希望经理能给适当授权。\u003c/strong>\u003c/p>\u003cp>杜拉拉：“对于一些突发性的小费用，按费用的性质、类别，定个额度，销售代表在额度内可以自主，这样能解决你们的问题吗？\u003c/p>\u003cp>苏浅唱：“我们同意，但是经理不同意，他觉得费用累积太多会失控？”\u003c/p>\u003cp>杜拉拉：“在哪些方面觉得会失控?保证费用不超过计划的总额呢？”\u003c/p>\u003cp>\u003cstrong>这里杜拉拉再次用到了WHERE和WHAT来提问。\u003c/strong>\u003c/p>\u003cp>苏浅唱：“主要是担心我们钱是都花完了，但是指标没有按进度完成。”\u003c/p>\u003cp>杜拉拉：“那这样，除了事先规定好单笔费用的额度外，根据指标达成的进程，以周为单位，限定当月小笔费用的比例，你们觉得这个建议妥当不妥当？”\u003c/p>\u003cp>苏浅唱：“这个办法可以，我没问题。”\u003c/p>\u003cp>卢秋白：”我也可以，每两周核对一次指标进度，以此为据，控制小额费用的累积。”\u003c/p>\u003cp>\u003cstrong>这次“报销费用”的主题会议上，能将问题解决，正是因为杜拉拉在讨论中，做出了用5W提出的有效提问。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>⑴日常会议是一种讨论，⑵头脑风暴是一种讨论，⑶与客户/上司/同事等面谈也是一种讨论，⑷与下属个别谈工作安排也是一种讨论。只要是我们希望通过分享信息，影响别人产生我方期待的行为的场景，都可以应用“讨论”的方式。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>学会5W提问，不是教大家会在讨论中提问就好了。一定要明确角色和目的，看你/你方是提问方还是回答方？\u003c/p>\u003cp>⑴如果你是提问的一方，一定要围绕主题相关的结论，提出好的问题，切记不要跑偏，这样才可以得到想要的事实细节，来论证结论，看对方抛出的结论是否站得住脚；\u003c/p>\u003cp>⑵如果你是给出结论的另一方，就需要对内容准备足够充足，时刻准备回答对方的提问。\u003c/p>","interaction":"\u003cp>\u003cstrong>五、【A2】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：使用【A2】技能点环节指令清晰，涵盖了三级催化应用的技巧：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1）学习者根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事。2）学习者可以根据指令，写出自己未来的一个具体的要做的应用（比如某个特定任务、和人分享、事后复盘，或找人陪练。）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：对学习者的分享和提问，有体现通过向学习者提问来进行回应式反馈。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【教学习者编辑剧本的A2】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>刚刚和大家一同学习了在“讨论”中采用提问的方式，问出事实依据，通过客观事实来论证结论是否正确，以及如何在讨论中提问的5W句式。接下来，要请在场的小伙伴编个剧本、小故事，几百字即可。设计出任务、情节变化（起因、经过、结果）和双方的对话、动作等，其中\u003cstrong>对话用到讨论中提问的5W句式\u003c/strong>。比如：刚坐下开会讨论方案，对方就直接说“你的这份计划书不太满足客户的需求”；再比如，你们人资部和行政部开会讨论竞聘行政主管，行政部的结论是“A不如B工作好”，给大家三分钟时间，大家思考下，将要点写在纸上，三分钟后，请小伙伴来分享。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>哪位小伙伴来分享下自己的剧本？\u003c/p>\u003cp>\u003cstrong>学习者案例分享（小伙伴YLIU）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>背景：\u003c/strong>要交付上一年度的审计报告\u003c/p>\u003cp>\u003cstrong>时间：\u003c/strong>12月底\u003c/p>\u003cp>\u003cstrong>地点：\u003c/strong>会议室\u003c/p>\u003cp>\u003cstrong>人物：\u003c/strong>领导和我\u003c/p>\u003cp>\u003cstrong>起因：\u003c/strong>领导点评我的报告内容太简单，可我明明交了10页纸，实在搞不懂领导为什么这么说，于是在会议室和领导进就“报告太简单”进行讨论。\u003c/p>\u003cp>\u003cstrong>经过：\u003c/strong>\u003c/p>\u003cp>领导：“你这个审计报告也太简单了！”\u003c/p>\u003cp>我：“领导，您是指什么方面太简单了？是缺少什么方面的内容吗？”\u003c/p>\u003cp>领导：“据上级要求的格式，报告缺少不足之处的分析以及下一步整改计划！”\u003c/p>\u003cp>我：“不足之处分析是按什么时间段？是按全年分析还是按季度分析？”\u003c/p>\u003cp>领导：“都不是，按上半年和下半年来分析。”\u003c/p>\u003cp>我：“好的，领导。最迟什么时候需要提交新的报告？是否有过往可以学习的资料吗？”\u003c/p>\u003cp>领导：“下周一吧，我把去年的合格审计报告发给你参考。”\u003c/p>\u003cp>我：“好的，谢谢领导！”\u003c/p>\u003cp>\u003cstrong>结果：\u003c/strong> 得到了领导的正面反馈和参考资料，最终提交了合格的审计报告。\u003c/p>\u003cp>\u003cstrong>拆书家反馈：\u003c/strong>在剧本中，小伙伴YLIU运用了讨论中提问的方式，知道了：⑴领导为什么会给出“自己的报告太简单”这个评价；⑵自己的报告还需要修改哪些部分；⑶最迟什么时候再次提交。通过讨论中提问，最终解决了她的问题。感谢YLIU的分享。\u003c/p>\u003cp>\u003cstrong>【过渡】\u003c/strong>\u003c/p>\u003cp>刚刚我们一同RIA拆解了“讨论”，学会了“讨论”中不再用争辩、驳斥，而是采用提问的方式，得到客观事实和细节。A2应用中，伙伴们也运用了5W句式的提问，得到事实依据，解决实际问题。在“讨论”完之后，我们再一同来拆解第二个RIA“汇报”。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":20204,"quote":"\u003cp>\u003cstrong>第二个RIA “汇报”（用时\u003c/strong>\u003cstrong>40分钟\u003c/strong>）\u003c/p>\u003cp>一、\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：学习目标中包含学习者要完成行动的具体内容和完成程度，现场学习设计清晰体现了该学习目标。\u003c/strong>\u003c/p>\u003cp>希望通过第二个RIA学习后，能帮助在座的各位伙伴，在“汇报”时，针对一个主题，不仅要有事实，有观点，还要能提出合理的预测和有说服力的建议，影响受众，获得认可。GET“汇报”这项职场必备技能，成为既会说、又会干的真把式。\u003c/p>\u003cp>\u003cstrong>【解说两拆页之间关系】\u003c/strong>\u003c/p>\u003cp>第一个RIA 是“讨论”。讨论是指至少两人或多人参与的对话。会议中，我们通过“讨论”来分享信息，信息里有对客观事实的提炼、看法观点的提炼。我们希望通过分享这些信息，影响别人产生我方期待的行为。\u003c/p>\u003cp>第二个RIA 是“汇报”。会议中，汇报，指汇集材料，针对明确的主题。汇报\u003cstrong>不仅要有\u003c/strong>“讨论”中的说事实，讲观点，\u003cstrong>还要有\u003c/strong>基于事实和观点，提出的建议和预测。通过“汇报”中有说服力的观点、合理的预测和恰当的建议，让听众受到影响和触动，认可“汇报”的内容。会议中，我们一般先“讨论”，再“汇报”。\u003cstrong>两个RIA呈递进关系。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1】请大家自测\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：使用【A1】技能点环节的量表题清晰设置多个选项，学习者通过自测可以了解在某种情况下自己的表现。\u003c/strong>\u003c/p>\u003cp>首先，我们通过量表自测题了解下“汇报”在大家身边的表现，根据自己的情况打分。\u003c/p>\u003cp>1分不符合，5分非常符合，给大家1分钟时间，填好后，统计下分数。\u003c/p>\u003cp>\u003cstrong>【I】解释自测题\u003c/strong>\u003c/p>\u003cp>这些自测题，主要是了解大家对“汇报”方式的理解程度如何：\u003c/p>\u003cp>≥20分，说明在日常工作沟通中，能轻松运用“汇报”的方式。\u003c/p>\u003cp>19≤x≤10分，说明在沟通中，运用“汇报”说话方式的能力一般，还可以做得更好。\u003c/p>\u003cp>＜10分，说明你对如何在沟通中运用“汇报”的说法方式，还不清晰。你要打起精神，好好听今天的分享啦！\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>大家得分多少？\u003c/p>\u003cp>\u003cstrong>学习者C姐: \u003c/strong>19分\u003c/p>\u003cp>\u003cstrong>学习者L哥: \u003c/strong> 14分\u003c/p>\u003cp>\u003cstrong>学习者YLIU：\u003c/strong> 17分\u003c/p>\u003cp>\u003cstrong>拆书家回应：\u003c/strong>好的，从现场自测的情况来看，大家对“汇报”的方式，还有提升的空间，没关系，接下来我们来系统学习下“汇报”的表达方式。\u003c/p>\u003cp>\u003cstrong>二、【R】阅读原书拆页\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：每个拆页未超过2页图书内页，至少有一个拆页不包括HOW的内容。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>片段2              “汇报  ”              《说话的力量》\u003c/strong>\u003c/p>\u003cp>具备思想基础的说话形式就是汇报。汇报是以一方为主，另一方为辅的交流形式。为主的一方向另一方系统性地叙述一件事情的来龙去脉，并完整地表达自己因此形成的观点，以及在观点的基础上提出相应的建议。\u003c/p>\u003cp>仅仅提供信息、事件、前因后果等客观事实不是汇报，而是叙述。仅仅添加主观看法和观点也不是汇报，而是表达。汇报要求在表达的基础上形成观点之后，提供相应的建议和预测。\u003c/p>\u003cp>汇报，是指汇集材料向上级或群众报告，表达一个明确的主题，提出一定的建议，达到预期的效果，要让听的人受到影响和触动。\u003c/p>\u003cp>从这个定义中，我们可以看出，汇报并不仅局限在下级对上级。员工需要向领导做“工作汇报”，党员需要向组织做“思想汇报”，官员需要向群众做“政府工作汇报”。\u003c/p>\u003cp>为什么干了同样的事，别人总能说得天花乱坠。\u003c/p>\u003cp>在职场中，有的人会感叹，为什么干了同样的事，自己没话说，别人却能说得天花乱坠，自己干了十分，只能说出五分，别人只干了八分，却能说出十五分呢？那是因为你没有掌握说话的技巧，没有掌握汇报的技巧。光说不干假把式，光干不说傻把式，既会说又会干才是真把式。毫不夸张地说，及时汇报和在合适的时机汇报，是职场必备的技能之一。\u003c/p>\u003cp>在现实生活中，你可能经常遇到这样的情况，领导对下属说，“你给我汇报一下情况”，但是下属汇报完了以后领导又总是不满意，这是为什么呢？是因为汇报不完整、不合格，缺少了必备的元素。不完整的汇报，可能是只有观点、缺乏足够的事实；也可能是只有观点没有事实。最常见的不完整的汇报是缺乏建议。汇报不同于讲述、叙述和表达，最与众不同的地方就是要有相应的建议。所以，真正合格的汇报必须具备的元素是：有事实、有观点，且要有基于事实和观点的建议。\u003c/p>","explains":"\u003cp>\u003cstrong>三、【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：有体现出【I】环节的互动，且拆书家能精准掌控。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：在未包含HOW拆页的【I】环节，涵盖了三级讲解引导的技巧：1）给出清晰的HOW，2）通过对比概念和匹配例子引出知识点逻辑、步骤和边界等。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【互动提问】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>片段中，提到“合格的汇报”要具备哪些元素?\u003c/p>\u003cp>\u003cstrong>学习者C姐：\u003c/strong>要有事实、有观点、且有基于事实和观点的建议和预测。\u003c/p>\u003cp>\u003cstrong>拆书家回应：\u003c/strong>很好，谢谢C姐。看得非常仔细。\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>汇报，一般指汇集材料，针对明确的主题，不仅要有“讨论”中的讲事实，讲观点，而且在形成观点之后，还要提出相应的建议和预测，达到预定效果，让听众受到影响和触动。 \u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>从片段中看到，做了同样的事，有人能说得天花乱坠，自己没有掌握汇报的技巧，不会讲，因此在职场上吃了大亏。这也是为什么要学会“汇报”。我们要干得好，也要说得好。\u003c/p>\u003cp>\u003cstrong>【互动提问】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>我们再来回顾一下，前面“北京的麦当劳不如上海的麦当劳”的案例里，哪些是观点？哪些是事实？哪些是建议、预测？它是不是一个“汇报”呢？\u003c/p>\u003cp>\u003cstrong>学习者L哥：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>观点：\u003c/strong>“北京的麦当劳不如上海的麦当劳”；\u003c/p>\u003cp>\u003cstrong>事实：\u003c/strong>“在北京的麦当劳，看见桌子空着，但是桌上留着很多剩下的食物，这种情况在上海几乎见不到。”举例在人流量较大的朝阳区和北淀区的写字楼下的麦当劳，都见过这样的情况，甚至连人气最旺的北京火车站的麦当劳，都有这样的情况。”\u003c/p>\u003cp>\u003cstrong>建议和预测：\u003c/strong>案例中没有，因此它不是一个汇报。\u003c/p>\u003cp>\u003cstrong>拆书家回应：\u003c/strong>非常好。麦当劳的案例中，有观点，有论证观点的实施，但并没有基于观点和事实的预测和建议。因此它并不是一个汇报。\u003c/p>\u003cp>\u003cstrong>【易混淆概念对比】工作总结&amp;工作汇报\u003c/strong>\u003c/p>\u003cp>当我们把工作的过程和结果整理好，都汇报给了领导，领导却不满意。这是为什么？就是因为你的汇报，实际上是”工作总结“，并不是”工作汇报“。这里我对“工作总结”和“工作汇报”做一个区分：\u003c/p>\u003cp>\u003cstrong>工作总结：\u003c/strong>是一个阶段或者完成后的总结，目的一般是为了研究，肯定成绩、找出问题、总结经验教训，提高认识。简单说，工作总结重回顾，重分析。\u003c/p>\u003cp>\u003cstrong>工作汇报：\u003c/strong>针对特定的对象，对一定时期内的工作进展进行归纳和报告，目的是为了请示。简单说，工作汇报重目的，重建议。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>汇报的目的：⑴可能是为了进行一次决策，⑵也可能是为了进行一次评估；\u003c/p>\u003cp>汇报的对象：①可以不仅限于上级，②也可以是平级和下级。\u003c/p>\u003cp>实际工作中，对上级的汇报形式偏多。简单来说，无论是否在职场中，只要想让听众受到影响和触动，都可以采用“汇报”的方式。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>或许你会问，“汇报”时我可不可以先给建议再说事实和观点？\u003c/p>\u003cp>⑴首先，当然可以。但是任何信息在传达时，都可能遇到不同的反应。观点可能被认同，但更大的可能性是会被质疑。对方“质疑的态度”先入为主，比较难以继续沟通。\u003c/p>\u003cp>⑵以书中“汇报”的方法更好，有充分的事实引出观点，再给出合理的预测和建议，逻辑性更强，更容易被受众接受。\u003c/p>\u003cp>\u003cstrong>【例子】：\u003c/strong>\u003c/p>\u003cp>有个朋友向我吐槽她的领导脾气不好，还摸不透。说她每次汇报销售计划，领导都不满意。报多报少，都不高兴，每次让她再好好想想。我很好奇问她，你是怎么汇报的？\u003c/p>\u003cp>她说：“我汇报了上个季度团队的经营指标和完成情况。现在的大环境这么难，我的观点就是维稳不要激进，就按照去年的标准报了500万。领导瞄了我一眼，但没说话，我估摸她觉得我报少了，狠一狠心，我说争取到600万。没想到她还不满意，说让我再想想。真搞不懂，她到底要我报多少？”\u003c/p>\u003cp>我问她：“你每次报计划，是不是只有一个数字，并没有汇报数字的构成？有没有结合市场行情的预判，和上一季度销售和库存情况？你对于销售计划的完成，有没有汇报建议的措施和分工方案？\u003c/p>\u003cp>她摇摇头：“难怪领导总让我再想想，她一定觉得我是拍脑袋决定的。”\u003c/p>\u003cp>按照“汇报”的逻辑，经过调整，下一次她是这样汇报的：\u003c/p>\u003cp>”二季度我们已完成销售指标600万，超预期计划20%，超全年需时进度40%（事实1）。\u003c/p>\u003cp>团队全体销售人员30人，已有22人在手的预订单均已满（事实2）。\u003c/p>\u003cp>保守估计三季度可完成销售指标800万（观点1）。\u003c/p>\u003cp>考虑到四季度价格可能低走，市场降温，订单会减少（预测）。\u003c/p>\u003cp>我们目前在仓库还有3000吨的库存（事实3）。\u003c/p>\u003cp>建议要扣除仓库库存折旧的亏损100万（建议1）。\u003c/p>\u003cp>综上所述，三季度我们团队报销售计划700万。（观点2）”\u003c/p>\u003cp>\u003cstrong>【与学习目标相关的HOW】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、观点：是否清晰？确定观点是对方想听/关注的内容。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>对应案例：观点清晰，确定观点是领导想听的内容。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、事实：尽量准确、量化；给出的事实有效支撑你的观点；1个观点一般要给到2个事实来佐证。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>对应案例：事实准确、量化，给出的事实有效支撑了观点；1个观点也给到2个事实来佐证。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3、预测和建议：一定要基于事实和观点之上，有说服力，得到受众认可；讲与主题相关有价值/收益的，吸引和影响受众。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>对应案例：预测和建议基于事实和观点之上，有说服力；讲与销售指标完成这个主题相关有价值/收益的内容，比如：现有订单情况、市场价格走势、库存折旧情况等，吸引和影响受众，等到了领导认可。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【互动提问】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>伙伴们，如何完成一个合格的汇报，已经清晰明了了。大家结合过往的经验想一想，未来你在工作中，运用这样的汇报方法，会遇到什么问题吗？\u003c/p>\u003cp>\u003cstrong>学习者L哥：\u003c/strong>汇报时提的建议经常被否定。\u003c/p>\u003cp>\u003cstrong>学习者YLIU\u003c/strong>：领导说我的建议站不住脚，我的建议都听不进去。\u003c/p>\u003cp>\u003cstrong>学习者C姐：\u003c/strong>我自己就是销售岗位，每次开会都准备的很充分，包括产品分析、市场分析，团队人员分析，但有时候给的建议，领导就是不接纳、不满意，搞不懂领导想要啥。\u003c/p>","interaction":"\u003cp>\u003cstrong>四、【A3】促动参与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：在未包含HOW拆页的【A3】环节指令清晰，学习者在拆书家主持的微行动学习环节，讨论出了这类问题的解决方案。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：对学习者的分享和提问，有体现通过向学习者提问来进行回应式反馈。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>微行动学习5步骤：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、【明确问题】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[拆书家提问式反馈与回应]：\u003c/strong>刚刚大家都觉得“向领导提建议”比较难，对“如何提出让领导接受的建议”很关心，是吗？\u003c/p>\u003cp>\u003cstrong>学习者们：\u003c/strong>是的。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>既然大家都认为这个问题很重要，又有普遍性，那接下来我们将围绕着这个问题“如何提出让领导接受的建议”进行讨论，我们将通过微行动学习，来分析和解决这个问题。\u003c/p>\u003cp>\u003cstrong>2、【引导讨论问题本质】\u003c/strong>\u003c/p>\u003cp>接下来，请大家在小组内探讨这个问题的本质是什么？问题的本质，是指这个问题存在的关键原因，找到了问题的本质，意味着找到解决问题的钥匙。大家可以结合自己的经验，对这个问题进行追问。给大家4分钟的时间。\u003c/p>\u003cp>[小组4分钟讨论]\u003c/p>\u003cp>\u003cstrong>\u003cem>学习者讨论实录：\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者L哥：\u003c/strong>我觉得“提建议难”的根本原因是因为领导的经验和权威性，很难被一两句建议说服。\u003c/p>\u003cp>\u003cstrong>学习者YLIU\u003c/strong>：我觉得建议能否被领导接受，并不在于话多话少，而是领导觉得建议是否有效。\u003c/p>\u003cp>\u003cstrong>学习者C姐：\u003c/strong>我同意这个观点，建议的科学性和有效性，才是关键。\u003c/p>\u003cp>\u003cstrong>学习者L哥：\u003c/strong>什么是科学和有效的建议？我觉得不要太多高谈阔论，而是紧密结合现有工作和目标，说领导重点关心的、想听的。\u003c/p>\u003cp>\u003cstrong>学习者YLIU：\u003c/strong>还有足够的数据支持，比如SWOT分析、现有组织人员分析等，提供理性分数据分析，给出破局策略或新增长点的建议，才能打动领导。\u003c/p>\u003cp>\u003cstrong>学习者C姐：\u003c/strong>是的是的，和我的想法一样，提建议的时候，要重点讲领导关心的当下的工作目标与任务 ，还要包含现状，客观事实存在的问题和情况，并且提供的数据分析能够支撑建议成立，老板才能足够信服。\u003c/p>\u003cp>\u003cstrong>3、【明确问题本质】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[拆书家提问式反馈与回应]：\u003c/strong>大家对于如何提出让领导接受的建议”这个问题，找到的本质是什么呢？\u003c/p>\u003cp>\u003cstrong>学习者C姐：\u003c/strong>建议的内容要紧密结合当下工作目标，并提供足够的事实和详细数据分析，这样的建议，科学且有预见性，有足够的说服力，才能被领导接受。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，我们的问题可以转化为：\u003cstrong>向上级提出有说服力的建议，该建议包含哪些要素？\u003c/strong>我们确定一下，大家找到的问题本质是：\u003cstrong>具有说服力的建议至少包含：1、建议要围绕当下工作目标与任务  2、建议要包含客观事实，数据分析能够支撑建议成立。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>4、【引导讨论解决方案】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[拆书家提问式反馈与回应]：\u003c/strong>好，针对这个问题本质，请大家在小组内讨论该问题本质的解决方案，大家觉得要给到什么样的方案才觉得可以？\u003c/p>\u003cp>\u003cstrong>学习者C姐：\u003c/strong>⑴建议的内容要应该一个标准。⑵建议不仅要考虑过往标准，还要参考外部单位的标准。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>其他小伙伴，有其他思路嘛？\u003c/p>\u003cp>\u003cstrong>学习者L哥：\u003c/strong>⑴我觉得首先，一定要搞懂老大到底在想什么。⑵再一个，一定要加强沟通，各方面都聊一聊，公司发展规划、经济形势，什么都聊一聊，看他有什么想法，希望我做到哪一步，我才好给建议。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>这位伙伴，你还有补充的吗？\u003c/p>\u003cp>\u003cstrong>学习者YLIU：\u003c/strong>我认同C姐的观点，给建议要有标准。这个标准，我认为是找准自己的定位，对自己具体情况有详细分析，领导才觉得我的建议是深思熟虑，且有大量的数据支持的，才有可能是科学有效的。\u003c/p>\u003cp>\u003cstrong>学习者C姐：\u003c/strong>是的，我再补充一下，我们一定要找到相应资源。给建议的时候，要提供资源信息给领导，让领导信任，我提出的建议，我能匹配相应的资源。\u003c/p>\u003cp>\u003cstrong>拆书家回应：\u003c/strong>好的，刚才几位小伙伴根据自己的情况，分享了自己的流程步骤，接下来，大家再讨论下，把刚才提出的一些想法进行整合，最终提出一个大家都认同的解决方案。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，接下来大家讨论解决方案的步骤，组内讨论，将要点写在白纸上，给大家4分钟时间，然后我们请伙伴上来进行分享\u003c/p>\u003cp>[小组4分钟讨论]\u003c/p>\u003cp>\u003cstrong>\u003cem>学习者讨论实录：\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者L哥：\u003c/strong>我来做记录。\u003c/p>\u003cp>刚刚说的一定要和领导加强沟通，搞懂老大的想法。一定要了解TA对于建议内容的要求、标准。按TA要求的标准来建议。\u003c/p>\u003cp>\u003cstrong>学习者YLIU\u003c/strong>：这点我非常赞同。另外就是一定要紧密结合自己的工作目标和当下工作情况。\u003c/p>\u003cp>建议的内容要符合“三圈原理”：我能做什么，我能找到什么资源，以及我能寻求到什么资源。自我定位要清晰。\u003c/p>\u003cp>\u003cstrong>学习者C姐：\u003c/strong>是的，是的。还有建议前的分析数据，刚刚YLIU提到的SWOT分析、现有组织人员分析等，越客观、详细越好，比如对比数据、环比数据。建议的内容的科学性也要符合SMART原则。\u003c/p>\u003cp>\u003cstrong>5、【代表讲解成果】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，哪位小伙伴来分享下解决方案？\u003c/p>\u003cp>\u003cstrong>学习者C姐：\u003c/strong>我代表我们组来讲一下我们最终讨论出来的解决方案是：\u003c/p>\u003cp>\u003cstrong>向领导提出有说服力的建议，应该：\u003c/strong>\u003c/p>\u003cp>1、掌握领导的要求。加强和领导的沟通，确定TA对\u003cstrong>建议内容的标准\u003c/strong>是什么样的。\u003c/p>\u003cp>2、结合自己的工作目标，\u003cstrong>找准定位\u003c/strong>。建议的内容不能脱离实际，向领导说明我能找到的资源，和我实际需要领导协助的资源等。\u003c/p>\u003cp>3、提供详细分析数据，越客观越好、越详细越好。可以比对同期、同比、同行等。参考科学设立目标的SMART原则。\u003c/p>\u003cp>\u003cstrong>拆书家反馈：\u003c/strong>感谢伙伴们的探讨，通过不断挖掘问题背后的根本原因，最终找到了解决的方案，非常精彩。\u003c/p>\u003cp> 我们微行动的学习就讨论到这儿。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：使用【A2】技能点环节指令清晰，涵盖了三级催化应用的技巧：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1）学习者根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事。2）学习者可以根据指令，写出自己未来的一个具体的要做的应用（比如某个特定任务、和人分享、事后复盘，或找人陪练。）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：对学习者的分享和提问，有体现通过向学习者提问来进行回应式反馈。\u003c/strong>\u003c/p>\u003cp>学完“汇报”的方式后，我们现在要来运用，给大家布置个任务。这两天就找机会在会议中运用“汇报的方法”向领导汇报工作：\u003c/p>\u003cp>1、观点：是否清晰？确定观点是对方想听或关注的内容。\u003c/p>\u003cp>2、事实：尽量准确、量化；给出的事实有效支撑你的观点；1个观点一般要给到2个事实来佐证。\u003c/p>\u003cp>3、预测和建议：\u003c/p>\u003cp>1）一定要基于事实和观点之上，有说服力，得到受众认可；\u003c/p>\u003cp>2）讲与主题相关有价值/收益的，吸引和影响受众。\u003c/p>\u003cp> 并事后复盘运用后的情况。\u003c/p>\u003cp>\u003cstrong>【事后复盘反馈】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者CHANG：\u003c/strong>我向领导汇报上半年迪拜公司业绩运营情况良好，但业务们反馈工作比较忙碌出差，当地缴水费、电费、上网费都需要去银行排队，稍微晚两天就会掐断。缺少一名行政人员运营办公室杂务。\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>希望领导同意聘用一名当地秘书。\u003c/p>\u003cp>\u003cstrong>结果：\u003c/strong>领导同意\u003c/p>\u003cp>\u003cstrong>反思：\u003c/strong>亮点和不足之处\u003c/p>\u003cp>\u003cstrong>①亮点：\u003c/strong>按照汇报的三个方法来汇报，得到了领导的认可。\u003c/p>\u003cp>1、观点：是否清晰？确定观点是对方想听或关注的内容。\u003c/p>\u003cp>观点清晰，迪拜公司上半年运营良好，但目前缺人。（老板关注效益和公司的正常运营）\u003c/p>\u003cp>2、事实：尽量准确、量化；给出的事实有效支撑你的观点；1个观点一般要给到2个事实来佐证。\u003c/p>\u003cp>事实1）：迪拜公司的业务们上半年持续出差，非常忙碌，没有空去缴费。\u003c/p>\u003cp>事实2）：迪拜各种缴费，需要人工到银行办理，耗时。且稍微迟交两天会被断水断电断网。\u003c/p>\u003cp>3、预测和建议：一定要基于事实和观点之上，有说服力，得到受众认可；讲与主题相关有价值/收益的，吸引和影响受众。\u003c/p>\u003cp>预测：如果各种缴费继续由现在的业务代办，一定会影响他们的主职的绩效；如果拖延不办缴费，会导致办公室断水断电影响正常办公运营。\u003c/p>\u003cp>建议：聘用一名当地秘书，专门运营办公室杂务。\u003c/p>\u003cp>\u003cstrong>②不足之处\u003c/strong>\u003c/p>\u003cp>1、汇报时，可以提供业务的盈利数据，来证明利润可以覆盖聘用人员的成本。\u003c/p>\u003cp>2、应多准备与有关当地聘用人员的法律法规和招聘渠道。\u003c/p>\u003cp>\u003cstrong>下一步行动：\u003c/strong>在今后的汇报中，反复练习使用“汇报的方法”。\u003c/p>\u003cp>\u003cstrong>结语\u003c/strong>（简短有力的结语）\u003c/p>\u003cp>我们学习了说话的两种表达方式：讨论与汇报。讨论要有观点有事实，汇报还要基于事实和观点，给出预测和建议。要让知识成为技能，是需要不断的刻意练习的，所以希望在座的各位小伙伴，在今后工作生活中的沟通，刻意的运用我们今天学习的两个表达方式，从而不断提高你的说话能力。希望能够帮到大家。谢谢各位的陪伴。\u003c/p>\u003cp> \u003cstrong>结束录音：22+40，总时长62分钟\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1687844987000,"updated_at":1690628608000,"ria":true},{"id":16032,"topic":"说话的力量","learn_goal":"","remark":"无","level":"","duration":30,"status":19,"type":0,"chaishujia":{"username":"王礼界","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>为了方便随后的讨论， 我们进行分组，左边伙伴为1组，右边伙伴为2组。\u003cbr>\u003cbr>大家好！ 我是王礼界， 欢迎大家参加本次拆书活动， 我的三个标签是， 销售员、 新手拆书家、 学习者。\u003cbr>\u003cbr>在跟我完成本次 RIA 现场学习后， 学习者在沟通中， 在不确定对方是否理解，我们表达的概念的意思的时候，学习者能够运用 （ 行为） 让对方听懂我的3个步骤（澄清），来进行沟通， 让对方听懂我， 消除对方误解（界定）\u003cbr>\u003cbr>图书介绍（场景介绍法）\u003cbr>\u003cbr>[ 事件场景 ]我相信大家应该有工作的经历吧！在工作中， 几乎每天， 我们都在进行沟通， 可有时候，会出现，对方不理解的情况， 比如， 几年前的一天， 我接到一个同事的电话，他问我，有个门店要的超时赠品， 是给他，还是不给他？我就说给他要这么说， 不给他要那么说。 他听了过后说， 你就说给，还是不给吗， 我就说， 可以给他， 也可以不给他（但要避免下次又问超时赠品的问题），给他要这么说， 不给他要那么说， 回答了三次， 他还是说不明白，过后，我说我这是讲第 4 次了， 他才听懂。\u003cbr>\u003cbr>[ 提问 ] 在过去的生活，或者工作中， 大家有没有遇到过类似的场景，在沟通中， 对方很难理解我们表达的意思的情况， 当时，你是怎么做的呢？结果又怎样呢？\u003cbr>\u003cbr>[ 影响 ] 如果很难让领导听懂我， 那领导的心里肯定会对我们有看法， 如果很难让客户听懂我， 那就很难得到客户的支持， 结果不仅会影响到我们工作的开展， 还会影响到自己职业的发展。\u003cbr>\u003cbr>[ 解决 ] 那如何让对方听懂我呢？ 《说话的力量》这本书中， 就为我们提供了解决问题的思路，那就是，在解释过后，还需要确认对方是否听懂了。\u003cbr>\u003cbr>请大家自测\u003cbr>\u003cbr> 在开始片段拆解前，请大家做下量表自测题，来了解自己在沟通中，争取让对方听懂我的能力。请仔细阅读表上的每一句话， 根据自己的实际情况，来勾选对应的数字，不用去纠结分数， 按照自己的实际情况做出选择， 就可以了。 现在， 请大家用一分钟的时间来完成这个测试。\u003cbr>\u003cbr>自测说明： 请仔细阅读表格中的每句话， 根据自己的实际情况打分。 在这份自测题中 （ “1” 代表完全符合实际情况， “6” 代表完全不符合实际情况； ） 测试完后， 相加勾选的数字， 得出总分。\u003cbr>\u003cbr>1、我总是认为对方能够理解我表达的概念的意思。1 2 3 4 5 6\u003cbr>\u003cbr>2、解释概念的时候，我不知道要讲哪些要点。1 2 3 4 5 6\u003cbr>\u003cbr>3、解释概念的时候，我总是感觉到比较困难。1 2 3 4 5 6\u003cbr>\u003cbr>4、解释概念后，我总是认为对方听懂了我讲的概念的意思。1 2 3 4 5 6\u003cbr>\u003cbr>5、多次解释概念的时候，我会显得不耐烦。1 2 3 4 5 6\u003cbr>\u003cbr>合计分数： \u003cbr>\u003cbr>解释自测题\u003cbr>\u003cbr> 好的，大家完成了这个测试，这个测试一共有5道题目，总分是30分，下面，我们就来看看大家的得分。\u003cbr>\u003cbr>1、总分在20分以上的伙伴，说明在沟通中，你让对方听懂我的能力很强。\u003cbr>\u003cbr>2、总分在10 - 20分之间的伙伴，说明在沟通中，我们让对方听懂我的能力，还有提升空间，通过今天的片段拆解，可以提升让对方听懂我的能力，来消除对方的误解。\u003cbr>\u003cbr>3、总分在10分以下的伙伴。\u003cbr>\u003cbr>我们就更应该要注意，如何让对方听懂我，这个问题。\u003cbr>\u003cbr>当然，这只是一个测试，我们不用去纠结分数的多少，因为，我们今天要拆解的这个片段，就是让对方听懂我的一个案例。下面，我们就来拆解这个片段，请大家用1分钟的时间来阅读拆页，阅读完后，请举手示意我。 \u003c/p>","ratings_count":3,"texts":[{"id":20110,"quote":"\u003cp>《说话的力量》作者： 孙路弘\u003cbr>\u003cbr>下面我们来看一段电影《心灵捕手》中，\u003cbr>\u003cbr>心理学教授西恩向充满困惑的男主人公威尔的发问。 这部电影描写的是一个天赋极高但因童年阴影而止步不前的男孩的故事， 片中充满了睿智的对话。\u003cbr>\u003cbr>西恩： 你有心灵伴侣吗？\u003cbr>\u003cbr>威尔： 我有 …… ？ 说清楚点。\u003cbr>\u003cbr>西恩： 能够和你匹敌的人。\u003cbr>\u003cbr>威尔： 我有查克。\u003cbr>\u003cbr>西恩： 不是， 查克是你的家人， 我讲的是触动你心灵的人 ……\u003cbr>\u003cbr>威尔： 我有 ……\u003cbr>\u003cbr>西恩： 谁？\u003cbr>\u003cbr>威尔： 有很多。\u003cbr>\u003cbr>西恩： 说出来 ……\u003cbr>\u003cbr>威尔： 莎士比亚、 尼采、 福斯特、 奥康纳、 康德、 洛克 ……\u003cbr>\u003cbr>[ 插图 ] 图 7—1\u003cbr>\u003cbr>电影《心灵捕手》截图\u003cbr>\u003cbr>西恩： 很棒， 但他们都死了。\u003cbr>\u003cbr>威尔： 对我而言， 他们没死。\u003cbr>\u003cbr>西恩： 他们当然死了，\u003cbr>\u003cbr>威尔， 你无法和他们对谈， 你无法回应他们。\u003cbr>\u003cbr>威尔： 对啊， 没有法术把他们弄醒超生， 是没办法和他们对谈的。\u003cbr>\u003cbr>西恩： 对， 那就是我所说的。 你只看到这个世界中负面的事， 如果你不踏出这第一步， 就永远不会拥有那种关系。\u003c/p>","explains":"\u003cp>好的， 大家阅读了拆页，大部分伙伴都举手了。\u003cbr>\u003cbr>what ： 片段中有一段对话，说的是，心理学教授西恩，争取让威尔听懂他讲的概念，心灵伴侣的意思。\u003cbr>\u003cbr>下面我们就来看，西恩是如何“让对方听懂我&quot;的。\u003cbr>\u003cbr>理解片段：我们先来看片段中的第1段对话，西恩说，你有心灵伴侣吗？威尔回答，我有，说清楚点，这里，咸尔是不是没有听懂，心灵伴侣的意思？\u003cbr>\u003cbr>伙伴：是的。\u003cbr>\u003cbr>是的，没有听懂，心灵伴侣的意思。\u003cbr>\u003cbr>过后，西恩进行了解释，能够和你匹敌的人，威尔回答，我有查克。西恩又说，不是，查克是你的家人，我讲的是触动你心灵的人，这里，我们来看，他们双方，是不是对心灵伴侣讲的是人，达成了共识？\u003cbr>\u003cbr>伙伴：是的。\u003cbr>\u003cbr>是的，对心灵伴侣讲的是人，达成了共识，同时，西恩又进行了解释，我讲的是触动你心灵的人。\u003cbr>\u003cbr>随后，威尔回答，我有，有很多，在这个时候，西恩问咸尔，谁，并要对方，说出来，\u003cbr>\u003cbr>在威尔说了一连串的人物名称过后，西恩说，很棒，这里，我们来看，他们双方，是不是对心灵伴侣讲的是，触动你心灵的人的理解，达成了共识？\u003cbr>\u003cbr>伙伴：是的。\u003cbr>\u003cbr>是的，对心灵伴侣讲的是，触动你心灵的人的理解，达成了共识。\u003cbr>\u003cbr>why ： 在日常沟通中， 当对方不理解我们表达的意思的时候， 我们就努力 的进行解释， 想让对方听懂我， 来理解我。 多次解释过后， 对方还不明白， 我们就可能会显得不耐烦， 心里面认为自己明明说清楚了， 可是对方还听不懂。 当然， 对方也有可能将没有听懂的原因指向你， 认为是你没有说清楚， 结果很可能就会有人认为， 这么简单的事情还弄不清楚， 是不是有意的， 这样的话， 双方就可能产生误会。\u003cbr>\u003cbr>如果用上让对方听懂我的办法， 先给出一个概念， 然后，进行解释， 直到双方对概念的理解达成共识，就能让对方听懂我表达的意思， 因为， 一步一步解释了对方不理解的部分。\u003cbr>\u003cbr>how ： 那如何让对方听懂我呢？根据刚才，我们对片段的理解来看，可以归纳出以下三个步骤：\u003cbr>\u003cbr>1 、 结出概念。给出一个概念， 比如， 案例中的 “ 心灵伴侣 ” 。\u003cbr>\u003cbr>2 、 解释概念。解释自己给出的这个概念，比如，案例中，西恩说，能够和你匹敌的人，还有，我讲的是触动你心灵的人。\u003cbr>\u003cbr>3 、 达成共识。对概念的理解达成共识。\u003cbr>\u003cbr>共识有2点，①对概念讲的事物类别达成共识，比如，案例中，双方对心灵伴侣讲的是人物，达成了共识，②对概念讲的事物区别于它事物的理解达成共识，比如，案例中，在威尔说了一连串的人物名称过后，双方对心灵伴侣讲的是触动你心灵的人的理解，就达成了共识，因为，共识从人物，具体到了，那个人。\u003cbr>\u003cbr>举例：下面，举个例子，来说明一下，以上三个步骤的具体应用。\u003cbr>\u003cbr>前几天，我和一个朋友讨论，他在网上直播卖书的事情，1我说，你有用户思维吗？他说，什么用户思维，说清楚点。2我说，就是要替用户着想，也就是要替顾客着想，他说，我是在替顾客着想啊①，我推荐的都是一些经典书，很有用的。我说，不是你认为有用的意思，我讲的是要站在用户的角度去思考问题。他说，是这样的呀，3我说，那样的？他说，要去思考，用户有什么想法，用户有什么需求啊②。\u003cbr>\u003cbr>在这个时候，我就认为，他听懂了我讲的用户思维的意思，因为，他讲了，要去思考用户有什么想法，用户有什么需求，这里，就从思考的事情，具体到了，思考那件事情。过后，我说，是的，我们就聊用户的事情了。\u003cbr>\u003cbr>那么，在解释概念的时候，让对方听懂我，我们就可以得出，概念讲的事情，就需要对方具体到那件事情，概念讲的人，或物，就要具体到什么？\u003cbr>\u003cbr>伙伴：那个人，那个物，\u003cbr>\u003cbr>是的，要具体到那个人，或那个物。\u003cbr>\u003cbr>在沟通中，我们给到对方一个概念的时候，有的时候说出来对方就懂了，我们就可以继续后面的谈话内容；有的时候，需要来回进行解释，比如拆页中西恩跟威尔说的概念心灵伴侣，就解释了两次。在日常生活或者工作中，有一些比较复杂的概念，有可能需要来回解释很多次，比如元认知。我们今天讲的三个步骤，是给到大家一种思路，先给出概念，然后，解释概念，最后，达成共识，对概念的理解达成共识过后，我们后面的沟通才会更有效。\u003cbr>\u003cbr>where ： 在日常沟通中， 我们都可以运用， 让对方听懂我的办法， 来进行沟通， 当对方不讲道理的时候， 就不太适用， 因为你的解释对方听不进去。\u003c/p>","interaction":"\u003cp>以上就是我对片段的拆解， 下面我们来进行现场演练，\u003cbr>\u003cbr>场景是这样的，新手拆书家小王， 在准备晋级选片段的时候， 将自己手中的图书翻了又翻， 看了又看， 还是没有找到一个让自己满意的片段， 于是， 小王打算，明天上班，午休的时侯， 在办公室，找同事老张，借实用类图书，\u003cbr>\u003cbr>（问题）现在，请大家思考一下，在明天上班，午休的时候，在办公室， 小王应该怎样运用，让对方听懂我的三个步骤，来进行沟通，让老张听懂小王说的实用类图书？\u003cbr>\u003cbr>（指令）1、下面，请在小组内，每两人一组，一人扮演小王，一人扮演老张，相互协助，先写下解决问题的，双方的对话台词，要求，①小王的对话台词内容，要用上，让对方听懂我的三个步骤，②对话的结果，至少要明确出，那一本实用类图书。\u003cbr>\u003cbr>2、再进行角色扮演，一人扮演小王， 一人扮演老张，按写下的对话台词，先预演一次，5 分钟后， 我们邀请 一组伙伴，按写下的对话台词，进行现场演练分亨。\u003cbr>\u003cbr>处理异议：如果有单独一人，那就请他观摩指导讨论。\u003cbr>\u003cbr>二位伙伴现场分享，\u003cbr>\u003cbr>林同学1扮演小王\u003cbr>\u003cbr>林同学2扮演老张\u003cbr>\u003cbr>小王：老张，你好，给你商量个事。\u003cbr>\u003cbr>老张：什么事，你说。\u003cbr>\u003cbr>小王：我借本实用类图书。\u003cbr>\u003cbr>老张：实用类，图书，说清楚点。\u003cbr>\u003cbr>小王：实用类图书，就是侧重解决实际问题，强调实战的书。\u003cbr>\u003cbr>老张：那些实际问题哦!\u003cbr>\u003cbr>小王：比如，解决沟通问题，还有举例子说明的，\u003cbr>\u003cbr>老张：这样的书，我有。\u003cbr>\u003cbr>小王：说出来，书名是什么？\u003cbr>\u003cbr>老张：《关键对话如何高效能沟通》\u003cbr>\u003cbr>小王：那我就借这本书。\u003cbr>\u003cbr>\u003cbr>\u003cbr>为了学以致用，下面，我们来安排一个作业：\u003cbr>\u003cbr>在接下来的两三周内，在沟通中，我们是否有，不确定对方是否理解我们表达的概念的意思的情况，如果有，请大家用让对方听懂我的办法来进行沟通，让对方听懂我，如果没有，那请大家将这个方法分享给身边的伙伴，然后，请将这个过程记录下来，整理成文字，或者图片私信发给我。\u003cbr>\u003cbr>以上就是我的 TF3-2 的晋级分享，让对方听懂我， 欢迎大家留言指导， 谢谢大家！\u003cbr>\u003cbr>王老师分享：\u003cbr>\u003cbr>背景：活动过后，我收集反馈，微信上，又找王同学要苹果、洋葱，好半天，他才回复，几段文字，我看了过后，就说，收到，谢谢王老师的细心讲述[强]，不多久，他说，细心的意思，我还知道，但讲述的意思是什么啊？你说一下呀。\u003cbr>\u003cbr>1、我说，好的 ，收到，谢谢王老师的细心讲述[强]\u003cbr>\u003cbr>他说，细心，我晓得，讲述是啥子？\u003cbr>\u003cbr>2、我说，讲述就是讲解事情的情况。\u003cbr>\u003cbr>他说，我讲的是，我给的苹果和洋葱哟。\u003cbr>\u003cbr>3、我说，不是说苹果洋葱，我讲的是，给的苹果、洋葱，在客观表述事情，\u003cbr>\u003cbr>他说，是的，事后，收集苹果（写下晋级者表现好的部分）和洋葱（写下晋级者可改善部分）。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1686632056000,"updated_at":1692769218000,"ria":true},{"id":15879,"topic":"解释","learn_goal":"","remark":"和别人遇到分歧或矛盾时，通过解释四步法来听取对方结实，化解矛盾解决问题。","level":"TF2-3","duration":21,"status":30,"type":0,"chaishujia":{"username":"开心1314","city":""},"club":{"name":"东京ひかり分舵","city":""},"prologue":"\u003cp>大家好，我是赵丽。我今天的分享是《说话的力量》这本书中的拆页。\u003cbr>【学习目标】\u003cbr>在随我完成本次RIA现场学习后，学习者能在和他人遇到问题或矛盾时，运用倾听解释的4个层级理解对方的解释，并从对方的合理解释中找到进行下一步沟通的对话内容。\u003cbr>【分组】\u003cbr>因为下面有小组讨论和分享环节，那我们先以两两一组的形式分一下组。\u003cbr>以下是我的分享内容：\u003cbr>【FAB 图书介绍】\u003cbr>F特征（Feature）\u003cbr>这本《说话的力量》作者是孙路弘，他是一名营销和销售专家。本书讲了如何训练你的说话技巧来提高沟通能力和工作能力。\u003cbr>A优势（Advantage）,\u003cbr>这本书使用浅显易懂的文字和我们生活中经常遇说话的到的状况作为实例来介绍说话的技巧的，相比其它同样内容的图书更容易上手。其中介绍了8个说话方法，4个说话技巧，2种实战工具。\u003cbr>B利益（Benefit）\u003cbr>你在和孩子谈话时是不是常常遇到沟通不顺让你大发雷霆。你在和同事工作交流中解释说明不到位而产生工作分歧。你在面试时是不是不知道如何有逻辑的把自己的特长介绍给面试官而让你面试失败。如果你确实遇到过以上的问题不妨跟这本书学习一下说话的技巧，让你与其他人沟通时更高效更顺畅，工作也事半功倍。\u003c/p>","ratings_count":1,"texts":[{"id":19961,"quote":"\u003cp>[R]原文片段\u003cbr>解释有一个核心，就是听懂。听到不等于听懂，中国有句老话“锣鼓听声，听话听音”，你真的听懂了吗？\u003cbr>真正的听懂有四个层次：第一个是听懂对方，第二个是让对方知道我听懂了，第三个是争取让对方听懂我，第四个是确认对方听懂我了。这也就是解释的四个层次。\u003c/p>","explains":"\u003cp>我看到小伙伴已经都读完了，下面我们一起来解读这段文字。\u003cbr>what ：这段文字讲了如何使用倾听四步法来听懂对方解释，并讲自己意见反馈给对方的一种方法。出现问题我们会解释原因，如何高效听懂对方的解释是进行下一步交流的关键步骤。\u003cbr>why：一件事情一旦需要解释就意味着一方对一些问题有不同的看法或不理解的地方，他的预期和现实是不一致的，跟对方互动有障碍。一份合理的解释可以减少许多麻烦和矛盾，相反听不懂对方解释甚至曲解了解释内容会让矛盾更激化，所以如何接受对方而又觉得他不是在推脱责任，一个清楚明了让他人听懂的解释就变得至关重要。\u003cbr>how： 那如何准确理解对方的解释呢，具体步骤如下\u003cbr>第一步：听懂对方的说话逻辑\u003cbr>判断对方所说内容是否为事实，有没有主观意志在干扰，以及他描述的细节，再听对方所下结论，分析事实和结论之间的关系。\u003cbr>第二步：要给予对方你的意见反馈。\u003cbr>跟对方产生共情，即使不完全接受对方的观点也没必要生气，可以跟他说：我觉得你说的不错，但我觉得...... 是不是会更好更合适呢 \u003cbr>第三步：以对方已知内容为基础阐明自己的观点。\u003cbr>跟孩子讲话不要用难懂的人生大哲理跟他讲通。对一个业务内容门外汉的人不要用专业术语来说服他。所以要以双方都理解的内容作为谈话的基础。\u003cbr>第四步：确认对方是否听懂。\u003cbr>询问对方是否同意自己的意见。可以问：你觉得我的想法如何，如果你有更好的意见我们也可以再考虑。\u003cbr>【举例子】\u003cbr>上个月的一天，天都黑了弟弟还没有放学回家，我发现他的钥匙还在桌子上。我问了好几个朋友都说没看到他，天慢慢黑了，也越来越冷了，心里开始着急了。害怕他出了什么事。过了一会儿弟弟回来了看到我有些害怕，正打算偷偷溜进屋。\u003cbr>我对弟弟说：\u003cbr>“弟弟，你回来怎么这么晚呢，放学怎么没回家啊，能跟我说说你去哪里和谁玩了吗，都玩儿了什么呢，你能跟我说说吗?\u003cbr>弟弟：”我本来是回家了可是我没带钥匙进不了屋，我就跑到马路对面明明家去玩儿了，在他家吃了水果 还写了作业，后来玩儿游戏忘记回家的时间了所以回来晚了。（他说出了事实，细节和结论）\u003cbr>妈妈：“原来是这样啊，我理解你没带钥匙进不了屋的心情，外面又那么冷，在外面玩儿也没有忘记先写完作业，你很棒。但是妈妈看你很晚没回家很担心怕你在外面遇到坏人.”（说出我的共情和担心）\u003cbr>妈妈:“钥匙我们扣在书包上的挂扣处，用完马上扣回去，就不会再把钥匙拉到家里了。以后即使再忘记拿钥匙的话呢，可以给妈妈留个条塞进门缝，写上去哪里和谁玩，打算几点回家，不会的汉字可以写拼音或者画图，这样妈妈就不会那么担心了.“（提一些他能力范围内能做到的建议）\u003cbr> ”那么，你认为妈妈的想法怎么样呢，你还有更好的办法吗？“（听反馈，给对方更多的考虑空间）\u003cbr>弟弟”我会借用邻居李伯伯的手机给妈妈打电话。“\u003cbr>妈妈：“弟弟你的方法比妈妈的还要好。”\u003cbr>where 不论在教育子女和家人沟通或和同事之间有矛盾时，在听取对方解释的时候都可以采用这四个步骤。\u003c/p>","interaction":"\u003cp>我们刚刚学习了用倾听四步法来听懂对方解释，即，听懂对方说话逻辑，给出反馈并说出自己的意见。\u003cbr>现在，为了更好的运用如何倾听解释请大家做一个演练。假设一个这样的场景\u003cbr>背景：小刘今天下班很晚都快12点钟了还没有回来，他老婆打他电话怎么也打不通，问了他几个同事都说单位早就下班已经没人了，快1点钟的时候小刘醉醺醺的回来了，什么也没说倒头就睡。第二天一大早小刘老婆运用所学的倾听四步骤：听逻辑，有反馈，讲观点，要确认这一方法来跟小刘沟通，谈谈昨天到底什么回事。\u003cbr>下面以小组为单位讨论：写出小刘老婆如何应用今天的方法和小刘进行沟通的对话场景。\u003cbr>提示：尽可以详细的写下包括双方的语言、肢体、表情、声音等等内容，确保有画面感，伙伴们可以自行体会代入，把要点写下来。\u003cbr>五分钟后我们邀请一组小伙伴现场表演一下，看看他们是怎么说的，现在开始。\u003cbr>好时间到，我么请一组小伙伴给大家演练下刚才你们的对话：\u003cbr>【学习者演练】\u003cbr>FUJI来扮演老婆，skyfly来扮演小刘\u003cbr>老婆：昨天怎么回来这么晚呢\u003cbr>小刘：遇到了发小，好多年不见，喝了几杯喝迷糊了头还有些疼\u003cbr>老婆：这样啊，那你现在还头疼吗，要不给你冲杯蜂蜜水解酒，怎么也不给我打电话联系一下，我也联系不上你，我还是很担心的。\u003cbr>小刘：居酒屋有点吵可能没听到你的电话，后来喝多了就把给你打电话这事忘记了，抱歉下次不会这样了。为了表示歉意我请你吃西餐。\u003cbr>老婆：好，那下不为例哦。\u003cbr>\u003cbr>好，谢谢两位小伙伴的分享，现在我们还有一些时间，我们再请一组小伙伴来演练一下。\u003cbr>第二组：时和来扮演老婆，香精来扮演小刘\u003cbr>老婆：你昨晚怎么回来这么晚\u003cbr>小刘：昨天公司有一个迎接新人会，也不能不去，所以回来晚了\u003cbr>老婆：这样啊，这个是得参加。但你回来这么晚我很担心，你也不给我联系会胡思乱想，担心你出了什么事，如果可以希望你提前通知我一下。\u003cbr>小刘：老婆对不起我下次注意，我会事先告诉你，几点回家我也会给你发信息。\u003cbr>老婆：我很高兴你这么想。\u003c/p>\u003cp>【点评与总结】\u003cbr>谢谢小伙伴的精彩分享，两组都运用了今天学到的方法，避免了矛盾冲突，解决了实际问题还增进了夫妻感情。\u003cbr>【结束语】\u003cbr>以上就是我的拆书分享，希望这次分享能让大家学会倾听对方的解释，听逻辑，有反馈，说观点，要确认这四步法来倾听对方，缓解矛盾提高沟通能力。谢谢大家。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1684894086000,"updated_at":1684894294000,"ria":true},{"id":15367,"topic":"解释概念，争取对方听懂我","learn_goal":"","remark":"提升说话影响他人的能力。","level":"TF3-2","duration":25,"status":19,"type":0,"chaishujia":{"username":"王礼界","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":null,"ratings_count":3,"texts":[{"id":19416,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1679217565000,"updated_at":1692769240000},{"id":15310,"topic":" 解释","learn_goal":"","remark":"和别人遇到分歧或矛盾时，通过解释四步法来听取对方结实，化解矛盾解决问题。","level":"TF2-2","duration":19,"status":30,"type":0,"chaishujia":{"username":"开心1314","city":""},"club":{"name":"东京ひかり分舵","city":""},"prologue":"\u003cp>大家好，我是赵丽。我今天的分享是《说话的力量》这本书中的拆页。\u003cbr>【学习目标】\u003cbr>在随我完成本次RIA现场学习后，学习者能在和他人遇到问题或矛盾时，运用倾听解释的4个层级理解对方的解释，并从对方的合理解释中找到进行下一步沟通的对话内容。\u003cbr>【分组】\u003cbr>因为下面有小组讨论和分享环节，那我们先以两两一组的形式分一下组。\u003cbr>\u003cbr>以下是我的分享内容：\u003cbr>【FAB 图书介绍】\u003cbr>F特征（Feature）\u003cbr>这本《说话的力量》作者是孙路弘，他是一名营销和销售专家。本书讲了如何训练你的说话技巧来提高沟通能力和工作能力。\u003cbr>A优势（Advantage）,\u003cbr>这本书使用浅显易懂的文字和我们生活中经常遇说话的到的状况作为实例来介绍说话的技巧的，相比其它同样内容的图书更容易上手。其中介绍了8个说话方法，4个说话技巧，2种实战工具。\u003cbr>B利益（Benefit）\u003cbr>你在和孩子谈话时是不是常常遇到沟通不顺让你大发雷霆。你在和同事工作交流中解释说明不到位而产生工作分歧。你在面试时是不是不知道如何有逻辑的把自己的特长介绍给面试官而让你面试失败。如果你确实遇到过以上的问题不妨跟这本书学习一下说话的技巧，让你与其他人沟通时更高效更顺畅，工作也事半功倍。\u003c/p>","ratings_count":1,"texts":[{"id":19351,"quote":"\u003cp>下面请大家花3分钟看一下我的拆页内容，我的 拆页选自&lt;说话的力量&gt;电子版P186～189\u003cbr>[R]听懂，解释的核心\u003cbr>解释有一个核心，就是听懂。听到不等于听懂，中国有句老话“锣鼓听声，听话听音”，你真的听懂了吗？\u003cbr>真正的听懂有四个层次：第一个是听懂对方，第二个是让对方知道我听懂了，第三个是争取让对方听懂我，第四个是确认对方听懂我了。这也就是解释的四个层次。\u003cbr>◆第一层：我听懂对方\u003cbr>听懂对方是指听懂对方所讲的事实，听懂对方所描述的细节，听懂对方所下的结论。要做到这些，首先你要听懂对方的逻辑，知道对方说的事实和结论之间依据什么样的逻辑。\u003cbr>学习倾听，关键听的是逻辑。我们常听人说：“这件事我跟你说了多少遍了？你还是左耳进、右耳出。你根本就把我的话当耳旁风。”老干部看报纸，都能看出文字背后的意思，这就是加工信息的能力。听别人说话时，如果在对方的话里听不到逻辑，听不出背后的意思就不叫听懂，就会左耳朵进、右耳朵出。如果听到逻辑了，一个信息、事实或者细节从耳朵进去以后，在你头脑里经过了加工，你就能听明白他通过这个事实是为了说明哪些观点。在你脑海里加工过就不会遗忘，这就是真正地听懂了。\u003cbr>◆第二层：让对方知道我听懂了\u003cbr>不管是面对一个人说话还是面对一群人演讲，听者一定会给予说话者反馈。点头是一种反馈，鼓掌是一种反馈，微笑也是一种反馈。比如我问你：“小时候上过学吧？”你肯定会点头：“对，上过学。”我问：“有没有留过级？”你摇摇头：“没有。”点头和摇头表示你对我所说的事情的认可与否，但这不叫听懂，也不叫让我知道你听懂了。\u003cbr>◆第三层：让对方听懂我\u003cbr>如何让对方听懂我？首先你要找到对方能够听懂的话题基础。比如讲课的时候老师提到“傅立叶函数”这个概念，如果以前没有听说过这个概念，恐怕你连“傅立叶”三个字怎么写都不知道。老师就没有做到让你听懂。说一个微积分术语，要想让人听懂，就必须展开说：“一个非规则的曲面体，想要知道它的体积，尤其是曲面的弧度，只有一个工具，就是微积分。”也就是说，我要想让你听懂，必须得知道你能听懂的已知的东西。\u003cbr>◆第四层：确认对方听懂了\u003cbr>要确认对方听懂就需要双方沟通。我给你讲完一件事，我要听到你的反应，如果你说“我明白了”，这才叫你听懂我了。我想说一件事，先得了解对方知道哪些事，在他已知部分的基础上，我再跟他说下一件事，最后他跟我确定他听懂了，完整地完成了这样一个过程，才达到了沟通的目的。\u003c/p>","explains":"\u003cp>【I】拆页家讲解引导\u003cbr>我看到小伙伴已经都读完了，下面我们一起来解读这段文字。\u003cbr>【what 】\u003cbr>这段文字讲了如何听懂对方解释这一方法。出现问题我们让对方解释原因，如何高效听懂对方的解释是进行下一步交流的关键步骤。\u003cbr>【how】 听懂解释过程的具体步骤如下\u003cbr>第一步：听逻辑。\u003cbr>听懂对方说话逻辑。\u003cbr>第二步：有反馈。\u003cbr>要给予对方你的意见反馈。\u003cbr>第三步：说观点。\u003cbr>以对方已知内容为基础阐明自己的观点。\u003cbr>第四步：要确认。\u003cbr>确认对方是否听懂，让对方简单重复。\u003cbr>【why】\u003cbr> 一件事情一旦需要解释就意味着一方对一些问题有不同的看法或不理解的地方，他的预期和现实是不一致的，跟对方互动有障碍。一份合理的解释可以减少许多麻烦和矛盾，相反听不懂对方解释甚至曲解了解释内容会让矛盾更激化，所以如何接受对方而又觉得他不是在推脱责任，一个清楚明了让他人听懂的解释就变得至关重要。\u003cbr>【不这么做的坏处】\u003cbr>我们平时都是听到过什么样的解释呢。一， 压根不听解释，直接发脾气来质问。这样根本不能进行下一步沟通，甚至合作终止。二，对方说了一堆理由你根本听不出重点在哪里。三，因为自己认知水平低根本听不懂对方说了什么。\u003cbr>【举例子说明】\u003cbr>以前老公会偷偷的在单位抽烟，我只要看到他口袋里有烟我就把烟扔掉然后跟他大吵一顿，他也总说马上戒烟但是效果不好，也影响了我们两人的感情。\u003cbr>如果以后我再在他口袋里发现香烟，我会找他坐下来谈谈，问问他的工作累不累，压力大不大，什么时候最想吸烟呢，再好好倾听他戒不掉烟的理由。如果他的理由合理我是不会同他大吵大闹的，我会陪着他一起戒烟。\u003cbr> 第一步听逻辑：他是为什么只在单位吸烟的呢，是工作压力大还是为了和有吸烟习惯的同事说话方便呢，或者其他什么原因呢，听到他具体的原因后再下结论。\u003cbr> 第二步有反馈：我会告诉他我理解他的工作压力，知道他上班会犯困需要靠外力来提神，能不能换成咖啡或茶呢。\u003cbr> 第三步说观点：吸烟带来的危害是永久的，以我爸爸为例年轻时候吸烟很多，现在时不时的因为肺炎住院，不但自己饱受病痛的折磨还给子女们填了很多麻烦。\u003cbr> 第四步要确：老公听完我的分析，应该不会再偷偷买烟了，如果他愿意戒烟，我会陪他慢慢把烟戒掉。\u003cbr>where 不论工作和生活中只要有矛盾出现，在听取对方解释的时候都可以采用这四步骤。\u003cbr>【异议预防1】\u003cbr>有的小伙伴可能会说，他们都是来找借口搪塞你，不要相信他们的解释。其实一开始我也这么想，但仔细想想，当别人给你解释一次两次你不听的时候，估计他不会再想向你解释第三次了，不管对方的理由是否合理，当你一次次拒绝对方解释的时候其实你是关闭了下一步交流通道。不妨我们给对方一次机会，增加一次信任的交流。\u003c/p>","interaction":"\u003cp>\u003cbr>【A2】催化作用（分布催化1）\u003cbr>【技能点：分布催化中，提问中包括情境或场景，有学习者受启发联想到自己的具体应用场景】\u003cbr>不知道在座的各位拆书家在未来生活或工作当中有没有可能遇到由于对方没有解释或解释不清楚而带来矛盾冲突这样的事情呢？\u003cbr>比如说你的孩子到了放学时间一直没有回家，电话也打不通，晚上十点多了才回来，你是打算上来就大发雷霆还是给他个解释的机会呢。\u003cbr>比如去购物，服务员爱理不理服务态度差，导致发生争执？\u003cbr>等等…\u003cbr>类似的事件你还可能遇到哪些，你打算怎么做呢？\u003cbr>下面给大家时间2分钟时间，两两分享自己的过往经历。\u003cbr>时间到，每组派一位伙伴来分享下，时间1分钟。\u003cbr>【学习者分享记录】\u003cbr>香京的分享：以前自己父亲由于吸烟身体不好而戒掉香烟，她生活在一个无烟家庭，所以在她认为老公就是不该吸烟的，如果有一天再发现他吸烟肯定会很生气，跟他发脾气。\u003cbr>时和的分享：未来遇到孩子放学一直没回家父母很着急，电话也打不通，等他回到家肯定会特别生气，骂他一顿。\u003cbr>【A2】催化作用（分布催化2）\u003cbr>【技能点：分步催化中指令清晰，有学习者根据指令，规划出了以后可以如何做的具体计划】\u003cbr> 请大家根据刚才联想到的具体场景，然后设想一下如何运用今天学到的倾听对方解释的四个步骤，听逻辑,有反馈,说观点,要确认，来处理问题。\u003cbr>给大家3分钟思考时间，一会儿邀请小伙伴来分享。\u003cbr>时间到，我想邀请小伙伴分享一下。\u003cbr>【学习者分享记录】\u003cbr>香京的分享：先听听老公的想法，对承诺不吸烟却再犯的解释。表示我的关心，再提议自己的想法，最后问老公能接受自己的建议吗。\u003cbr>时和的分享：第一步克制住发怒的情绪，听孩子的解释，是电没电了或者别的特殊情况。第二步理解了他的情况后表达出自己担心的心情。第三步提议一些安全对策，比如可以用公共电话通知家人。\u003c/p>\u003cp>【结束语】以上就是我的拆书分享，希望这次分享能让大家学会倾听对方的解释，听逻辑，有反馈，说观点，要确认这四步法来倾听对方，缓解矛盾提高沟通能力。谢谢大家。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1678448125000,"updated_at":1679871081000,"ria":true},{"id":15225,"topic":"解释","learn_goal":"","remark":"和别人遇到分歧或矛盾时，通过解释四步法来听取对方结实，化解矛盾解决问题。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"开心1314","city":""},"club":{"name":"东京ひかり分舵","city":""},"prologue":"\u003cp>大家好，我是来自美丽古城保定的赵丽，目前定居日本。我的三个标签是： 专业主妇 ，教育热爱者，庄稼汉 。虽然做了十几年的家庭主妇但因为以前做过老师所以教育的情怀一直还在，最近两年喜欢上了种菜所以又成了一名庄稼汉。\u003cbr>学习目标\u003cbr>在随我完成本次RIA现场学习后，学习者能在和他人遇到问题或矛盾时，运用倾听解释的4个层级，从对方的合理解释中，找到进行下一步沟通的对话内容。\u003cbr>FAB 图书介绍\u003cbr>F特征（Feature）\u003cbr>这本《说话的力量》作者是孙路弘，他是一名营销和销售专家。本书讲了如何训练你的说话技巧来提高沟通能力和工作能力。\u003cbr>A优势（Advantage）,\u003cbr>这本书使用浅显易懂的文字和我们生活中经常遇到的状况作为实例来介绍说话的技巧的，相比其它同样内容的图书更容易上手。其中介绍了8个说话方法，四个说话技巧，两种实战工具。\u003cbr>B利益（Benefit）\u003cbr>你在和孩子谈话时是不是常常遇到沟通不顺让你大发雷霆。你在和同事工作交流中解释说明不到位而产生工作分歧。你在面试时是不是不知道如何有逻辑的把自己的特长介绍给面试官而让你面试失败。如果你确实遇到过以上的问题不妨跟这本书学习一下说话的技巧，让你与其他人沟通时更高效更顺畅，工作也事半功倍。\u003c/p>","ratings_count":1,"texts":[{"id":19258,"quote":"\u003cp> 拆页选自&lt;说话的力量&gt;电子版P186～189\u003cbr>听懂，解释的核心\u003cbr>解释有一个核心，就是听懂。听到不等于听懂，中国有句老话“锣鼓听声，听话听音”，你真的听懂了吗？\u003cbr>真正的听懂有四个层次：第一个是听懂对方，第二个是让对方知道我听懂了，第三个是争取让对方听懂我，第四个是确认对方听懂我了。这也就是解释的四个层次。\u003cbr>◆第一层：我听懂对方\u003cbr>听懂对方是指听懂对方所讲的事实，听懂对方所描述的细节，听懂对方所下的结论。要做到这些，首先你要听懂对方的逻辑，知道对方说的事实和结论之间依据什么样的逻辑。\u003cbr>学习倾听，关键听的是逻辑。我们常听人说：“这件事我跟你说了多少遍了？你还是左耳进、右耳出。你根本就把我的话当耳旁风。”老干部看报纸，都能看出文字背后的意思，这就是加工信息的能力。听别人说话时，如果在对方的话里听不到逻辑，听不出背后的意思就不叫听懂，就会左耳朵进、右耳朵出。如果听到逻辑了，一个信息、事实或者细节从耳朵进去以后，在你头脑里经过了加工，你就能听明白他通过这个事实是为了说明哪些观点。在你脑海里加工过就不会遗忘，这就是真正地听懂了。\u003cbr>◆第二层：让对方知道我听懂了\u003cbr>不管是面对一个人说话还是面对一群人演讲，听者一定会给予说话者反馈。点头是一种反馈，鼓掌是一种反馈，微笑也是一种反馈。比如我问你：“小时候上过学吧？”你肯定会点头：“对，上过学。”我问：“有没有留过级？”你摇摇头：“没有。”点头和摇头表示你对我所说的事情的认可与否，但这不叫听懂，也不叫让我知道你听懂了。\u003cbr>◆第三层：让对方听懂我\u003cbr>如何让对方听懂我？首先你要找到对方能够听懂的话题基础。比如讲课的时候老师提到“傅立叶函数”这个概念，如果以前没有听说过这个概念，恐怕你连“傅立叶”三个字怎么写都不知道。老师就没有做到让你听懂。说一个微积分术语，要想让人听懂，就必须展开说：“一个非规则的曲面体，想要知道它的体积，尤其是曲面的弧度，只有一个工具，就是微积分。”也就是说，我要想让你听懂，必须得知道你能听懂的已知的东西。\u003cbr>◆第四层：确认对方听懂了\u003cbr>要确认对方听懂就需要双方沟通。我给你讲完一件事，我要听到你的反应，如果你说“我明白了”，这才叫你听懂我了。我想说一件事，先得了解对方知道哪些事，在他已知部分的基础上，我再跟他说下一件事，最后他跟我确定他听懂了，完整地完成了这样一个过程，才达到了沟通的目的。\u003c/p>","explains":"\u003cp>what \u003cbr>这段文字讲了如何听懂对方解释这一方法。出现问题我们让对方解释原因，如何高效听懂对方的解释是进行下一步交流的关键步骤。。\u003cbr>why 一件事情一旦需要解释就意味着一方对一些问题有不同的看法或不理解的地方，他的预期和现实是不一致的，跟对方互动有障碍。一份合理的解释可以减少许多麻烦和矛盾，相反听不懂对方解释甚至曲解了解释内容会让矛盾更激化，所以如何接受对方而又觉得他不是在推脱责任，一个清楚明了让他人听懂的解释就变得至关重要。\u003cbr>【不这么做的坏处】\u003cbr>我们平时都是听到过什么样的解释一， 压根不听解释，直接发脾气来质问。这样根本不能进行下一步沟通，甚至合作终止。二，对方说了一堆理由你根本听不出重点在哪里。三，因为自己认知水平低根本听不懂对方说了什么。\u003cbr>【失败案例】 \u003cbr>前一段时间我经常从我儿子口袋里搜出糖果纸，而且我放在抽屉里的钱少了，我猜肯定是背着我拿钱偷偷买糖了。那天孩子放学刚到家我就问他是不是偷拿我的钱买糖果了，他只是哇哇的哭说没有偷拿钱，当时我就认为他在撒谎根本没给他解释的机会不由分说就给了他一巴掌，还说以后每天半小时看电视的时间也取消了。孩子听了特别伤心什么也没说，晚饭也没吃好几天也不跟我讲话。\u003cbr>how 听懂解释过程的具体步骤如下\u003cbr>第一步：听逻辑。\u003cbr>听懂对方说话逻辑。\u003cbr>第二步：有反馈。\u003cbr>要给予对方你的意见反馈。\u003cbr>第三步：说观点。\u003cbr>以对方已知内容为基础阐明自己的观点。\u003cbr>第四步：要确认。\u003cbr>确认对方是否听懂，让对方简单重复。\u003c/p>\u003cp>【成功案例】\u003cbr>结合片段的方法，后来我跟孩子再次进行了沟通，听了孩子的解释，\u003cbr>（第一步听逻辑）他说：偷拿了两块钱买的糖果，豆豆是他班里面最好的朋友他想买给豆豆吃，原来孩子的需求不是单纯的想吃糖果而是想交朋友。\u003cbr>（第二步有反馈）我告诉他：我也希望他能交到好朋友，可以把家里的零食和豆豆一起分享不用偷偷摸摸的。\u003cbr>（第三步说观点）我告诉他阻止他吃糖果是怕他会长蛀牙，而且不能偷拿钱这是小偷行为是不对的。\u003cbr>（第四步要确认）跟孩子确认是否明白了我的心思。最后他保证每天只吃两块糖并好好刷牙，需要钱会和我要不会偷偷摸摸拿了。\u003cbr>反思：如果当时我让孩子解释一下，知道孩子的需求是想交朋友，我也会给他零花钱买些零食和朋友一起分享，我没有听到孩子的需求更没有给他一个很好的意见，让母子之间出现了矛盾。\u003cbr>where 不论工作和生活中只要有问题出现听取对方解释的时候都可以采用这四步骤。\u003c/p>","interaction":"\u003cp>【显象提问】不知道在座的各位拆书家在生活或工作当中有没有遇到过，由于对方没有解释或解释不清楚而带来矛盾冲突这样的类似事情呢？\u003cbr>比如说你的孩子到了放学时间一直没有回家，电话也打不通，晚上十点多了才回来，你好好听对方解释还是直接大发雷霆了呢。\u003cbr>比如去购物，服务员爱理不理服务态度差，导致发生争执？\u003cbr>等等…\u003cbr>类似的事件你还遇到过哪些，你是怎么做的呢，请各位思考30秒，想一下你这方面的经历或经验。\u003cbr>下面给大家时间2-3分钟时间，两两分享自己的过往经历。\u003cbr>时间到，每组派一位伙伴来分享下，时间1分钟。\u003cbr>【学习者分享】\u003cbr>时和小伙伴分享了以前她在做导游的时候去景点买门票时发生的一幕，她说买票员当时服务态度很差出票很慢，自己大声训斥那个售票员还要她叫出领导来解决这件事，事情闹得不可开交。\u003cbr>FUJI小伙伴分享了她的妈妈来日本之后有一次出门很久了也没有回来也没有跟家里打电话，她担心妈妈不会日语是不是出了什么意外，等妈妈回来之后没有忍住就和妈妈大吵了一顿。\u003cbr>【A1+】（反思加工）\u003cbr>既然我们学习了倾听对方解释的四个步骤，那我们就学以致用，假如时间能倒流再给你一次机会遇到这种情况你是怎么运用解释四步骤：听逻辑,有反馈,说观点,要确认，来处理当时的问题。\u003cbr>给大家1分钟思考时间，可以写关键词在便利贴上，一会儿邀请小伙伴来分享。写好的伙伴示意我下。\u003cbr>时间到，请2位伙伴来分享下，时间1-2分钟。\u003cbr>【学习者分享】\u003cbr>时和的分享：学了解释四步法之后，她当时不会直接大吵而是听那个售票员不给他票的原因，体谅她的工作特点，并把自己的需要再具体些态度再温和一些，在互相理解的基础上解决问题。\u003cbr>FUJI的分享：学了解释四步法之后，她会先听妈妈说回来晚的原因，然后再给她些建议下次出门前一定让家人知道她去哪里什么时间回来，带电话出门。这样的话就能避免争吵还能加深母女俩的感情。\u003c/p>\u003cp>\u003cbr>以上就是我的拆书分享，希望这次分享能让你学会倾听对方的解释来缓解矛盾提高沟通能力\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1677066162000,"updated_at":1677066876000,"ria":true},{"id":14038,"topic":"说话的力量","learn_goal":"","remark":"晋级","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"立慧","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>尊敬的观察家、亲爱的小伙伴们，大家好！我是今天晋级2-3的立慧。用3个标签来介绍自己，分别是：一名PET父母效能训练讲师，二个孩子的妈妈，三级心理咨询师。\u003c/p>\u003cp>图书介绍：（F）今天我要带大家拆的这本书名叫《谈话的力量》，作者是美国著名的沟通学专家艾伦.加纳，在书里他传授了克服谈话障碍以及出色交谈的技巧，畅销上百万册，堪称社交指南图书中的经典图书。\u003c/p>\u003cp>A：在书里，艾伦.加纳将他20多年教授学生谈话技巧培训班的经验以及数百列的科学研究成果融入书中，并将很多沟通学和心理学的相关知识，用很生活化的语言阐述出来，还运用大量具体详实的例子来说明，相比同类书籍，既有理论深度又通俗易懂简洁实用，是一本值得反复阅读的沟通书籍。\u003c/p>\u003cp>B1:如果你想通过谈话改善你的人际关系，带给自己快乐和幸福，提升职业发展水平，那么学习运用这本书里教给你的技巧，获得的成功会出乎你意料。\u003c/p>\u003cp>B2:学习了今天的拆页“怎样让别人对你的自我透露感兴趣”，你掌握了这项技巧，就能在交流时吸引对方对你说的话感兴趣，让你一吐为快，畅谈心中所想，不会冷场，不会让你觉得沮丧，也不会让彼此尴尬。\u003c/p>\u003cp>学习目标：大家跟随我完成本次RIA现场学习后，能够了解到什么是“自我透露法”，并且能复述出来，还可以通过一次现场演练来运用这个方法。\u003c/p>","ratings_count":1,"texts":[{"id":18054,"quote":"\u003cp>拆页选自书上第五章“让别人知道你”，请大家花2分钟的时间阅读拆页，看完后请在聊天区回复1。\u003c/p>\u003cp>\u003cstrong>怎样让别人对你的自我透露感兴趣\u003c/strong>\u003c/p>\u003cp>要让别人感兴趣，仅仅列出事实是不够的，还要告诉他们这些事实与你的联系。年近50的麦克斯是洛杉矶市中心一家银行的职员,他在一次上课前向我抱怨说，别人似乎对他说的关于自己的事情毫无兴趣。我建议我们模拟一个简单的场景，看看问题出在哪里。\u003c/p>\u003cp>我问他:“上次度假你做了些什么?”他回答说:“我和妻子开车去了维加斯,住在联盟广场,花了一整天的时间去赌钱。我们输了大概50美元,玩得很高兴。”我说尽管他陈述的是事实，但是就自我透露来说，他做得并不好。他谈到了事情的场景,却没有提到场景中的自己，那才是个人交流得以进行的所在!麦克斯又试了一次，这回是用笔写的:\u003c/p>\u003cp>我和格雷斯开车去维加斯，想要体验一下豪赌的感觉。最初我是在投币机上玩，心想输上两三美元就撒。几分钟之后，我一拉操纵杆，中了大奖!铃声响过，绿灯闪烁，周围的人都冲着我微笑。我异常兴奋,拍着双手,冲着妻子叫喊。我赢了!尽管只有7.5美元，但是我太高兴了，感觉就像是贏了100万一样!被这种胜利的喜悦刺激着，我接着花了5个小时和32美元，又赢了第二次。\u003c/p>\u003cp>年纪更大一点的休斯顿的马蒂，也因为同样的问题而苦恼。她起初这样描述她的工作:“我是几家小公司的会计，我为他们做好所有的账目,让他们正确地缴税。”\u003c/p>\u003cp>加人自己的感受之后，她又重新作了一番描述:我是几家小公司的会计。有时候当我有些心不在焉时,我就开始想到这些数字代表的是成千上万的美元，于是我就会紧张起来生怕会犯什么错误。每当有这种感觉时，我总会重新检查一遍，确保万无一失。\u003c/p>\u003cp>有时候我拿到的账本简直一团糟一到处都是数字。 尽管牢骚满腹，我还是喜欢这种挑战，一点一点地整理出来，并且让最终的结果相互吻合。\u003c/p>","explains":"\u003cp>Why：大家或许有这样的经历，当你想把自己的一些事情告诉别人时，你侃侃而谈，别人却兴趣索然；你三言两语，平铺直叙，别人也“波澜不惊”，无动于衷，让你觉得很尴尬很沮丧，那怎么聊才能吸引别人呢？\u003c/p>\u003cp>What：这个拆页就介绍了一种让别人对你的自我透露感兴趣的方法，我把它叫做“自我透露法”。\u003c/p>\u003cp>How（细化原文步骤）：它包含4个步骤，分别是：\u003c/p>\u003cp>一. 讲事实：开场做自我介绍或介绍自己的一些近况等具体事实。\u003c/p>\u003cp> 对生人：就是自我介绍，比如：我叫余立慧，是威远县职业中学的老师。\u003c/p>\u003cp> 对熟人：介绍近况，比如：我这两周都在准备拆书家2-3这个关口的晋级。\u003c/p>\u003cp> 二、说经历：说出你上面介绍的某个事实中你的所做所为。\u003c/p>\u003cp> 1.说重点：就是要抓住你的经历中你最想表达的内容来说，切忌泛泛而谈，有的放矢才更容易达到你的目的。 \u003c/p>\u003cp> 2.描细节：描述让你印象特别深刻的细节，从而吸引对方。\u003c/p>\u003cp>三、谈感受：向对方描述出你在经历上面的事件时你的真实感受。\u003c/p>\u003cp> 1.忌宽泛。不要仅仅使用：“我很高兴”，“我好害怕”等太宽泛的表达，否则太普通，不容易让人相信，也不吸引人。 \u003c/p>\u003cp> 2. 要具像：要用文字描绘出具体的图像，以此来表达你的感受。比如：我双手发抖，膝盖互相碰撞着。张开嘴想喊叫，却喊不出声来。”就比一句“我好害怕”更可信也更吸引人。\u003c/p>\u003cp>四.表看法：表达出对你经历的事或者谈到的人的看法，因为看法比你介绍的基本情况和经历更让人了解你，它能体现你的价值观。比如：我认为学习心理学能让我对自己和他人有更多的了解和接纳，从而减少内心的冲突，让我活得更自在。\u003c/p>\u003cp>Where：“自我透露法”适用于你想让别人对你的一些情况有所了解，对你说的话感兴趣，并且在对方有时间有心情来听的时侯。\u003c/p>\u003cp>预防异议：\u003c/p>\u003cp>有人可能会问：这个“自我透露法”在你想让别人对你的自我透露感兴趣的时侯，必须全部按题这四个步骤来用吗？那倒不一定，你可以选择性使用。比如有时基于某个原因，你不想说出看法，那就不说好了。\u003c/p>\u003cp>下面我运用“自我透露法”来给大家讲下我最近二周为了晋级选拆页的事情。\u003c/p>\u003cp> 【1.讲事实】 \u003c/p>\u003cp>我从4月1号到5月20号，用了50天时间，为了晋级来读书选拆页。\u003c/p>\u003cp>【2.说经历】\u003c/p>\u003cp>我读了二本新书《伯恩斯新情绪疗法》和《谈话的力量》，又读了两本旧书《非暴力沟通》和《心理学家的倾听术》，先在这四本书里选了七个拆页，前六个拆页都没通过师父审核，有的是因为我提炼的步骤与拆页差不多，不符合“细化步骤”这个技能点，有的是因为我细化的步骤是拆页上没有的，有点“无中生有”，有的又是因为细化的步骤太多，讲解完会超时，有的又因为拆页介绍的知识点太复杂估计学习者现场接收不了等等原因。\u003c/p>\u003cp>【3.谈感受】\u003c/p>\u003cp>所以在4月1号到5月20号这50天里，我仿佛一步步走进沼泽地一般，动弹不得，心里非常郁闷，做事都打不起精神，直到5月21号选的第七个拆页，就是今天大家学习的这个拆页，被师父审核通过时，我才长吁了一口气，感觉悬起的心终于落下来了，然后精神一振，有力量可以纵身一跳，从沼泽地上岸，开始新的进程，就是写逐字稿啦！\u003c/p>\u003cp>【4.表看法】\u003c/p>\u003cp>有了这次选拆页的经历，我深刻的意识到，平时一定要多看书多积累拆页，并且一定围绕每个级别的技能点来选拆页，这样才不会“书到用时方恨少”，才不会“事倍功半”！\u003c/p>","interaction":"\u003cp>【A3】\u003c/p>\u003cp>促动参与\u003c/p>\u003cp>我们刚刚学习了“自我透露法”，1.讲事实；2.说经历；3.谈感受；4.表看法，现在，大家来做一个演练，先请大家认真听一下演练的场景。\u003c/p>\u003cp>演练场景：两个相互都很熟悉的同事A和B，在周一中午休息时聊天，互相在问对方周末是怎样过的，过得怎么样，然后各自就给对方聊了周末干了些啥，也许是看了场电影，也许是参加了某个活动，也许是去某个地方吃了顿美食，等等。在聊天的过程中他们都要想办法用上【自我透露法】的四个步骤。\u003c/p>\u003cp>角色扮演：今天因为是线上晋级，网上学习者有5个，刚刚洪琪因故退出下线了，剩下的四人，高老师和肖老师一组，就请用视频进行交流，边边和雅心一组，请在聊天区进行交流。现在就请你们针对前面的演练场景，进行组内商量，谁来扮演A？谁来扮演B？以及你们交流的具体对话。请注意，重点来啦，那就是每个角色在对话的过程中，都要用上我们刚学到的“自我透露法”。\u003c/p>\u003cp>这个环节我给大家8分钟，时间到后，我要请一个小组来跟大家进行角色演练，大家有不清楚的地方吗？请举手提问。现在大家都清楚啦，请开始你们的思考，协商和对话。\u003c/p>\u003cp>对现场完整案例记录：办公室的同事A（雅心）和B（边边）在午休时聊天。\u003c/p>\u003cp>A（雅心）：边边，上周末我带家人去爬了龙泉山（1讲事实），那里很凉快，路上补给食物也很方便，坡道也不陡，老人和小孩都能适应（2.说经历）。一路上呼吸着大自然清新的空气，心情特别放松（3.谈感受）。我觉得这是一次锻炼孩子毅力的好时机，以后还要多带孩子去徒步,爬山，也是值得坚持的（4.表看法）。边边，你上周末怎么过的呢？\u003c/p>\u003cp>B（边边）：我带孩子去了兴隆湖（1.讲事实）。以前我认为带孩子出门玩是一件很累的事，因为爱人要上班，只有我一个人陪孩子，但那天去兴隆湖，那里有滑梯，有4个小朋友一起玩，我就坐在旁边看着，还可以玩手机，一点不累。玩一会儿滑梯后孩子觉得无聊，又去旁边的小沙滩玩（2.说经历）。因为疫情很久没去海边了，在这里又体验了在海边玩的乐趣，我和孩子都挺开心（3.谈感受）。我觉得兴隆湖真的是一个很有趣的地方，你们喜欢徒步，那里也可以绕圈走，不同的地方景色也不同，挺有趣的（4.表看法）。\u003c/p>\u003cp>A（雅心）：那好啊，今后我们可以约着一起带孩子去玩。\u003c/p>\u003cp>今天我们学习了拆页教授的“自我透露法”，它包含哪4个步骤呢？大家跟随我一起来回忆并复述下：1.讲事实，2.说经历，3.谈感受；4.表看法，另外大家今天也演练了这样的交流方式，有了切身的体会。希望大家回到工作生活中，在你想让别人对你说的话感兴趣时运用起来，让你能畅所欲言，说出心中所想，让听的人也听得津津有味，兴趣盎然，进而增进彼此的了解，促进你的人际关系。今天我的分享到此结束，谢谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1661242749000,"updated_at":1661494404000,"ria":true},{"id":12559,"topic":"合格汇报的三大要素","learn_goal":"","remark":"让你清晰掌握汇报的三大要素，助力职业发展","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"秋香","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>大家好！我是一名一级拆书家，我叫秋香。开始拆书之前呢，我先给大家分个组（根据现场人数给学习者分组）。今天是我在拆书路上打怪升级之TF2-2的分享。希望大家在跟随我完成本次RIA现场学习后，能够针对未来的某个汇报场景，利用汇报三要素，制定出一个行动规划。\u003c/p>\u003cp>F:《说话的力量》这本书的作者是孙路弘，他是营销及销售行为专家，高级营销顾问，著有《看电影学管理》、《用脑拿订单》等多本畅销书。本书讲了8大说话方法、4大说话技巧和2大说话工具，都是作者首创的。\u003c/p>\u003cp>A:里面集结了作者25年的营销和销售经验，书中有大量丰富的案例都是作者多年经历的真实事件。也是国内首部系统学习说话的实战指南。它不像有的书空谈理论，这是一本能直接运用于具体生活、工作的手册。\u003c/p>\u003cp>B1(书籍带来的利益）：你有没有过在工作中遭遇挑衅的情况？书中的说话方法之“回应”可以帮助你反戈一击。你有没有过在沟通过程中感觉尴尬的时候，书中的说话技巧之“垫子”，可以让你创造一来一往舒适的说话氛围。你有没有过在说话时处于劣势的局面，书中的说话技巧之“制约”可以让你赢得无与伦比的优势地位。\u003c/p>\u003cp>B2（拆页带来的利益）：你是否还有过，在向领导汇报工作后，总得不到满意的结果呢？今天我们聚焦在书中8大说话方法之一的“汇报”，可以帮助你清晰的掌握工作汇报的三要素，让你的汇报更有价值，从而有利于达成自己的汇报目的。\u003c/p>","ratings_count":1,"texts":[{"id":16479,"quote":"\u003cp>为什么干了同样的事，别人总能说得天花乱坠\u003c/p>\u003cp>在职场中，有的人会感叹，为什么干了同样的事，自己没话说，别人却能说得天花乱坠，自己干了十分，只能说出五分，别人只干了八分，却能说出十五分呢？那就是因为你没有掌握说话的技巧，没有掌握汇报的技巧。光说不干假把式，光干不说傻把式，既会说又会干才是真把式。毫不夸张地说，及时汇报和在合适的时机汇报，是职场必备的技能之一。\u003cbr>在现实生活中，你可能经常遇到这样的情况，领导对下属说，“你给我汇报一下情况”，但是下属汇报完了以后领导又总是不满意，这是为什么呢？是因为汇报不完整、不合格，缺少了必备的元素。不完整的汇报，可能是只有观点、缺乏足够的事实；也可能是只有观点没有事实。最常见的不完整的汇报是缺乏建议。汇报不同于讲述、叙述和表达，最与众不同的地方就是要有相应的建议。所以，真正合格的汇报必须具备的元素是：有事实、有观点，且要有基于事实和观点的建议。\u003c/p>\u003cp>\u003cbr>合格汇报的3大要素\u003cbr>汇报的主要构成有三大要素：事实、观点和建议，用时比例约为4：2：4。如果是下级向上级汇报，至少要提供两点建议，并预留时间对建议的实施进行一定的预测；更高层的汇报则要求提供落实建议的资源规划内容。\u003c/p>","explains":"\u003cp>\u003cstrong>WHAT:\u003c/strong>这个片段主要讲了合格进行工作汇报的三大要素。\u003c/p>\u003cp>\u003cstrong>WHY:\u003c/strong>人们在向领导汇报工作的时候，通常会叙述一大段经过，或是提出一堆存在的问题，亦或是表达出自认为的感受，这样做让领导根本无法清楚的知道你的工作情况，更难以做出决策，当然就很难达到你想要的效果。\u003c/p>\u003cp>\u003cstrong>HOW：\u003c/strong>那合格汇报工作的三大要素有哪些呢？\u003c/p>\u003cp>1、讲事实。对客观情况的阐述，要实事求是，最好能够有数据的支撑。\u003c/p>\u003cp>2、抛观点。可以是自己对这件事情的看法，或是发现的一些优势，亦或是存在的一些问题等。\u003c/p>\u003cp>3、提建议。是基于事实和观点提出的解决方案，至少提2点建议，最好是对建议实施后有一定的预测。如果是更高层的汇报，还需要提出落实建议的资金和资源规划等。\u003c/p>\u003cp>\u003cstrong>适用边界：\u003c/strong>这个方法适用于工作汇报和沟通的方方面面，同时也适用于家庭沟通。当然，如果在沟通双方的情绪没有得到解决的情况下，是不适用于此方法的。\u003c/p>\u003cp>\u003cstrong>举例说明：\u003c/strong>正好下周我要向领导汇报工作，如果运用工作汇报的三要素，我可以这么汇报：“杜总，公司近二个月的项目回款不太理想，据我了解，总项目额有300万，而回款额只有21万，回款率仅有7%。（讲事实）再这样下去，会严重影响到公司的资金运转。你看是否需要由专人来进行统一管理（抛观点）那根据目前公司情况，我建议1.由于杜总你平时比较忙，可以聘请一位职业经理人，对公司进行统一管理。这样虽然管理成本会有所上升，但是资金回笼和整体工作效率可以得到很大提升。2.由项目经理梳理各自小组的项目情况，交由我这里汇总，我再对所有未回款项目进行统一安排处理，这样至少可以提升5倍回款率。（提建议）\u003c/p>\u003cp>预防可能的异议：有的小伙伴可能会说，自己能力有限，提不出合适的建议，这个时候其实可以在汇报之前，与相关人员进行讨论，一起寻找解决办法再提议；确实没有合适建议，只需要领导指示的，也可以将最后的建议改为请示指示。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>请大家设想一下，在接下来的一个月，你将会有一个什么样的沟通？是在办公室向领导汇报工作，或是和同事探讨协作，还是在家和伴侣沟通家事？设想一个具体的时间、地点、和谁沟通、主题是什么？请大家把场景想出来，然后在小组内分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>学习者介绍，计划运用此方法的场景：我们公司最近在招人，有一个同事师弟介绍了他的师兄过来面试，针对这个事情，我需要向领导汇报沟通。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>根据刚才大家的联想，请选择一个最有可能会遇到的汇报场景，写下具体的时间、地点，向谁汇报，汇报内容结合今天学习的工作汇报三要素，去做一个行动规划，在小组内分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>学习者：明天等领导面试完，我就会给他说，面试的这个人是我们另外一个同事推荐过来的，从简历上来看，他的工作经历并不是很丰富，虽然他已经工作了有一段时间了。还有简历上表现的东西，和我们公司招人的需求不太一致。（讲事实）我的观点就是，他和推荐的那位同事关系比较好，容易在公司内部进行小团体，不利于整体合作。（抛观点）建议先不着急确定人选，再多面试几个对比一下，或是等秋招的时候再会有更多的选择，以便于选到更合适的人。（提建议）\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1635237985000,"updated_at":1635397031000,"ria":true},{"id":11922,"topic":"3步说到对方心坎里","learn_goal":"","remark":"无","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"余盛莲","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>尊敬的观察家和各位爱学习的小伙伴：大家晚上好！我是余盛莲。用三个标签介绍自己：财务管理，餐饮精细化管理，二级拆书家。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>今天是我3-1拆书晋级，等一下会有分享环节，我们先来分一下组，今天我们人比较少，就分为一个组，请康雄担任组长，谢谢！\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【事件场景】\u003c/strong>上周女儿回家一直嘟着小脸，她说同学们不喜欢她，不跟她一起玩游戏。老公脱口而出：“怎么可能，我女儿这么可爱，同学们不会不喜欢你的。爸爸最爱你了。”女儿什么也没说，继续生闷气……\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>大家在生活中有没有遇到过类似的情况？你们之前都是怎么处理的呢？效果怎么样？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>如果我们没有用对方法，会让对方觉得我们根本不理解他们，不体会他们的感受，影响进一步沟通，甚至导致关系破裂！\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>《说话的力量》这本书教给我们一个技巧：迎合，可以帮助我们解决这个问题。它教给我们一种“我们所说就是对方所想”的说话方式，让对方有一种相见恨晚的感觉，从而认可我们的想法，更加地信任我们。今天跟大家分享的主题是《3步说到对方心坎里》\u003c/p>\u003cp>\u003cstrong>【学习目标\u003c/strong>\u003cstrong>】\u003c/strong>大家在跟随我完成本次RIA现场学习后，能够运用\u003cstrong>【行为】“体会感受，分析逻辑，表达共情”3个步骤\u003c/strong>\u003cstrong>【澄清】，【界定】\u003c/strong>说出对方的感受和想法，让对方认可自己。\u003c/p>","ratings_count":2,"texts":[{"id":15881,"quote":"\u003cp>下面请大家跟我一起来阅读拆页，并勾出关键词。这个片段摘自《说话的力量》P164 第10章 迎合 里的第一个片段表达共情\u003c/p>\u003cp>迎合不是吹牛、拍马屁，也不是奉承，而是，获得对方认同。共情，是指在人际交往过程中，能够体会他人的情绪和想法，理解他人的立场和感受，并站在他人的角度思考和处理问题的能力，又叫做换位思考、移情、共情。\u003cstrong>迎合是快速将共情用说话的方式表达出来\u003c/strong>，让对方直接、快速、明了地感受到这个人跟他自己一样，跟他有一样的逻辑，有一样的经验和体会，什么都跟他一样，双方就容易相互接近了。\u003c/p>","explains":"\u003cp>\u003cstrong>【WHY】:\u003c/strong>俗话说：“酒逢知己千杯少，话不投机半句多”只有投机了，话才能进行得下去。当我们走进对方的心里，在意对方的在意，理解对方的感受，让对方受用、顺耳，自然认可我们的思路，信任我们。\u003c/p>\u003cp>\u003cstrong>【WHAT】（\u003c/strong>强化概念讲解\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>这个拆页中向我们提出\u003cstrong>“\u003c/strong>迎合”不是拍马屁，也不是奉承，而是要快速将共情用说话的方式表达出来，但是我们在用得时候很容易混淆奉承和共情。\u003c/p>\u003cp>接下来我们一起来看它们的区别：\u003c/p>\u003cp>奉承是指逢迎、谀媚，用好听的话恭维对方。\u003c/p>\u003cp>而共情强调的是“共同”性，也就是拆页里的一样，一样的感受，一样的逻辑，一样的体会和经验；一样的感受是指五感受外部事物刺激的影响心理反应一致；一样的逻辑是两者间思维、表达、交流等的方式一致；一样的体会是对外部环境或事物的体验感一致；一样的经验是指对在实践基础上获得的对客观现实的感性认识一致；\u003c/p>\u003cp>举个例子：前几天我去买衣服，由于天气炎热，走得满头大汗。我刚进店，还没来得及看，忽然就来了一个洪亮的女高音：“哎呀，美女，你身材这么好。穿什么都好看。”这是奉承还是共情呢？学员答：“奉承”，是的，这就是奉承，很明显穿什么都好看是她的刻意恭维，她这样说我会觉得她很假，同时也信不过她推荐的衣服。\u003c/p>\u003cp>回到刚才这个例子，精明的导购会迎过来说：“这个天气逛街挺难受吧，快坐下来吹吹空调，喝点水。”然后问我：“你这个身材属于XX型，可以试试我们这几款衣服！”这就很符合我的感受了。\u003c/p>\u003cp>再举个例子：你到餐厅去吃饭，勺子掉地上了，于是你喊：“服务员帮我拿个勺子来。”服务员对你说“等一下”。这叫不叫共情呢？学员答：“不叫”是的，即使他马上拿来了勺子。但是你听到她让你“等一下”，心里仍然会不高兴。\u003c/p>\u003cp>优秀的服务员会立刻说：“我马上去拿。”虽然他拿的速度慢一点，但他嘴上先回答了你，这就符合你的心理了。\u003c/p>\u003cp>再举个例子：你到银行开了个账户，开通了网上银行功能，存了3万块钱，但是晚上你回到家里上网一查，账户里只剩30块了。你去找银行，营业员对你说：“你别着急，冷静一点。”这叫不叫共情呢？学员答：“也不叫”，是的，这个时候我钱都查不到了能冷静吗？\u003c/p>\u003cp>有经验的营业员就会说：“怎么会这样呢？太不正常了。我立刻帮你查一下，这件事是不应该发生的。”这就符合逻辑了。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>预防异议\u003cstrong>】\u003c/strong>大家可能会觉得片段中的共情，可能会与心理学或其它共情方式有部分偏差，我们持保留意见。这里我们学习的是用共情去迎合对方，让对方觉得我们什么都跟他一样的技巧。\u003c/p>\u003cp>\u003cstrong>【适用边界\u003c/strong>\u003cstrong>】\u003c/strong>这里的迎合适用于与人交谈时创造良好的交流氛围，拉近彼此的关系，让对方感受到我们什么都跟他一样，让对方认可自己，促进沟通。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>那我们应该怎么去迎合，才能让对方认可呢？我归纳为三个步骤\u003c/p>\u003cp>1、\u003cstrong>体会感受：\u003c/strong>洞察对方真实的情绪，将心比心地体验对方的感受\u003c/p>\u003cp>\u003cstrong>2、分析逻辑：\u003c/strong>站在对方的角度思考对方想要的是什么，想听的是什么。\u003c/p>\u003cp>\u003cstrong>3、：表达共情：\u003c/strong>用说话的方式把前两步体会到对方的感受和分析到对方的逻辑表达出来（这里要注意语气和语调）。\u003c/p>\u003cp>大家觉得分析对方的逻辑难不难？“难”，这里给大家分享3种方式技巧:\u003c/p>\u003cp>如果对方表达了自己的看法，你就按逻辑给对方提供一个事实；如果对方表达的是事实，你就帮对方总结出一个观点。如果看法和事实都有了，就补充自己的细节。\u003c/p>\u003cp>比如：对方说“今天太热了”，你跟一句：“是啊，38度呢”，反之亦然，如果对方都说了，你就说：“是啊，像蒸笼一样！”，如果全说了，你就补充一个自己的体会或者经历：“是啊，我家女儿都睡地上去了”。创造出你们什么都一样的感觉！\u003c/p>\u003cp>\u003cstrong>【EXAMPLE】\u003c/strong>总的来说用共情去迎合对方，比如刚刚就我家女儿说：“在学校同学不带她玩”这个例子，我是这样来回应孩子的：\u003c/p>\u003cp>1、\u003cstrong>体会感受：\u003c/strong>“宝贝，同学不跟你一起玩，所以你觉得有点伤心。”孩子点了点头 \u003c/p>\u003cp>\u003cstrong>2、\u003c/strong>\u003cstrong>分析逻辑：\u003c/strong>女儿还小，除了撒撕娇，寻求安慰，可能还想寻求帮助。\u003c/p>\u003cp>\u003cstrong>3、表达共情：\u003c/strong>“宝贝，我能体会你有多么伤心和失落，需要我跟你一起想办法解决吗？”\u003c/p>\u003cp>接下来，我就跟女儿就她在学校与同学相处的问题进行了交流……\u003c/p>","interaction":"\u003cp>通过以上的讲解，相信大家已经清楚了运用共情迎合对方的3个步骤“\u003cstrong>体会感受，分析逻辑，表达共情\u003c/strong>”，在大脑中过一遍，等于实际应用了一遍，下面我们来做个练习。请大家各自编写一个小剧本，设想在未来的一周或者一个月在工作、生活中可能会遇到哪些场景需要用到“\u003cstrong>体会感受，分析逻辑，表达共情\u003c/strong>”3个步骤得到对方的认可 ，剧本写到模板里，需要包括时间、地点、人物、背景、起因、经过、对话、结果等等。时间5分钟，请组长负责掌控小组的编写进程。谢谢！5分钟后我邀请1位小伙伴来分享！大家都清楚我的指令了吗？学员答：“清楚了”。好的，大家在编写过程中有不清楚的地方可举手示意我，谢谢！\u003c/p>\u003cp>\u003cstrong>【学员康雄分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>背景\u003c/strong>：平时的日常生活，我和老婆两个人住在一起，明天晚上家里要来客人\u003c/p>\u003cp>\u003cstrong>时间\u003c/strong>： 明天晚上\u003c/p>\u003cp>\u003cstrong>地点\u003c/strong>：家里\u003c/p>\u003cp>\u003cstrong>人物\u003c/strong>：我和老婆\u003c/p>\u003cp>\u003cstrong>起因\u003c/strong>：晚饭后，需要洗碗， 老婆犯嘀咕：“那么多碗？”\u003c/p>\u003cp>\u003cstrong>经过\u003c/strong>：这个时候我会用到今天学的方法去迎合老婆的心情\u003c/p>\u003cp>第一步、\u003cstrong>体会感受\u003c/strong>：\u003cstrong>“\u003c/strong>老婆，看到这么多碗很烦吧。”“嗯”\u003c/p>\u003cp>第二步、\u003cstrong>分析逻辑：\u003c/strong>老婆讨厌水，今天碗又多，又脏又累，心里肯定不爽\u003c/p>\u003cp>第三步、\u003cstrong>表达共情： “\u003c/strong>老婆，我知道你很烦，今天人多碗都20多个，你又不喜欢水，干脆不洗了”\u003c/p>\u003cp>\u003cstrong>结果\u003c/strong>：老婆听了我的话，笑了笑还是把碗洗了。\u003c/p>\u003cp>掌声感谢小伙伴的分享，运用共情迎合了老婆不想洗碗的心情，让老婆感受到了你的体贴，心情好了，碗也洗了，皆大欢喜。祝你家庭幸福！\u003c/p>\u003cp>OK，通过以上的学习，我们学会了迎合对方的3个步骤“\u003cstrong>体会感受，分析逻辑，表达共情\u003c/strong>”，希望大家在工作、生活中多多运用起来，得到对方的认可，走进对方的心里。祝大家生活愉快！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1626502125000,"updated_at":1629182699000,"ria":true},{"id":11330,"topic":"如何汇报","learn_goal":"","remark":"你的工作需要做汇报吗？你有没有这样的时候，感觉你的汇报没有让领导很满意，或者没有达到你汇报的目的，或者没有给领导带来什么影响和触动。还有可能汇报的不好，造成领导对你的能力的质疑。如何做一个合格的汇报，促进达成汇报目的，更体现你的思想和能力？","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"陈羽西","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp> 大家好，我是陈羽西，羽西二字和一个品牌化妆品碰巧同字，蹭一下品牌热度，希望大家记住我。我现阶段的3个标签，第一我是生物公司的技术部部门经理，第二我是兼职的企业内训师，第三我是拆书帮的品宣小助手。 \u003c/p>\u003cp>\u003cstrong>【技能点】分组 \u003c/strong>\u003c/p>\u003cp>为了便于待会学习过程的讨论和分享，我们先分一下组，左手边的两位为一组，右手边的两位为一组。\u003c/p>\u003cp>\u003cstrong>【技能点】设定学习目标 \u003c/strong>\u003c/p>\u003cp>今天跟着我完成RIA现场学习后，大家能够学会用汇报三要素做一个合格的汇报，让听汇报的人更容易受到影响和触动，使得更容易达到你的汇报目的。\u003c/p>\u003cp>\u003cstrong>【技能点】FAB介绍法，能够清晰辨别出F、A、B \u003c/strong>\u003c/p>\u003cp>\u003cstrong>F:特征，核心是“书”，用于满足好奇心。 \u003c/strong>\u003c/p>\u003cp>这次我要和大家一起拆解的片段来自《说话的力量》这本书。这本书的作者是孙路弘，他是营销及销售行为专家，贯穿全书的8大说话方法、4大说话技巧以及两大说话工具，都是作者首创的，倾其25年营销、销售经验的精华之作，涵盖了讲述、表达、汇报、解释等等内容，是国内首部系统学习说话的实战指南。\u003c/p>\u003cp>\u003cstrong>A:优势，重点是“比较”，用于建立安全感。\u003c/strong>\u003c/p>\u003cp>这本书与市面上其他同主题讲授说话技巧的书相比，它不像《沟通的艺术》那样涵盖很多生涩的概念，也不像《关键对话》那样，可能没有分具体的场景，这本书，不仅有分各种说话的场景，有生动的案例，还帮助我们在案例中归纳提取出一个可操作的技巧或者方法去应对对应的场景，更重要的是有给我们训练的方法，是一本能直接运用于具体生活、工作的手册。\u003c/p>\u003cp>\u003cstrong>B:利益，强调的是“你（学习者）”用于引发兴趣\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B1：指这本书给学习者带来的好处 \u003c/strong>\u003c/p>\u003cp>我们的工作生活都离不开说话，不管是面对同事、面对客户、面对家人、要沟通、要交流、要合作、要谈判都离不开说话。在职场和日常生活中，说话水平高的人，往往能够得到更多的机会，也比别人更有影响力，说话在一定程度上决定了一个人的发展和命运。这本书就是帮助你打造会说话的能力。在没有读这本书之前，我没有想到，原来说话这件事情归纳成这么多具体的方法和技巧，读完完全可以跟着书的规则进行有意识的训练与运用。\u003c/p>\u003cp>\u003cstrong>B2：指接下来的这个片段给学习者带来的好处 \u003c/strong>\u003c/p>\u003cp>你有没有这样的时候，领导让你汇报一下某一项工作的情况，你说完以后感觉领导没有很满意，可能没有直接达到你的汇报目的，或者没有给领导带来什么影响和触动，汇报得不好，还可能让领导质疑你的能力。你不知道该如何汇报，才能让领导更满意，促进达成汇报的目的。更体现出你的思想和能力。接下来的这个片段所讲述的汇报三要素，将提高你的汇报水平，做出一个合格的、让领导更满意的汇报。 \u003c/p>","ratings_count":1,"texts":[{"id":15256,"quote":"\u003cp>接下来请大家阅读我为大家准备的原书片段，阅读完毕之后请举手示意我。\u003c/p>\u003cp>R 原文片段\u003c/p>\u003cp>为什么干了同样的事，别人总能说得天花乱坠\u003c/p>\u003cp>在职场中，有的人会感叹，为什么干了同样的事，自己没话说，别人却能说得天花乱坠，自己干了十分，只能说出五分，别人只干了八分，却能说出十五分呢？那就是因为你没有掌握说话的技巧，没有掌握汇报的技巧。光说不干假把式，光干不说傻把式，既会说又会干才是真把式。毫不夸张地说，及时汇报和在合适的时机汇报，是职场必备的技能之一。\u003cbr> 在现实生活中，你可能经常遇到这样的情况，领导对下属说，“你给我汇报一下情况”，但是下属汇报完了以后领导又总是不满意，这是为什么呢？是因为汇报不完整、不合格，缺少了必备的元素。不完整的汇报，可能是只有观点、缺乏足够的事实；也可能是只有观点没有事实。最常见的不完整的汇报是缺乏建议。汇报不同于讲述、叙述和表达，最与众不同的地方就是要有相应的建议。\u003cstrong>\u003cu>所以，真正合格的汇报必须具备的元素是：有事实、有观点，且要有基于事实和观点的建议。\u003c/u>\u003c/strong>\u003cbr> 合格汇报的3大要素\u003cbr> 汇报的主要构成有三大要素：\u003cstrong>\u003cu>事实、观点和建议\u003c/u>\u003c/strong>，用时比例约为4：2：4。如果是下级向上级汇报，至少要提供两点建议，并预留时间对建议的实施进行一定的预测；更高层的汇报则要求提供落实建议的资源规划内容。\u003c/p>","explains":"\u003cp>我看大家都看完了原文片段，下面我来和大家分享一下我对这段话的解读。\u003c/p>\u003cp>\u003cstrong>【技能点】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【I】拆书家讲解引导-预防异议\u003c/strong>\u003c/p>\u003cp>（一般做法）当我们接到一个汇报的任务的时候，我们通常会给领导汇报一些信息、事件、前因后果等客观事实，亦或是没有客观事实，给领导一些主观的感受和观点。说完以后就等领导决策该怎么办，领导说怎么办我就怎么办，对领导是言听计从。\u003c/p>\u003cp>（后果）没有信息、事件、前因后果等客观事实，领导不容易做出具体的决策，因为决策往往都是要基于客观事实的。\u003c/p>\u003cp>没有基于事实的观点领导不一定清楚这个客观事实，他应该持有什么样的态度和他要做什么方向的决策。\u003c/p>\u003cp>没有建议，领导的决策不一定最合适，因为汇报者才是最了解真实情况的人，汇报者提出的建议才是最具可行性的。汇报者如果想把自己的一些想法付诸实施，得到领导的批准，必须要提出具体如何实施的建议，才能使得你与领导沟通更顺利，达到你的汇报目的，也让领导对你的能力表示肯定。\u003c/p>\u003cp>（反例）举一个例子\u003c/p>\u003cp>在我刚刚做部门经理的时候，有段时间订单特别多，已经基本超过了我们部门可以完成的订单量，部门员工加班加点，我听到了一些怨言，我在给我的领导汇报部门工作情况的时候，我就说我们最近单子多了，比较忙，经常加班，员工有怨言。领导问我，订单增量是多少，员工的加班时数是多少，我答不上来，因为汇报前没有做具体的计算，我说感觉每天都有员工提加班单吧，客观事实没有具体的数据，叙述的很模糊。接着领导问我，有加班，是要加加班工资吗？我才意识到，我没有表达出我的观点，其实我没有想要多给加班工资，我是想既然订单多了，部门定员人数能不能再加一个人，人手多加一个，能缓解实验第一步的限速步骤。我是部门经理，我对这个流程设计人员配备更了解情况。于是，我就提出希望加一个人。领导继续追问我加人了以后会提高多少产能？绩效分配上有没有问题？我给出的回答不是很确切，最终这个事情领导让我再考虑考虑。 \u003c/p>\u003cp>（What）真正合格的汇报必须具备的元素是：有事实、有观点，且要有基于事实和观点的建议及预测。三者缺一不可。\u003c/p>\u003cp>（How）合格汇报三要素具体的做法如下：\u003c/p>\u003cp> 1）陈述事实，要对事实进行收集和筛选，给出具体的信息、数据、前因后果。\u003c/p>\u003cp>2）表达观点，明确自己的汇报目的，提出观点指出需要决策的方向。\u003c/p>\u003cp>3）提出建议，是基于汇报的事实和观点，根据逻辑提出具体的解决方案、建议和预测，是汇报者思维能力的体现，汇报价值的体现。\u003c/p>\u003cp>（反例变正例）\u003c/p>\u003cp>还是刚刚那个想要加人的汇报，我应该按合格汇报三要素法进行汇报。\u003c/p>\u003cp> 1）陈述事实，领导，最近三个月每个月的订单量从80万提高到了120万，增长了30%，从加班单的提交情况来看，我们部门的员工这几个月的加班时数从零提高到了，平均每人每天1小时。\u003c/p>\u003cp>2）表达观点，您看我们部门的定员人数能不能增加一个人。\u003c/p>\u003cp>3）提出建议，从整个实验平台的流程设计上来看如果在第一个环节增加一人，能有效改善第一步的限速制约，产能还能提高10%，人手够了，大家不用因为每天加班影响工作情绪了，对订单的结果分析和进度跟进会更加细致，能减少一部分的失误重复，从而降低成本，绩效上不会因为多一个人分配上少太多。\u003c/p>\u003cp>这样汇报领导可能就更能清晰理解我的汇报目的，沟通更顺畅。\u003c/p>\u003cp> （why好处）汇报三要素法是对上级汇报非常清晰可操作的方法，从事实出发， 给出观点，提出建议。可以促进汇报者汇报前对汇报的内容进行相对全面深入的思考，可以促进汇报目的的达成，体现个人能力。\u003c/p>\u003cp> （where）汇报三要素法可以用于下级对上级的汇报，党员向组织的思想汇报，官员向群众的政府工作汇报等等。平级的汇报属于日常的沟通，可以不用这么严格。\u003c/p>\u003cp> （预防异议）1）有的小伙伴可能会说， 这样三要素汇报太麻烦了，我们之前汇报方式沟通方法，省事多了，事实上，因为没有用这三要素法，我们跟领导之间的反复沟通有异议再沟通再确认，带来的时间，精力要更多，虽然很麻烦，但是用汇报三要素的方法思考和汇报，非常有理有据，是有必要的。\u003c/p>\u003cp> （预防异议）2）有的小伙伴可能会问，那这三要素的顺序可以调换么，事实和观点可以调换，也就是先罗列事实再摆观点，和先摆观点再罗列事实都可以，一般通过受众的情况进行选择，如果受众同意观点的可能性很大，就先表明观点，反之还是先罗列事实，但建议一般还是都放到最后面。\u003c/p>","interaction":"\u003cp>\u003cstrong>【技能点】【A2】分步催化1，运用显像提问法。\u003c/strong>\u003c/p>\u003cp>接下来，我们请大家想象一下，在未来的一周或一个月内，是否有可能会遇到需要作出汇报的情景，向领导请求资源？向领导汇报业绩？向领导汇报培训的效果？等等。。。只要找到这个情景即可，把情景写下来就好了。这个情景要有具体的时间地点待会我会请一个小伙伴来分享一下。请铃铃铃分享一下。\u003c/p>\u003cp>我所想到的具体情境是会向领导汇报新的财年的年度工作计划，新财年是4月1日开始的。\u003c/p>\u003cp>\u003cstrong>【技能点】【A2】分步催化2，引导学习者将刚才记下的情景加工成符合拆页所示方法的例子。\u003c/strong>\u003c/p>\u003cp>大家想到的都跟 工作 有关，这确实是我们汇报三要素法最普遍的应用情景。\u003c/p>\u003cp>接下来我们可以把我们刚才想到的这个情景，加工一下，加工成具体的例子。比如你可以想一想，如果今后，你遇见了这种情景，比如说像刚才铃铃铃分享的这个，你汇报的时候，如何使用今天学习的汇报三要素法，促使汇报目的的达成，请大家小组内分享一下，你针对这个将来可能出现的情景，拟定一段使用汇报三要素的话。\u003c/p>\u003cp>我们的时间是3分钟。还是请铃铃铃分享一下：\u003c/p>\u003cp>1）陈述事实，目前现状的数据，比如说流失率，新进员工的保留率，总结人员状态和诉求。\u003c/p>\u003cp>2）表达观点，针对事实做以下几件事：做一些会议、培训\u003c/p>\u003cp>3）提出建议，希望领导给予我想做的事情予以批准、建议，以及相关的资源支持，预测我做了这些事情以后对我上述的数据有哪些改善。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>感谢铃铃铃找了这样一个适用的情景，用汇报三要素法做一个合格的汇报！\u003c/p>\u003cp>接下来也希望大家可以把它运用到我们的工作生活中，让我们能够更好体现我们的能力和价值，被组织重用和提拔！\u003c/p>\u003cp>这就是我今天分享到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1618195553000,"updated_at":1618909853000,"ria":true},{"id":11150,"topic":"你真的听懂了吗","learn_goal":"","remark":"无","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"余盛莲","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>【自我介绍】 \u003c/p>\u003cp>尊敬的观察家和各位爱学习的小伙伴：大家晚上好！我是余盛莲。用三个标签介绍自己：财务管理，80后宝妈，一级拆书家。今天我给大家分享的主题是《你真的听懂了吗？》 \u003c/p>\u003cp> 【分组】\u003c/p>\u003cp>等一下会有分享讨论环节，我们先来分一下组，一共分为2组，左边3人一组，右边4人一组，左边隆老师担任组长，右边刘老师担任组长，谢谢！\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，当他人与我们理解不一致，发生误会时，能够运用“确认听懂4步法”，倾听对方描述的事实，用对方熟悉的语言诠释观点，让对方接受我们的表达。 \u003c/p>\u003cp>图书介绍（FAB法）\u003c/p>\u003cp>【\u003cstrong>Feature\u003c/strong>】：大家看到我手里拿的这本书《说话的力量》是营销及销售行为专家，高级营销顾问孙路弘的最新作品。本书通过8个说话方法，4个说话技巧，两种实战工具，帮你打造说话的能力。\u003c/p>\u003cp>【\u003cstrong>Advantage\u003c/strong>】：本书是国内首部系统学习说话的实战指南。与其它沟通类书籍相比，并没有过多地强调理论，而是直接把知识转化为行动技能，运用于具体生活和工作的手册。\u003c/p>\u003cp>【\u003cstrong>Benefit\u003c/strong>】：“说话决定发展，说话决定命运“。通过学习本书技能，能够帮助你用共情创造共振，赢得优势地位，把主动权牢牢掌握在自己手中。 \u003c/p>\u003cp>【\u003cstrong>B2\u003c/strong>】：今天这个拆页将教会我们在与他人发生矛盾和误会时，听懂对方的逻辑，通过分析确认，促使双方互相理解，让沟通更加顺畅。\u003c/p>\u003cp>下面请大家花2分钟阅读手中的拆页，读完后请举手示意，谢谢！\u003c/p>","ratings_count":1,"texts":[{"id":15065,"quote":"\u003cp>\u003cstrong>摘自《说话的力量》第七章：解释——P122、123\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学会倾听 远离误解\u003c/strong>\u003c/p>\u003cp>家用电脑刚刚走进中国的时代，我曾在一家公司辅导售后电话支援，当时我就发现与用户沟通中最重要的一点就是听懂对方。\u003c/p>\u003cp>一次，一位用户打电话来说：“我在你们那儿买的电脑，电脑里那个咖啡托盘坏了。”我得\u003cstrong>先让对方知道我听懂了他的话\u003c/strong>：“您在我们这买了一台电脑，我们送了您一个咖啡托盘，那个咖啡托盘坏了，是吗？”用户说不是。我又问：“那您说的咖啡托盘是什么呢？我们卖的是电脑，没卖过咖啡托盘。”用户说：“就是按下电脑键盘就出来的东西，中间还有一个圆圈。您说除了放咖啡，还能放什么呢？我们办公室的同事还把CD盘往里放。”我终于听明白了，他把光驱当成了咖啡托盘。\u003c/p>\u003cp>还有一位用户，他上不了网了，打电话来问我们怎么回事。我问：“您看一下您的猫有什么问题吗？”他说：“你怎么知道我们家有猫？我们家确实养了一只波斯猫，在窗台上呢。”我这样说就没有\u003cstrong>让对方听懂\u003c/strong>，因为对方不一定知道“猫”是什么东西。等你好不容易说清楚了“猫”是什么，接好“猫”以后，问题又来了。我说：“您桌面上有一个‘我的电脑’的图标，看见了吗？”他说：“对，我桌面上是有一个电脑。”我说：“您桌面上还有一个开始键。”他说：“桌面上没开始键，我桌面上就只有一个电脑啊。”这就是没有让用户听懂我的话，因为我没有用他熟悉的术语，他不明白什么是桌面，只明白什么是屏幕，你得跟他说屏幕。“哦，你说的是屏幕啊，我还当你说我们家桌子呢。”争取对方听懂后，还要\u003cstrong>确认对方听懂\u003c/strong>：“我现在说的是屏幕上的东西，你把鼠标往左下角一挪，有一个开始键，看见了吗？”终于他说：“看见了，看见了！”这就叫确认对方听懂 \u003c/p>","explains":"\u003cp>【\u003cstrong>WHAT\u003c/strong>】大家阅读完这个拆页，看到辅导电话服务与客户沟通的两个例子\u003c/p>\u003cp>【\u003cstrong>WHY\u003c/strong>】是不是有“鸡同鸭讲”、“对牛弹琴”的感觉？生活中的很多对话过程，我们会想当然地认为双方互相理解，可是我们理解的和对方想说的却不一定是一回事。听到不等于听懂，中国有句老话：“锣鼓听声，听话听音”你真的听懂了吗？\u003c/p>\u003cp>【\u003cstrong>HOW\u003c/strong>】\u003cstrong>（细化原文步骤）：\u003c/strong>那么到底如何做才能听懂对方呢？通过原文我把它细分为四个步骤： \u003c/p>\u003cp>第1步、倾听：倾听对方描述的事实、细节，听懂对方语言背后的逻辑。\u003c/p>\u003cp>我听到：对方说了\u003cu> \u003c/u> ，他想表达的观点可能是\u003cu> \u003c/u>。\u003c/p>\u003cp>第2步、复述：用自己的话重复对方提出的问题，表示听懂。\u003c/p>\u003cp>运用句式：“你说的是\u003cu> \u003c/u> ，对吗？”\u003c/p>\u003cp>第3步、分析：分析对方已知的内容，用对方熟悉的语言说给对方听，争取让对方听懂。\u003c/p>\u003cp>运用句式：“这是\u003cu> \u003c/u> ，也就是说\u003cu> \u003c/u> 。”\u003c/p>\u003cp>第4步、确认：询问对方是否明白或者认同你的表达，确认对方听懂！\u003c/p>\u003cp>运用句式：“\u003cu>我说明白了吗？”\u003c/u>\u003c/p>\u003cp>当对方点头示意或者用他自己的话重复表达了你的观点，就证明对方听懂了。如果对方的描述跟你的理解仍然不一致，你需要回到第1步重复前面3个步骤。\u003c/p>\u003cp>\u003cstrong>【强调不这么做的坏处\u003c/strong>\u003cstrong>】\u003c/strong>： 生活中经常会出现对话中的一方要求另一方解释某件事的情境，如果没有听懂对方的问题，就会越描越黑，导致双方的关系受到严重影响。\u003c/p>\u003cp>【\u003cstrong>EXAMPLE\u003c/strong>】接下来给大家举一个我工作中的例子：我们酒楼做促销送代金券，零点菜品满200送40，套餐由于原本就是7.5折的价格，所以10桌以下每桌送40，满10桌送1桌。碰巧两家不同消费的客人撞上了，一个零点5000获得代金券1000，一个9桌套餐消费9000获得代金券360，客人李阿姨找到我们：“别人消费5000你送1000，我消费9000你送360，什么意思？”我正好在前台，就运用了今天学习的“确认听懂4步法”倾听李阿姨的问题。\u003c/p>\u003cp>第1步、倾听：我听客人说：“别人消费5000我们送了1000，她消费9000我们送了360”，她想表达的观点可能是我们对待客人有失公平。\u003c/p>\u003cp>第2步、复述：“你说的是她们消费5000送1000，你消费9000，我们送360，你觉得不公平对吗？”\u003c/p>\u003cp>第3步、分析：这是因为你们消费的套餐已经是7.5折的价格，也就是说按零点算，你消费的金额应该是12000元，付了9000，送你360，你一共是节约了3360元。\u003c/p>\u003cp>第4步、确认：“我说明白了吗？”\u003c/p>\u003cp>通过“确认听懂4步法”，倾听，复述，分析，确认，李阿姨高高兴兴地离开了。\u003c/p>\u003cp>【\u003cstrong>WHERE\u003c/strong>】\u003cstrong>：\u003c/strong>这个方法适用于他人对某个问题与我们有不同的看法或者不理解的地方需要我们做出解释的时候。需要注意的是：如果对方带着情绪，需要先处理好情绪。\u003c/p>","interaction":"\u003cp>场景演练：\u003c/p>\u003cp>通过以上的讲解，相信大家都清楚了解了“确认听懂4步法”，倾听，复述，分析，确认。学习将予致用，现在我们来做一个演练，场景是这样的：\u003c/p>\u003cp>小张是移动营业厅业务员，元旦促销小张根据老王家的通讯账单（电视30元，2个电话：通话300分钟近60元，流量10G/30元）推荐老王换了88元的家庭套餐（30G流量+500分钟话费），春节期间老王的孙子天天跟同学煲电话粥、追剧，账单出来（用了40G+900分钟）扣费170多元，老王来找小张赔偿。\u003c/p>\u003cp>老王生气地说：“小张，你说我换了88元的套餐全家都够用，现在一个月用了170多，你要赔我！”\u003c/p>\u003cp>小张：“……”\u003c/p>\u003cp>现在请大家在小组内讨论：小张用“确认听懂4步法”应该如何做呢？请大家两两一组进行演练：一个扮演小张，一个扮演老王，合编一个小剧本写到拆页后面，这边组3个人，其中1人担任观察家。请大家注意：我们演练的目的是练习今天学到的“确认听懂4步法”，所以扮演小张的伙伴一定要用“确认听懂4步法”，现在开始，时间8分钟。请组长帮忙组织一下，谢谢。等一下我会邀请1组小伙伴上来分享。\u003c/p>\u003cp>角色扮演：\u003c/p>\u003cp>好的，大家都演练的差不多了，我们请一组的小伙伴分享一下，你们谁扮演小张，谁扮演老王呢，（巧玉扮演小张，海清扮演老王）\u003c/p>\u003cp>现在开始：\u003c/p>\u003cp>老王生气地来到了营业厅找小张：\u003c/p>\u003cp>老王：“小张，你说我换了88元的套餐全家都够用，现在一个月用了170多，你要赔我！”\u003c/p>\u003cp>小张：“我听王大爷说换了88元的套餐全家都够用，这个月实际扣费170多，他可能是觉得超过88元不能接受！”（第1步：倾听）\u003c/p>\u003cp>小张：“王大爷，你的意思是扣费不应该超过88元，对吗？”（第2步、复述）\u003c/p>\u003cp>老王：“对!”\u003c/p>\u003cp>小张：“这是因为根据你以往的消费情况给你推荐的88元套餐包含30G流量和500分钟，是完全可以覆盖到你以前的消费情况的，这个月的账单呢显示你们用了40G流量和900分钟，也就是说超出来的10G和400分钟是需要单独扣款的！”（第3步、分析）\u003c/p>\u003cp>老王：“也就是说我这个月电话打多了吗？”\u003c/p>\u003cp>小张：“是的，我这样说你清楚了吗？”（第4步：确认）\u003c/p>\u003cp>老王：“清楚了！”\u003c/p>\u003cp>掌声感谢两位小伙伴的分享! \u003c/p>\u003cp>结束语：\u003c/p>\u003cp>通过演练我看到大家都掌握了今天的“确认听懂4步法”倾听，复述，分析，确认，希望大家在今后的工作和生活中多多运用！以上就是我的全部分享内容，感谢各位的配合和聆听，有请主持人!\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1615715852000,"updated_at":1616248564000,"ria":true},{"id":10800,"topic":"表达时的受众分析","learn_goal":"","remark":"在与形形色色的人群交往的时候，可以提前从三个方面对想要表达的对象进行分析，将使对话更轻松的展开，更快建立认同感。","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"于潇潇","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>大家好！我叫于潇潇。\u003c/p>\u003cp>我的三个标签—\u003c/p>\u003cp>第一个：誓要完成三级拆书的拆书小白\u003c/p>\u003cp>第二个：运动达人（游泳、爬山、瑜伽、羽球、室内攀岩、户外）\u003c/p>\u003cp>第三个：绝对吃货（肚皮够大 ，胃口超好，期望广交天下吃友）\u003c/p>\u003cp>今天和大家分享的拆页片段来自—《说话的力量》，是著名营销及销售行为专家孙路弘的最新作品。书中通过8大说话方法、4大说话技巧和两大说话工具给读者提供了实战指南。它不是一本空谈理论的教科书，而是一本能直接运用于具体生活、工作的手册。书中丰富的案例也能让我们能更形象、具体地理解说话的方法、技巧和工具，解决我们在日常人际关系遭遇的困境。\u003c/p>\u003cp>而有关于拆书和拆书帮，我来给新来的伙伴进行一下介绍。\u003c/p>\u003cp>“拆书”是一种学习方法论，使用“RIA便签法”，通过R阅读原书拆页I拆书家讲解引导A学习者拆为己用这三个便签，将内化与应用知识、分析与整理信息、追问与反思经验这三个学习维度提升为解决问题的学习目标，并最终构建出每个人自己的知识体系。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，比如我们现在的拆书帮分舵，是非营利性青年自组织，其使命是“释放学习促进者的能量”，帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":14687,"quote":"\u003cp>在表达中需要提前进行受众分析。分析应该从3个方面展开：\u003c/p>\u003cp>1、分析受众的认知水平。包括受教育程度、文化程度、生活环境以及水平，甚至要了解他们的用语、他们习惯的词汇。\u003c/p>\u003cp>2、分析受众的价值取向。大致的思想境界、意识形态，以及对表达者可能的态度，是敌意还是善意。\u003c/p>\u003cp>3、分析受众的内心期待。就是他们期待听到什么，他们希望通过倾听你的表达有什么收获，是知识方面的还是信息方面的，还是得到启发、增长实际技能等。\u003c/p>\u003cp>分析受众就是从以上3个阶段入手。在收集到的信息不足以支持我们做出判断的情况下，一般采取中等假定，并在开始表达的初期随时观察受众的反应，随之及时调整自己的讲话内容。\u003c/p>","explains":"\u003cp>（why)大家还记得前不久的美国大选吗？总统竞选时会在全国各州对各种不同的人群发表演讲和竞选宣言。他们在面对商业州和农业州，面对黑人白人以及不同种族，面对政客、商人，甚至不同性别的人群时大多会发表不同的说辞。\u003c/p>\u003cp>而在我们的生活中，也都会遇见各种形形色色的人们。他们的年龄不同、文化水平不同、成长经历不同，职业不同，还有民族不同、肤色不同、信仰不同。。如果面对不同的人群，采取同一套说辞来表达自己的观点，势必会有理解不畅的时候。\u003c/p>\u003cp>(what)那面对这么多的自身内在和外在的不同，我们在与对方的交往过程要如何展开对话，让彼此间的沟通更为顺畅和获得他们的认同呢?\u003c/p>\u003cp>这里有个很好的方法，可以在表达中提前从三个方面对于想要表达的对象进行分析，做好分析将有效的帮助我们解决与不同人群打交道时的尴尬感，也将推动更为顺畅的人际交往。\u003c/p>\u003cp>(how)进行受众分析的三个方面是：\u003c/p>\u003cp>第一个方面：了解对方的认知水平。他/她们的教育程度怎么样？生活环境是怎样的？他们的语言是怎样的？有什么特别的表达方式。比如中学生和大学生的认知肯定是不一样的，一个富人和一个穷人看待金钱的态度也是不一样的。\u003c/p>\u003cp>第二个方面：知道对方人群的价值取向和立场。不同的国籍、不同的职业职位都会有自己的生活经验经历，从而对一些事物会有不同看法和不同立场。比如说公司经理在分析处理一些事情时候的方式很可能会跟主管、跟员工不一样。\u003c/p>\u003cp>第三个方面：充分明白对方心里所想所望。他/她们期待什么，通过倾听我们的表达想收获什么？如果你不能充分了解他们的意愿，那么说出的话很可能跟他们的期望不能匹配或达成一致，这样的交谈大多就会遇见瓶颈。\u003c/p>\u003cp>所以在面对公众表达以及熟悉/不熟悉的人员进行沟通和交谈时，我们可以从以上三个方面来进行分解，并根据对方所透露出来的情况来调整自己的说话方式和讲话内容，将会收到更好的反馈效果。\u003c/p>\u003cp>适用边界：基本适用于大多数场合及人群。通过分析对方的情况和期待，将引导谈话往有利于自己的方面进行；并在开始表达的初期观察受众反应来确定谈话方向。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1描述经验：\u003c/strong>\u003c/p>\u003cp>今年疫情期间在家，总公司工厂和长沙公司均不能正常开工。当时外界负面和糟心的消息也很多。时间一长，不确定性增大，人心易涣散。所以作为人事的我在公司群和工厂群里每隔两三天会发送一些正能量的消息，比如如何在家做一些健身运动啊，哪里可以有免费的学习资源啊，推介读些什么电子书啊以及一些好精选公众号推文的。\u003c/p>\u003cp>过了一段时间发现，公司群里时不时会有一些同事反馈或者有个表情冒泡，但是工厂群里基本就是毫无动静，没有任何回应。\u003c/p>\u003cp>反省：\u003c/p>\u003cp>我意识到，为了省事把同样的讯息分发在两个群里是起不到鼓励和抱团的作用的。\u003c/p>\u003cp>一从文化程度出发。公司办公室和工厂人员文化知识面的不同，所以发送同样推文的内容，肯定是不能产生共鸣的。\u003c/p>\u003cp>二从公司和工厂人员所处环境和立场出发。办公室年轻人关心的是业界事件，现阶段能做些什么，公司之后的经营思路和方向会不会因此发生一些变化。而工厂人员承担养家糊口的重担，心里肯定更加盼望和焦急。他们更担心什么时候能复工，会不会给他们生活带来重大变故等。\u003c/p>\u003cp>三从对方的心理期望来说，工人除了想要得到公司准确回复以外，也希望能够有一些切实他们生活的小事件小技巧来吸引注意力和打发时间。\u003c/p>\u003cp>所以后来，我重新挑选了一些内容和信息分别在两个群里进行发送和传达。公司群仍以充实、丰盛自我为主，强调当下大家在家里可以韬光养晦、学习提升自我。而工厂群我会发送一些非疫情的热点小事件、生活小妙招、政府支持返工的利民政策以及时常通报目前厂区道路恢复、审批手续等等情况，让大家尽量安心。并取得一定效果，群内互动和转发消息的也逐步多了起来。\u003c/p>\u003cp>\u003cstrong>A2规划运用：（2分钟）\u003c/strong>\u003c/p>\u003cp>背景：每周六晚上妈妈都会做好美味的晚餐等我回家，然后晚餐之后一起出去散散步聊聊一周的生活，这成为了每周末一个固定的休闲亲情时光。如果我某个周末有事情晚回了或者不回了，妈妈就会开始抱怨：“陪我的时间又少了，就知道自己去玩。”\u003c/p>\u003cp>目标：下周六下班后准备参加一个俱乐部活动，回家肯定又很晚了，需要跟妈妈打“申请报告”，通过对妈妈的分析，我决定采用新的对话方式取得认同。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>1、由于对母上大人的熟悉，采用亲和习惯称呼：“亲爱的娘老子大人，你此刻是不是又趴在沙发上了呀？跟你商量一个事情哈~”（用对方熟悉的词汇和语言）\u003c/p>\u003cp>2、“我明晚要参加一个活动，是有关于培训演讲内容的。我知道这样就不能享受你精心为我准备的晚餐也不能陪你散步了。娘老子你别不开心哈？这也是个难得的机会，而且这次的主题和我目前工作中的困惑也挺贴近的，所以我想能去参加一下。但是这样呢，我明晚可能要11点才能到家了。”等待反应。（站在对方的立场思考，并判断可能有的态度）\u003c/p>\u003cp>3、“作为明晚不能陪你的补偿，我周日晚上就不回自己那边了，仍然可以多陪你一晚，然后周日家务的我都包了，拖地抹桌子擦窗户，有事您说话~”（了解对方的期待，投其所好）\u003c/p>\u003cp>综合应用受众分析三步，虽然是熟悉的亲人，也并非什么要事，但是为了顺畅的取得对方认可，根据对方情况做出一些话语技巧的调整，也将显得更加温婉。\u003c/p>\u003cp>以上就是我拆解片段的全部内容。《说话的力量》之表达时的受众分析，从三个方面出发来调整对话内容，将让我们能更从容的面对不同人员的交往。希望能给大家带来帮助。谢谢~\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1608103141000,"updated_at":1608544870000,"ria":true},{"id":8207,"topic":"用迎合的技巧建立信任","learn_goal":"掌握用迎合的技巧建立信任","remark":"《说话的力量》是国内首部系统学习说话的实战指南。它不是一本空谈理论的教科书，而是一本能直接运用于具体生活、工作的手册。贯穿全书的8大说话方法、4大说话技巧和两大说话工具是作者倾其25年的营销、销售经验的精华之作。书中大量、丰富的案例也都是作者多年来经历过的真实事件，通过这些案例我们能更形象、具体地理解说话的方法、技巧和工具。","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"郭宏江","city":"深圳"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":null,"ratings_count":0,"texts":[{"id":11817,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1561025579000,"updated_at":1561025579000},{"id":8206,"topic":"用迎合技巧建立信任","learn_goal":"在对方愤怒时，使用迎合的技巧，解决存在的误会，缓解对方情绪","remark":"在对方愤怒的时候，使用迎合的方式，解决可能存在的误会，达到缓解对方情绪的效果；组合使用迎合的三种方式，在对方陈述了事实或观点后，解决事实或观点不一致的情况，达到获得他人认同，增进彼此关系的效果。","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"郭宏江","city":"深圳"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":null,"ratings_count":0,"texts":[{"id":11816,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1561025545000,"updated_at":1561025545000},{"id":6585,"topic":"解释是一种说话技能","learn_goal":"在对话中，使用解释的说话方式，消除对话中的误解，维持良好关系","remark":"听的人听完你的话还在期待知道你的原因，你仍然需要进行进一步的解释。 解释是一个说话技能，但到底应该如何解释？","level":"TF2-3","duration":30,"status":30,"type":0,"chaishujia":{"username":"慎蓓","city":""},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"三个标签：80后；湘妹子；静\r\n今晚拆解的片段来自《说话的力量》一书\r\n（F）作者孙路弘，是营销及销售行为专家，高级营销顾问，书中通过8大说话方法、4大说话技巧和两大说话工具给读者提供了实战指南。\r\n（A）本书是国内首部系统学习说话的实战指南。豆瓣评分：7.8分；与大家熟知的《沟通的艺术》对比，作者以西方缜密的思维结合中国本土多变的现实，提出了符合国人的操作性强且可以落实的执行步骤和方法。\r\n（B1）本书可以帮助你在与人交往时，说话更具有逻辑性，建立属于自己的话术体系。\r\n（B2）今晚这个片段是在告诉我们在对话中，一方对问题有不同理解或不清楚的地方时，使用解释的说话方式，可以消除对话中的误解或障碍，维持良好的人际关系。","ratings_count":1,"texts":[{"id":9909,"quote":"\u003cp>我想说一件事，先得了解对方知道哪些事，在他已知部分的基础上，我再跟他说下一件事，最后他跟我确定他听懂了，完整地完成了这样一个过程，才达到了沟通的目的。\u003c/p>\u003cp>生活中需要解释的情况比比皆是。结合上述四个要点，我们来分析下面的例子。\u003c/p>\u003cp>一天，你作为某知名电器品牌的工作人员接待了一位要求退货的顾客。这位顾客生气地说：“我从你们公司买的这台冰箱，刚用了三个月门就总是关不严，冰箱里都结霜了，为了这台破冰箱，我老婆都跟我吵了好几次了！我要求退货！”\u003c/p>\u003cp>现在你就需要做出解释了。首先，你要让对方知道你听懂了。你可以重复他的话：“您是说这台冰箱是从我公司买的，刚用了三个月，门关不严，想退货是吗？”你要先核实上述事实。接下来你就应该问：“您用它做什么了？什么情况下用的？如果真坏了，我们肯定给您退，但是我想了解您都用冰箱装了什么东西？您把冰箱放在家里什么位置了？您能给我讲讲这些细节吗？”\u003c/p>\u003cp>一次，一位用户打电话来说：“我在你们那儿买的电脑，电脑里那个咖啡托盘坏了。”我得先让对方知道我听懂了他的话：“您在我们这买了一台电脑，我们送了您一个咖啡托盘，那个咖啡托盘坏了，是吗？”用户说不是。我又问：“那您说的咖啡托盘是什么呢？我们卖的是电脑，没卖过咖啡托盘。”用户说：“就是按下电脑键盘就出来的东西，中间还有一个圆圈。您说除了放咖啡，还能放什么呢？我们办公室的同事还把CD盘往里放。”我终于听明白了，他把光驱当成了咖啡托盘。\u003c/p>\u003cp>还有一位用户，他上不了网了，打电话来问我们怎么回事。我问：“您看一下您的猫有什么问题吗？”他说：“你怎么知道我们家有猫？我们家确实养了一只波斯猫，在窗台上呢。”我这样说就没有让对方听懂，因为对方不一定知道“猫”是什么东西。等你好不容易说清楚了“猫”是什么，接好“猫”以后，问题又来了。我说：“您桌面上有一个‘我的电脑’的图标，看见了吗？”他说：“对，我桌面上是有一个电脑。”我说：“您桌面上还有一个开始键。”他说：“桌面上没开始键，我桌面上就只有一个电脑啊。”这就是没有让用户听懂我的话，因为我没有用他熟悉的术语，他不明白什么是桌面，只明白什么是屏幕，你得跟他说屏幕。“哦，你说的是屏幕啊，我还当你说我们家桌子呢。”争取对方听懂后，还要确认对方听懂：“我现在说的是屏幕上的东西，你把鼠标往左下角一挪，有一个开始键，看见了吗？”终于他说：“看见了，看见了！”这就叫确认对方听懂。\u003c/p>","explains":"\u003cp>我看大部分伙伴都已经阅读完了，没有读完的也没有关系，我会带着大家一起来解读一下这个片段：\u003c/p>\u003cp>what：解释，是用于解决误解的一种说话技能和方式。当对方和我的“解释”不在同一频道上时，解释的再多反而会加重误会，使双方关系受到严重影响。\u003c/p>\u003cp>why：而一件事需要解释，意味着对话中有一方对问题、意见、话语有不同的理解、不清楚的地方，或者产生了人际互动的障碍。如果此时不做出有效的解释，就会产生误解，甚至引发冲突，造成人际关系的破裂。\u003c/p>\u003cp>where：所以当对话中有一方对问题、意见、话语有不同的理解、不清楚的地方，或者产生了人际互动的障碍时，我们又想维持良好的人际关系时，就需要解释的说话技能了。\u003c/p>\u003cp>how：到底要如何来解释呢？我根据原文的片段提炼出了具体的行动步骤：\u003c/p>\u003cp>1、表示听懂：让对方知道我听懂了他所说的话，可以用自己的话重述一遍对方所表达内容的理解。\u003c/p>\u003cp>开场白句式参考：您是说。。。您刚说的是。。。。您的意思是+自己对对方所表达内容的理解\u003c/p>\u003cp>大家看到片段中的第一个案例，开场说了：您是说，后面接的就是这位工作人员从顾客所说的话中提炼出了自己的理解，而不是原原本本的重复一遍。\u003c/p>\u003cp>2、了解对方：了解对方能听懂什么，对什么事情比较熟悉\u003c/p>\u003cp>就如案例1中，工作人员核实信息所问出的问题，你可以看做是核实，也可以看做在收集对方已知的信息，从对方的表达中找出对方熟悉的话术或者是说话方式；想要了解对方知道哪些事情，熟悉哪些术语，我们可以采用提问的方式，我想问问大家还有什么方式呢？（提问）\u003c/p>\u003cp>学习者回应：可以提取信息中的关键字\u003c/p>\u003cp>补充：也可以根据对方的职业背景，过往经历等，如果能说的明白，也可以直接用最通俗易懂的话来跟对方说明。\u003c/p>\u003cp>3、清楚解释：第2步中了解到的对方熟悉的话语、术语了，那么我们就需要用对方熟悉的话语、术语来进行解释对方遇到的问题或对方不理解，不清楚的名词\u003c/p>\u003cp>4、确认听懂：确认对方听懂了我的表达\u003c/p>\u003cp>当我表达完后，对方明显表示：我听懂了，明白了，问题解决了。。。。。等明确的话语时，就表示对方真的听懂了。只是点头或者摇头这些就都不算。\u003c/p>\u003cp>不这么做的坏处：\u003c/p>\u003cp>当对方不是很清楚我们所表达的内容时，我们不用解释的这种说话技能与对方去沟通时，在沟通的过程中，很有可能出现尴尬的境况，又或者变成鸡同鸭讲，完全不在一个频道上，费时又费力。\u003c/p>\u003cp>举例：\u003c/p>\u003cp>最近我公司上了一款新产品，价格比较贵，我深圳的客户杨先生就打电话来问我：\u003c/p>\u003cp>杨先生：这个产品怎么这么贵，我看跟其他的产品也没什么区别啊，是不是价格搞错了？\u003c/p>\u003cp>我：（为了表示我听懂了）您刚刚是说这款产品看起来跟其他产品没什么区别，价格却贵了，觉得价格弄错了，是吗？\u003c/p>\u003cp>杨先生：对啊。你赶紧跟公司确认下。\u003c/p>\u003cp>我：（第一次解释）新产品的后摄像头是HUD高清的，其他的产品都是模拟的，当然要贵一些啦。\u003c/p>\u003cp>杨先生：看起来都一样啊。\u003c/p>\u003cp>这个时候我就发现他可能不是很明白什么是HUD，模拟这些概念。根据今天的片段，我知道我需要用对方熟悉的话语来解释。我想到他曾经跟我提到过夜视效果的产品，那我想他肯定明白夜视这个概念（这是我根据过往经历了解对方知道哪些事）\u003c/p>\u003cp>我：（用对方熟悉的话语，进行了第二次的解释。）新产品的后镜头是有夜视效果的，就是你前几天提到的那种夜视，其他的产品都没有这种效果。\u003c/p>\u003cp>杨先生：哦，那我明白了，那让公司赶紧把新品给做出来、\u003c/p>\u003cp>（当她催促我做出产品时，我就确认到对方听懂了我想要表达的）\u003c/p>","interaction":"\u003cp>给出具体的场景：\u003c/p>\u003cp>请各位伙伴设想这样一个场景：\u003c/p>\u003cp>小王的妈妈生日到了。小王买了部最新款的手机给妈妈做生日礼物。妈妈拿到手机后，说了一句：我有手机啊，还买来干嘛？看起来跟我之前的也没啥区别啊。\u003c/p>\u003cp>指令：\u003c/p>\u003cp>请大家按照设定的场景，在小组内讨论出一个小剧本，如果你是小王，你将如何运用我们刚学到的解释的方式对妈妈进行解释说明呢？\u003c/p>\u003cp>我们先来回顾下解释的步骤\u003cbr>1、表示听懂\u003c/p>\u003cp>2、了解对方\u003c/p>\u003cp>3、清楚解释\u003c/p>\u003cp>4、确认听懂\u003c/p>\u003cp>请大家根据解释的这个步骤及设定的场景，进行讨论，将你们的对话，在纸上写下来，并进行演练，这里我说明白了么？5分钟之后，我会邀请两位伙伴到我们现场来演练一下，你们所写的剧本。\u003c/p>\u003cp>注意事项：我们现场是演练解释这种对话的技能，而不是来解决问题的。\u003c/p>\u003cp>好的，大家现在可以开始了。\u003c/p>\u003cp>学习者案例分享：\u003c/p>\u003cp>你们谁扮演小王，谁扮演小王的母亲呢？\u003c/p>\u003cp>学习者胡敏新扮演小王；学习者王晓静扮演小王的母亲\u003c/p>\u003cp>（胡敏新）小王：妈，给你买了一部手机\u003c/p>\u003cp>（王晓静）小王的母亲：我有手机，为什么要买呢？浪费钱\u003c/p>\u003cp>（胡敏新）小王：这个性能会好一点，屏幕会大一点，容量会大一点\u003c/p>\u003cp>（王晓静）小王的母亲：屏幕大，不也会看到你嘛\u003c/p>\u003cp>（胡敏新）小王：但是它的字也会大一点啊，看的也会清晰一点\u003c/p>\u003cp>（王晓静）小王的母亲：那我调手机字号就好了\u003c/p>\u003cp>（胡敏新）小王：那个容量会更大一点，你能存放更多的歌，比如说啊，你要跳跳广场舞什么的，就可以装很多东西，比之前那个性能要好一些\u003c/p>\u003cp>（王晓静）小王的母亲：它可以下很多很多歌对吧\u003c/p>\u003cp>（胡敏新）小王：对对对，就是能下很多歌\u003c/p>\u003cp>学习者王晓静：我们讨论的点有2点：\u003c/p>\u003cp>1、要跟母亲说的是手机容量更大，如果从16G到32G她可能不懂什么意思，我们解释的点就是母亲喜欢听歌，那就告诉她，你有了这个手机后，可以存储更多的歌在里面，从能存1首歌到很多首歌，她可能更容易理解一点；\u003c/p>\u003cp>2、屏幕大：我们就用字体大来说明\u003c/p>\u003cp>学习者胡敏新：当母亲说到能下很多歌的时候，我就知道她听懂了我所想表达的。\u003c/p>\u003cp>回应：非常感谢你们，我没有想到，容量可以用这样的方式来表达，太谢谢你们了。\u003c/p>\u003cp>结束：在我们的生活中，常常会出现别人要求你解释某件事，或者你要求别人解释某件事的情境时，好好掌握解释的说话方式时，消除对话的误解或障碍，维持良好的人际关系。\u003c/p>\u003cp>我今天的分享就到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1543287726000,"updated_at":1543287726000,"ria":true},{"id":6403,"topic":"解释也是一种说话技能","learn_goal":"在对话中，一方对问题有不同理解的地方使用解释技巧，消除误解","remark":"","level":"TF2-3","duration":25,"status":29,"type":0,"chaishujia":{"username":"慎蓓","city":""},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"三个标签：不吃辣的湘妹子；10；慢。\r\n今晚拆解的片段来自《说话的力量》一书\r\n（F）作者孙路弘，是营销及销售行为专家，高级营销顾问，书中通过8大说话方法、4大说话技巧和两大说话工具给读者提供了实战指南。\r\n（A）与《沟通的艺术》这本书对比，作者以西方缜密的思维结合中国本土多变的现实，提出了符合国人的操作性强且可以落实的执行步骤和方法。\r\n（B1）本书可以帮助你在与人交往时，说话更具有逻辑性，建立属于自己的话术体系。\r\n（B2）今晚这个片段是在告诉我们，在对话中，一方对问题有不同理解或不清楚的地方时，使用解释的说话方式，可以消除对话中的误解或障碍，维持良好的人际关系。","ratings_count":1,"texts":[{"id":9704,"quote":"\u003cp>我想说一件事，先得了解对方知道哪些事，在他已知部分的基础上，我再跟他说下一件事，最后他跟我确定他听懂了，完整地完成了这样一个过程，才达到了沟通的目的。\u003c/p>\u003cp>生活中需要解释的情况比比皆是。结合上述四个要点，我们来分析下面的例子。\u003c/p>\u003cp>一天，你作为某知名电器品牌的工作人员接待了一位要求退货的顾客。这位顾客生气地说：“我从你们公司买的这台冰箱，刚用了三个月门就总是关不严，冰箱里都结霜了，为了这台破冰箱，我老婆都跟我吵了好几次了！我要求退货！”\u003c/p>\u003cp>现在你就需要做出解释了。首先，你要让对方知道你听懂了。你可以重复他的话：“您是说这台冰箱是从我公司买的，刚用了三个月，门关不严，想退货是吗？”你要先核实上述事实。接下来你就应该问：“您用它做什么了？什么情况下用的？如果真坏了，我们肯定给您退，但是我想了解您都用冰箱装了什么东西？您把冰箱放在家里什么位置了？您能给我讲讲这些细节吗？”\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;一次，一位用户打电话来说：“我在你们那儿买的电脑，电脑里那个咖啡托盘坏了。”我得先让对方知道我听懂了他的话：“您在我们这买了一台电脑，我们送了您一个咖啡托盘，那个咖啡托盘坏了，是吗？”用户说不是。我又问：“那您说的咖啡托盘是什么呢？我们卖的是电脑，没卖过咖啡托盘。”用户说：“就是按下电脑键盘就出来的东西，中间还有一个圆圈。您说除了放咖啡，还能放什么呢？我们办公室的同事还把CD盘往里放。”我终于听明白了，他把光驱当成了咖啡托盘。\u003c/p>\u003cp>&nbsp; &nbsp; 还有一位用户，他上不了网了，打电话来问我们怎么回事。我问：“您看一下您的猫有什么问题吗？”他说：“你怎么知道我们家有猫？我们家确实养了一只波斯猫，在窗台上呢。”我这样说就没有让对方听懂，因为对方不一定知道“猫”是什么东西。等你好不容易说清楚了“猫”是什么，接好“猫”以后，问题又来了。我说：“您桌面上有一个‘我的电脑’的图标，看见了吗？”他说：“对，我桌面上是有一个电脑。”我说：“您桌面上还有一个开始键。”他说：“桌面上没开始键，我桌面上就只有一个电脑啊。”这就是没有让用户听懂我的话，因为我没有用他熟悉的术语，他不明白什么是桌面，只明白什么是屏幕，你得跟他说屏幕。“哦，你说的是屏幕啊，我还当你说我们家桌子呢。”争取对方听懂后，还要确认对方听懂：“我现在说的是屏幕上的东西，你把鼠标往左下角一挪，有一个开始键，看见了吗？”终于他说：“看见了，看见了！”这就叫确认对方听懂。\u003c/p>","explains":"\u003cp>我看大部分伙伴都已经阅读完了，没有读完的也没有关系，我会带着大家一起来解读一下这个片段：\u003c/p>\u003cp>what：解释，是用于解决误解的一种说话技能和方式。当对方和我的“解释”不在同一频道上时，解释的再多反而会加重误会，使双方关系受到严重影响。\u003c/p>\u003cp>why：而一件事需要解释，意味着对话中有一方对问题、意见、话语有不同的理解、不清楚的地方，或者产生了人际互动的障碍。如果此时不做出有效的解释，就会产生误解，甚至引发冲突，造成人际关系的破裂。\u003c/p>\u003cp>where：所以当对话中有一方对问题、意见、话语有不同的理解、不清楚的地方，或者产生了人际互动的障碍时，我们又想维持良好的人际关系时，就需要解释的说话技能了。\u003c/p>\u003cp>how：到底要如何来解释呢？我根据原文的片段提炼出了具体的行动步骤：\u003c/p>\u003cp>1、让对方知道我听懂了他所说的话：\u003c/p>\u003cp>用自己的话重述一遍对方所表达内容的理解。\u003c/p>\u003cp>开场白句式参考：您是说。。。您刚说的是。。。。您的意思是+自己对对方所表达内容的理解\u003c/p>\u003cp>大家看到片段中的第一个案例，开场说了：您是说，后面接的就是这位工作人员从顾客所说的话中提炼出了自己的理解，而不是原原本本的重复一遍。\u003c/p>\u003cp>2、了解对方能听懂什么，对什么事情比较熟悉\u003c/p>\u003cp>就如案例1中，工作人员核实信息所问出的问题，你可以看做是对信息进行核实，也可以看做在收集对方已知的信息，从对方的表达中找出对方熟悉的话术或者是说话方式；案例2就是很明显的反例，对不对。\u003c/p>\u003cp>想要了解对方知道哪些事情，熟悉哪些术语，我们可以采用提问的方式，也可以根据对方的职业背景，过往经历等，如果能说的明白，也可以直接用最通俗易懂的话来跟对方说明。\u003c/p>\u003cp>3、用对方熟悉的话语、术语来解释对方遇到的问题或对方不理解，不清楚的名词\u003c/p>\u003cp>以确保对方能听懂我的解释\u003c/p>\u003cp>4、确认对方听懂了我的表达\u003c/p>\u003cp>当我表达完后，对方明显表示：我听懂了，明白了，问题解决了。。。。。等明确的话语时，就表示对方真的听懂了。只是点头或者摇头这些就都不算。\u003c/p>\u003cp>预防异议：\u003c/p>\u003cp>有些伙伴可能会说：\u003c/p>\u003cp>如果有些人他明明没有听懂，他却说他听懂了，明白了，这种情况如何确认呢？\u003c/p>\u003cp>在这种情况下，如果你想确认对方是否真的听懂了，你可以让对方来重述一下你所解释的内容，并让对方解释下他行为的原因，相当于再重复一个复述和解释的过程。\u003c/p>\u003cp>举例：\u003c/p>\u003cp>最近我公司上了一款新产品，价格比较贵，我深圳的客户杨先生就打电话来问我：\u003c/p>\u003cp>杨先生：这个产品怎么这么贵，我看跟其他的产品也没什么区别啊，是不是价格搞错了？\u003c/p>\u003cp>我：（为了表示我听懂了）您刚刚是说这款产品看起来跟其他产品没什么区别，价格却贵了，觉得价格弄错了，是吗？\u003c/p>\u003cp>杨先生：对啊。你赶紧跟公司确认下。\u003c/p>\u003cp>我：（第一次解释）新产品的后摄像头是HUD高清的，其他的产品都是模拟的，当然要贵一些啦。\u003c/p>\u003cp>杨先生：看起来都一样啊。\u003c/p>\u003cp>这个时候我就发现他可能不是很明白什么是HUD，模拟这些概念，我想到他曾经跟我提到过夜视效果的产品，那我想他肯定明白夜视这个概念（这是我根据过往经历了解对方知道哪些事）\u003c/p>\u003cp>我：（用对方熟悉的话语，进行了第二次的解释。）新产品的后镜头是有夜视效果的，就是你前几天提到的那种夜视，其他的产品都没有这种效果。\u003c/p>\u003cp>杨先生：哦，那我明白了，那让公司赶紧把新品给做出来、\u003c/p>\u003cp>（这个时候我就确认到对方听懂了我想要表达的）\u003c/p>","interaction":"\u003cp>\u003cstrong>给出具体的场景：\u003c/strong>\u003c/p>\u003cp>请各位伙伴设想这样一个场景：\u003c/p>\u003cp>小王的妈妈从老家过来照顾小王的生活起居。早上小王跟妈妈一块吃早餐的时候，小王跟妈妈说晚上要去参加拆书帮的活动，不回来吃饭了。妈妈听后问了一句：你加入了什么帮派啊？不是黑社会吧？&nbsp;\u003c/p>\u003cp>指令：\u003c/p>\u003cp>请大家按照设定的场景，在小组内讨论出一个小剧本，如果你是小王，你将如何运用我们刚学到的解释的方式对妈妈进行解释说明呢？\u003c/p>\u003cp>1、让对方知道我听懂了他所说的话：\u003c/p>\u003cp>用自己的话重述一遍对方所表达内容的理解。\u003c/p>\u003cp>开场白句式参考：您是说。。。您刚说的是。。。。您的意思是+自己对对方所表达内容的理解\u003c/p>\u003cp>2、了解对方能听懂什么，对什么事情比较熟悉\u003c/p>\u003cp>我们可以采用提问的方式，也可以根据对方的职业背景，过往经历等，如果能说的明白，也可以直接用最通俗易懂的话来跟对方说明。\u003c/p>\u003cp>3、用对方熟悉的话语、术语来解释对方遇到的问题或对方不理解，不清楚的名词\u003c/p>\u003cp>以确保对方能听懂我的解释\u003c/p>\u003cp>4、确认对方听懂了我的表达\u003c/p>\u003cp>请大家根据解释的这个步骤及设定的场景，进行讨论，在纸上写下你们对话，并进行演练。\u003c/p>\u003cp>这里我说明白了么？4分钟之后，我会邀请两位伙伴到我们现场来演练一下，你们所写的剧本。\u003c/p>\u003cp>注意事项：我们现场是演练解释这种对话的技能，而不是来解决问题的。\u003c/p>\u003cp>好的，大家现在可以开始了。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>你们谁扮演小王，谁扮演小王的母亲呢？\u003c/p>\u003cp>（学习者苏武林扮演小王、陈昭光扮演小王的母亲）\u003c/p>\u003cp>小王：今天晚上我们要去参加拆书帮的活动\u003c/p>\u003cp>小王的母亲：什么帮？不是什么黑社会组织吧？\u003c/p>\u003cp>（拆书家引导：第2步先复述一下妈妈的话）\u003c/p>\u003cp>小王：您是说拆书帮是一个黑社会性质的组织吗？\u003c/p>\u003cp>小王的母亲：是啊，一般帮都不是什么不太好的吧，是法轮功之类的啊。\u003c/p>\u003cp>（拆书家引导：这个时候可以想到妈妈平时对什么比较熟悉和了解）\u003c/p>\u003cp>小王旁白：妈妈可能对我那些的大学的社团比较了解，我可以通过这个去跟她解释一下。\u003c/p>\u003cp>小王：其实拆书帮有点类似于大学生的那种社团，帮助我们学习拆书技能的。\u003c/p>\u003cp>小王的母亲：有老师吗？\u003c/p>\u003cp>小王：有老师的。我们是师徒制的。\u003c/p>\u003cp>小王的母亲：像那种社团一样的，帮我们学习的。\u003c/p>\u003cp>（拆书家引导：最后确认一下）\u003c/p>\u003cp>小王：那您有了解到这个拆书帮嘛？\u003c/p>\u003cp>小王的母亲：嗯嗯，了解，那应该就是一种社团了。\u003c/p>\u003cp>结束：在我们的生活中，常常会出现别人要求你解释某件事，或者你要求别人解释某件事的情境时，好好掌握解释的说话方式时，消除对话的误解或障碍，维持良好的人际关系。\u003c/p>\u003cp>我今天的分享就到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1541470203000,"updated_at":1541470203000,"ria":true},{"id":6354,"topic":"如何用触动人心的事实传达观点","learn_goal":"通过有利的事实来传递自己的观点","remark":"孙路宏先生关于说话的方法总结","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"绿竹","city":"厦门"},"club":{"name":"厦门鹭见欢喜分舵","city":"厦门"},"prologue":"\u003cp>\u003cstrong>&nbsp; &nbsp;自我介绍：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 大家下午好。我是丽华，美丽中华的丽华。接下来我用三个标签来介绍一下自已：第一个标签：HR,我目前是一家企业的HR负责人，工作十几年，秉承着专业的人做专业的事。其次，内心一直期望自已能做一个美丽而有才华的人，为了成为更好的自已而学习了礼仪，并且希望把自已所学的知识分享给大家，所以第二个标签是形象礼仪讲师，并在今年申请了自已的版权课程《服务至上，礼仪为王》，《三字经》里说到：为人子，方少时，亲师友，习礼仪。学礼、懂礼、传播礼仪是我的最终目标。第三个标签是，绿竹，这是我的网名，翠绿色的竹子的意思，竹子用了4年的时间，仅仅长了3cm，在第五年开始，以每天30cm的速度疯狂的生长，仅仅用了六周的时间就长到了15米。其实，在前面的四年，竹子将根在土壤里延伸了数百平米。这也是我做人做事的准则。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;分 组：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 接下来为了增强学员之间的交流和互动，我们按照人数，3-4个人一组。组内成员可以微笑或握手相互问好。&nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>&nbsp;图书介绍：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;这本《说话的力量》营销及销售行为专家孙路弘的作品，是国内首部系统学习说话的实战指南，是一本能够直接运用于具体生活、工作的手册。\u003c/p>\u003cp>&nbsp; &nbsp; 作者在书中用8大说话方法，4大说话技巧，两大说话工具，详细的解读了如何说话，读者可根据书中的练习题，坚持练习在平时工作、生活、学习中不断利用各种身边的机会来练习，那么所得到的不仅仅是沟通能力上的提高。随着对说话次序的把握，对事实与观点的透彻思才以及不断扒测听者的疑问，将大大提高说话的条理性，使得更多的人容易理解你的意图 ，从而提高你的影响力。\u003c/p>\u003cp>&nbsp; &nbsp; \u003cstrong>学习目标：\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;今天大家跟随我完成本次RIA现场学习后，大家在叙述时能通过有利的事实来传递自已观点，并因此让对方通过这些事实认同自己的观点。\u003c/p>","ratings_count":1,"texts":[{"id":9651,"quote":"\u003cp>\u003cstrong>《用触动人心的事实传达观点》\u003c/strong>\u003c/p>\u003cp>【叙述】\u003c/p>\u003cp>\u003cstrong>通过对事实的筛选，将事实按次序讲给别人，有目的的影响别人，使得别人接受你的看法和观点，影响他所得出的结论，进而影响他的行为，这就是叙述。&nbsp;\u003c/strong>\u003c/p>\u003cp>&nbsp;在电影《黑客帝国2》中，面临逼近的电脑乌贼大军，人类的领袖墨菲斯对聚集在一起的人类发表了一段震撼人心的战前动员。他是这样说的：\u003c/p>\u003cp>锡安的同胞们！听我说。你们所听说的大部分都是真的，电脑召集的机器兵团，正在逼近我们的家园，我们将有一场艰辛的硬战要打。\u003c/p>\u003cp>想要贏得这场战争的胜利，首先要斩除内心的恐惧。我现在站在这里，心中毫无惧意！为什么?是因为我跟你们有着不同的信念吗?不是！\u003c/p>\u003cp>我能无惧地站在这里是因为我记得，我记得我之所以能在这里，不是因为遵从前人所铺下的路，而是因为相信自己能创造属于我们的未来。我记得我们跟这些机器对抗了百余年，我记得这百余年来，它们不停地派军队来企图消灭我们。经过了这一个世纪的战争，我记得最重要的一件事是，我们依然活着\u003c/p>\u003cp>今晚，让我们向机器兵团宣战！今晚，让这里因我们而震动起来！今晚，让这儿的大地，钢铁与石头都因我们而颤抖！让我们的呐喊由火红的地底，直达乌黑的天上去！今晚，我们要让它们记得这就是锡安！而我们无所畏惧！\u003c/p>\u003cp>在影片中，墨菲斯的战前动员引发了人们的欢呼，激昂的斗志。而对在影院中观看电影的观众来说，这段精彩的的出电影带入了一个高潮。这就是说话的第二个基本功，叙述的的力量。\u003c/p>\u003cp>墨菲斯的这段演讲为什么触动人心?为什么能收到如此良好的效果，鼓舞了人们的斗志?\u003c/p>\u003cp>首先，墨菲斯在叙述之前是对事实进行了筛选的。\u003cstrong>当你有一个明确的看法、试图影响对方的时候，要把一些对你不利的、与你看法不一致的事实屏蔽掉，也就是筛选事实。\u003c/strong>\u003c/p>\u003cp>百余年中可能发生了很多事情，比如可能实际上一年中有半年的时间是不打仗的，不打仗的时候虽然人们过得不自由但还是安于现状的，比如反抗者们以血肉之躯对抗钢铁机器可能死得非常惨，等等。但在现在这个时刻，墨菲斯不会叙述这些事实，而是选择了如下事实：电脑召集的机器兵团逼近了(现在我们别无选择)；我们跟机器对抗了百余年(我们已经受压迫百余年了)；百年来机器不停派军队企图消灭我们(人为刀俎，我为鱼肉)；我们还活着(我们活到现在不容易，也许这是最后的机会了)。\u003c/p>\u003cp>其次，他通过这些事实表达了自己的观点：我们要向机器兵团宣战；我们要消灭敌人；我们要无所畏惧。如果你是片中的幸存人类，通过墨菲斯已经筛选过然后传达给听者的事实，你是不是也会觉得他的观点有着非常充分的理由?我们已经被电脑压迫一百多年了，现在背水一战，别无选择，我们必须无所畏惧地消灭敌人。\u003c/p>\u003cp>\u003cstrong>叙述\u003c/strong>\u003cstrong>=\u003c/strong>\u003cstrong>事实\u003c/strong>\u003cstrong>+\u003c/strong>\u003cstrong>观点\u003c/strong>\u003c/p>\u003cp>叙述仍然将重点放在“述”上，但是是规划过的“述”，是在大量的事实基础上筛选后按照一定的思路讲出来的，而不是简单下一个主观结论。\u003cstrong>所以叙述等于事实加观点，讲述的重点是事实，而叙述要求你对事实进行筛选。\u003c/strong>\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;原书拆页用了电影《黑客帝国》墨菲斯的战前动员精彩演讲做为案例，提出了说话的第二个基本功，叙述的力量，并给叙述和讲述做了区别。叙述是要求你讲完事实以后，还要概括出自己的观点，对事实进行筛选，要把一些对自己不利的、与自己看法不一致的事实屏蔽掉。叙述将重点放在述上，但是他规划过的述，是在大量事实基础上筛选后按照 一定思路讲出的，而不是简单下一个主观结论，所以叙述等于事实加观点，并且说叙述要求你对事实进行筛选。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;案例：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;例如你的老板想向你了解新进的财务总监入职以来的工作表现情况，那么你应该如何汇报呢？你应该就财务总监对部门工作的统筹计划，人员安排、成本节约，跨部门沟通等各方面的事实筛选后进行汇报。“总裁，吴总入职后对部门人员工作进行了梳理，并重新制定了岗位职责，要求财务经理对每个员工新的工作职责进行跟踪，并针对员工实际情况进行调整。使部门的工作效率大大的提高了，所以目前来看财务吴总工作能力是很不错的，也能胜任这个部门负责人的工作”。“嗯，看来吴总工作能力还可以，不错“。我先用了事实描述了财务总监工作近况， 最后通过有利的事实来总结自己的观点，表达了我认为新来的财务总监能胜任这个工作的观点，并且让老板认同我的观点。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp;激活经验：\u003c/strong>通过刚才拆页的学习，了解如何更好的叙述，在你们的工作和生活中，有没有经历过类似的情境或者有没有相关经验的分享，将有利事实进行筛选后表达从而传递自己的观点。大家用5分钟的时间进行小组内分享，结束后我们邀请每组一位伙伴代表进行分享。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; \u003cstrong>&nbsp;学习者分享：\u003c/strong>我们公司产品，是做威固汽车隔热膜，有次客户李女士咨询产品，问到这产品质量怎样？我当时和客户这样说，十年前我的客户陈先生买的宝来车，来店里贴了全车顶级威固膜，贴完后，陈先生反馈隔热效果确实好，十年后的2017年，陈先生换新车奔驰，又来我店里贴全车膜，当时我问陈先生，宝来车还有开嘛？他说，偶尔会开下，我问他隔热效果怎样，陈先生说，如果十年前隔热效果是10分，现在坐在车里，感觉隔热效果是8分。十年从10分到8分，威固顶级隔热膜隔热效果性能稳定，质量有保证，你可以放心购买。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp; 拆书家反馈：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;感谢这位小伙伴的分享，小伙伴将本拆知识运用在产品销售中，通过有利的事实十年间隔热效果的稳定性，传达了产品质量的可靠，客户可以放心购买。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; 催化应用：\u003c/strong>通过这次的拆页学习，了解到成功叙述是说话的一项基本功，日常生活中以及每天的实际工作中，说话是日常的事情，在未来的生活和工作过程，你可以应用在哪些场景中，现在用2分钟时间在便签纸上写下各自的应用或行动步骤。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp;学习者分享：\u003c/strong>在未来一周客户咨询产品时，使用叙述表达方式，\u003c/p>\u003cp>（1）选择有利事实:针对产品特性，防晒美白，隔热，节油等特性，选择匹配有利的案例事实。\u003c/p>\u003cp>（2）传递观点:威固隔热膜质量有保证，放心购买。\u003c/p>\u003cp>这样，当客户咨询时，我就先说匹配的有利事实，在说，我的观点，威固膜质量好，放心购买。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;\u003cstrong>&nbsp;拆书家反馈：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;感谢这位小伙伴的分享，大家最终要将写在便签的行动计划付出实际，我今天的拆书到此结束，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1540821317000,"updated_at":1540860373000,"ria":true},{"id":6306,"topic":"三个铺垫方法，沟通更顺畅","learn_goal":"掌握说话的铺垫的方法，并能在现场运用演练出来 ","remark":"学习如何运用铺垫子的方法创造舒服的说话环境，提升我们的对话质量","level":"TF2-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"扫地僧  王伟","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"\u003cp>&nbsp; &nbsp; 大家好，欢迎来到拆书帮的活动现场。我是今天的拆书家王伟，我的三个标签是培训师、正面管教讲师、超级奶爸，现在我来为大家做一个分组：左边 小伙伴为一组，右边 小伙伴为一组。让我们一同学习、一起成长！\u003c/p>\u003cp>\u003cstrong>&nbsp;\r\n一、【学习目标】\u003c/strong>（0.5）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;在跟随我完成本场学习之后，学习者能够掌握说话时铺垫子的方法，并且能在现场运用演练出来。\u003c/p>\u003cp>\u003cstrong>&nbsp;二、【图书介绍】\u003c/strong>（3分钟）\u003c/p>\u003cp>\u003cstrong>&nbsp;F 特征（核心是“书”，用于满足好奇心）：\u003c/strong>我今天拆解的片段是来自孙路弘著作的《说话的力量》。他是营销及销售行为专家，高级营销顾问。本书通过8大说话方法、4大说话技巧和两大说话工具给读者提供了实战指南。\u003c/p>\u003cp>\u003cstrong>&nbsp;A 优势（重点是“比较”，用于建立安全感）：\u003c/strong>这是国内首部系统学习说话的实战指南。它不是一本空谈理论的教科书，而是一本能直接运用于具体生活、工作的手册。书中大量、丰富的案例也都是孙路弘25年来经历过的真实事件，通过这些案例我们能更形象、具体地理解说话的方法、技巧和工具。\u003c/p>\u003cp>\u003cstrong>&nbsp;B 利益（强调的是“学习者”的利益，用于引发兴趣）\u003c/strong>如果你说话时常常表现出如下问题，说话时间短，不会充分利用别人给你的时间；说话内容缺乏逻辑性，东一榔头西一棒子；那么你一定要读这本书！找工作屡屡受挫，长时间不能升职，团队关系紧张，家庭关系疏离——如果你正在遭遇这样的困境，那么你更要读这本书！提高说话技能，让说话改变你的人生轨迹。\r\n &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;请大家阅读刚刚发到手上的原文拆页，并按照箭头指示的方向进行阅读。时间为2分钟，阅读完的小伙伴请举手示意一下。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":9597,"quote":null,"explains":"\u003cp>\u003cstrong>四、【I】拆书家讲解引导（\u003c/strong>\u003cstrong>4\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>好的。有时候，我们会面临一些比较严肃的沟通场景或棘手的提问，持续的严肃问答会使沟通者之间的关系变得紧张，适时的巧妙的加上垫子，可以使沟通更加顺畅，在问答过程里，\u003cstrong>“垫子”就是一层缓冲。它既能避免生硬的一问一答造成对立情绪，\u003c/strong>又可以为自己寻找如何应答争取到宝贵时间。铺垫子的常用的三个方法是：\u003c/p>\u003cp>\u003cstrong>1. “赞美垫”，赞扬别人问得好\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;‘’赞美垫‘’的方法根基是表扬别人，但也不能老说“你的这个问题问得好”。这就需要根据具体的情况衍生一些接地气的变种。\u003c/p>\u003cp>比如提问的是一个硕士研究生，你就可以说：这个问题也就你这样水平的人才问得出来。\u003c/p>\u003cp>比如“你这个问题一下子就问到点子上了。”\u003c/p>\u003cp>“你这个问题很专业。”\u003c/p>\u003cp>\u003cstrong>2. “多人垫”，承认对方的问题很多人都问过\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;如果说‘’赞美垫‘’多适用于晚辈，那‘’多人垫‘’在平辈间的使用效果是极好的。\u003c/p>\u003cp>你可以说，“你这个问题问得很有深度，这可是MBA的课程里才会涉及到的。”对方分分钟被抬高的感觉有木有？\u003c/p>\u003cp>比如“您这个问题昨天有三个签约的客户都问了。”\u003c/p>\u003cp>“您的这个问题是我们售后服务工程师不断要求我们熟悉的问题。”\u003c/p>\u003cp>\u003cstrong>3.“示弱垫”，说明自己的处境\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;大多人会潜意识地希望自己比别人强。“示弱垫”就是一块让别人分外喜爱的高明垫子。\u003c/p>\u003cp>“哎呀，这个问题您可真把我难住了”。\u003c/p>\u003cp>你可以说，\u003c/p>\u003cp>“您的这个问题我恐怕大学老师都无法回答你，我只能试着说说看。”\u003c/p>\u003cp>“您是怎么想到这个问题的？您是不是一直关注这个领域很多年了？”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; “示弱垫”特别适合作为对长者的回答，不但让他人产生优越感，还能留给人谦逊的印象。\u003c/p>\u003cp>\u003cstrong>\u003cem>【\u003c/em>\u003c/strong>\u003cstrong>\u003cem>举例\u003c/em>\u003c/strong>\u003cstrong>\u003cem>】\u003c/em>\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;如上是日常沟通中常用的三种垫子，比如，上周五我下班回家，开了一天的会，身心疲惫。到家后，吃完晚饭与小朋友一起玩积木，这时，5岁的小朋友突然问我：“爸爸，我是从哪里来的？”我一下愣住了，大脑飞速的旋转，我内心想：小朋友怎么会问这种问题？是不是发生了什么事情？这个问题怎么回答？如实回答，从爸爸肚子里生出来的？然后讲一堆生理学知识？不行。这样讲太深奥了，孩子也听不懂。从石头里蹦出来的？从路边捡的？充话费送的？这样骗小朋友也不太好吧。多种答案在我头脑里盘旋。正在踌躇犹豫中，想起说话避开尴尬正好可以使用“铺垫子”。\u003c/p>\u003cp>我回答：\u003c/p>\u003cp>爸爸：“呦，豆豆，你长大了，都开始问这个问题了”\u003c/p>\u003cp>其实我并没有回答他的问题，而是肯定了他的问题，铺了一个赞美垫，\u003c/p>\u003cp>豆豆接着说：“今天我们班来了一个新同学，老师说他是四川来的，我想知道我是哪里来的。”\u003c/p>\u003cp>我瞬间放松下来了“豆豆，你这个问题问的很有意思，你的老家是萍乡，所以是萍乡来的。”\u003c/p>\u003cp>其实，我还可以这样问“这个问题，是不是很多小朋友都在问呀？”这是多人垫。\u003c/p>\u003cp>或，“豆豆，你这个问题有些难度，是怎么想到这个问题的？”这是示弱垫。\u003c/p>\u003cp>\u003cstrong>\u003cem>【预防异议】\u003c/em>\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;你可能会有这样的疑问，这样做真的有效果吗？虽然这样做，不能完全解决你所有对话过程中的尴尬问题。但不这样做的话，则很容易会处在一方在问、一方在答的状态，双方之间的关系也很难做到更加密切。试着增加垫子，创造舒服的说话环境和氛围，我相信你的沟通效果将会比以前更好。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 有人可能会说，刻意的铺一层垫子，会不会不自然，让对方觉得你这人怎么这么圆滑，老不直接回答问题。我们说，起初刚开始练习的时候，会出现不自然，所以我们要准备一些垫子清单，时刻练习，养成习惯。那么，你铺垫子的时候就会自然而然了。当然，用了垫子以后，一定要给予对方问题的正面回复。否则对方听了后没有回答，反而就会觉得你不真诚。\u003c/p>","interaction":"\u003cp>\u003cstrong>五、【A2】催化应用\u003c/strong>\u003cstrong>（9分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>【步骤1】拆书家提问设计：\u003c/em>\u003c/strong>\u003c/p>\u003cp>想象一下未来一周或一个月内，你可能会遇到哪些棘手的问题，让你一下子不知道怎么回答? 请大家将你想到的场景描述出来，具体到什么时间，什么地点，什么人什么事情，棘手的问题是什么？注意，是未来一周或者一个月内可能发生的事情。3分钟时间，写在便签上，写好的小伙伴可以小组讨论并分享一下。\u003c/p>\u003cp>\u003cem>比如(参考场景如下)：\u003c/em>\u003c/p>\u003cp>\u003cem>一天下午上班，\u003c/em>\u003cem>客户买了冰箱回来质问你：“这台冰箱怎么关不紧门？”\u003c/em>\u003c/p>\u003cp>\u003cem>有位\u003c/em>\u003cem>顾客向你投诉：“你们这个铁锅是次品，我要退货。不给我退的话，我就到消协去告你们。至少要原价赔偿，我不问你们要精神损失费就不错了。”\u003c/em>\u003c/p>\u003cp>\u003cstrong>\u003cem>学习者案例记录：\u003c/em>\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;下周一，老公出差，自己一个人在家带小朋友，小朋友生病了。第二天老公回来，马上生气严肃的问话：“你怎么搞的，我就出差一天，就把小朋友弄生病了？”\u003c/p>\u003cp>\u003cstrong>\u003cem>【步骤2】拆书家提问设计：\u003c/em>\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 刚才大家讨论的未来可能遇到的棘手问题，现在运用刚学习到铺垫子的方法，如何回答才能更好地创造舒服的说话环境呢？具体你会怎么说？你会选择赞美垫、多人垫、示弱垫的哪个垫子呢？请大家进行小组讨论，讨论的时间为三分钟。在讨论完之后，请一位小伙伴做个分享。\u003c/p>\u003cp>\u003cstrong>\u003cem>学习者案例记录：\u003c/em>\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;我会采用赞美垫回答\u003c/p>\u003cp>&nbsp; &nbsp; “老公，你这么忙，还这么关心孩子，真是孩子的好爸爸。我忙于准备自己考试，晚上没有给小朋友盖好被子，不过不用担心，医生说明天就会好的。”\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 感谢各位，今天我们学习了如何运用铺垫子的方法来创造舒服的对话环境，分别是赞美垫、多人垫、示弱垫，希望大家可以现学现用，真正提升我们的对话质量。谢谢大家。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1540295884000,"updated_at":1540295971000},{"id":6236,"topic":"如何让自己的表达更具有影响力","learn_goal":"借助观点+事例+内容细节呈现完美的沟通","remark":"孙璐宏先生关于如何沟通表达的技巧汇总和案例呈现","level":"TF3-3","duration":60,"status":30,"type":0,"chaishujia":{"username":"王文元","city":"厦门市"},"club":{"name":"厦门鹭见欢喜分舵","city":"厦门"},"prologue":"\u003cp>\u003cstrong>拆一学习目标：\u003c/strong>\u003cstrong>——技能点：学习目标中包含学习者要完成行动的具体内容和完成程度，现场学习设计清晰体现了该学习目标。\u003c/strong>\u003c/p>\u003cp>学习完本拆RIA后，学习者在沟通中运用“讲述”表达方式时，逻辑呈现有次序且清晰，内容呈现有事实细节。\u003c/p>\u003cp>\u003cstrong>自我介绍：\u003c/strong>大家好，我叫王文元，我给自己定位了三个标签，\u003c/p>\u003cp>“引领者”我希望在思想上和行动上引领着一群人，\u003c/p>\u003cp>“拆书家”我要成为教师培训领域顶尖的拆书家，帮助教师打造个人学习力，构建个人知识体系。\u003c/p>\u003cp>“运营师”从新媒体运营，到IP打造，构建个人品牌形象力。\u003c/p>\u003cp>\u003cstrong>分组：\u003c/strong>今天我定级TF3-3，我们分下组，这三位小伙伴为一组，组内小伙伴互相握下手，问声好。\u003c/p>\u003cp>在场的小伙伴，都是熟悉的面孔。刚才我用三个标签，展示了，我未来的定位，及发展方向。在沟通中，我们每时每刻都在向身边的人展示着自己。\u003c/p>\u003cp>比如，\u003c/p>\u003cp>\u003cstrong>图书介绍：《说话的力量》作者孙路弘。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>——技能点：\u003c/strong>\u003cstrong>选择图书是实用类或理论类图书。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>——技能点：在学习者场景介绍法中，能够清晰辨别出事件提问影响解决4个步骤。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>你去面试一家大公司的总经理助理，你已经凭借自己的实力进入了面试阶段，也非常清楚这个职位需要应聘者具有细心的特点。于是在面试时你说：“我是一个细心的人。我从小到大都特别仔细、特别认真。我从来没粗心大意过。”\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>你觉得这种说法有说服力吗？其实这三句话全是个人看法，虽然你在生活中可能真是一个细心的人，但你的话却并不足以说服对方。\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>关于“细心”的事实没有呈现，给人感觉“空口无凭”，面试官无法判定是“真细心”，应聘者将失去一次展示自己实力的机会，面试将被淘汰。如果你是一颗金子，工作生活中的这种表达方式犹如沙子，将你埋没在黑暗之中。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>孙路弘的《说话的力量》这本书提到，没有受过说话训练的人在说话时表现出来的三个弱点：时间短、内容零散、内容多是个人看法，想要改变这些弱点，就要系统地学习说话。这是一本能够直接运用于具体生活、工作的手册，书中有8个说话方法，4个说话技巧，两种实战工具。一步一个脚印，打造你说话的能力。\u003c/p>\u003cp>\u003cstrong>解说两拆页之间关系：\u003c/strong>\u003c/p>\u003cp>拆一片段是关于“讲述”表达方式，拆二片段是关于“叙述”表达方式。\u003c/p>\u003cp>“讲述”是沟通的基础，“讲述”所呈现的只是讲事实，而要提升沟通中的影响力，就要采取“叙述”的方式，在讲完事实后，还要概括出自己的观点。&nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":9518,"quote":"\u003cp>首先我们来看下拆一片段：\u003c/p>\u003cp>\u003cstrong>【R】阅读原书拆页——\u003c/strong>\u003cstrong>技能点：每个拆页未超过2页图书内页，至少有一个拆页不包括HOW的内容。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>《给你30秒，你该说什么》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【讲述】\u003c/strong>\u003c/p>\u003cp>讲述是一切沟通的基础。讲述是对已知事物的一种讲解。已知事物可以是自己认识的一个人物，体验的一个情景，知道的一段有过程、有发展的故事，或者了解到的一个事实。\u003c/p>\u003cp>讲述是说话的最基本形式之一，\u003cstrong>因此学习讲述是学习说话的第一个步骤。\u003c/strong>\u003c/p>\u003cp>……\u003c/p>\u003cp>五年前，我采访了一个人。这个人在火车上买了一瓶一元五角钱的水，然后他问列车员要发票。列车员乐了，说我们火车上自古就没有发票。然后这个人把铁道部告上了法庭。他说，人们在强大的力量面前总是选择服从。但是，如果今天我们放弃了一元五角钱的发票，明天我们就有可能被迫放弃我们的土地权、财产权和生命的安全。权利如果不用来争取的话，就只是一张纸。他后来赢了这场官司，我以为他会跟铁道部结下梁子，结果他上了火车之后，在餐车要了一份饭，列车长亲自把这份饭菜端到他面前说，您是现在要发票呢，还是吃完了之后我再给您送过来？我问他，你靠什么赢得尊重？他说，我靠为维护我的权利所做的斗争。这个人叫郝劲松，三十四岁的律师。\u003c/p>\u003cp>……\u003c/p>\u003cp>一个国家是由一个个具体的人构成的，她由这些人创造，并且决定。只有一个国家拥有那些能够寻求真理的人能够独立思考的人，能够记录真实的人，能够不计利害为这片土地付出的人，能够去捍卫自己宪法权利的人，能够知道世界并不完美但仍不言乏力、不言放弃的人，只有一个国家拥有这样的头脑和灵魂，我们才能说我们为祖国骄傲。只有一个国家能够尊重这样的头脑和灵魂，我们才能说我们有信心让明天更好。\u003c/p>\u003cp>以上是最近很火的女记者柴静在“首都女记者协会演讲大赛”上的一段演讲片段。这段题为《认识的人，了解的事》的主题演讲最终获得了比赛的特等奖。之所以能够获奖，一方面是由于其内容真切动人，另一方面也与柴静高超的演讲技巧密不可分。\u003cstrong>在这段演讲中，柴静就出色地使用了讲述的沟通方法\u003c/strong>\u003cstrong>。\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>——技能点：有体现出【I】环节的互动，且拆书家能精准掌控。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>——技能点：在未包含HOW拆页的【I】环节，涵盖了三级讲解引导的技巧：1）给出清晰的HOW，2）通过对比概念和匹配例子引出知识点逻辑、步骤和边界等。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【互动提问】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：（1）柴静演讲之所以精彩，是因为运用了什么的表达方式？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>讲述。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>是的。\u003c/p>\u003cp>\u003cstrong>【概念讲解】\u003c/strong>讲述是一切沟通的基础。讲述是对已知事物的一种讲解。已知事物可以是自己认识的一个人物，体验的一个情景，知道的一段有过程、有发展的故事，或者了解到的一个事实。柴静的演讲中就是讲述了自己认识的一个人。\u003c/p>\u003cp>\u003cstrong>拆书家：（2）在柴静的演讲中，哪个事实的细节让你印象深刻？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>他后来赢了这场官司，我以为他会跟铁道部结下梁子，结果他上了火车之后，在餐车要了一份饭，列车长亲自把这份饭菜端到他面前说，您是现在要发票呢，还是吃完了之后我再给您送过来？\u003c/p>\u003cp>\u003cstrong>拆书家回应：\u003c/strong>这片段中呈现的事实，会与我们现实生活有种反差。平常我们买瓶水，买一样小东西，不会在意发票。这位律师通过他的行动争取到的结果，他在餐车买了份餐，列车长问他什么时候要发票，这个事实的细节，也就是柴静演讲中的精彩之处。\u003c/p>\u003cp>讲述是对已知事物的一种讲解。已知事物可以是自己认识的一个人物，体验的一个情景，知道的一段有过程、有发展的故事，或者了解到的一个事实。从“讲述”的定义看，我们可以提炼出，“讲述”的内容是事情的真实情况。\u003c/p>\u003cp>\u003cstrong>【概念对比】事实&amp;看法\u003c/strong>\u003c/p>\u003cp>没有受过说话训练的人，说话有个弱点——内容多是个人看法。\u003c/p>\u003cp>\u003cstrong>看法：\u003c/strong>对客观事物所抱的见解。\u003c/p>\u003cp>\u003cstrong>事实\u003c/strong>：事情的真实情况。\u003c/p>\u003cp>\u003cstrong>【举例对比】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>看法：\u003c/strong>厦门今天有点冷。\u003c/p>\u003cp>\u003cstrong>事实：\u003c/strong>厦门今天气温23度。\u003c/p>\u003cp>至于在23度的气温之下，你觉得冷，还是觉得热，这是每个人都可以有的、不同的看法。 &nbsp;&nbsp;&nbsp; &nbsp; &nbsp; 看法有时候表示对某人的不满，比如，我对小明做的这件事很不满。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>以事实为基础的讲述，是沟通真诚的表现。事实是可以被证实或者证伪的东西，事实有真假。而出于某种善意的原因，并且不为自身的利益，没有说出真实的情况，我们称之为“善意的谎言”，“善意的谎言”能够让情绪低落，意志消沉的人燃起希望火焰和信心。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>在《肖申克的救赎》影片中，一个服役20年的囚犯要申请假释，每十年有一次申请的机会，警官衡量能不能让他获得自由的标准是，他出去以后对社会还有没危害。\u003c/p>\u003cp>第一次申请假释没通过。\u003c/p>\u003cp>第二次警官仍问：“你被判无期徒刑已经30年，你悔过自新吗？”囚犯的回答是：“是的，确实如此，老实说我已改过了，上帝为证，我不会危害社会，我完全悔过自新了。”第二次又没通过。\u003c/p>\u003cp>第三次囚犯会怎么说呢？\u003c/p>\u003cp>\u003cstrong>警官：\u003c/strong>“你被判无期徒刑已经40年，你悔过自新吗？”\u003c/p>\u003cp>\u003cstrong>囚犯：\u003c/strong>“悔过自新？我不懂这是什么意思。我后悔犯罪吗？没有一天我不感到后悔的，但并非因受处罚才后悔。我回首前尘往事，想到当年那个犯下重罪的小笨蛋，我想跟他谈谈，我试图讲道理，让他明了。但我办不到，那个少年早就不见了，只剩下我这副垂老之躯，我得接受事实。”\u003c/p>\u003cp>警官终于被打动，假释被核准了。\u003c/p>\u003cp>囚犯之所以打动警官，是因为他做到以下两点。\u003c/p>\u003cp>\u003cstrong>【清晰的步骤HOW】\u003c/strong>\u003c/p>\u003cp>1、按一定次序，清晰地将事实表达。\u003c/p>\u003cp>2、内容呈现时，重点对事实细节进行描述。囚犯回首前尘往事，想和少年的自己对话，但是做不到，只剩垂老之躯。同时囚犯也融入了自己的情感。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>——技能点：使用【A2】技能点环节指令清晰，涵盖了三级催化应用的技巧：1）学习者根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事。2）学习者可以根据指令，写出自己未来的一个具体的要做的应用（比如某个特定任务、和人分享、事后复盘，或找人陪练。）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>——技能点：对学习者的分享和提问，有体现通过向学习者提问来进行回应式反馈。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【教学习者编辑剧本的A2】\u003c/strong>\u003c/p>\u003cp>有这样一个关于学习的研究成果：在头脑中过一遍，等于实际运用了一遍，接下来，大家编个剧本。大家想想，未来哪个场景会运用到讲述的表达方式，比如你用讲述的表达方式向面试官介绍自己，比如旅游回来后，运用讲述表达方式向同事介绍旅游中认识的一个人。剧本字数几百个字，大家拿下笔记下这几个要点，竖着写，时间、地点，人物，情节变化（起因、经过，结果），经过用对话呈现，其中对话用“讲述”方式表达，给大家三分钟时间，大家思考下，可将要点写在纸上，三分钟后，我们请小伙伴来分享。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>哪位小伙伴来分享下自己的剧本：\u003c/p>\u003cp>\u003cstrong>学习者分享（小伙伴1）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间：\u003c/strong>下周一\u003c/p>\u003cp>\u003cstrong>地点：\u003c/strong>会议室\u003c/p>\u003cp>\u003cstrong>人物：\u003c/strong>我和老板\u003c/p>\u003cp>\u003cstrong>起因：\u003c/strong>公司的货物现场需要用到一种胶水，胶水是化工品，属于易燃易爆物品，要由供应商处直接寄到昆明。我要向老板汇报工作进展，我了解到的情况和老板不太符合，老板要的是三天，我咨询到的是五天。\u003c/p>\u003cp>\u003cstrong>经过：\u003c/strong>\u003c/p>\u003cp>我：老板，现在有空嘛？要向你汇报下胶水的进展情况。\u003c/p>\u003cp>老板：好，现在到会议室。\u003c/p>\u003cp>我：老板，胶水是易燃易爆的化工品，运输有特殊的要求，我联系了6家的快递公司，快递公司的回答都是两方面，一、空运都是不能走的，二、物流方面，像德邦韵达等都告诉我，他们没有这种资质运送胶水。最终找到中通，他们说可以运送胶水，需要的是五天。你的要求是三天，我就和中通工作人员沟通了一下，能否加急，或者专线运输胶水。中通回复，胶水只是很小的物品，走专线费用是大几千块钱，胶水才多少钱。中通建议走物流公司，按照他们正常实效是5天，想加急是加急不了，快递公司也不承接这些业务。目前最理想的就是中通的五天时间。\u003c/p>\u003cp>老板：我们的人员3天以后到，胶水要5天以后到，2天的时间，我们的人员可以接受，那就选择中通。\u003c/p>\u003cp>\u003cstrong>结果：\u003c/strong>老板选择了中通，运送胶水。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家反馈：\u003c/strong>在剧本中，用讲述的表达方式，只要说明胶水运输情况就好，转述中通快递说的内容，然后让老板自己做出决定。要留意不要出现，我建议走中通五天。因为一旦出现建议，就变成了事实+建议/观点，这是我们片段二要学习的。这位小伙伴向老板汇报了胶水运输的情况，通过事实的呈现，自己联系快递，有哪些快递，分别多少天可以到，什么样的方式可以到，从事实的细节中，我们可以感受到小伙伴是在尽心尽力的做事。感谢这位小伙伴的分享。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":9519,"quote":"\u003cp>\u003cstrong>拆二学习目标：\u003c/strong>\u003cstrong>——技能点：学习目标中包含学习者要完成行动的具体内容和完成程度，现场学习设计清晰体现了该学习目标。\u003c/strong>\u003c/p>\u003cp>学完本拆RIA后，学习者在沟通中运用“叙述”表达方式时，能够筛选有利的事实，进而传达自己的观点。\u003c/p>\u003cp>\u003cstrong>拆一与拆二过渡：\u003c/strong>刚才我们学习了“讲述”的表达方式，“讲述”只讲事实，而要在沟通中有目的影响他人，提升自己的影响力，在讲完事实后，还要概括出自己的观点。这就是“叙述”的表达方式。\u003c/p>\u003cp>\u003cstrong>【A1】请大家自测\u003c/strong>\u003c/p>\u003cp>\u003cstrong>——技能点：使用【A1】技能点环节的量表题清晰设置多个选项，学习者通过自测可以了解在某种情况下自己的表现。\u003c/strong>\u003c/p>\u003cp>首先，我们通过量表自测题了解下“叙述”在大家身边的表现，根据自己的情况打分，1分不符合，5分非常符合，给大家1分钟时间，填好后，统计下分数。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>序号\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>内容\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>分值\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>1\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>我会选择一些对我影响力有提升，与我观点一致的事实，发布到朋友圈状态。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>2\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>我会选择一些与产品优势相关的事实，作为成功的案例，叙述给客户听。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>3\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>我会从“有趣”的视角入手，从暑假巴厘岛旅游经历中选择一些事实告诉朋友。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>4\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>在谈到我最喜欢的书时，我会通过叙述我的成长中所遇到的书，对我造成影响的事实，从而让听的人也喜欢这（几）本书。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>5\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>&nbsp;在使用“三个标签”自我介绍时，我能够通过叙述与“标签”匹配的事实，进而传达我的观点。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>【I】解释自测题\u003c/strong>\u003c/p>\u003cp>这些自测题，主要是了解大家对“叙述”表达方式理解的程度怎样，\u003c/p>\u003cp>≥20分，说明你在沟通中，能轻松运用“叙述”表达方式。\u003c/p>\u003cp>19≤x≤10分，说明在沟通中，运用“叙述”表达方式能力一般，还可以做得更好。\u003c/p>\u003cp>＜10分，说明你对如何在沟通中运用叙述的表达方式，还不清晰。你要打起精神，好好听今天的分享啦！\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>大家得分多少？\u003c/p>\u003cp>\u003cstrong>小伙伴2: &nbsp;\u003c/strong>19分\u003c/p>\u003cp>\u003cstrong>小伙伴1: \u003c/strong>&nbsp;14分\u003c/p>\u003cp>\u003cstrong>小伙伴3： \u003c/strong>17分\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>从大家的情况来看，大家对“叙述”的表达方式，理解一般，没关系，接下来我们来系统学习下“叙述”的表达方式。\u003c/p>\u003cp>接下来大家花3分钟时间阅读下片段。\u003c/p>\u003cp>\u003cstrong>【R】阅读原书拆页\u003c/strong>\u003cstrong>——\u003c/strong>\u003cstrong>技能点：每个拆页未超过2页图书内页，至少有一个拆页不包括HOW的内容。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>《用触动人心的事实传达观点》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【叙述】\u003c/strong>\u003c/p>\u003cp>通过对事实的筛选，将事实按次序讲给别人，有目的的影响别人，使得别人接受你的看法和观点，影响他所得出的结论，进而影响他的行为，这就是叙述。\u003c/p>\u003cp>&nbsp;\u003cstrong>在电影《黑客帝国2》中，面临逼近的电脑乌贼大军，人类的领袖墨菲斯对聚集在一起的人类发表了一段震撼人心的战前动员。他是这样说的：\u003c/strong>\u003c/p>\u003cp>锡安的同胞们！听我说。你们所听说的大部分都是真的，电脑召集的机器兵团，正在逼近我们的家园，我们将有一场艰辛的硬战要打。\u003c/p>\u003cp>想要贏得这场战争的胜利，首先要斩除内心的恐惧。我现在站在这里，心中毫无惧意！为什么?是因为我跟你们有着不同的信念吗?不是！\u003c/p>\u003cp>我能无惧地站在这里是因为我记得，我记得我之所以能在这里，不是因为遵从前人所铺下的路，而是因为相信自己能创造属于我们的未来。我记得我们跟这些机器对抗了百余年，我记得这百余年来，它们不停地派军队来企圈消灭我们。经过了这一个世纪的战争，我记得最重要的一件事是，我们依然活着。\u003c/p>\u003cp>今晚，让我们向机器兵团宣战！今晚，让这里因我们而震动起来！今晚，让这儿的大地，钢铁与石头都因我们而颤抖！让我们的呐喊由火红的地底，直达乌黑的天上去！今晚，我们要让它们记得这就是锡安！而我们无所畏惧！\u003c/p>\u003cp>在影片中，墨菲斯的战前动员引发了人们的欢呼，激昂的斗志。而对在影院中观看电影的观众来说，这段精彩的的出电影带入了一个高潮。这就是说话的第二个基本功，\u003cstrong>叙述的的力量\u003c/strong>。\u003c/p>\u003cp>\u003cstrong>墨菲斯的这段演讲为什么触动人心?\u003c/strong>为什么能收到如此良好的效果，鼓舞了人们的斗志?\u003c/p>\u003cp>首先，墨菲斯在叙述之前是\u003cstrong>对事实进行了筛选的。当你有一个明确的看法、试图影响对方的时候，要把一些对你不利的、与你看法不一致的事实屏蔽掉，也就是筛选事实\u003c/strong>。\u003c/p>\u003cp>百余年中可能发生了很多事情，比如可能实际上一年中有半年的时间是不打仗的，不打仗的时候虽然人们过得不自由但还是安于现状的，比如反抗者们以血肉之躯对抗钢铁机器可能死得非常惨，等等。但在现在这个时刻，\u003cstrong>墨菲斯不会叙述这些事实，而是选择了如下事实：\u003c/strong>电脑召集的机器兵团逼近了(现在我们别无选择)；我们跟机器对抗了百余年(我们已经受压迫百余年了)；百年来机器不停派军队企图消灭我们(人为刀俎，我为鱼肉)；我们还活着(我们活到现在不容易，也许这是最后的机会了)。\u003c/p>\u003cp>\u003cstrong>其次，他通过这些事实表达了自己的观点：\u003c/strong>我们要向机器兵团宣战；我们要消灭敌人；我们要无所畏惧。如果你是片中的幸存人类，通过墨菲斯已经筛选过然后传达给听者的事实，你是不是也会觉得他的观点有着非常充分的理由?我们已经被电脑压迫一百多年了，现在背水一战，别无选择，我们必须无所畏惧地消灭敌人。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>——技能点：有体现出【I】环节的互动，且拆书家能精准掌控。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>——技能点：在未包含HOW拆页的【I】环节，涵盖了三级讲解引导的技巧：1）给出清晰的HOW，2）通过对比概念和匹配例子引出知识点逻辑、步骤和边界等。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【互动提问】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>片段中，“叙述”表达方式包含哪些部分？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>&nbsp;经过筛选的事实和观点。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>\u003cstrong>【概念讲解】\u003c/strong>\u003cstrong>叙述：\u003c/strong>通过对事实的筛选，将事实按次序讲给别人，有目的的影响别人，使得别人接受你的看法和观点，影响他所得出的结论，进而影响他的行为。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>《黑客帝国2》墨菲斯的有利的事实，观点分别是什么呢？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>有利的事实：\u003c/strong>电脑召集的机器兵团逼近了。我们跟机器对抗了百余年。百年来机器不停派军队企图消灭我们；我们还活。\u003c/p>\u003cp>\u003cstrong>观点：\u003c/strong>我们要向机器兵团宣战；我们要消灭敌人；我们要无所畏惧。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>是的，这正是墨菲斯的演讲能触动人心，鼓舞了人们的斗志的原因。\u003c/p>\u003cp>\u003cstrong>【易混淆概念对比】讲述&amp;叙述\u003c/strong>\u003c/p>\u003cp>\u003cstrong>片段一是讲述：\u003c/strong>只讲事实。\u003c/p>\u003cp>\u003cstrong>叙述：\u003c/strong>讲完事实后，还要归纳自己的观点。观点：观察事物时所处的立场或出发点。“观点”比“看法”更复杂、更深入、更成熟。\u003c/p>\u003cp>“讲述”和“叙述”两种在内容的呈现是怎样的呢？\u003c/p>\u003cp>\u003cstrong>【举例对比】我最喜欢的颜色。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“讲述表达”：\u003c/strong>比如，我五岁的时候喜欢什么颜色，长大些之后喜欢什么颜色，工作之后又喜欢什么颜色。\u003c/p>\u003cp>\u003cstrong>“叙述表达”：\u003c/strong>通过叙述我成长经历中所遇到的那些颜色对我造成的影响事实，从而让听的人也喜欢这种颜色。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>当我们要有目的的影响他人，提升自己影响力，就要用“叙述”表达方式。简单的说：用事实来传达观点。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>或许你会问，我可不可以先说观点在说事实。任何信息在传达给它的对象时，都会遇到不同的反应，要么被质疑，要么被认同，要么被中立。针对会质疑、中立的对象，要由事实引出观点。针对会赞同的对象，才可以先观点再事实。从“叙述”的表达方式来看，运用逻辑，由事实引出观点，这样的效果会比较好。\u003c/p>\u003cp>\u003cstrong>【例子】：\u003c/strong>\u003c/p>\u003cp>有个朋友发了一个课程的推荐语让我帮忙看下，\u003c/p>\u003cp>内容是这样的:\u003c/p>\u003cp>我上过沟通课，育儿课，学习力课，如果评个“最好”的标签的话，就是“学习力课程”，从拆书定级到赋能班，我的成长，我感受的到，我身边的人也感受的到。\u003c/p>\u003cp>看到这，我大脑第一秒反应，这内容呈现的是看法，没有事实，说服力一般般，\u003c/p>\u003cp>第二秒我大脑反应，说服力一般般，带有评价，我应该给他回复，可以了解看法与事实的区别，重新做关于事实的呈现。\u003c/p>\u003cp>第三秒我大脑反应，刚才我将答案告诉了对方，我应该给他一个标准，以提问引导对方找到答案，这样对方通过自己寻找到答案，内心就有种愉悦感，成就感。\u003c/p>\u003cp>最终我是这样回复的:\u003c/p>\u003cp>学习力体现在成长，成长体现在成长前，成长后的对比，刚才推荐语已经体现了成长前的思考方式[看法]，\u003c/p>\u003cp>成长后的思考方式是怎样的，才能形成前后对比？\u003c/p>\u003cp>有了前后对比，你要通过什么形式呈现呢，比如故事？\u003c/p>\u003cp>拆书给了我思考的层次标准，让我更好的洞察这世界。欢迎你，和我一起来拆书，成长。\u003c/p>\u003cp>\u003cstrong>【引出清晰的HOW】\u003c/strong>\u003c/p>\u003cp>1、\u003cstrong>观点：\u003c/strong>你想传递什么思想，是否鲜明，易懂？\u003c/p>\u003cp>2、\u003cstrong>有利的事实：\u003c/strong>哪些事实有效支撑你的观点？哪些事实细节更启发对方？\u003c/p>\u003cp>3、\u003cstrong>内容呈现：\u003c/strong>用接地气的语言进行表达，运用逻辑从事实引出观点，进而感染对方。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】促动参与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>——技能点：在未包含HOW拆页的【A3】环节指令清晰，学习者在拆书家主持的微行动学习环节，讨论出了这类问题的解决方案。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>——技能点：对学习者的分享和提问，有体现通过向学习者提问来进行回应式反馈。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【微行动学习步骤】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【明确问题】\u003c/strong>\u003c/p>\u003cp>我将“叙述”的三步骤发到群里，大家一起看下，\u003c/p>\u003cp>1、\u003cstrong>观点：\u003c/strong>你想传递什么思想，是否鲜明，易懂？\u003c/p>\u003cp>2、\u003cstrong>有利的事实：\u003c/strong>哪些事实有效支撑你的观点？哪些事实细节更启发对方？\u003c/p>\u003cp>3、\u003cstrong>内容呈现：\u003c/strong>用接地气的语言进行表达，运用逻辑从事实引出观点，进而感染对方。\u003c/p>\u003cp>\u003cstrong>[拆书家\u003c/strong>\u003cstrong>提问式反馈与回应\u003c/strong>\u003cstrong>]\u003c/strong>\u003cstrong>：\u003c/strong>大家结合过往的经验想一想，未来将叙述的表达方式运用到工作生活当中，你会遇到哪些障碍？有没哪个知识点不太理解或者觉得操作起来有难度？\u003c/p>\u003cp>\u003cstrong>小伙伴2：\u003c/strong>叙述时如何有激情？内容呈现，叙述的人不同，带来的效果不同。\u003c/p>\u003cp>\u003cstrong>小伙伴1：\u003c/strong>内容呈现。每个人的表达方式不同。\u003c/p>\u003cp>\u003cstrong>小伙伴3：\u003c/strong>事实细节的呈现比较难，细节是不是带有感情。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[拆书家\u003c/strong>\u003cstrong>提问式反馈与回应\u003c/strong>\u003cstrong>]：\u003c/strong>好的，从刚才大家的反馈，内容的呈现，会比较难吧？\u003c/p>\u003cp>\u003cstrong>[伙伴确认]\u003c/strong>是的。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，接下来我们将围绕着这个问题“如何做好内容呈现”进行讨论，我们将通过微行动学习，来分析和解决这个问题。\u003c/p>\u003cp>\u003cstrong>【引导讨论问题本质】\u003c/strong>接下来，请大家在小组内探讨这个问题的本质是什么？问题的本质，是指这个问题存在的关键原因，找到了问题的本质，意味着找到解决问题的钥匙。大家可以结合自己的经验，对这个问题进行追问。时间4分钟。\u003c/p>\u003cp>[小组讨论]\u003c/p>\u003cp>\u003cstrong>【明确问题本质】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[拆书家\u003c/strong>\u003cstrong>提问式反馈与回应\u003c/strong>\u003cstrong>]\u003c/strong>\u003cstrong>：\u003c/strong>大家对于“如何更好的内容呈现？”这个问题，找到的本质是什么呢？\u003c/p>\u003cp>\u003cstrong>小伙伴\u003c/strong>\u003cstrong>3\u003c/strong>\u003cstrong>：\u003c/strong>多重因素的叠加，会导致我们临场的把控度下降。所以，会对现场内容呈现会造成影响。\u003c/p>\u003cp>\u003cstrong>拆书家反馈\u003c/strong>：好的，大家找到的问题本质是：多重因素的叠加，会导致我们临场的把控度下降。&nbsp;\u003c/p>\u003cp>\u003cstrong>【引导讨论解决方案】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[拆书家\u003c/strong>\u003cstrong>提问式反馈与回应\u003c/strong>\u003cstrong>]\u003c/strong>\u003cstrong>：\u003c/strong>好，针对这个问题本质，请大家在小组内讨论该问题本质的解决方案，\u003c/p>\u003cp>你们要解决到什么程度才觉得可以？\u003c/p>\u003cp>\u003cstrong>小伙伴\u003c/strong>\u003cstrong>3\u003c/strong>\u003cstrong>：\u003c/strong>可操作的原则。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，接下来大家讨论解决步骤，大家思考下，将要点写在白纸上，给大家3分钟，然后我们请伙伴们进行分享。\u003c/p>\u003cp>\u003cstrong>【代表讲解成果】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，哪位小伙伴来分享下解决方案？\u003c/p>\u003cp>\u003cstrong>小伙伴1：\u003c/strong>\u003c/p>\u003cp>（1）内容呈现前，列出影响我控场的因素，如有人针对某观点喧哗，我如何应对。\u003c/p>\u003cp>（2）先稳定我的情绪和信念。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>其他小伙伴，有其他思路嘛？有补充的地方嘛？\u003c/p>\u003cp>\u003cstrong>小伙伴2：\u003c/strong>\u003c/p>\u003cp>（1）从多个视角，预备多个观点，以应对现场反应。\u003c/p>\u003cp>（2）事先了解听众的需求，避免反对意见。\u003c/p>\u003cp>（3）对事实的精选，现场情绪的表达，是激情四射，还是循序渐进的表达。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>这位小伙伴还有补充的嘛？\u003c/p>\u003cp>\u003cstrong>小伙伴3：\u003c/strong>\u003c/p>\u003cp>（1）先调整内在状态准备。\u003c/p>\u003cp>（2）根据事实多准备几个观点，在阐述不同观点时，对应的事实细节，也要提供。\u003c/p>\u003cp>（3）依据事先准备，根据现场情况，临场应变调整内容。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>刚才三位小伙伴根据自己的情况，分享了自己的流程步骤，接下来，大家在讨论下，最终提出一个大家都认同的解决方案。\u003c/p>\u003cp>\u003cstrong>小伙伴2：\u003c/strong>我认同小伙伴3的方案，先管理情绪，在管理事情。因为你要上场，情绪没有到位，很多表达会有差疵。因此先管理情绪，然后根据现场的情况来调整，包括我们的观点都会临时调整。所以管理情绪要第一步。\u003c/p>\u003cp>\u003cstrong>小伙伴1：\u003c/strong>我也认同。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，最终大家讨论出来的解决方案是：\u003c/p>\u003cp>（1）先管理情绪，调整内在状态准备。\u003c/p>\u003cp>(2)事先准备，根据事实多准备几个观点，在阐述不同观点时，对应的事实细节，也要有。\u003c/p>\u003cp>(3)依据事先准备，根据现场情况，临场应变调整内容。\u003c/p>\u003cp>\u003cstrong>拆书家反馈：\u003c/strong>\u003c/p>\u003cp>感谢小伙伴们的探讨，小伙伴们通过不断挖掘问题背后的根本原因，最终找到了解决的方案，大家很棒。我们微行动的学习就讨论到这。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【特定任务的A2】布置任务\u003c/strong>\u003c/p>\u003cp>——\u003cstrong>技能点：使用【A2】技能点环节指令清晰，涵盖了三级催化应用的技巧：1）学习者根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事。2）学习者可以根据指令，写出自己未来的一个具体的要做的应用（比如某个特定任务、和人分享、事后复盘，或找人陪练。）\u003c/strong>\u003c/p>\u003cp>学完“叙述”表达方式，要践行，那么现在给大家布置个任务。\u003c/p>\u003cp>今天就找机会运用“叙述”和人表达“我的兴趣爱好是阅读”，按照“叙述三步骤”1、观点：你想传递什么思想，是否鲜明，易懂？2、有利的事实：哪些事实有效支撑你的观点？哪些事实细节更启发对方？3、呈现：用接地气的语言进行表达，运用逻辑从事实引出观点，进而感染对方。\u003c/p>\u003cp>\u003cstrong>【线下作业反馈】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小伙伴2：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我的兴趣爱好是阅读\u003c/strong>\u003c/p>\u003cp>我的兴趣爱好是阅读，平常我喜欢阅读沟通、礼仪方面的书。在阅读的过程当中，我会想想我的过往经验，想想如何改善现在不好的状况，如何规划未来的应用。\u003c/p>\u003cp>有一次我在阅读《改变提问，改变人生》这本书的时候，看到提问式思维，面对所发生的事情，抱怨是无济于事的，要向内思考，如何做才能改变这种情况，简单的说就是由向外思考变为向内思考。这让我想到一件事，一个朋友曾经问我，有没小记者规章制度方面的资料，当时我百度查找了下，找到了2篇就发给了她。第三天，当我正在忙的时候，她又问我，有没小记者笔试的资料，当时因为忙，我一下子有点火：你不会自己百度下嘛？后来我很不情愿的百度查了资料又发给了她。回想这件事，我感觉到当时确实有不好的情绪，因为我希望她能够自己找资料，不要每次都问我。当时我就没有向内思考，我应该告诉她如何做——百度查找，而不是将答案告诉她——直接发文章给她。因此，下次她在向我要资料方面，我应该告诉她，通过什么方式可以找到。\u003c/p>\u003cp>阅读，让我能够洞察到以前做得不好的地方，进而改进，使自己工作生活更谐和。你的兴趣爱好是什么呢？\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>\u003c/p>\u003cp>今天我们学习了说话的两种表达方式：讲述与叙述。讲述只讲事实，叙述讲完事实还要归纳自己的观点。要让知识成为技能，还需要不断的刻意练习，所以也希望各位小伙伴，在今后工作生活中的沟通，刻意的运用我们今天学习的两个表达方式，从而不断提高你的说话能力。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1539606261000,"updated_at":1539607093000,"ria":true},{"id":5773,"topic":"让人舒心的解释","learn_goal":"现场应用解释的四个步骤，化解沟通误会，达到良好的沟通效果","remark":"一个好的解释主要有一个核心四个层次。核心是要听懂。为避免沟通过程中因为没有正确理解对方意思而出现误会，我们可以使用解释的四个步骤，去避免因沟、没有听懂对方产生的误会，做一个沟通小达人","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"冬夜读书YHY","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp;大家好，欢迎大家来到我的TF2——3练级现场。首先我先做个自我介绍。我是杨红燕。我的三个标签是1、学习成长中的拆书家。2、科学沟通的实践者。3、热爱教育的教育工作者。我请大家分成3个组。每组3人。&nbsp;\u003c/p>\u003cp>\u003cstrong>〔学习目标\u003c/strong>〕小伙伴们， 希望大家经过今天的RIA现场学习，能够现场应用解释的四个步骤去化解因在沟通过程中没有听懂对方而造成的误会，达到良好的沟通效果。&nbsp;\u003c/p>\u003cp>【图书介绍】&nbsp; &nbsp;\u003c/p>\u003cp>\u003cstrong>F（特征）\u003c/strong>《说话的力量》作者孙路弘，营销及销售行为专家，高级营销顾问。他以西方缜密的思维结合中国本土多变的现实，提出操作性强且可以落实的执行步骤和方法，切实改善了中国企业在营销方面的竞争实力。本书就是教你如何说话的实战指南。 \u003c/p>\u003cp>\u003cstrong>A（优势）\u003c/strong>它不是一本空谈理论的教科书,而是一本结合了中国文化语言艺术的书，能直接运用于具体生活、工作的手册。\u003c/p>\u003cp>\u003cstrong>&nbsp;B1（利益）\u003c/strong>你在生活中是不是有以下几种情况呢? 1、找工作屡屡受挫,因为面试的时候总是说不到重点。 2、长时间不能升职,团队关系紧张。一张嘴就 得罪人,本来是好心帮忙结果说错了话反而被 人记恨。 3、因为不会说话,在家里和父母有冲突和妻子 或者是丈夫等家人关系紧张。4年度工作时你总发现同事表达得很好，总是能得到领导表扬，而自己工作很不错但却表达不出来。如果上面的情况让你感到困扰，那么，恭喜大家，这本书将从沟通技巧和工具上给大家一些实际的帮助和启发。贯穿全书的八 大说话方法、四大说话技巧和两大说话工具是孙 路弘首创的,都是倾其25年的营销、销售经验的精华之作。\u003c/p>\u003cp>\u003cstrong>B2（利益）\u003c/strong> 今天的拆页学习主要就是了解如何运用解释的方法化解沟通过程中因为对一件事不同的理解而造成的误会，从而让沟通变得更加流畅。\u003c/p>","ratings_count":1,"texts":[{"id":8978,"quote":"\u003cp>p116――117当别人要求你解释时,你首先该做什么\u003c/p>\u003cp>生活中处处需要解释。比如,妻子问你:“今天怎么这么晚才回 来?” 她期待的是你给她一个解释。领导问你:“这个月的预算怎么 花超了?”他期待的也是你给出一个解释。回想一下,你的生活中是 不是经常出现别人要求你解释某件事,或者你要求别人解释某件事的情境？一 件事情一旦需要解释,就意味着对话中的一方对一些问题有 不同的看法或不理解的地方,他的预期与现实不一致,跟对话的另 一方互动有障碍了。\u003c/p>\u003cp>解释有比较正式的形式,也有比较随意的形式,但无论哪种形 式都应该认真对待。因为解释要求质量和效率,如果多次解释后 对方仍然没有完全理解,或者依旧理解错误,双方关系就会受到严重影响。解释是一个说话技能,但到底应该如何解释?回想一下,在需要解释的时候,你通常的本能反应是什么? \u003c/p>\u003cp>比如经理质问你为什么上个月预算花超了,没有受过训练的人通常有三种反应:第一种是说:“哎哟,对不起经理,我下次一定不 花超了。”这是在强调“下次”。第二种是说:“哎哟,您不知道这次 的客户太难伺候了。”这是在讲客观原因。第三种是说:“哎哟,经理, 您看我一年就花超这一回。”这是在说明花超预算是个偶然事件,不经常发生。 实际上,上述三种情况都不符合解释的要求,因为听的人听完 你的话还在期待知道你的原因,你仍然需要进行进一步的解释。\u003c/p>\u003cp>听懂,解释的核心解释有一个核心,就是听懂。听到不等于听懂,中国有句话“鼓听声,听话听音”,你真的听懂了吗?\u003c/p>\u003cp>真正的听懂有四个层次\u003c/p>\u003cp>:第一个是听懂对方\u003c/p>\u003cp>,第二个是让对方知道我听懂了\u003c/p>\u003cp>,第三个是争取让对方听懂我\u003c/p>\u003cp>,第四个是确认对方听懂我了。这也就是解释的四个层次。﻿﻿\u003c/p>","explains":"\u003cp>在日常生活中,解释的说话方式不管在家庭还是职场、企业内部沟通还是外部沟通中都非常重要。\u003c/p>\u003cp>牛根生说过一句话:&quot;企业80%的矛盾和误会都来自于沟通不畅。&quot;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;矛盾和误会是不可避免的,但是当矛盾和误会发生时,如何解释就是见功力的地方所在。\u003c/p>\u003cp>今天我们要学习的就是说话的八大方法之解释的方法。\u003c/p>\u003cp>一个好的解释主要有一个核心四个层次。核心是要听懂。\u003c/p>\u003cp>\u003cstrong>【新技能之一细化行动步骤】\u003c/strong>为避免沟通过程中因为没有正确理解对方意思而出现误会，我们可以使用解释的四个步骤，分别是：\u003c/p>\u003cp>1、通过用句式“你是问关于什么什么吗？”来核实我是不是听懂了对方的话。\u003c/p>\u003cp>2、通过聆听对方回答和观察对方的行为确认我听懂了。例如对方说“是的”或者点点头。\u003c/p>\u003cp>3、正面回答对方的问题，让对方听懂我。例如你会根据对方的需求正面的回答对方需要了解的问题。\u003c/p>\u003cp>4、我通过聆听和观察对方行为确认对方听懂了。例如，对方在语言中或行为表示了自己的正确理解。或者重复了听到的结果。\u003c/p>\u003cp>\u003cstrong>〔不这样做的坏处〕\u003c/strong>很多时候，因为我们没有听懂对方的话，或者自认为听懂了对方的话却没有确认。在这种没有听懂的情况下采取了行动往往会发生不必要的纠纷和误会。\u003c/p>\u003cp>\u003cstrong>〔不这样做的坏处举例〕\u003c/strong>有一天你在单位加班到很晚，拖着疲惫的步伐走进家门，你的妻子迎上来说：“你怎么这么晚回来？儿子等你讲故事呢。”你心想，我在外加班这么辛苦，一进家门你就指责我。于是没好气的说：“回来这么晚还不是为了赚钱？我这么辛苦，你一点都不体谅，还责怪我，还吵着要给儿子讲故事，真是烦死了。”于是扭头进卧室睡觉，留下一脸茫然的妻子。面对妻子的提问，你首先想到的是自己的辛苦和妻子的不理解，而并没有对妻子的提问做出正确的解释，所以造成了夫妻关系的一个小纠纷。你不痛快，妻子也不高兴。〔这样做的好处〕但是假如那个丈夫在行动前首先想到的是听懂妻子，特别是让对方确认自己听懂的是正确的事实后再表达自己的观点，并通过交流确认对方听懂了自己。这样就会避免出现纠纷。\u003c/p>\u003cp>\u003cstrong>〔这样做的好处的例子\u003c/strong>〕 按今天的知识点我们来重现一下丈夫和妻子的沟通过程。运用今天的知识点。\u003c/p>\u003cp>“解释”：核心是听懂两个字。\u003c/p>\u003cp>妻子：“你怎么这么晚回来？儿子等你讲故事呢”\u003cstrong>（这就是解释第一步：丈夫首先考虑的是用提问确认听懂了妻子的意思）\u003c/strong>。\u003c/p>\u003cp>他猜测妻子想知道原因。就问“你是想知道我为什么回来晚吗”妻子点点头。\u003cstrong>（这就是\u003c/strong>\u003cstrong>解释的\u003c/strong>\u003cstrong>第二步，通过观察到妻子的点头动作确认了丈夫听懂她的话了。）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（解释\u003c/strong>\u003cstrong>的\u003c/strong>\u003cstrong>第三步丈夫争取让妻子听懂自己）\u003c/strong>正面细致地回答妻子的问题，于是说“下班前临时接到一个任务，很重要，一直在做事，忘了打电话给你了。”\u003c/p>\u003cp>妻子反馈说：“是哟，儿子今天早早在家等你，说你答应了他讲故事的，原来你是因为加班耽误了，明天和儿子解释一下，辛苦了，我给你倒杯水。（\u003cstrong>这是解释的第四步，妻子通过回答明确表达听懂了丈夫的话）”\u003c/strong>\u003c/p>\u003cp>至此，完成了解释的四个步骤，丈夫得到了妻子的理解。相信这样的沟通一定会增进夫妻之间的感情。\u003c/p>\u003cp>\u003cstrong>〔适用边界〕\u003c/strong>当然解释的前提是沟通者对双方的关系非常重视。反之则不需要使用解释的方法。\u003c/p>\u003cp>\u003cstrong>（预防异议）\u003c/strong>可能有些伙伴会问是不是使用了解释的四步骤就一定能解决所有的问题，但事实上这四个步骤不一定能够解决所有的问题，但它对于改善沟通双方的沟通效果是很有帮助的。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）\u003cbr>\u003c/p>\u003cp>下面为了强化对这三个步骤的应用，大家想象一个这个场景。下面是场景描述：〔新技能之场景设计〕\u003c/p>\u003cp>场景一：:在部门会议结束后，部门财务经理发现有个部门上个月预算超支，而且也没有任何人提前和他汇报过此事，心里有点纳闷，于是他找来小强了解情况，沟通过程中，小强自我感觉经理是在责难自己，于是用抵触的态度含糊回答，强调说是第一次超支，超出预算是偶然行为而且有些开支很难控制等。主管听完后还是不知道没什么超支，于是就有些不满意了。在沟通结束时还批评了小强一顿。\u003c/p>\u003cp>\u003cstrong>场景二\u003c/strong>:小强回到科室后很郁闷，把事情和小明说了，小明意识到是小强误解了部门经理的意思，部门经理只是想了解超支原因，并不是责怪他。只是小强的回答让部门经理不高兴了。于是小明自告奋勇地去向财务经理解释。他应用了解释的四个步骤，最终让财务经理了解了超支的原因，表达了理解，双方化解了误会。\u003c/p>\u003cp>下面就请大家设计角色对话剧本，并请三个人分别扮演财务经理小强和小明。\u003c/p>\u003cp>第一个对话剧本是财务经理和小强的对话，内容主要是财务经理希望知道部门超支的原因，而小强误以为财务经理责怪他超支，所以只是强调什么以前从不超支，这次是偶然呀，什么有些很难控制什么的，结果财务经理不太高兴，还批评了小强。\u003c/p>\u003cp>第二个对话剧本，就是小明如何引用解释四步骤化解沟通误会，赢得财务经理的理解，双方愉快沟通。\u003c/p>\u003cp>请大家分组讨论，并安排好角色。给大家8分钟讨论，8分鈡后请一组上来进行角色分享。\u003c/p>\u003cp>\u003cstrong>分享案例:\u003c/strong>\u003cstrong>分享伙伴（王伟扮演财务经理\u003c/strong>\u003cstrong>&nbsp;&nbsp;黄瑜扮演小强 吴小园扮演小明。）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>对话剧本一：财务经理与小强的不成功的沟通。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>财务经理：小强，你们这个月预算怎么超支了？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;小强：哎呀，经理，你不知道那个客户多难缠，太难伺候了，我好不容易搞定的。我哪里超支了，我就超了这么一回。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;财务经理：啊说什么，我问你这预算怎么超支了？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;小强：没有超支。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;财务经理：明明超支了你还说没有超支？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;小强：我就超支了这么一回，好不容易搞定的。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;财务经理：好好好，就这样。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>对话剧本二：小明应用解释的四个步骤成功沟通，达成谅解。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>财务经理：小明，你们这个月预算怎么超支了？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;小明：经理，你是问预算超支的原因吗？（第一步：使用问句向对方确认我是否听懂了）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>财务经理：恩。（第二步：通过观察对方反应确认我听懂了对方的意思）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;小明：“是这样的，就是说本来预算是不会超支的，但是临时客户那边出了点问题，因为我们这批产品涉及到邮费，客户的那个东西太大了，临时加了笔邮费，所以增加了一点点预算，但这是可以理解的吧？（第三步：正面回答对方的问题，让对方听懂我）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;财务经理：哦是这样的是吧？行我会向总经理反馈这件事情。（第四步：通过聆听和观察确认对方听懂了我）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;小明：谢谢领导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;财务经理：恩也谢谢你。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>结束语：谢谢三位伙伴的参与。刚才大家看到了小明使用解释的四个步骤，成功与主管沟通，赢得了理解和支持。沟通效果很好。我发现还有其他伙伴也分享得很棒，但因为时间原因，不能一一请上来分享了。\u003c/p>\u003cp>我们来回顾一下今天的学习内容，学习了解释的四个步骤，大家刚才也应用了，希望大家在今后的生活和工作中积极地使用解释的四个步骤去避免因沟通过程中没有听懂对方而产生的误会，做一个沟通小达人。再次感谢大家来到我的TF2-3练级现场，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1534041420000,"updated_at":1534041850000,"ria":true},{"id":5388,"topic":"把握四要素，让你的汇报清晰，准确，高效","learn_goal":"学完后能够完成清晰、准确、高效的汇报","remark":"汇报也是说话的一种方式，每个有工作经历的人，都面对过向领导汇报工作情况的场景。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"魏世英","city":"兰州"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp;我是魏世英，在企业从事办公室文字秘书工作。今天，我要拆解的书，是孙路弘教授倾心之作《说话的力量》。孙路弘毕业于北京师范大学数学系，他常年致力于各种产品的销售、营销，在国内营销咨询领域，声名远播。值得一提的是，他写的这本《说话的力量》，是国内首部，系统介绍如何说话的实战指南。这不是一本空谈理论的教科书，书中大量、丰富的案例都是作者本人多年来真实的经历，对于职场小白或者试图想提高自身说话能力的我们，该书都能从鲜活的、接地气的事件中，更形象、更具体教会我们一些说话的方法、技巧。\u003c/p>\u003cp>&nbsp; &nbsp;因为今天，我们会进行小组讨论，所以先进行分组，基于今天小伙伴的参与情况分为一组。\u003c/p>","ratings_count":1,"texts":[{"id":8543,"quote":"\u003cp>&nbsp; &nbsp; &nbsp;在职场中，有人会感叹，为什么干了同样的事情，自己没话说，别人却能说得天花乱坠，自己干了十分，只能说五分。别人只干了八分，却能说出十五分来呢？那就是因为你没有掌握说话的技巧，没有掌握汇报的技术。光说不练假把式，光干不说傻把式，即会说又会干才是真把式。毫不夸张的说，-及时汇报和合适时机汇报是职场必备技能之一。&nbsp;\u003c/p>\u003cp>在现实生活中，你可能经常遇到这样的情况。领导对下属说：“你给我汇报一下情况”，但是下属汇报完以后，领导又总是不满意，这是为什么呢？是因为汇报不完整、不合格，缺少了必备的元素。不完整的汇报，可能是只有观点、缺乏足够的事实，也可能是只有观点没有事实。最常见的不完整的汇报是缺少建议。汇报不同于讲述、叙述和表达，最与众不同的地方就是要有相应的建议，所以，真正合格的汇报，必须具备的元素是：有事实、有观点、有建议且要有基于事实的措施。\u003c/p>","explains":"\u003cp>汇报也是说话的一种方式，每个有工作经历的人，都面对过向领导汇报工作情况的场景。也许我们也正在为此苦恼，为什么同样的工作，不同的人去汇报，结果却大相径庭。文中的片段阐述，告诉我们：作为汇报人员，汇报是要基于现实，但是要提炼事实，对于复杂的情况，在汇报过程中要有个人观点和倾向，对于下一步工作，有具体的建议和可行措施，这样的汇报，才能有效的实现下情上达。如文中所述：汇报不同于讲述、叙述和表达，最与众不同的地方就是除了有事实，有观点，更要有建议和措施”，所以说，合格的汇报，要具备：有事实、有观点、有建议，有措施的四元素。\u003c/p>","interaction":"\u003cp>A1：通过对原文片段的学习，使我对于自己最近一次汇报工作之后，领导拂袖而去的场面，有了答案。去年年底，年终的最重要的职代会召开在即，会前，领导召集各部门进行筹备进度的汇报。核心是了解此项活动的准备情况和进展。我作为办公室汇报人员，简单叙述了自己部门自接到通知后的一些相关准备事宜，拟好议程，准备好颁奖音乐，安排好会议通知，做好会场设置等等，对于需要其他科室一起协调的会务事项，没有太多思考，也没有具有建议。（汇报就是表达）。领导随即问道，针对一年一度的大型会议（事实），各单位负责人有无认真考虑会务的各个环节如何确保会议顺利进行（观点）有无明确领奖人员的请假人数，会议涉及的几个部门如何做好协调（建议），领导的讲话稿有那个部门最后审核，会议下一步如何宣贯（措施）…因为毫无准备也没有思考的使会议气氛异常尴尬（无事实，无观点，无建议，无措施）汇报，结果必然是领导佛袖离开。事后一直在反省在即，直到看到书中原文片段，我知道自己的问题出在哪儿了。我的汇报更多的是陈述，是叙述，认为事情交代清楚就可以了。但是忽略了对于会议顺利召开这个事实，年度职代会年终一次比较重要的会议，不能出现半点披露的观点，没有提出会议有序进行的建议，当然更谈不上措施，所以，这种流水账式的汇报自然无法过关。以上我本人分享做的不好的一次汇报。\u003c/p>\u003cp>下面，我们有请在座的小伙伴来分享自己在职场中面临的汇报，自己满意的案例，或者不尽人意的经历。当时的你，是怎么做的呢？2-3分钟时间。时间到了，现在请1位小伙伴来进行小组分享。\u003c/p>\u003cp>现场小伙伴1的分享：\u003c/p>\u003cp>我也是企业的员工，也遇到过汇报的问题。我们经常遇到一些需要处理的问题，在各个科室之间很难抉择，就需要向上级领导汇报。在以前的汇报中，我只讲述事实，没有观点和建议，很多时候领导也很难决策，往往是“再商量”。造成汇报达不到效果。后来看到其他同事汇报时提出解决方案，领导很快就表明态度，问题也得到了解决。我也尝试了这种方法，取得了不错的效果。今天通过拆书分享学习，我才知道这种方法是有深厚的理论基础，也就是汇报不能只讲事实，还要表明观点、提出建议和措施。只讲事实，不表明观点，没有建议的汇报是无效的，领导很难了解事情的全貌，也很难知道汇报者的想法和诉求，更不能快速做出决策。所以通过学习，我觉得汇报“四要素”的掌握对我工作帮助很大，我会理论结合实践去应用。谢谢分享。\u003c/p>\u003cp>A2：刚刚我们的小伙伴已经分享了自己过往的经验，现在给大家1分钟时间，写下自己将在未来面对汇报场景时，应如何使用今天讲到的汇报要有事实，有观点，有建议，有措施的四要素的汇报方法，请写出你们的A2便签。\u003c/p>\u003cp>现场小伙伴2的分享：\u003c/p>\u003cp>通过今天的学习，对于即将面临的上半年工作汇报要运用四要素的方法：具体如下\u003c/p>\u003cp>事实：6月底要汇报上半年工作，基于事实汇报生产任务、技术指标等完成情况；汇报工作中存在的问题；下半年的工作目标；需要上级帮助协调解决的问题。通过有条理、有逻辑的汇报，让上级对工作有全面的了解。\u003c/p>\u003cp>观点：通过自己对上半年工作的分析，提出工作中存在的氮气成本高，循环水排放损失大，员工操作技能不高导致设备操作出现故障等三方面的情况，是导致整体生产任务完成不好的主要因素。\u003c/p>\u003cp>建议：结合上述分析和观点，建议公司开办空分知识培训班，并组织骨干人员参加杭氧公司举办的空分技术讲座，提高操作人员技术能力。\u003c/p>\u003cp>措施：单位内部针对氮气成本高，循环水排放损失大的情况，提出控制压缩机负荷节电的措施，制定班组节水奖励细则，通过激励手段降低成本；员工培训采用传帮带的形式，开展师傅带徒弟的活动，对效果好的给予奖励。上述活动需要公司给予一定的经费支持。\u003c/p>\u003cp>各伙伴的分享过程，也是对文中的知识再一次进行了运用和消化，希望我的带拆能带给你更多的收货，也希望各位小伙伴加油，成就更好的自己。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1529884863000,"updated_at":1529885090000,"ria":true},{"id":5335,"topic":"不是教你“说假话”，而是教你“有选择的说实话”","learn_goal":"如何运用叙述的说话技巧","remark":"你真的会“说话”吗？你是否有过这样的经历：参加一个活动，主持人请你做1分钟的自我介绍，结果你10秒就说完了；又或者讲得零零散散，还夹带了很多“嗯、啊、然后”之类的口头禅；又或者讲了很多个人看法，比如：我是一个吃货、我是一个很细心的人之类……\r\n\r\n不会充分利用别人给的时间说话！不会组织说话内容！不会说有价值的“实话”！这都是没有受过说话训练的人表现出来的弱点。想要改变这些弱点，我们就要系统学习说话。\r\n\r\n在《说话的力量》一书中，我们可以学到8种说话方法、4种说话技巧以及两套训练说话的工具。那么，在日常生活中，我们如何“有选择的说实话”，欢迎报名参加本期拆书活动。","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"思蓓","city":"深圳"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"大家好，我是拆书家思蓓。有三个关键词可以帮助大家记住我：拆书帮便签训练营教练、龙岗线下活动的组织者、女子国学讲师。很高兴和大家一起拆读《说话的力量》这本书。","ratings_count":1,"texts":[{"id":8484,"quote":"\u003cp>\u003cstrong>【图书简介】\u003c/strong>\u003c/p>\u003cp>在开始今天的拆书之前，我想问一下大家，大家觉得说话是一件简单的事吗？有的人说，简单；有的人说，不简单。好，我跟大家分享一个小故事。\u003cstrong>（事件）\u003c/strong>最近，我的一个男同事去参加了一场相亲联谊活动，回来后，他很沮丧说：我做完自我介绍，现场的姑娘都灭灯了。我追问他是怎么做自我介绍的，他说：我告诉大家，我是一个吃货，很喜欢美食，尤其喜欢吃自助餐，每次吃自助餐的时候，我可以每种菜都吃六份。听他这么一说，我就知道为什么现场的姑娘都灭灯了。因为他本人体型显胖，而做自我介绍时，还强调自己能吃，这样的自我介绍无异于自曝其短。\u003cstrong>（提问）\u003c/strong>请问大家，在日常生活或者职场中，当你想要通过说话来感动对方，甚至是让对方的思想或行为做出改变的时候，你会如何做？你会在话出口前，筛选一下有利于自己的说话内容吗？你会通过一些细节来启发听众吗？你会逻辑清晰的传达自己的观点，进而改变听众的思想或是行为吗？\u003cstrong>（影响）\u003c/strong>假如我们说话时，不能确保有足够的事实基础，且说出的话有一定的启发性，并用一般听众认同的逻辑表达出结论，那么我们就很难令对方的思想或者行为发生改变。\u003cstrong>（解决）\u003c/strong>孙路弘老师是一位营销及销售行为专家。他把二十多年营销以及销售领域方面的说话经验萃取编写成《说话的力量》这本书。在书中，他首创了8大说话方法、4大说话技巧和两大说话工具。帮助读者提升日常生活或职场中的语言说服力和影响力。这本书被业界誉为国内首部系统学习说话的实战指南。今天，我们就通过两个简单的片段，来学习如何应用叙述的说话方法，来改变听众的思想，进而使他们的行为发生改变。\u003c/p>\u003cp>\u003cstrong>【拆页一：学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够：\u003cstrong>（行为）\u003c/strong>区分讲述和叙述的说话方法\u003cstrong>（澄清）\u003c/strong>并应用叙述的说话方法\u003cstrong>（界定）\u003c/strong>来改变听众的思想，进而使他们的行为发生改变。 \u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【R】阅读拆页一\u003c/strong>\u003c/p>\u003cp>\u003cstrong>叙述\u003c/strong>\u003c/p>\u003cp>通过对事实的筛选，将事实按次序讲给别人，有目的地影响他人，使别人接受你的看法和观点，影响他所得出的结论，进而影响他的行为，这就是叙述。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（不这么做的坏处）\u003c/strong>在日常生活和职场中，很多人会混淆了叙述和讲述，这两种说话方式。正如开场时，我跟大家讲的案例中，我的同事去相亲时，本意是希望通过自我介绍，向女方传递我是美食爱好者的信息，由此来达到寻找有同样生活爱好的对象的目的。可是他做的自我的介绍，即没有体现出自己的说话目的——想要找一个同样爱好美食的对象，也没有围绕这个目的，好好的准备一些能引起对方进一步交流欲望的事实来作为自我介绍的内容。所以最终导致了相亲失败。\u003c/p>\u003cp>\u003cstrong>（what）\u003c/strong>那么，什么样的说话方式是符合叙述的特点的呢？\u003c/p>\u003cp>（互动）请问片段中说叙述要对什么进行筛选？（学习者）事实。（拆书家）是的，所以在说话前，我们要想一想，说出哪些事实才能影响到对方的看法和观点，对吗？\u003c/p>\u003cp>（互动）那么，筛选了事实以后，要怎样说给对方听呢？（学习者）按次序说。（拆书家）是的，要影响对方所得的结论，我们说话的逻辑很重要，所以要按逻辑次序来表达。\u003c/p>\u003cp>\u003cstrong>（对比概念）\u003c/strong>我们来看两个现实中常见的说话方式，看看是否符合叙述的要点。\u003c/p>\u003cp>（举反例）老婆想要买新的手机，于是她对老公说：老公，我的手机最近不是闪退就是死机，你给我买台新的吧。请问，老婆这种说话方式是叙述吗？（学习者）不是，因为老婆只是简单的说了事实，而这些事实不一定能让老公同意给她买新手机。\u003c/p>\u003cp>（拆书家）是的，老婆准备的事实不够说服力对吗？再来看下一个例子：\u003c/p>\u003cp>（举反例）小王在公司已经工作了三年，最近有一个升迁的机会，在做述职时，他对领导说：我在公司服务了三年，每年都获得了公司优秀员工的称号，在今年的储备干部学习考核中，我获得了前三名的好成绩。假如有机会担任主管，我会继续精进自己的业务技能，带领团队为公司创造更大的利益。请问，小王这样的表达，符合叙述的要点吗？（学习者）不符合，虽然他列举了几个事实，但是这些事实与他想要的结果之间并没有必然的逻辑关系，所以未必能影响到领导的决策。是的，小王的表达中，列举的事实与想要的结果之间，缺乏了有说服力的逻辑关系，所以很难影响对方的结论。\u003c/p>\u003cp>\u003cstrong>（适用边界）\u003c/strong>由此可见，在日常生活和职场中，假如想要改变听众的思想，影响对方所得的结论，让对方的行为发生改变的话，就必须应用叙述的说话技巧。\u003c/p>\u003cp>\u003cstrong>（行动步骤）\u003c/strong>具体的方法就是：\u003c/p>\u003cp>首先，明确自己说话的目的。你是想要向听众传递自己所知道的信息？还是想要影响听众，使对方的思想或行为发生改变？如果是后者，那么说话时就要运用叙述的技巧。\u003c/p>\u003cp>接下来，在脑子里想一想，有哪些事实是能够触动到对方的，把这些事实找出来备用。\u003c/p>\u003cp>第三步，结合说话目的，将筛选出的事进行排序，同时组织好自己的语言。\u003c/p>\u003cp>最后，先按次序说出事实，再明确表达出自己的观点或看法。\u003c/p>\u003cp>（预防异议）听到这里，可能有些小伙伴会说，这么说话也太费劲了吧？事实上，叙述的前三步都是说话前要做的准备工作，可能在脑子里一瞬间就完成了，我们只有养成三思而行的说话习惯，才能让我们说出来的话，更具有说服力和影响力。\u003c/p>\u003cp>（举正例）给大家分享一个我用叙述的技巧，成功改变好友想法和行为的例子。上周我的闺蜜在微信上跟我抱怨说，她的房东又要加她的房租了，感觉很不爽。于是，我用叙述的方式说了这么一段话：房东要加房租，相信绝大多数租客内心都是拒绝的（事实一）。所以，当事情真的发生时，有的租客选择搬家（事实二），有的租客就像你一样，发发牢骚后无奈的接受，但心里很不爽（事实三）。其实，你可以尝试用置换的思路来跟房东进行谈判，如果谈判成功，你获得了利益，那么加房租这件事也就没有那么难以接受了。朋友听完以后，马上追问我：什么是置换的思路？于是我给他介绍了置换的概念以及运用到谈判上的技巧。他听完，很庆幸的对我说：幸亏跟你唠叨了这件事，否则，就像你说的那样，我准备发完牢骚，就接受房东加房租的要求了。现在，我决定听取你的建议，用置换的方式先去跟房东谈判一下，为自己争取点利益。\u003c/p>\u003cp>（小结）就这样，我通过三个简单的事实和一个建议+技巧，不仅成功的安抚了好友的情绪，还让好友改变了想法，最后还付诸了行动。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A】催化应用——编小剧本\u003c/strong>\u003c/p>\u003cp>接下来，请大家做一个练习，用编剧本的方式，来学习运用叙述的技巧。大家如何构思剧本呢？请先想象一个日常生活或职场中的说话场景，比如：同事或朋友之间聊起阅读、养生、旅游之类的话题，或者妈妈之间聊起孩子教育的话题？等等。请构思一个说话的场景，来编一小段故事，几百字即可。故事里要设计出人物、情节变化（包括：起因、经过、结果）和人物之间的对话，其中部分对话运用了叙述的说话技巧。请大家用5分钟来编写这个小剧本。5分钟后我们请人站起来分享一下。\u003c/p>\u003cp>\u003cstrong>（学习者剧本：）\u003c/strong>\u003c/p>\u003cp>故事背景：公司要搞团建活动，经过多方调研，以及比价后，小红决定向老板推荐一种新的团建形式，并希望老板能采纳团建建议。\u003c/p>\u003cp>人物：小红和老板\u003c/p>\u003cp>时间： 某个工作日\u003c/p>\u003cp>地点：公司里，老板办公室\u003c/p>\u003cp>对话：\u003c/p>\u003cp>小红：老板，下个月的团建方案我做好了，这次的团建形式和以往有很大不同，如果你现在方便的话，我想用几分钟时间简单跟你说一下，可以吗？\u003c/p>\u003cp>老板：好的，你说吧。\u003c/p>\u003cp>小红：老板是这样的，我们公司以往团建活动，不是吃饭唱K，就是去行走爬山，很多同事反馈说，对这些形式都不感兴趣了。（事实一）而且，针对我们每次团建活动后调查数据显示，这些活动也没有达到我们团建的预期目标。（事实二）\u003c/p>\u003cp>老板：嗯，这些情况我也听说了，那么，这次的团建活动有什么新创意？\u003c/p>\u003cp>小红：老板，我在准备这次方案前，跟团建专家A老师专门请教了一些策划团建活动的方法和技巧，并且结合公司内部的团建需求进行了研究和分析，发现我们公司的员工非常希望能在户外以游戏的方式进行一些交流（事实三），所以，我建议这次的团建活动以野外求生的形式开展，主题就叫做“老板去哪儿”。我们通过分组PK的方式来完成一些指定任务，活动最后评选出优秀团队前三名，你觉得这个概念怎么样？\u003c/p>\u003cp>老板：听起来很不错，那就这么办吧。\u003c/p>\u003cp>小红：好的，谢谢老板\u003c/p>\u003cp>（拆书家）好的，非常棒的剧本，很有创意的团建概念。最重要的是，在于老板的对话中，小红先后讲述了三个事实来让老板知道，自己的团建方案不是随性而为，是经过精心的准备的，所以，当小红说出自己的建议时，老板才会认同了。\u003c/p>\u003cp>好的，关于叙述的练习，我们就先到这里。接下来我们来关注一下，如何提高叙述的影响力？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":8485,"quote":"\u003cp>\u003cstrong>【拆页二】学习目标\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够：在（行为）叙述时，（澄清）选取合适的视角（界定）进行有目的的表达。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1】请大家自测\u003c/strong>\u003c/p>\u003cp>请大家做一个简单的测评。仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分。（1代表完全不符合，5代表非常符合。）时间2分钟。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>项目\u003c/p>\u003c/td>\u003ctd>\u003cp>完全不符合\u003c/p>\u003c/td>\u003ctd>\u003cp>不符合\u003c/p>\u003c/td>\u003ctd>\u003cp>偶尔符合\u003c/p>\u003c/td>\u003ctd>\u003cp>符合\u003c/p>\u003c/td>\u003ctd>\u003cp>非常符合\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>每次叙述所见所闻前，我会先从不同的视角观察所见所闻。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>当我叙述所见所闻时，听众都能清晰的知道我的立场和定位。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>当我叙述完所见所闻，听众会改变自己的认知，进而接受我的观点和看法。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>当我评价一个朋友时，除了从朋友的视角进行叙述，我还可以从五个不同的视角进行叙述。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>当我谈论一件事情时，除了从事情影响度的视角进行谈论，我还可以从五个不同的视角进行谈论。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【I】解释自测题\u003c/strong>\u003c/p>\u003cp>好的，大家已经测评完了。我跟大家解释一下这份测评题，这份测评题是帮助大家反思，在日常生活和职场中，当你叙述自己的所见所闻时，是否能做到多视角观察，并选取合适的视角进行表达？\u003c/p>\u003cp>假如得分是20分以上，说明在日常的叙述中，你能做到多视角观察和表达。\u003c/p>\u003cp>假如得分是15-19分，说明在日常的叙述中，你只是偶尔能做到多视角观察和表达，如果要提升这方面的能力，就要做一些刻意练习了。\u003c/p>\u003cp>假如得分是14分以下，说明在日常的叙述中，你观察和表达的视角比较有限，如果想要提升自己说话的影响力，那就要在这方面下一番功夫了。\u003c/p>\u003cp>那么，我们在日常生活和职场中，如何做到多视角观察，并且在叙述时选取合适的视角呢？请阅读拆页二。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【R】阅读拆页二\u003c/strong>\u003c/p>\u003cp>\u003cstrong>选取合适的视角\u003c/strong>\u003c/p>\u003cp>视角是指叙述者观察事物、人物、情景的角度，既体现了叙述者与事物的关系，也体现了叙述者对自我的定位。因此，在叙述一个事物、人物、情景时，首先确定自己的角度非常重要，视角的选取将会影响到你和听者之间关系的发展方向。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>（预防异议）看到“选取视角”这个词，可能很多学习者会想到“换位思考”。换位思考，指的是站在对方的角度，去思考对方的想法和感受；所以换位思考其实只有一个视角，那就是对方的视角。而“选取视角”是在运用叙述的说话技巧前，要做的准备工作之一，指的是：从不同的角度去观察要叙述的人、事、物。选取视角的目的，是让听众能够通过说话者观察事物的角度，来理解说话者更深层的说话目的。\u003c/p>\u003cp>（举例）给大家举个例子，妈妈看到孩子犯了错误，于是想要告诉孩子这个错误可能造成的影响，那么，妈妈可以从哪些角度来告诉孩子呢？\u003c/p>\u003cp>1、可以从“这个错误给妈妈带来了不便以及烦恼”的角度说；\u003c/p>\u003cp>2、可以从“认可犯错是成长的必经之路，接受知错能改”的角度说；\u003c/p>\u003cp>3、可以从“这个错误对当事人造成的伤害”的角度说；\u003c/p>\u003cp>4、可以从“如何规避错误”的角度说；\u003c/p>\u003cp>大家看，面对孩子犯错这件事，假如妈妈能从不同的视角去观察，然后选取一个，与自己说话目的匹配的视角，来与孩子沟通，这时候的沟通效率就可以大大的提高。\u003c/p>\u003cp>（how）那么，叙述中要如何选取视角呢？其实，在《说话的力量》这本书中，作者并没有给到非常明确的行动步骤，只是在片段中给了几点建议：\u003c/p>\u003cp>1、选取视角前，说话的人要先从不同的视角去做观察。\u003c/p>\u003cp>2、选取的视角，要能体现出说话者与事物之间的关系。比如：当你表达自己的烦恼时，你与事件的关系就是被影响、被伤害的关系\u003c/p>\u003cp>3、选取的视角，要能体现出说话者自己的定位。比如：当你表达建议时，你的定位是有经验的人。\u003c/p>\u003cp>4、选取的视角，能让说话者和听者之间的关系朝着理想的方向发展。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】促动参与——微行动学习\u003c/strong>\u003c/p>\u003cp>（A1）知道了关于选取视角的行动建议，那么请大家回想一下，在过去一周，你与家人、朋友、同事交谈时，是否有过这样的经验：因为没有做到从多角度观察，并选取合适的视角进行叙述，所以导致你的叙述没有得到想要的结果？有哪位小伙伴愿意来分享一下自己的经验吗？\u003c/p>\u003cp>（学习者）昨天，我公司里的一个下属，午休的时候出去跟朋友吃饭，到下午三点才回到公司。那时候距离午休结束时间已经超过快一个小时了。我当时感觉很生气，所以等他回到公司以后，就把他叫到办公室里说了一通。结果，我义正言辞的说了10分钟，他最后就回了一句：我下次会注意的。听到这样的反应，我更郁闷了。\u003c/p>\u003cp>（拆书家）听起来，这确实是一个让人哭笑不得的谈话经历，那么你觉得自己当时的叙述存在什么问题？\u003c/p>\u003cp>（学习者）我其实想要从“认可犯错是成长的必经之路，接受他知错能改”的角度跟他谈话的。结果，说出来，却变成了另一个视角的意思。\u003c/p>\u003cp>\u003cstrong>（明确问题）\u003c/strong>\u003c/p>\u003cp>（拆书家）好，我来明确一下你的问题，你的问题是：在叙述前，明明选取好了视角，可是叙述时，却表达了另一个视角的说话内容，是这样吗？\u003c/p>\u003cp>（学习者）是的。\u003c/p>\u003cp>（拆书家）好的，请问现场的小伙伴，你们平时说话的时候，是否也遇到过同样的问题？\u003c/p>\u003cp>（学习者）有的。\u003c/p>\u003cp>（拆书家）看来这个问题很普遍，值得我们讨论讨论，对吗？\u003c/p>\u003cp>（学习者）是的\u003c/p>\u003cp>（拆书家）好，既然大家都认为这是一个值得讨论的问题，那么我们就用微行动学习的方法，尝试分析和解决这个问题。\u003c/p>\u003cp>\u003cstrong>（引导分组讨论问题的本质）\u003c/strong>\u003c/p>\u003cp>（拆书家）首先，请大家以小组为单位，讨论这个问题背后隐藏的真实问题是什么？请大家注意结合自己的经验，通过互相追问的方式来找到问题的本质。请注意，我们要寻找的是问题的本质，所以，大家请尽可能的聚焦在分析问题上，时间暂定为5分钟，5分钟后，看大家讨论到什么程度。\u003c/p>\u003cp>（拆书家）好的，讨论时间到了，我们先有请提供了案例的这个小组，来分享一下他们分析的结果。请问你们觉得问题的本质是什么？\u003c/p>\u003cp>（小组代表）我们觉得主要是在叙述的时候，没有应用逻辑思维组织语言才导致的。\u003c/p>\u003cp>（拆书家）好的，这是这个小组分析出来的问题的本质，其他小组认同吗？有补充吗？\u003c/p>\u003cp>（小组2代表）我们觉得控制好情绪，也很重要，有时候可能就是情绪没控制好，才会语无伦次。\u003c/p>\u003cp>（拆书家）好的，这个小组补充了一点，说话前要控制好自己的情绪，其他小组认同吗？\u003c/p>\u003cp>（学习者）同意。\u003c/p>\u003cp>（拆书家）还有补充吗？\u003c/p>\u003cp>（学习者）差不多就是这样了。\u003c/p>\u003cp>\u003cstrong>（明确问题的本质）\u003c/strong>\u003c/p>\u003cp>（拆书家）好的，我们刚才遇到的问题是：在叙述前，明明选取好了视角，可是叙述时却词不达意，没有得到想要的说话结果。经过大家的讨论和分析，现在明确了这个问题的本质是：说话前没有管理好情绪，表达时没有应用逻辑思维，就容易造成叙述时词不达意，无法达到说话目的的结果。对吗？\u003c/p>\u003cp>（学习者）是的\u003c/p>\u003cp>\u003cstrong>（引导分组讨论解决方案）\u003c/strong>\u003c/p>\u003cp>（拆书家）好的，那么接下来请大家围绕这个问题，在小组内讨论出一个解决方案。我们要如何做，才能在说话前管理好情绪，并且说话时能运用逻辑思维进行表达，把想说的话表达清楚呢？讨论时间是5分钟，请大家把讨论的思路和解决方案记录在一张纸上。5分钟以后，我们请每个小组派代表说出小组讨论的方案。\u003c/p>\u003cp>（拆书家）好的，5分钟时间到了，请每个小组派一位代表来分享一下你们的解决方案。\u003c/p>\u003cp>（小组代表）我们的方案分为两个部分，关于说话前如何管理好情绪，我们的办法是：\u003c/p>\u003cp>l&nbsp; 首先，深呼吸，直到自己呼吸平缓。\u003c/p>\u003cp>l&nbsp; 然后，回想自己的说话的目的，在心里把说话目的重复几次。\u003c/p>\u003cp>通过这两个步骤把先让自己冷静下来，并且明确自己的说话目的，才开口说话。\u003c/p>\u003cp>开口说话的时候，可以\u003cstrong>运用金字塔原理里的“因为……所以……”的逻辑思维进行表达。\u003c/strong>\u003c/p>\u003cp>l&nbsp; 先说出自己的一个观点，相当于提出第一个“因”。比如：我找你来，是想要跟你说一下，你午休时间迟到1小时的事，今天这件事在部门中造成了很不好的影响。\u003c/p>\u003cp>l&nbsp; 然后针对这个“因”，说出一个事实，相当于是“果”比如：在你回来之前，有几个部门的同事来找你对接工作，都扑了空。\u003c/p>\u003cp>l&nbsp; 接着在这个果的基础上，讲出第二个“因”，比如：因为不能跟你及时对接清楚工作，使其他部门同事的工作，也跟着耽误了。\u003c/p>\u003cp>l&nbsp; 然后针对第二个“因”，再说出一个事实，比如：你迟到一小时的事，全公司的领导都知道了。\u003c/p>\u003cp>如此循环，把想要表达的意思表达出来，而听的人也会非常清晰的接收到信息，不会造成误会。\u003c/p>\u003cp>（拆书家）好的，非常棒的解决方案，请问其他小组有补充吗？\u003c/p>\u003cp>（学习者）跟我们的差不多，大同小异。\u003c/p>\u003cp>\u003cstrong>（拆书家总结）\u003c/strong>好的，刚才大家针对说话前如何管理情绪和如何清晰的表达说话内容进行了一场微行动学习，在大家群策群力的努力下，也找到了问题的解决方案。结合到今天我们学习的说话技巧，我做个归纳总结：\u003c/p>\u003cp>当我们要用叙述的技巧与人对话的时候，我们首先要注意管理好自己的情绪，如果遇到情绪激动的时候，可以先深呼吸，让情绪平缓下来。调整好情绪以后，要再次明确自己的说话目的。明确了自己的说话目的后，选取一个说话的视角，筛选符合说话目的的事实，然后用“因为……所以……”的逻辑思维来进行表达。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2】催化应用——布置任务。\u003c/strong>\u003c/p>\u003cp>好的，听起来好像有点复杂，没关系，现在我就给大家布置一个小任务，让大家有机会做一个刻意练习。这个练习不需要在现场完成。请你在未来一周内，找机会向你身边的人，可以是亲人、朋友，也可以是同事、客户，做一次叙述练习。话题可以围绕你的兴趣爱好、当天遇到的人或事等方面展开。练习的重点是，请运用到今天所学到的叙述技巧：包括，从不同视角观察，明确说话目的、筛选有利事实、做有逻辑的表达等。请大家在纸上，写出自己的A2便签。你计划什么时候完成这个任务？找谁做这个练习？你要做到什么程度算是达成你的说话目的？给大家2分钟时间\u003c/p>\u003cp>（学习者）\u003c/p>\u003cp>目标：我今天晚上回去以后，要用今天学到的方法来跟室友分享参加拆书帮活动的心得，争取吸引她下周跟我一起来参加拆书帮的活动。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>1、 调整好自己的情绪，不要让对方感觉自己像被打了鸡血一样。\u003c/p>\u003cp>2、 明确我的目的是，动员她下周跟我一起参加拆书活动\u003c/p>\u003cp>3、 针对她最关心的三个点选择三个事实\u003c/p>\u003cp>4、 用“因为……所以……”的方式，把三个事实讲给她听\u003c/p>\u003cp>5、 最后，就是提出我的建议：下周可以跟我一起参加拆书活动\u003c/p>\u003cp>（拆书家）非常棒的A2便签，目标清晰，行动规划也都应用到了今天所学到的知识。谢谢你的分享。也期待你明天能在群里分享你的实践结果。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>好的，为今天的学习做个总结，今天学习的说话方法——叙述，可以帮助我们把话说得生动、触动人心，当我们筛选有利事实，从合适的视角进行有逻辑的表达，我们就能用语言来影响听众的思想和行为。以上就是今天我分享的全部内容，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1529050979000,"updated_at":1529050979000,"ria":true},{"id":3867,"topic":"影响力是“演”出来的","learn_goal":"学习者能够学会受众分析","remark":"","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"空林文子","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"学习目标：在跟随我完成本次RIA现场学习后，学习者能够在需要得到别人支持或者肯定的时候，提前从认知水平、价值取向及内心期待去分析受众。\r\nF：《说话的力量》的作者是孙路弘，他是营销及销售行为专家，这本书里有8大说话方法以及4大说话技巧，涵盖了讲述、表达、汇报、解释等等内容。\r\nA：市面上讲授说话技巧的书不胜枚举，但是往往都是给你提供一个绝佳的具体案例，让你在对这个案例拍案叫绝的同时，自己去领悟该案例涉及的技巧，却没帮助我们在案例中提取一个可操作的技巧或者方法，去应对各种情况，比如刘墉的《把话说到心窝里》。这本书不一样，他不仅有生动的案例，有归纳，更重要的给我们训练的方法\r\nB1：如果我们能按照书中给出的训练方法进行训练并持之以恒的践行，一定能让我们的沟通表达的能力得到很大的提升，用心地精读这一本书之后再去践行，胜过我们去读很多沟通类的书籍。当然，看完这本书只是第一步，根据书中的内容进行有意识的训练才是最重要的。\r\nB2:今天我们拆的这个片段的主题是受众分析，可以让我们大家在面对谈判和沟通对象的时候，知道该如何去分析他们，从而提高我们的成功率。接下来请大家花两分钟的时间阅读一下片段。","ratings_count":0,"texts":[{"id":6802,"quote":"\u003cp>【R】在表达中需要提前进行受众分析。分析应该从3个方面展开：\u003c/p>\u003cp>1.分析受众的认知水平。包括受教育程度、文化程度、生活的环境以及水平，甚至要了解他们的用语、他们习惯的词汇。\u003c/p>\u003cp>2.分析受众的价值取向。大致的思想境界、意识形态，以及对表达者可能的态度，是敌意还是善意。\u003c/p>\u003cp>3.分析受众的内心期待。就是他们期待听到什么，他们希望通过倾听你的表达有什么收获，是知识方面的还是信息方面的，还是得到启发、增长实际技能等。\u003c/p>","explains":"\u003cp>【I】\u003cstrong>适用边界\u003c/strong>：今天我们讲的受众分析，可以使用在很多地方，沟通、产品宣讲、工作汇报，都是可以使用这些技巧的，我总结了一下，只要是我们要将自己的想法告诉给别人并且想取得他人认可的时候，都可以使用到受众分析的方法。下面我来给大家分析一下为什么要用受众分析，以及如何使用受众分析。\u003c/p>\u003cp>1.分析受众的认知水平。认知水平就是个体对外界事物认识、判断、评价的能力,认知水平的高低与实践经验,知识水平、思维能力,信息储量等因素有关。简单说就是这个听众，对于这件事，凭借他自己本身的能力，能有多少的了解。 &nbsp; &nbsp;\u003c/p>\u003cp>eg:\u003c/p>\u003cp>案例：我教我们闺女念三字经的时候，一开始挺好的，我念人之初，她也跟着念，人之初，性本善，性相近，习相远。苟不教——她好奇地说，谁家的狗狗！我咋解释的呢？楼下的狗狗不叫。她哦一下，好像明白了。其实我知道她不明白，但是我总不能告诉她，如果不好好给小孩子教育，会产生什么现象。这样会让她蒙圈，毕竟是个小孩子。认知水平在那里，只能这样讲解了。\u003c/p>\u003cp>\u003cstrong>HOW:怎么了解对方的认知水平呢？回到\u003c/strong>原文：就是受教育程度、文化程度、生活的环境以及水平，甚至要了解他们的用语、他们习惯的词汇。\u003c/p>\u003cp>2.分析受众的价值取向。在这里指的就是对于你的表达，听众是支持还是反对的，主要考虑的是立场。\u003c/p>\u003cp>eg：比如你喜欢看书，你想让别人也喜欢上看书。你分享的对象有两类，一类是渴望通过学习提升自己的人，另外一类是持读书无用论的人。试想，这两类人，你能用同一套说辞吗？如果是我，对于渴望学习提升自己的人，我会讲述自己的一些读书心得，如何用不同的方法读不同的书，推荐一些我看过的能帮到他的书；对于读书无用论者，我会询问他们，有没有觉得自己在工作生活中有什么困惑，能力方面有什么不足，引导他们认识到读书可以解决他们的这些问题。所以，针对不同立场的人，我们要从不同的角度去沟通，否则容易造成听众的反感，试想，我举的案例中，如果对于读书无用论者，我大讲怎么读书，什么书好，他们能听的进去吗？这就达不成我们的预期目标。\u003c/p>\u003cp>\u003cstrong>HOW：怎么分析价值取向呢？\u003c/strong>回到原文：受众大致的思想境界、意识形态，以及对表达者可能的态度，是敌意还是善意。这个需要多方面收集信息，比如其所处的环境，其职位或者角色。\u003c/p>\u003cp>3.分析受众的内心期待，其实就是他们想要什么，只有知道了他们想要什么，我们才可以有的放矢，让他们成为我们的忠实听众。\u003c/p>\u003cp>eg:内心期待，其实就是对方的需求，这一点应该是最重要的。举个反例。现在微课很多，很多小伙伴应该或多或少都有购买。如果一堂微课的标题是：让你的梦中情人爱上你，大家对它的期待应该集中在怎么做？但是，如果作者上来就开讲，让你的梦中情人爱上你，你一定要有钱，怎么有钱呢，这里有一款理财产品，是量子基金旗下的什么什么设立的，它能什么什么。大家会不会有想揍人的冲动？\u003c/p>\u003cp>\u003cstrong>HOW：怎么分析对方的需求呢？\u003c/strong>这个可以提前做好问卷调查或者用询问的方式跟对方沟通，了解情况之后再做出我们的决定。\u003c/p>\u003cp>适用边界：所有需要沟通，让对方被我们说服或者将我们的观点传达给对方的场合都可以使用受众分析，比如授课、销售、日常沟通，都可以使用。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不这么做的坏处：\u003c/strong>如果不知道受众的认知水平，没有分析对方的价值取向，不知道受众的内心期待，会导致什么情况呢？对牛弹琴，一言九顶，形成沟通障碍，无法有效的达成我们的沟通目的。如果是销售，被拒绝是肯定的。如果是产品宣讲，肯定是不成功的。如果是授课，只能收获一群迷茫的眼神。以及其他的需要沟通的场合，没有做好受众分析，都非常可能造成不好的结果。\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; 分析受众就是从以上3个阶段入手。在收集到的信息不足以支持我们做出判断的情况下，一般采取中等假定，并在开始表达的初期随时观察受众的反应，随之及时调整自己的讲话内容。中等假定，其实就是保守，对于自己的立场持模糊态度，不偏不倚，可以用试探性的提问看着观众的表情，再慢慢表明的自己的观点或者表达方式，这样才能保证不至于被人轰下台，取得预期的效果。\u003c/p>","interaction":"\u003cp>A1（激活经验 显像提问）：请大家回顾一下自己有没碰到过这样的情形，比如在公司里向领导做申请或汇报，被领导驳回，再写一遍；在家里跟爸妈日常对话中；在与朋友的交往中，比如你想让他陪你去逛商城却被无情拒绝。你因为没有提前去了解对方的一些信息，比如需求、立场等相关信息，结果当你向对方表述你的想法时，遭到对方的误解、排斥乃至拒绝。\u003c/p>\u003cp>A1+（反思加工）经过今天的学习之后，让你回到当初，在沟通之前，你会提前做什么准备以防止自己被拒绝？给大家5分钟的时间在小组内分享及讨论，学习今天的知识后，以后碰到类似的情形，从受众分析的角度，你会提前做什么准备。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 我们总共有2个问题，第一个是你由于没给对方做受众分析，从而遭到拒绝的情形。第二个是如果回到过去，在谈话之前，你会做什么样的受众分析来提高被接受的成功率。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者:\u003c/strong>上个月我夫妻俩跟朋友在聊天，对方也是夫妻俩，男方人很聪明，以前还指导过我们做生意。他老婆我是第一次见面，我以为他们夫妻俩水平不会差太远。所以我跟她聊天的时候，就按照跟她老公聊天的方式聊。说着说着，发现他老婆看我的眼神是一脸懵逼的。我觉得我说的东西有问题了。后面我们还聊了其他东西，但是他老婆不时的就插话，说我们要聊的是这个，不是那个啊。后面我了解了一下他们的情况，他们刚生二胎，如果不生这个二胎，他们可能已经离婚了。男方一直在成长，女方则停滞不前。对于他们这样受众，当时我就没考虑到他们差距这么大。\u003c/p>\u003cp>\u003cstrong>拆书家\u003c/strong>：那学习了今天的受众分析之后，再给你一次机会，你会怎么会谈？\u003c/p>\u003cp>\u003cstrong>学习者：\u003c/strong>我会多听他讲，因为他在家里是说一不二的，脾气暴躁的人。那天如果由她去说，她说的越多，我就能了解的更多，从而不会导致说话的不愉快。\u003c/p>\u003cp>拆书家：这样的案例我们生活中经常可能碰到，比如我们看到对方一起过来，可能就觉得他们是朋友，其实他们可能只是电梯上碰到的。所以这警示我们，一定要问一问，你们是认识的吗？\u003c/p>\u003cp>\u003cstrong>拆书家总结：\u003c/strong>我们今天学习的受众分析，主要帮助我们在情况比较迷糊，或者我们想要达成我们的谈话目的的时候，要提前做好受众分析，没有做受众分析，就像打一场无准备的仗。作者给我们的这3个受众分析的角度，让我们的思考有章可循。可能很多小伙伴都知道注意对方的需求，但是对于对方的价值取向及认知水平的考虑可能就有所欠缺了。今天讲的这3点，刚好弥补了我们的不足。今天我们讲的受众分析，不仅可以用在商务谈判，演讲及沟通的时候也都是可以使用的。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1508399152000,"updated_at":1508399500000,"ria":true},{"id":3805,"topic":"迎合，共情","learn_goal":"用共情创造共振的场","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"梅砸","city":"南京"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"大家好，我是梅砸，在拆书之前，我先给大家分个组，在我左手边的甜甜微笑和书书何为一组，在我右手边的薏米和如风为一组。现在我给大家介绍一下今天要拆的这本书。\r\n 你认为那些口才优秀的人是天生的演讲家吗？你错了，每个人都有好口才，都可以成为演讲家，只是我们需要方法、技巧和工具不断完善与生俱来的语言能力。\r\n 《说话的力量》是国内首部系统学习说话的实战指南。它不是一本空谈理论的教科书，而是一本能直接运用于具体生活、工作的手册。贯穿全书的8大说话方法、4大说话技巧和两大说话工具是孙路弘首创的，都是倾其25年的营销、销售经验的精华之作。书中大量、丰富的案例也都是孙路弘多年来经历过的真实事件，通过这些案例我们能更形象、具体地理解说话的方法、技巧和工具。","ratings_count":1,"texts":[{"id":6723,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 迎合的3种方式\u003c/p>\u003cp>&nbsp; &nbsp; 1.给观点找事实\u003c/p>\u003cp>&nbsp; &nbsp; 叙述的要求是什么？是讲事实、筛选事实，通过事实证明观点。迎合的原理就在于此。当你听到了对方话语中的事实的时候，或者你听到他给了你一个结论的时候，你能听出他依据的逻辑，这时，你就能跟他产生共鸣。\u003c/p>\u003cp>举一个例子：“今年夏天北京可真够热的。”这句话是事实还是结论？这是一个结论，是个人看法。“地坛公园可真够大的。”这是事实还是结论？这也是一个结论，“大”是与哪里相比？这是你的判断。“我认识一个朋友，他每月挣的钱可真够多的。”在不同人的概念里，“多”的概念都是不同的。我在10个人里面调查过，有人认为1万元就算多了。有人写10万元。所以当有人对你说“今年夏天北京可真够热的”时，你要知道，这是一个结论，不是事实。那么怎么去迎合呢？你跟一句：“是啊，43℃呢，45年来最高纪录了。”你等于为他的结论提供了一个事实，他就会觉得和你投缘。\u003c/p>\u003cp>对方说了他的看法，说了一个结论，而你补充了一个事实，不知不觉中对方就觉得和你说话很投机。所谓“酒逢知己千杯少，话不投机半句多”，只有投机了，对话才容易进行下去。\u003c/p>\u003cp>&nbsp; &nbsp; 2.给事实找观点\u003c/p>\u003cp>&nbsp; &nbsp; 那么有没有可能是对方给了事实，你帮他总结出一个现点呢？当然也可以。\u003c/p>\u003cp>比如，对方说“今天刚到这里的长途汽车站，就把手机丢了”，是事实。你可以补一句：“长益汽车站那里人流量特别大，确实挺乱的“这也是一种迎合的方法，他说了一个事实，你按照他的事实补充一个结论，他会觉得你理解他的意思。不论是他说事实、你给结论，还是他说结论、你给事实，两者的逻辑是一致的，这样你们俩不知不觉就站在一起了。\u003c/p>\u003cp>&nbsp; &nbsp; 3.事实和观点都有的情况下，补充自己的细节\u003c/p>\u003cp>&nbsp; &nbsp; 如果对方说：“上周我去银行办事，人太多了，排队排了一个小时，太耽误事情。”这句话既有事实又有结论，事实是他排队排了一个小时，结论是太耽误事情。那么你又怎么去迎合？你可以这样回答：“太有同感了！上次我银行卡丢了，让我去支行补办，就这样的业务还要取号排队，结果我等了一个半小时，太耽误时间了。”\u003c/p>\u003cp>&nbsp; &nbsp; 当他有事实有结论的时候，你就给一个类似体验，让他觉得你有过共同的体会，共同的经验。这就是第三种迎合的方式一补充一个自己的体会，同样要包括类似的细节，创造出一种你们是同类的感觉。\u003c/p>","explains":"\u003cp>[What]：迎合不是吹牛，拍马屁，也不是奉承，而是表达共情，获得对方认同，共情是指在人际交往过程中，能够体会他人的情绪和想法，理解他人的立场和感受，并站在他人的角度思考和处理问题的能力，又叫做换位思考、移情、共情。\u003c/p>\u003cp>[Why]：使用共情，通过承接对方的语势，快速对对方语言中的事实，观点进行逻辑分析，通过对对方说的话进行补充等手段，使对方认可自己。能够让生活更幸福，更充实，也会提高工作的生产力。\u003c/p>\u003cp>[How]如何使用迎合的方式\u003c/p>\u003cp>1.给观点找事实\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp;意思就是别人给了一个观点，你要给一个例子来呼应。\u003c/p>\u003cp>比如对方跟你说：“南京的夏天真热啊！”，你就可以跟一句“谁说不是呢，今天都39度了！”你等于给他的结论提供了一个事实，他就会觉得跟您特别投缘。\u003c/p>\u003cp>2.给事实找观点\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp;当别人给你提供一个例子的时候，你就顺着他的话给出一个结论。\u003c/p>\u003cp>比如我的室友跟我说：“我的论文导师已经叫我改了五次了！”我当时就回答她说：“是啊，改论文好烦啊，我导师也叫我改了很多次！”我给她的事实补充了一个结论，这也是一种迎合的方式。\u003c/p>\u003cp>3.事实和观点都有的情况下，补充自己的细节\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp;当别人事实和观点都有的情况下，你可以补充一个和他类似的案例，让你和对方产生共鸣。\u003c/p>\u003cp>比如对方和你说：“上周我去银行办事，人太多了，排队排了一个小时，太耽误事情了。”这句话既有事实，又有结论，你就可以给一个类似的经验，让他觉得你和他有过共同的体会，你可以这么回答：“太有同感了，上次我银行卡丢了，去银行补办，等了整整两个小时，太耽误时间了。”\u003c/p>","interaction":"\u003cp>给出A1的指令：\u003c/p>\u003cp>&nbsp; &nbsp; 我们读过这个拆页，了解到要想和别人产生共情，就要使用一定的迎合技巧，那么，请大家想一想自己有没有过类似的因为没有使用“”事实＋观点“的说话方法而导致对话失败或者沟通不顺利的的经历，要有具体的事件，有时间、人物、起因后果。\u003c/p>\u003cp>&nbsp; &nbsp; 现在给大家2分钟的时间在小组内讨论一下，然后请一个代表来回答。\u003c/p>\u003cp>&nbsp; &nbsp; 拆书家记录：\u003c/p>\u003cp>&nbsp; &nbsp; 书书何：上次和老板一起出差，他对我说：“你看，外面的景色真漂亮！”，我向外面瞥了一眼，说“有什么好看的！”老板的脸都黑了……\u003c/p>\u003cp>A2：\u003c/p>\u003cp>&nbsp; &nbsp; 好，学习了今天的迎合技巧，你在生活中会如何用？请在便签纸上写下来。要有具体的做法，要有明确的时限，要有可衡量或可观测的语预期结果。\u003c/p>\u003cp>&nbsp; &nbsp; 拆书家记录：\u003c/p>\u003cp>&nbsp; &nbsp; 甜甜微笑：在未来的一周内，说话时注意用“事实＋观点”的方法回应别人，不要总是用“嗯嗯、是的”或者点头来表达，应该找出一个事实来证实观点，这样才能更好地迎合他人的观点。同时注意用便签来及时监督自己，做出反馈。\u003c/p>\u003cp>&nbsp; &nbsp; 棒妈：在近三天的时间里，记录老公带宝宝的时间，然后把这个“事实”告诉老公，让他意识到他陪宝宝的时间不太多（观点），希望能够说服他，多花一些时间来陪宝宝。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":6724,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":6725,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":6726,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":6727,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":6728,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":6729,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":6730,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":6731,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1507343414000,"updated_at":1507343414000,"ria":true},{"id":3804,"topic":"表达沟通","learn_goal":"用触动人心的事实传达观点","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"梅砸","city":"南京"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"自我介绍（1分钟） 大家好，我叫梅子，目前是南京师范大学研二的学生。我的专业是对外汉语。阅读、写作、记手账是我的三个标签。\r\n 阅读能让我在这个喧嚣、浮躁的社会里保持冷静、写作让我不断地进行自省与反思，记手账让我感受生活中的小确幸，同时我可以通过手账设立自己的目标，并一步一步地去达成。\r\n 目前我在我的学院国际文化教育学院教预科班的留学生，我的班里有16个学生，他们来自15个国家，身为一个老师，跟学生之间的沟通交流是必不可少的，以前是跟中国人交流，我们有相同的文化背景，交流起来更容易。但现在面临着世界各地的不同语言背景、文化背景下、宗教背景下的学生，交流的难度也大大增加。所以如何沟通、如何说话也显得尤为重要了。在乔阳的推荐下，我选择的也是一本和沟通交流有关的书籍《说话的力量》，希望今天能和大家一起学习一下。 \r\n 很久以前我就知道了拆书帮这个组织，对于“把知识拆成能力”的理念非常认同也非常感兴趣，很高兴在南京找到了组织。希望能和大家一起在这个大家庭中一起进步，早日成为一个合格的拆书家，努力践行“终身学习”的理念，学而不已， 阖棺乃止。","ratings_count":2,"texts":[{"id":6722,"quote":"\u003cp>◆筛选有利的事实\u003c/p>\u003cp>世界上每天发生的新鲜事成百上千，为什么报纸上只登了十件？那是因为报纸的编辑对信息进行了筛选。什么样的新闻有它的特色，什么样的新闻有它的价值，都是经过了评判的。而每个人就如同一个媒体，你所传达给听者的事实同样是需要经过筛选的。\u003c/p>\u003cp>因此，叙述的重要要求之一就是，当你有一个明确的看法、试图影响对方的时候，要把一些对你不利的、与你看法不一致的事实屏蔽掉，这就是筛选事实。\u003c/p>\u003cp>在国内很火的相亲娱乐类节目《非诚勿扰》中，每位男嘉宾登场时都会播放一段录像，来展示他在日常生活中的风貌。有的男嘉宾想把自己的形象塑造成事业心很强的职业人，面对镜头他就会着重叙述自己加班到深夜，为公司创造了巨大的业绩，年收入数十万等事实。有的男嘉宾想把自己塑造成体贴顾家的经济适用男，他可能会更多的叙述自己照顾生病的父母，为女朋友做饭等事实。而某一期有一位男嘉宾，明明体型比较胖，还叙述自己吃自助餐时每种莱都吃六份。这样的事实，能给在场的女嘉宾传达什么观点呢？结果可想而知，他被全场的女嘉实灭灯了，这就是不注意筛选事实的后果。\u003c/p>\u003cp>●传达观点，造成影响\u003c/p>\u003cp>叙述的最终目的是传达你的观点，影响听者的思维和行动。而检验叙述成功与否的最终标准，就是你有没有对他人造成影响。观点必须鲜明，让听的人立刻理解你的立场、态度和看法，这是对叙述中最后引导出来的观点的考核。因此，请确保在你的叙述中，有足够的事实基础，符合一般社会常识，使用一般听者认同的逻辑演绎出你的结论，从而形成你自己有说服力的观点。终于可以表达你的个人看法了。比如，世博会对中国经济的影响，弊大于利。这个观点是否可以通过若千事实按照逻辑推导出，或者是否可以液教听者普遍认同、造成影响，这才是叙述的终极目标。\u003c/p>","explains":"\u003cp>[what] 通过对事实的筛选，将事实按次序讲给别人，有目的地影响别人，使别人接受你的看法和观点，影响他所得出的结论，进而影响他的行为，这就是叙述。\u003c/p>\u003cp>[why]使用叙述的技巧，能够使你在讲话时更具影响力，同时也能够让你的社交能力得到显著提高，这里面包括目的性思考的能力，动态观察的能力和灵活交谈的能力。\u003c/p>\u003cp>[how]\u003c/p>\u003cp>1.筛选出对自己有利的事实，摒弃、屏蔽一些对自己不利的、与自己看法不一致的事实。\u003c/p>\u003cp>2.观点必须鲜明，让听的人立刻理解你的立场、态度和看法。\u003c/p>","interaction":"\u003cp>【A1】反思加工经验\u003c/p>\u003cp>&nbsp; &nbsp; 我身边有很多朋友单身，他们都很优秀，但是因为圈子比较小的缘故，他们并没有机会去认识外面优秀的异性。有一次，我跟我一个大学的朋友聊天，他很苦恼啊，他说快七夕了，大街上到处都是情侣在撒狗粮，他只能关着门在家打农药。他就说师范学校女生资源多，让我给介绍介绍。我一听就来劲儿了，我说我有一个室友肤白貌美大长腿，本科英语系的，能讲一口麻溜儿的英语，又温柔又体贴还不败家，你肯定喜欢这一款的，然后还要把她的微信号给他，他就一直嗯嗯、哦哦地回应着，后来，就没有后来了。\u003c/p>\u003cp>&nbsp; &nbsp; 看完这一个片段之后，我就明白了，我之所以没有让我的话起到作用，很关键的原因就是，我只是在表达自己的观点，而没有筛选出论证我观点的有利事实，所谓“空口无凭”，那别人不以为然也是正常的。我当时说我室友肤白貌美大长腿的时候，我可以加一个事实，“她非常注意自己的形象，每天7点起床、11点睡觉，每天按时运动；当我说我室友英语好的时候，也可以加上这样的事实“她英语过了专八，拿到了高级商务英语的证书，每天中午都会看TED，在英语去配音的软件上配了几百个音频。”，如果我当初这样说的话，结果应该会不一样。\u003c/p>\u003cp>【A2】:&nbsp;下一步计划行动\u003c/p>\u003cp> &nbsp; &nbsp; 我打算在未来的一周内，用三次这个方法来和身边的学生、朋友进行沟通、交流。比如说当我的闺蜜和她男朋友吵架闹分手的时候，我就不能很主观地说“唉，情侣之间吵吵闹闹很正常啊，过几天就好了”“他对你不是挺好的嘛”等等，而是采用“事实＋观点”的方法，比如：“你想一想，你上次感冒生病，他淋着大雨过来给你送药，七夕节的时候，他还给你送花虐我们。吵架的时候多想一想他的好，情侣之间有矛盾很正常，不要伤了和气。”这样的说话方式，效果应该会好很多。\u003c/p>\u003cp>&nbsp; &nbsp; 每当我要表达自己的观点的时候，我都会提醒自己先筛选事实，然后明确地表达自己的观点。并且在完成对话之后拿便签记录反思一下，看看我今天的叙述有没有采用“事实＋观点”方法来做一个监督反馈、长此以往，形成习惯。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1507342028000,"updated_at":1507342484000,"ria":true},{"id":3747,"topic":"掌握合理汇报三要素","learn_goal":"学习者能够应用汇报的三个要素，做一次完整的无遗漏的汇报。","remark":"光说不练假把式，光练不说真把式，连说带练全把式。拆书家将给你带来汇报的三大技巧。以后再也不怕要汇报了。","level":"TF2-1","duration":18,"status":0,"type":0,"chaishujia":{"username":"郑娇","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"大家好，我是今晚的拆书家郑娇。今晚的想目标是在跟随我完成本次RIA现场学习法后，学习者能够应用汇报的三个要素，做一次完整的无遗漏的汇报。\r\n 【F】 ：今天我所分享的书籍是《说话的力量》，作者是孙路弘，资深营销专家。他提出这样要一个观点：说话是需要学习的。\r\n 【A】 ：这本书是拆书家们推荐的书籍之一。因为它符合拆书帮的理念和成人学习者的需要，不仅有理论更有方法、工具。运用8大说话方法、4大说话技巧、2大说话工具。让大家在理解理论的同时，也能用于生活中的练习。\r\n 【B】 ：工作和生活中离不开说话，但并不是所有人都能说出自己想要的样子。你希望活跃气氛，但一说话，整个场子都变冷变尴尬。你花了大量心力去做的一件事，当领导问及时，你的汇报不但没能等到上级的赞扬，反而被指指点点。让你自信心遭到了打击？碰到这些问题怎么办呢？这本书，告诉你说话是需要练习、是可以练习，并教你怎么练习的。拥有它，让你职场、生活大不一样。","ratings_count":0,"texts":[{"id":6660,"quote":"\u003cp>合格汇报的3大要素\u003c/p>\u003cp>汇报的主要构成有三大要素：事实、观点和建议，用时比例约为4：2：4。如果是下级向上级汇报，至少要提供两点建议，并预留时间对建议的实施进行一定的预测；更高层的汇报则要求提供落实建议的资源规划内容。\u003c/p>","explains":"\u003cp>大家工作生活中随处都需要汇报。领导会说：你那个事进展怎么样了？事件的进展、完成情况，这是一个汇报。月度、年度等时间节点，你做的工作总结计划，这是一个汇报。不管是正式的、还是非正式的，固定的还是临时的。可以说每个人的工作都离不开汇报。\u003c/p>\u003cp>1、【What】什么是汇报？\u003c/p>\u003cp>汇报：是指汇集材料向上级或群众报告，表达一个明确的主题，提出一定的建议，达到预期的效果，要让听的人受到影响和触动。\u003c/p>\u003cp>2、【案例】在这里我也分享一个我的案例。拆书帮其实就是个小职场，春哥是我的上级。有一天春哥来视察长沙分舵的运营情况，问到：最近拆书线下活动情况怎么样啊？我积极的回答说：李总，非常好，那活动是持续火爆啊。场场爆满。\u003c/p>\u003cp>我们来看看我的汇报是不是很完整？如果你是李总听到后，会有什么感受呢？可能肤浅的李总他会觉得很好啊，不错啊。但是李总他是有智慧的啊，他会想，场场火爆，到底每场来了多少人呐？火爆情况是什么样子呢？当我报出每场来了十个人，李总心里瞬间凉了。他会觉得你这个人有些浮夸，来了十个人你都说场场爆满。你这个人做事有些不踏实。标签就这么给我贴上了。为什么会这样呢？因为我的汇报里缺乏了事实。每场到底来了多少人？这就引出今天要讲，我们平时汇报都有哪些问题？\u003c/p>\u003cp>3、【不那么做的坏处】领导对你的汇报不满意，通常是因为汇报不完整，缺乏必要因素。回忆下大家平时的汇报是怎样的？① 有事实、没观点；② 有观点、没事实；③ 最常见的是没有建议。这样做有什么问题呢？有事实，没观点，会给人以没主见的印象；有观点没事实，让人觉得这人怎么这么不踏实，太过主观、个人化。而没有建议，大家注意，表面上看，它没有什么过错。而恰恰，它就是能体现你是否能对一件事情的结果负责，并积极思考解决问题的能力。能不能提拔你？为什么呢，因为领导通过这点可以看出你有没有积极的思考问题。试问，谁会愿意提拔一个万事只会做执行，只会找领导，问我该怎么办、怎么办的人？有几个人当有机会的时候，你会提拔这样的下级？所以我们会发现，不能好好的汇报对你的职场升迁影响是很大的。但往往被你忽略了。\u003c/p>\u003cp>4、【How】那我们该怎么做呢？正确合理的汇报应该是什么样子的呢？有一个万能公式：合理汇报＝事实＋观点＋建议。为了便于大家理解，我举一个正面的案例。\u003c/p>\u003cp>【正面案例】第二天李总又来巡视了，刚好是锦康在。同样被问到这个问题的锦康是这样回答的：李总，我们8月份一共举办了4场线下活动，平均到会人数高达15人。而最近一场报名人数超过20人。这是在说什么？数据，大量的数据说明事实。（事实）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;我认为随着帮的影响力越来越大，场地可能太小，将影响参与者的体验。这个是什么，我认为，我的观点。（观点）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;所以建议这边可以联系第二场地，在人数过多的时候，采用两地同期进行。或者咱们可以在活动发布时，就限制报名人数。您认为如何？李总？（建议）李总这个时候可能会去思考，评估两个建议的可行性了。同时他会认为锦康这个小伙子不错，很聪明，会想问题。这个时候锦康是用了这个公式，发生了什么？事实。我认为？观点。我建议？这样做了一个完整的汇报。所以汇报的三要素是：事实＋观点＋建议\u003c/p>","interaction":"\u003cp>【拆书家提问设计（逐字稿）】：现在请大家回忆一下，你有没有碰到过类似的情况？有一天在公司，你的上司突然走到你的身边。拍拍你的肩膀，很随意的询问，你目前在进行中一件事情的进展。当时，你说了什么？给大家2分钟的时间，大家组内分享。我们以桌子为界限，分为两组。\u003c/p>\u003cp>当时汇报了什么事情，你是怎么说的。说了什么？请问我指令清晰吗？有些人说我是当领导的，也没关系，你作为上级追问事情进展的时候，你的下属是怎样回答你的？说了什么？\u003c/p>\u003cp>【学习者案例】：\u003c/p>\u003cp>有个下属，当时我问他这个月款回得怎么样了？他跟我说这边好难，找不到人，怎么怎么样。其实我想知道的是这个月能回100万，回了80万，还有20万怎么样。\u003c/p>\u003cp>【拆书家提问设计（逐字稿）】：好的。那我们现在想，如果再碰到刚才那个场景，或者说你是这个下属的话，根据刚才拆页的建议，就汇报三要素（事实、观点、建议），你会怎么向你的上司汇报呢？组内分享下，给大家3分钟的时间。\u003c/p>\u003cp>重申一下，我们这三个要素没有固定顺序的。因为刚小组讨论时已经有超出本知识点的高度。所以沟通下。请问，我刚的点需要重复一下吗？刚刚那个场景里的汇报，如果是你，你会怎么说。好的。讨论结束后我们请一位伙伴再分享一下。.\u003c/p>\u003cp>【学习者案例】：\u003c/p>\u003cp>小张：这个月的回款怎么样啦？李总，是这样的。我们这个月的应回款是100万。现在已回款是80万，其中有20万是没有回来。为什么没回来呢？其中有10万，是对方躲着我们。另外十万呢，是对方财务表示确实有困难，给不了我们。我的建议，那个躲着我们的，咱们直接去找他们集团公司领导；而这个财务有困难的呢，因为只是这个月暂时有困难。为了不破坏我们的长期合作关系，邀约他们定出还款计划，明确还款时间。我的汇报完了。\u003c/p>\u003cp>运用事实、观点、建议的公式汇报，会让你的职场如鱼得水，那么从现在开始珍惜你的每一次说话、汇报吧。我的拆解到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1506321751000,"updated_at":1506322175000,"ria":true},{"id":3410,"topic":"受众分析","learn_goal":"学习者能够在需要得到别人支持的时候，运用受众分析提前准备。","remark":"","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"空林文子","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"【图书介绍】\r\nF：《说话的力量》的作者是孙路弘，他是营销及销售行为专家，这本书里有8大说话方法以及4大说话技巧，涵盖了讲述、表达、汇报、解释等等内容。\r\nA：市面上讲授说话技巧的书不胜枚举，但是往往都是给你提供一个绝佳的具体案例，让你在对这个案例拍案叫绝的同时，自己去领悟该案例涉及的技巧，却没帮助我们在案例中提取一个可操作的技巧或者方法，去应对各种情况，比如刘墉的《把话说到心窝里》。这本书不一样，他不仅有生动的案例，有归纳，更重要的给我们训练的方法\r\nB：如果自己根据书中的要求进行练习，我们都可以成为一个沟通大师。今天我们讲的是受众分析，它主要是从三个方面去思考我们的受众的信息的。下面请小伙伴帮我分发一下片段，请大家花1分钟的时间阅读一下这个片段。","ratings_count":0,"texts":[{"id":6267,"quote":"\u003cp>【R】在表达中需要提前进行受众分析。分析应该从3个方面展开：\u003c/p>\u003cp>1.分析受众的认知水平。包括受教育程度、文化程度、生活的环境以及水平，甚至要了解他们的用语、他们习惯的词汇。\u003c/p>\u003cp>2.分析受众的价值取向。大致的思想境界、意识形态，以及对表达者可能的态度，是敌意还是善意。\u003c/p>\u003cp>3.分析受众的内心期待。就是他们期待听到什么，他们希望通过倾听你的表达有什么收获，是知识方面的还是信息方面的，还是得到启发、增长实际技能等。\u003c/p>","explains":"\u003cp>【I】分析受众就是从以上3个阶段入手。在收集到的信息不足以支持我们做出判断的情况下，一般采取中等假定，并在开始表达的初期随时观察受众的反应，随之及时调整自己的讲话内容。\u003c/p>\u003cp>1.分析受众的认知水平。\u003c/p>\u003cp>不这样做的坏处:如果不知道受众的认知水平，大家觉得会出现什么情况？对牛弹琴，鸡同鸭讲，达不到我们沟通的目的。\u003c/p>\u003cp>Eg:我教我们闺女念三字经的时候，一开始挺好的，我念人之初，她也跟着念，人之初，性本善，性相近，习相远。苟不教——她好奇地说，谁家的狗狗！我咋解释的呢？楼下的狗狗不叫。她哦一下，好像明白了。其实我知道她不明白，但是我总不能告诉她，如果不好好给小孩子教育，会产生什么现象。这样会让她蒙圈，毕竟是个小孩子。认知水平在那里，只能这样讲解了。\u003c/p>\u003cp>2.分析受众的价值取向。在这里指的就是对于你的表达，听众是支持还是反对的，主要考虑的是立场。\u003c/p>\u003cp>eg：比如你喜欢看书，你想让别人也喜欢上看书。你分享的对象有两类，一类是渴望通过学习提升自己的人，另外一类是持读书无用论的人。试想，这两类人，你能用同一套说辞吗？如果是我，对于渴望学习提升自己的人，我会讲述自己的一些读书心得，如何用不同的方法读不同的书，推荐一些我看过的能帮到他的书；对于读书无用论者，我会询问他们，有没有觉得自己在工作生活中有什么困惑，能力方面有什么不足，引导他们认识到读书可以解决他们的这些问题。所以，针对不同立场的人，我们要从不同的角度去沟通，否则容易造成听众的反感，试想，我举的案例中，如果对于读书无用论者，我大讲怎么读书，什么书好，他们能听的进去吗？这就达不成我们的预期目标。\u003c/p>\u003cp>不这么做的坏处：如果我们不去分析受众的价值取向，容易被人直接拒绝或者反感，直接轰下台，一言九顶，被顶回去的顶。\u003c/p>\u003cp>3.分析受众的内心期待，其实就是他们想要什么，只有知道了他们想要什么，我们才可以有的放矢，让他们成为我们的忠实听众。\u003c/p>\u003cp>eg:内心期待，其实就是对方的需求，这一点应该是最重要的。举个反例。现在微课很多，很多小伙伴应该或多或少都有购买。如果一堂微课的标题是：让你的梦中情人爱上你，大家对它的期待应该集中在怎么做？但是，如果作者上来就开讲，让你的梦中情人爱上你，你一定要有钱，怎么有钱呢，这里有一款理财产品，它非常好，它能什么什么。大家会不会有想揍人的冲动？\u003c/p>\u003cp>不这么做的坏处：明白受众的内心期待，可以让我们抓住受众的内心，顺利达成我们的预期目标，否则容易被人称为标题党，骗子，或者要求退票退钱。\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A1\u003c/strong>\u003cstrong>】拆书家提问设计\u003c/strong>：\u003c/p>\u003cp>A1（激活经验 显像提问）：请大家回顾一下自己有没碰到过这样的情形，比如在公司里向领导做申请或汇报，被领导驳回，再写一遍；在家里跟爸妈日常对话中；在与朋友的交往中，比如你想让他陪你去逛商城却被无情拒绝。你因为没有提前去了解对方的一些信息，比如需求、立场等相关信息，结果当你向对方表述你的想法时，遭到对方的误解、排斥乃至拒绝。\u003c/p>\u003cp>A1+（反思加工）经过今天的学习之后，让你回到当初，在沟通之前，你会提前做什么准备？给大家5分钟的时间在小组内分享及讨论，学习今天的知识后，以后碰到类似的情形，从受众分析的角度，你会提前做什么准备。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 我们总共有2个问题，第一个是你由于没给对方做受众分析，从而遭到拒绝的情形。第二个是如果回到过去，在谈话之前，你会做什么样的受众分析来提高被接受的成功率。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>学习者:我们是做教育培训的，我们去工厂里做宣讲的时候，发现下面的人根本就不在听，完全不感兴趣，最终导致我们的宣讲非常失败，没有起到应有的作用。现在反思一下，就是我们当时去之前，没有考虑这些人的教育程度，是初中还是高中。另外，我们也不知道他们的需求，不能让他们对我们的宣讲感兴趣。这就是典型的没有做好受众分析导致失败的案例。\u003c/p>\u003cp>拆书家：那学习了今天的受众分析之后，以后你会怎么做？\u003c/p>\u003cp>学习者：学习今天的受众分析之后，我们会设计一些环节。首先是了解他们的受教育程度，安排我们的语言及措辞，让他们听得懂。其次就是他们的价值取向，如何激发他们的痛点。第三就是他们的期待，一个小时他们想从我们这里得到什么东西。这样重新梳理之后，相信我们的宣讲会有不一样的结果。\u003c/p>\u003cp>拆书家总结：这是典型的因为没做好受众分析从而导致的受挫。作者给我们的这3个受众分析的角度，让我们的思考有章可循。可能很多小伙伴都知道注意对方的需求，但是对于对方的价值取向及认知水平的考虑可能就有所欠缺了。今天讲的这3点，刚好弥补了我们的不足。今天我们讲的受众分析，不仅可以用在商务谈判，演讲及沟通的时候也都是可以使用的。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1502591705000,"updated_at":1502591705000,"ria":true},{"id":2867,"topic":"迎合三步骤","learn_goal":"学习者能够复述并在练习中使用迎合的三步骤。","remark":"人与人之间交流、沟通的目的是加强彼此的了解，建立关系，最终取得信任。如果彼此经历类似，看法相同，就特别容易理解对方，容易建立关系\r\n说话会让生活更幸福、更充实，也会提高工作的生产力。而迎合就是一种人与人之间和谐相处必须的沟通技巧。","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"李杏梅","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"伙伴们，大家晚上好，我是杏梅。今天的【学习目标】：在跟随我完成本次RIA现场学习后，学习者能够了解表达迎合3步骤，并在现场初步演练。【情景】 在周二，和家人一块去聚餐，吃饭的时候，侄女不小心勺子掉到地上了，于是我就喊：“服务员帮我拿个勺子来”。服务员说：“好的，你等一下“。我听到 “等一下”，心里仍然不高兴。等一下是等多久，2分钟过了，怎么还没有来。感觉很不耐烦。【提问】如果你是当时的服务员，你会怎么回答我呢？刘洋凌子：我可能也会说等一下。嗯，好的，贞贞：不满意，我想听到的是：好的，马上就来。【影响】 服务员对顾客的回答，看起来是个小事，其实一点也不小。一句不贴心的回答，加上后续服务没跟上，就等于说“你下次别来了，谢绝光临”。小则一个顾客，大则失去更多的客户，潜在的客流量走失。【解决】好的措辞就像做菜，是有谱可循的，只要掌握了菜谱，任何人都有可能做出美味佳肴，本书作者孙路弘把措辞菜谱写进了《说话的力量》，有8个菜系，4道甜品。如果餐厅的服务员看过这本书《说话的力量》， 学习了使用迎合的方式。他就会立刻回答：我马上去给您拿，这样就符合消费者的心理。在今天的内容我先给大家来一道小菜-迎合。","ratings_count":0,"texts":[{"id":5648,"quote":"\u003cp>片段来源：《说话的力量》p169页&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 作者:孙路弘\u003c/p>\u003cp>&nbsp; 在现实生活中，为人父母的读者可能经常遇到这样一个问题，你关心孩子，孩子却觉得你侵犯了他的空间和隐私。如果你掌握了迎合的技巧，就应该能够妥善处理这个状况。\u003c/p>\u003cp>&nbsp; 儿子回家一直嘟着小脸，他说在课间休息时，同学们欺负他不让他加入足球游戏。作为家长，你会做什么反应？\u003c/p>\u003cp>&nbsp; 有的家长可能脱口而出:“你怎么那么笨啊！他们欺负你，你不会打他们啊，你不会告诉老师啊？”这样的回答显然不合格。\u003c/p>\u003cp>&nbsp; 有的家长回答：“没有的事，同学们不会不喜欢你的。妈妈最爱你了。”这样的回答也不合格。\u003c/p>\u003cp>&nbsp; 一位有共情的妈妈是这么做的，她先坐在和儿子一样高的位置上，耐心听儿子把今天的遭遇讲完。儿子讲了半个小时，讲完后他的情绪就平复了一些了。\u003c/p>\u003cp>&nbsp; “因为他们不带你玩，所以你觉得伤心。“妈妈表示理解。\u003c/p>\u003cp>&nbsp; 小男孩点了点头。\u003c/p>\u003cp>&nbsp; “刚刚你给我讲了你在课间活动时遇到的不愉快，我能体会你有多么伤心和失落。但是我在想如果这样的事情再次发生的话，这儿可能有个解决方法。你愿意听听我的建议吗？“\u003c/p>\u003cp>&nbsp; 这时，如果孩子摇摇头说：“不用了，妈妈。”他并没有许可你给他任何建议。但如果他向你投来好奇的目光，你就可以打开闸门，尽情地向他解释、说明、教导他应该怎么做。\u003c/p>","explains":"\u003cp>谢谢刘洋凌子，声情并茂地为我们朗读了这个片段，我们一起给她送上掌声。\u003c/p>\u003cp>\u003cstrong>（提问）\u003c/strong>我想问一问大家，有哪位小伙伴愿意分享一下，看完片段后的感受。\u003c/p>\u003cp>\u003cstrong>学习者蓉姐\u003c/strong>：共情的妈妈，在耐心倾听孩子的事情之后，再与孩子交谈，保持平等的交流模式，最后再给出建议。\u003c/p>\u003cp>\u003cstrong>学习者丠丠\u003c/strong>：还有倾听孩子的需求，把双方的情绪平复下来，站在孩子的角度思考这个问题。\u003c/p>\u003cp>\u003cstrong>【拆书家】\u003c/strong>：两位伙伴都很好地提炼了片段中的核心观点：共情、耐心倾听、站在对方的角度、给出建议。这几点正是我们要分享的迎合说话技巧里面的内容。\u003c/p>\u003cp>片段中是为人父母，遇到了类似孩子的课间活动的不愉快，有些父母的回答不合格，而共情的父母却能很好地与孩子进行交谈，并且让孩子感觉到了受尊重，这就是一种高超的迎合技巧。\u003c/p>\u003cp>【\u003cstrong>区分概念\u003c/strong>】\u003c/p>\u003cp>片段中有\u003cstrong>共情\u003c/strong>指的是我们常说的换位思考，体会他人的情绪，理解他人的立场和感受，站在他人的角度和处理问题的能力。\u003c/p>\u003cp>\u003cstrong>举个例子\u003c/strong>:朋友说他今天考试考砸了，好难过。听完他的话，我能体会他的情绪-因为考试的事情，所以不开心。这就是\u003cstrong>共情\u003c/strong>。\u003c/p>\u003cp>\u003cstrong>迎合\u003c/strong>：将共情用说话的方式表达出来，让对方直接、快速，感受到这个人跟自己一样，有一样的逻辑，有同样的经验和体会，能够产生共鸣，双方就容易接近了。\u003c/p>\u003cp>\u003cstrong>举个例子\u003c/strong>：朋友说他今天考试考砸了，好难过。听完他的话，从他的角度上体会他的情绪之后，并且说：对啊，我能明白你的感受，我大二的医学课程就分数才67分，当时也是心里难受了很久。这就是\u003cstrong>迎合\u003c/strong>。\u003c/p>\u003cp>注意的是：在我们这里说的，共情是一种能力，而迎合是一种说话技巧。\u003c/p>\u003cp>\u003cstrong>【反面案例】\u003c/strong>小明在读书会现场，对桃子说：谁不知道你的鼎鼎大名呀！我们一起来做这个读书会，你是老大，你说了算。你看，这就不符合迎合。\u003c/p>\u003cp>迎合，不是吹牛，拍马屁，也不是奉承，而是表达共情，获得对方认可。\u003c/p>\u003cp>我们刚刚一起了解了迎合的概念和要点，以及在片段中两位伙伴提出的观点，从中能够归纳出迎合最核心的三个步骤：\u003c/p>\u003cp>\u003cstrong>耐心倾听——迎合感受——提出建议\u003c/strong>\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp; \u003cstrong>耐心倾听\u003c/strong>：片段中的妈妈坐一样高的椅子听孩子讲了半个小时。\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp; \u003cstrong>迎合感受\u003c/strong>：片段中妈妈在倾听之后，跟孩子说：“因为他们不带你玩，所以你觉得伤心。”这就是迎合孩子的感受，站在孩子的角度来表达。\u003c/p>\u003cp>\u003cstrong>迎合感受，也是三步骤的重点、难点\u003c/strong>，很多伙伴不知如何下手。\u003c/p>\u003cp>在这里分享有2种迎合感受的方式，把它称为\u003cstrong>黑白配\u003c/strong>\u003c/p>\u003cp>黑：\u003cstrong>他说观点我补事实\u003c/strong>：有人同我说“每年夏天长沙可真够热的”。这个是一个观点，不是事实。补一个事实来迎合他：“是啊，43℃，是45年来最高纪录了”。\u003c/p>\u003cp>白：\u003cstrong>他说事实我补观点\u003c/strong>：一个人向我抱怨：“5分钟不到网都断了8次。”他说的是个事实，不是观点。补一个观点迎合他：“是啊，这里的WIFI信号确实不好。”\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp; \u003cstrong>提出建议\u003c/strong>:片段中的妈妈对孩子说：“你愿意听听我的建议吗？&quot;&nbsp;\u003c/p>\u003cp>提出建议这一步骤，是为了更好地解决问题，如果对方只是需要倾听，那么这一步骤可以省略。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>总结：1耐心倾听 2 迎合感受 3 提出建议 （迎合感受：黑+白，二选一也可）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【边界】\u003c/strong>：不仅适合片段中的家人之间的对话，也适合客户，陌生人之间，还有朋友之间的交流，快速开启心门，容易建立关系。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>提问设计：\u003c/strong>我们刚才介绍了迎合的三个步骤（提问+总结），那么接下来我们就要编一编剧本了。请每个人自己来编一段小故事，未来很有可能遇到的场景，设计出人物、情节变化（包括起因、经过、结果）和当时和朋友或家人的对话、动作等。角色应用中能够结合到“迎合三步骤”的知识。在小组内讨论，时间为5分钟。5分钟后我们请人来分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>：故事的背景是：刘洋凌子的工作是客服，可能在以后会遇到不配合的顾客。\u003c/p>\u003cp>两种角色扮演：刘洋凌子是客服人员，蓉姐是顾客。\u003c/p>\u003cp>起因:蓉姐进店办业务，语气急得不行，说：“我的手机怎么回事，处理一下”。\u003c/p>\u003cp>刘洋凌子对蓉姐说：“您好，请问有什么需要帮助您的吗”？\u003c/p>\u003cp>蓉姐说：“您看看我这个新买的手机，怎么回事，昨天拿回去就充电2小时，一点反应都没有，你看看新买的，怎么会出现这样的问题”。（语气特别强硬，甚至敲桌子）\u003c/p>\u003cp>\u003cstrong>耐心倾听\u003c/strong>之后，刘洋凌子说：您说新买的手机充电充不进去，是吗？（\u003cstrong>迎合感受-\u003c/strong>\u003cstrong>对方给事实我补观点\u003c/strong>）\u003c/p>\u003cp>蓉姐说：”是的啊“。\u003c/p>\u003cp>刘洋凌子：“您把手机给我，我让我的技术人员处理”(了解对方的心理)。\u003c/p>\u003cp>蓉姐：“好的，快点啊，我着急用，离不开手机”（观点）\u003c/p>\u003cp>刘洋凌子:“好的，手机是现在每个人的必需品，我们的公司通告、联系好友、买电影票都是用手机呢，离不开手机”（\u003cstrong>迎合感受-\u003c/strong>\u003cstrong>对方给观点我补事实\u003c/strong>）。\u003c/p>\u003cp>蓉姐：“对啊，所以急嘛”。\u003c/p>\u003cp>刘洋凌子：“我理解你的情况，马上让技术人员来维修处理，您看这样好吗”？（\u003cstrong>提出建议\u003c/strong>）。\u003c/p>\u003cp>蓉姐:“这还差不多，可以”。\u003c/p>\u003cp>（结果：很好地解决蓉姐的情绪，并且有效解决问题）\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>人与人之间交流、沟通的目的是加强彼此的了解，建立关系，最终取得信任。迎合就是一种人与人之间和谐相处必须的沟通技巧，迎合3个步骤，这样的说话方式，让彼此特别容易理解对方，建立关系，让生活更幸福，更充实，也会提高工作的生产力。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1497143014000,"updated_at":1497143789000,"ria":true},{"id":2009,"topic":"用迎合为你的人际关系加分","learn_goal":"学完后，能够使用迎合来增进与他人的友谊","remark":"当遇到借钱的时候，你是选择义薄云天的施以援手，还是谨小慎微的直言拒绝？你相信自己的判断吗？你为什么相信？科学的方法可以帮助你更加明智地去控制风险，增强你的人际关系，因为有一个事实是我们无法回避的：借钱的是孙子，还钱的是老子。","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"空林文子","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"事件： 有些人说话如高山流水，让人听了赏心悦目；但是有些人说话却一言九顶，不开口还好，一开口就会让人有想顶死他的冲动。这是为什么呢？因为说话的方式方法不同。\r\n提问： 你想做一个通过说话就能让别人喜欢上你的人吗?\r\n影响： 我相信大家都想成为这样的人，万人迷与万人顶相比起来，无论是在工作中还是生活中，都能得到更多的便利，活的也更快乐。\r\n解决： 这本由孙路弘著作的《说话的力量》包括了说话的8个方法，4个技巧以及训练说话的3个工具，可以全方位的提升我们的说话能力，做一个人见人爱，花见花开，车间车爆胎的万人迷。","ratings_count":0,"texts":[{"id":4631,"quote":"\u003cp>\u003cstrong>【阅读原文-R】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>迎合：表达共情\u003c/strong>\u003c/p>\u003cp>共情，是指在人际交往过程中，能够体会他人的情绪和想法，理解他人的立场和感受，并站在他人的角度思考和处理问题的能力，又叫换位思考、移情、共情。迎合不是吹牛、拍马屁，也不是奉承，而是表达共情，获得对方认同。迎合是快速将共情用说话的方式表达出来，让对方直接、快速、明了地感受到这个人跟他一样，跟他有一样的逻辑，有一样的经验和体会，什么都跟他一样，双方就容易相互接近了。\u003c/p>\u003cp>在交谈中表达共情，对方听完你的话会觉得一拍即合：哎呀，我怎么没早认识你呢？咱俩想法太一致了，你简直是我的知音。如果他真有这样的感觉和体会，你就可以让双方有一种相见恨晚的感觉，谈话投机、滔滔不绝，自然建立了一个共振的场。\u003c/p>\u003cp>迎合就是使用共情，通过承接对方的语势，快速对对方语言中的事实、观点进行逻辑分析，通过对对方说的话进行补充等手段，使对方认可自己。迎合的前提就是使用共情，创造谈话的共振场。在沟通时使用迎合，就可以创造良好的人际氛围。迎合是将心比心的具体落实，通过说话来拉近彼此的距离，它不是奉承、套话和吹捧。\u003c/p>\u003cp>比如一家银行，早晨刚一开门就进来一个小伙子，急急忙忙到柜台前，着急地说：“我昨天在你们这儿开了一个账户，存了3万元钱。你们给我开了网上银行功能，但是昨天晚上回家我在网上一查，账户只剩30元钱了。”这时候要怎么表达共情，把迎合用到无声之处呢？\u003c/p>\u003cp>首先要想对方现在的心情是怎样的。钱查不到了当然很担忧，很紧张。有的营业员自以为有经验，上去就说：“小伙子您先别急，冷静一点。”小伙子一听肯定会说：“我能不紧张吗?我能冷静吗？这事儿跟你没关系你当然冷静了。”这样的回答不叫迎合，对于解决问题只能火上浇油。应该表达的不是告诉他别紧张，这样会让他觉得你说他紧张是不对的，他紧张当然是对的，他着急也是对的，他怎么可能冷静？换成是你，你能冷静吗？\u003c/p>\u003cp>所以要这样迎合：“怎么会这样呢？这太不正常了。这种情况无论如何不该出现的，要是真有这种情况，不仅我们银行不能容忍，我也不能容忍。”你一说出这番话，他会觉至少你跟他是有同样感受的。接着你再说：“我来帮你看一下，昨天您办理存款手续时的收据小条带来了吗?身份证带来了吗？我立刻帮您查，这件事是不应该发生的。”之后你们的沟通才会进入正常的理性沟通。\u003c/p>\u003cp>迎合就应该是符合别人的心情，符合别人的感受，甚至符合他的思考逻辑，迎合的目标就是得到对方的认可。\u003c/p>\u003cp>高超的迎合技巧就是，一、在对方陈述的是看法和观点时，你提出一些你看到非常符合对方表达的观点的现象；二、在对方陈述的是事实时，你将对方陈述的事实做一个总结和概括，提炼出一个观点，而这个观点又恰好可以印证对方所说的事实；三、当事实和观点都有的情况下，补充一个自己的体会，同样要包括类似的细节，创造出一种你们是同类的感觉。\u003c/p>","explains":"\u003cp>大家先看拆页背面的问卷调查部分，按照问卷的要求，请大家为自己打分，5分为完全符合，1分为完全不符合。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、当别人陈述观点时，我喜欢为其补充支撑他的观点的案例。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、我喜欢站在他人的立场上看问题。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、我喜欢听对方发表完观点之后再顺着他的意思说下去。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、当别人告诉他的观点之后，我会将自己的体会告诉他，让他知道我是支持他的。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>这次调查只是一个简单的了解测试，是为了让大家审视一下自己在与别人交流时，会不会不由自主的使用迎合的能力，但是结果不是绝对的。\u003c/p>\u003cp>分析问卷\u003c/p>\u003cp>10分以内：说话比较直接\u003c/p>\u003cp>11-16分：说话时候会为对方留有余地\u003c/p>\u003cp>17分以上：非常注意为对方留够面子\u003c/p>\u003cp>为什么要学会迎合呢？有一篇文章里说过，让别人舒服的程度，直接决定了你的赚钱能力。而迎合，就是让别人舒服的一个很重要的能力。如果你的得分太低了，那接下来的内容你一定要认真听一听。\u003c/p>\u003cp>\u003cstrong>【拆书家讲解引导I】\u003c/strong>\u003c/p>\u003cp>迎合到底是什么？\u003c/p>\u003cp>\u003cstrong>学习者\u003c/strong>：体会对方的感受，给予一些具有同样感受的案例，或者表达一致的观点。\u003c/p>\u003cp>\u003cstrong>拆书家分析\u003c/strong>\u003c/p>\u003cp>迎合就是承接对方的语势，即顺着对方的话说，也就是顺势而为。从而使对方认可自己。迎合与共情是密不可分的，只有通过共情，了解对方当前的实际状态，包括他的情绪，观点，你才能表达共情，迎合对方，最终达到我们的目标，即获得对方的认可。这里不展开对共情的讲解，因为在拆页最后面作者给出的3个技巧已经让我们能够直接使用迎合的技巧了，这3个技巧简单说就是给观点找事实，给事实找观点，如果事实观点都有，补充自己的细节。\u003c/p>\u003cp>\u003cstrong>举例分析\u003c/strong>\u003c/p>\u003cp>给大家举一个昨天发生在我身上的例子。帮一位洪姓客户做贷款，征信过了，然后他自己去平安银行面签，但是被平安银行拒绝了。拒绝的原因是因为他原籍广西，这个拒绝的原因我之前闻所未闻。但是他不管这些，他贷不到钱，非常生气，打电话给我，语气非常愤怒。其实当时我也很恼火，因为我份内的工作已经做完了，贷不下款来的原因也超出我的认知范围，但是客户这样来找我发火，如果我也直接把他顶回去，那工作也就不用做了。当他打电话给我咆哮的时候，我是这么说的：洪先生，对不起，让您白跑了一趟银行。现在您贷不下款来，肯定非常生气。我也一样啊，辛辛苦苦给你跑这跑那的，你贷不了款，我就没有业绩，我图啥呢？我是帮你的，我肯定不会明摆你不能贷还让你跑去银行碰壁。现在既然平安银行贷不了，那我帮你想办法，争取帮你从其他渠道把钱贷出来，您看可以吗？后来客户自己也知道发火没用，就同意了让我帮他另找渠道贷款。\u003c/p>\u003cp>这个案例里面，我没有让客户别生气，我只是顺着他的话，把我的处境告诉他，让他意识到我是帮他的，跟他是站一起的，得到他的认可，自然而然的，他的怒火也就平息了。\u003c/p>\u003cp>\u003cstrong>预防异议\u003c/strong>：迎合是不是万精油，到处都能用呢？什么地方不能使用迎合？\u003c/p>\u003cp>\u003cstrong>学习者1\u003c/strong>：问问题的时候。\u003c/p>\u003cp>\u003cstrong>学习者2\u003c/strong>：观点明确是不对的时候。\u003c/p>\u003cp>\u003cstrong>学习者3\u003c/strong>：如果我不需要获得你的认可，我就没有必要去迎合你。\u003c/p>","interaction":"\u003cp>\u003cstrong>【促动参与-A3】\u003c/strong>\u003c/p>\u003cp>情景演练：假设你要跳槽去一家新的公司，你应聘的岗位是人事部经理（也可以根据自己的实际情况调整），你成功进入了最终的面试，他们的总经理将直接面试你。想象你可能和总经理展开怎样的对话，揣摩他的立场和需求，恰当使用迎合的技巧。以角色扮演的形式和你的搭档一起完成这个练习。\u003c/p>\u003cp>\u003cstrong>学习者情景演练\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者1-面试者\u003c/strong>：总经理您好，我想问一下，你们上一个人事经理为什么离开？\u003c/p>\u003cp>\u003cstrong>学习者2-总经理\u003c/strong>：他要去其他城市发展，所以就走了。\u003c/p>\u003cp>\u003cstrong>学习者1-面试者\u003c/strong>：那你们对于这个职位有什么要求吗？\u003c/p>\u003cp>\u003cstrong>学习者2-总经理\u003c/strong>:首先呢他需要有一定的培训技能，他要负责给企业培训基层员工，储备干部，对于高层也需要定期进行培训。其次，我还需要他对于培养企业文化有一定的心得，我们公司是20多年的私营企业，这个人事主管需要能把老板的一些风格以及想法贯彻到全公司。\u003c/p>\u003cp>\u003cstrong>学习者1-面试者\u003c/strong>：我总结一下你的说法，首先这个岗位需要有培训技能，其次还要有培养企业文化的能力。你对这个职位还有什么其他的期待吗?\u003c/p>\u003cp>\u003cstrong>学习者2-总经理\u003c/strong>:除了这两方面的要求，我希望这个岗位能在人的培养上多花精力以及有一定的特长，从企业内部进行培养，因为我们不想一直从外面招聘新员工。\u003c/p>\u003cp>\u003cstrong>学习者1-面试者\u003c/strong>：好的，我对于这个岗位有一定的认识了。我分享一下我自己的情况吧。我现在在中科院人力资源的硕士班进行学习，而且我自己也一直做的是HR这方面的工作，所以对于人事的培训上是有一定经验的。其次，对于文化的培养，我在社会上也参加了一些社团，如拆书帮，平时也会经常组织一些活动，这些对于营造企业内部的学习文化是很有帮助的。最后，我现在在原单位培养了自己岗位的接班人，即使我离开了，原单位也是不会受影响的，在人的培养上我还是有很多心得的。\u003c/p>\u003cp>\u003cstrong>学习者2-总经理\u003c/strong>:挺好的，你的情况跟我们的要求非常符合，我在考虑一下。\u003c/p>\u003cp>\u003cstrong>【催化应用A2】\u003c/strong>\u003c/p>\u003cp>你有多久没有与父母亲好好聊天了？用上迎合的技巧， 与父母亲好好的聊一次，看看他们会不会说你更懂事了。\u003c/p>\u003cp>学习者:每次回家之前,我的心情都非常高兴,总想着该怎么好好陪爸妈,但是以前每次回家之后,跟父母聊不到两句,我就嫌他们啰嗦,不想跟他们讲话了.学会了今天的迎合技巧之后,等过年回家跟父母聊天的时候,我会在跟他们聊天的过程中恰当的迎合我感兴趣的话题,不断对这个话题进行提问,并且补充我的一些看法,添加一些我在外面碰到的类似的事情,让父母亲更加的了解我在外面的生活,我相信这样能让父母更加的高兴.\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1487604851000,"updated_at":1487604851000,"ria":true},{"id":2005,"topic":"创造一来一往舒适的说话氛围","learn_goal":"学会使用“垫子”为自己的的沟通加分","remark":"直言不讳是一种美德，但是如何避免直言伤人？有一颗乐于助人的心，却总是遭到别人的误解，这又是为哪般？守门员需要手套来减缓冲击力，我们开口回复别人之前，也需要加一层“垫子”来为自己赢得更多的机会。善用“垫子”能够为我们的沟通起到四两拨千斤的奇效。","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"空林文子","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"【图书介绍】\r\nF：《说话的力量》的作者是孙路弘，他是营销及销售行为专家，这本书里有8大说话方法以及4大说话技巧，涵盖了讲述、表达、汇报、解释等等内容。\r\nA：市面上讲授说话技巧的书不胜枚举，但是往往都是给你提供一个绝佳的具体案例，让你在对这个案例拍案叫绝的同时，自己去领悟该案例涉及的技巧，却没帮助我们在案例中提取一个可操作的技巧或者方法，去应对各种情况。这本书不一样，他不仅有生动的案例，更重要的是可操作性特别强，可以自己根据书中的要求进行练习，更恰当的说，这本书是一本说话训练手册。\r\nB：说话还要训练吗？我不知道在坐的各位会不会有这种疑惑，但是，话又说回来，你训练过说话吗？跑步谁都会，但是奥运冠军就那么几个，这就是因为他们付出了大量的努力在训练上，天赋很重要，但是我没听说过有谁的奥运金牌是凭借天赋就能取得的。这本书作为说话的训练手册，如果能按照它进行训练并持之以恒的践行，成为一个演讲大师或者谈判高手，也只是一个时间问题。","ratings_count":0,"texts":[{"id":4629,"quote":"\u003cp>垫子起到的是缓冲作用，缓解你问什么我答什么的紧张状态。比如小朋友经常问：妈妈，我是从哪里来的？妈妈们会怎么回答？我听到过很多种回答方法：捡来的，石头缝里蹦出来的……你可能会觉得这些回答都不好，面对孩子天真无邪的提问，应该耐心地给他讲科学道理。于是你会说“你是妈妈生的”，然后开始给他讲生理知识，但你可能发现她越听越糊涂。所以这也不是妥当的回答。对这种问题的问答就要使用垫子，怎么使用呢？看我是怎样回答这个问题的。\u003c/p>\u003cp>——妈妈，我是从哪里来的？\u003c/p>\u003cp>——哟，孩子，你长大了，都开始问这个问题了。\u003c/p>\u003cp>其实我并没有回答他的问题，而是超越了他的问题，对他的问题进行了一个肯定：你已经开始思考这个问题了，你真是长大了。这样一间断，孩子接着往下说了……\u003c/p>\u003cp>——今天我们班来了一个新同学，老师说他是四川来的，我想知道我是哪里来的。\u003c/p>\u003cp>在回答问题之前，你一定认为他想知道的是他怎么生出来的，你甚至在想他是否已经足够成熟到可以问生理知识了。其实这完全是一个误解。有的时候我们急于回答问题，可能根本没听清楚对方问这个问题的目的。对方问问题之前，有什么样的背景？这就要求你加一个垫子，先肯定他的问题，让谈话有一个停顿。\u003c/p>\u003cp>客户买了冰箱来质问你：“这台冰箱怎么关不紧门这台冰箱怎么关不紧门？”你回答：“哎呀，您遇到的这个问题还真是很少见，我还没碰到过，我在这里已经卖了一万多台同样的产品了，还是第一次遇到这种情况？您能说一下它是什么情况吗？”\u003c/p>\u003cp>面对棘手的问题，你要超越对方的问题，去关注这个问题的背景。怎么才能关注问题的背景呢？先要对他的问题给予肯定——你这个问题问得真好，你这个问题问得很专业，你这个问题的视角非常独特，你能想到这个问题很不简单。在回答别人的问题之前，让自己超越问题，这就是垫子的技巧。\u003c/p>","explains":"\u003cp>什么是垫子呢？床垫的作用是让我们不用直接接触硬邦邦的木板，睡的更舒服，在这里，它起到了缓冲的作用。那我们今天讲的垫子呢？不仅仅是缓冲的作用。有请一位小伙伴，跟我演练一个小示范。\u003c/p>\u003cp>\u003cstrong>情景演练：\u003c/strong>我手拿道具盾牌，小伙伴拿道具宝剑，它使用宝剑刺我，我用盾牌抵挡他的进攻。\u003c/p>\u003cp>\u003cstrong>拆书家提问\u003c/strong>：在上面的示范中，大家观察到了什么？请一位小伙伴来说一下。\u003c/p>\u003cp>\u003cstrong>学习者\u003c/strong>：在讲话中如果没有铺垫，容易伤到对方，对于我们自己，也没有足够的缓冲时间。\u003c/p>\u003cp>\u003cstrong>拆书家\u003c/strong>：他进攻的时候，因为我有盾牌的保护，既让我免于直接受到伤害，也让我有时间看清对手的状态，找出机会快速反击。这就是我们今天要讲的这个垫子。在说话中，面对对方的问题，不要直接去回答，而是通过一层类似“垫子”的东西，为我们争取时间，看清形势，最终取得最后的胜利。\u003c/p>\u003cp>\u003cstrong>异议处理：\u003c/strong>\u003c/p>\u003cp>这里大家可能会有一个异议，就拿刚才的示范来说，万一这个盾牌挡不住，对方刺透了盾牌或者直接无视盾牌又从另外个方向直接攻击过来怎么办？时间，不论是盾牌被刺透还是对方换方向攻击，都是需要时间调整的，这也为我们争取了时间去想好下一步的对策，你也可以用你的第二个垫子继续寻求突破。所以，无论如何，为我们的对话加一个垫子，能让我们在交谈中处于更加有利的位置。\u003c/p>\u003cp>\u003cstrong>适用边界：\u003c/strong>\u003c/p>\u003cp>当然，也会有小伙伴有疑问，垫子是什么时候都可以加吗？不是的。比如，我问邓淑惠同学，请问你叫什么名字？你要是加个垫子说，这个问题非常好，我经常碰到这样的问题…对方得直接给你灭灯了，然后加上两个字，逗逼！ \u003c/p>\u003cp>所以，垫子的应用范畴在于：当对方的表述不明朗，你没办法确定对方提出的要求或者问题的背景。\u003c/p>\u003cp>垫了之后呢，适当的加上你的提问，让对方的表述更加清晰，或许这时候你需要回答的问题，就已经不是最初的那个棘手的问题了。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2-分步催化1】\u003c/strong>\u003c/p>\u003cp>领导不根据实际情况要求你完成项目计划，客户怒气冲冲地找你要求退货，你的对象刁蛮任性地无理取闹，你在工作生活中会碰到哪一个情景？请大家在小组内讨论一个情景，5分钟后请两个小伙伴上来演练一下。有两个要求，首先，肯定对方。第二，向对方提问，为自己争取时间。\u003c/p>\u003cp>\u003cstrong>学习者情景演练\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者1-领导\u003c/strong>：明天把PPT做好，我们要交给甲方做沟通。有问题吗？\u003c/p>\u003cp>\u003cstrong>学习者2-职员\u003c/strong>：哪个PPT啊？\u003c/p>\u003cp>\u003cstrong>学习者1-领导\u003c/strong>：就是我们跟客户做交接的那个。\u003c/p>\u003cp>\u003cstrong>学习者2-职员\u003c/strong>：我手头上要做的PPT比较多啊，但是没问题，我加班可以做出来。但是这个PPT缺一些原始的数据，第一个是图片，这个我可以搞定。第二个甲方有一些技术参数没提供过来，我没办法填充，所以就卡在这了。\u003c/p>\u003cp>\u003cstrong>学习者1-领导\u003c/strong>：那这个什么时候能弄好？\u003c/p>\u003cp>\u003cstrong>学习者2-职员\u003c/strong>：这个要看甲方什么时候把数据给我，如果我们的胡总可以联系到甲方，让他今天把数据给我们，我两个小时就可以搞定。\u003c/p>\u003cp>学习者1-领导：好的，那我让胡总先把数据弄过来。\u003c/p>\u003cp>\u003cstrong>【A2-分步催化2】\u003c/strong>\u003c/p>\u003cp>请小伙伴们加工一个具体例子，说明今后你可以在该情景下怎么使用今天所学的垫子来应付。\u003c/p>\u003cp>学习者：被领导误解的时候，我会先同意领导的观点，让他的情绪得到释放，但是事后我会找出证据证明我是被误解的，以避免跟领导产生正面冲突。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1487604516000,"updated_at":1487604516000,"ria":true},{"id":2004,"topic":"台上一分钟，台下十年功","learn_goal":"学会做受众分析来准备一场谈话","remark":"伟大的演说家在去做演讲之前，都会提前到场去咨询举办方参会人员的相关情况，从而避免自己准备的演讲稿脱离现场实际。做好受众分析，对于一次成功的演讲至关重要。那受众分析，该从何处着手呢？","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"空林文子","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"我是林文，今天由我为大家拆解《说话的力量》这本书。\r\n【图书介绍】\r\nF：《说话的力量》的作者是孙路弘，他是营销及销售行为专家，这本书里有8大说话方法以及4大说话技巧，涵盖了讲述、表达、汇报、解释等等内容。\r\nA：市面上讲授说话技巧的书不胜枚举，但是往往都是给你提供一个绝佳的具体案例，让你在对这个案例拍案叫绝的同时，自己去领悟该案例涉及的技巧，却没帮助我们在案例中提取一个可操作的技巧或者方法，去应对各种情况。这本书不一样，他不仅有生动的案例，更重要的是可操作性特别强，可以自己根据书中的要求进行练习，更恰当的说，这本书是一本说话训练手册。\r\nB：说话还要训练吗？我不知道在坐的各位会不会有这种疑惑，但是，话又说回来，你训练过说话吗？跑步谁都会，但是奥运冠军就那么几个，这就是因为他们付出了大量的努力在训练上，天赋很重要，但是我没听说过有谁的奥运金牌是凭借天赋就能取得的。这本书作为说话的训练手册，如果能按照它进行训练并持之以恒的践行，成为一个演讲大师或者谈判高手，也只是一个时间问题。","ratings_count":0,"texts":[{"id":4628,"quote":"\u003cp>在表达中需要提前进行受众分析。分析应该从3个方面展开：\u003c/p>\u003cp>1.分析受众的认知水平。包括受教育程度、文化程度、生活的环境以及水平，甚至要了解他们的用语、他们习惯的词汇。\u003c/p>\u003cp>2.分析受众的价值取向。大致的思想境界、意识形态，以及对表达者可能的态度，是敌意还是善意。\u003c/p>\u003cp>3.分析受众的内心期待。就是他们期待听到什么，他们希望通过倾听你的表达有什么收获，是知识方面的还是信息方面的，还是得到启发、增长实际技能等。\u003c/p>","explains":"\u003cp>分析受众就是从以上3个阶段入手。在收集到的信息不足以支持我们做出判断的情况下，一般采取中等假定，并在开始表达的初期随时观察受众的反应，随之及时调整自己的讲话内容。\u003c/p>\u003cp>1.分析受众的认知水平。认知水平就是个体对外界事物认识、判断、评价的能力,认知水平的高低与实践经验,知识水平、思维能力,信息储量等因素有关。简单说就是这个听众，对于这件事，凭借他自己本身的能力，能有多少的了解。\u003c/p>\u003cp>2.分析受众的价值取向。在这里指的就是对于你的表达，听众是支持还是反对的，主要考虑的是立场。\u003c/p>\u003cp>3.分析受众的内心期待，其实就是他们想要什么，只有知道了他们想要什么，我们才可以有的放矢，让他们成为我们的忠实听众。\u003c/p>\u003cp>分析受众就是从以上3个阶段入手。在收集到的信息不足以支持我们做出判断的情况下，一般采取中等假定，并在开始表达的初期随时观察受众的反应，随之及时调整自己的讲话内容。中等假定，其实就是保守，对于自己的立场持模糊态度，不偏不倚，看着观众的表情，再慢慢表明的自己的观点或者表达方式，这样才能保证不至于被人轰下台，取得预期的效果。\u003c/p>\u003cp>分析受众之所以很重要，是因为如果不这样做，很容易导致听众对于我们所说的内容失去兴趣。我是做保险销售的,有一次朋友告诉我,他的一个朋友想要买一份保险。听到这个消息，我内心是高兴的，但是在去拜访这位客户之前，我向我的朋友询问了他这位朋友的详细情况，包括兴趣爱好、籍贯、年收入、婚姻子女状况、保险偏好等。因为我提前收集了这些信息，当我见到客户的时候，其实我已经清楚该用什么方式跟他沟通，该从哪个方向去激发他的需求，该设计什么类型的产品，产品的费用该控制在多少。当时我们谈的非常愉快，当场客户就决定了要购买我给他设计的产品。\u003c/p>","interaction":"\u003cp>\u003cstrong>【激活经验-A1】\u003c/strong>\u003c/p>\u003cp>&nbsp;请大家回顾一下自己有没碰到过这样的情形，因为没有提前去了解对方的需求、背景等相关信息，结果当我们向对方提出要求或者建议时，遭到对方的误解、拒绝，从而没有达成预期目标的情况？&nbsp;&nbsp; \u003c/p>\u003cp>-学习者：我偶尔会做香港代购，老家的亲戚朋友也都知道我在做这个。上个月老家的一个表姐让我帮她去香港买一个口红，她之前用的香奈儿的一款口红，感觉挺好的，这次想换一款，让我看看有没类似的可以帮她挑一支。我自己平时使用的是圣罗兰的一款口红，我感觉还不错，于是我就帮她带了这一款，也没收她的代购费。但是，当我把口红给她之后，她用了之后感觉很不好，觉得太艳了，对我颇有微词。这让我感觉非常不舒服。但是也是我自己的原因。因为这个口红我在深圳用的很好，周围的朋友也用。但是她在老家，周围的人跟我们这不一样，她们不用这样的款式，所以她不喜欢。\u003c/p>\u003cp>【A1+】因为没有搞清楚对方周围的人们使用款式，从而导致购买的产品不符合对方的预期。那如果再给你一个机会，你会向对方怎么提问，从而让你买的产品符合她的心意呢？\u003c/p>\u003cp>\u003cstrong>学习者\u003c/strong>：我想我会先问她自己，以前使用的是怎么样的颜色，是比较张扬的，还是比较含蓄的，她平时穿衣服的颜色是深沉的还是明艳的，还有就是要不要我在购买的时候，给她直接拍照片自己挑选。我想如果做了这几点，应该能保证我买到符合她的要求的产品。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1487604437000,"updated_at":1487604437000,"ria":true},{"id":2003,"topic":"用触动人心的事实传达观点","learn_goal":"学会通过筛选事实来让自己的观点更加无法辩驳","remark":"为什么伟大的演讲，总会让人感到无法辩驳？为什么古代的官员，都喜欢报喜不报忧？百战百败与百败百战，为什么能起到完全相反的效果？真相只有一个，但是，叙述有多种方法！","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"空林文子","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"大家好，我叫林文，今天由我为大家拆解《说话的力量》这本书。\r\n【图书介绍】\r\n《说话的力量》是由孙路弘著作，他是营销及销售行为专家，奇葩的人生：教师，成立了北京第一个奥数班；销售过16种产品，广告、房地产、汽车、保险等；奥迪顾问与奔驰教官；科特勒营销集团中国区高级顾问；等等。\r\n这本书里有8大说话方法以及4大说话技巧，涵盖了讲述、表达、汇报、解释等等内容。市面上讲授说话技巧的书不胜枚举，但是很多书都是给你提供一个案例，让你在对这个案例拍案叫绝的同时，自己去体会该案例涉及的方法，却没帮助我们在案例中提取一个可操作的技巧或者方法，去应对各种情况。这本书不一样，他不仅有生动的案例，更重要的是可操作性特别强，可以自己根据书中的要求进行练习，所以，更恰当的应该称其为说话训练手册。","ratings_count":0,"texts":[{"id":4627,"quote":"\u003cp>\u003cstrong>筛选有利的事实\u003c/strong>\u003c/p>\u003cp>世界上每天发生的新鲜事成百上千，为什么报纸上只登了十件？那是因为报纸的编辑对信息进行了筛选。什么样的新闻有它的特色，什么样的新闻有它的价值，都是经过了评判的。而每个人就如同一个媒体，你所传达给听者的事实同样是需要经过筛选的。\u003c/p>\u003cp>因此，叙述的重要要求之一就是，当你有一个明确的看法、试图影响对方的时候，要把一些对你不利的、与你看法不一致的事实屏蔽掉，这就是筛选事实。\u003c/p>\u003cp>在国内很火的相亲娱乐类节目《非诚勿扰》中，每位男嘉宾登场时都会播放一段录像，来展示他在日常生活中的风貌。有的男嘉宾想把自己的形象塑造成事业心很强的职业人，面对镜头他就会着重叙述自己加班到深夜，为公司创造了巨大的业绩，年收入数十万等事实。有的男嘉宾想把自己塑造成体贴顾家的经济适用男，他可能会更多的叙述自己照顾生病的父母，为女朋友做饭等事实。而某一期有一位男嘉宾，明明提醒比较胖，还叙述自己吃自助餐时每种菜都吃六份。这样的事实，能给在场的女嘉宾传达什么观点呢？结果可想而知，他被全场的女嘉宾灭灯了，这就是不注意筛选事实的后果\u003c/p>","explains":"\u003cp>\u003cstrong>【拆书家讲解引导】\u003c/strong>\u003c/p>\u003cp>今天我们的主题是用触动人心的事实来传达观点。那这里有一个疑问，就是什么叫触动人心的事实？是这个事实的过程跌宕起伏还是缠绵悱恻，又或是给我们一个意想不到的结局呢，就像是段誉，见一个爱一个，但是后来发现这都是他爹当年留下的风流债，即这些姑娘都是他的妹妹。我想段誉当时肯定死的心都有了。但是，金庸老先生最后笔锋一转，告诉各位看官，其实，段誉也不是段正淳的种，是那个四大恶人之首段延庆的。至此，这部戏才回到了王子与公主过上了幸福的生活。这个是跌宕起伏缠绵悱恻的经典案例，但是，我们要求的触动人心的事实，不是这样的，今天，我们要讲的触动人心的事实，指的是经过筛选的事实。\u003c/p>\u003cp>事实为什么要经过筛选才能触动人心呢？这是因为，如果不经过筛选，所有的事实堆叠在一起，有些是有利于我们的，有些是不利于我们的，势必会影响我们最终的目的，也就无法达到触动人心的结果了。如文中所说的男嘉宾，身材肥硕还把自己吃自助餐每种菜都吃六份的事实展现出来。这实在就是在找灭。\u003c/p>\u003cp>【步骤】\u003c/p>\u003cp>那到底怎么筛选呢？第一、我们要确立自己的谈话目标，这一步很重要，因为如果你没有自己的目标，那筛选也就失去依据，如书中所说的，如果你的目的是表现出自己的体贴顾家，那这就是我们筛选事实的方向；第二、把自己所掌握的事实列出个一二三来，第三、筛选出其中可以服务于谈话目的的事实，屏蔽掉无关紧要或与目的相悖的事实。三板斧：定目标、列事实、筛所需。\u003c/p>\u003cp>【概念明晰】\u003c/p>\u003cp>说完为什么筛选以及如何筛选，还有与筛选事实很接近的概念，我们要分析一下。\u003c/p>\u003cp>首先是扭曲事实。扭曲事实，是你颠倒黑白，把好的说成坏的。而筛选事实，同类事物中去掉不需要的,留下需要的。这是本质上的区别。\u003c/p>\u003cp>另外一个概念就是罔顾事实：不顾及事实,不考虑现实。没错，筛选：同类事物中去掉不需要的,留下需要的。 跟罔顾，其实都有故意忽略某一方面事实的意思，但是从词性上来说，筛选偏中性，但是罔顾，那就是彻底的贬义词了。筛选事实的说话方法没有好坏之分，只是看你用在什么地方了。用王阳明的话说就是，是否“致良知”，也就是你做这件事情是否符合你内心的光明与善良。好，以上就是我的I环节，下面进入A1环节。\u003c/p>","interaction":"\u003cp>\u003cstrong>【激活经验A1】\u003c/strong>\u003c/p>\u003cp>请大家在小组内分享一个自己生活中经历过或见过的“筛选事实以达成目的”的案例？\u003c/p>\u003cp>\u003cstrong>学习者\u003c/strong>：中国的媒体，如CCTV，经常报道国内的民生工程、利民政策有多么的好，但是报道国外的消息时，往往是战争，饥饿等消息，让大家觉得中国人民的幸福指数特别高。在娱乐界，宣传明星的时候，往往是说这些明星多么亲民，对记者多好，让大家觉得这个明星非常阳光向上，而不会去报道一些这个明星的阴暗面。\u003c/p>\u003cp>\u003cstrong>【催化应用A2】\u003c/strong>\u003c/p>\u003cp>写下最近可能需要用到筛选事实这个说话方法的地方?将其写在便签纸上。\u003c/p>\u003cp>学习者：最近要找客户促成一项生意，我们的价格比市场上的其他商家稍微贵一点，因为我们的质量值这个价格，但是我们不能告诉采购方这个事情，因为这可能会影响他的决策。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1487604296000,"updated_at":1487604296000,"ria":true},{"id":163,"topic":"发言引人入胜并具有说服力的技巧","learn_goal":"学习发言技巧","remark":"拆解片断来自：孙路弘《说话的力量》\r\n你是否发现，在会议上，在聚会上，或者谈判桌上……总有那么一些人很容易就能掌握交流的主导权，能抛出新问题，并且能吸引大家听下去？这类人往往能成为意见领袖影响到其他人，也很容易能在一个群体中脱颖而出。孙路弘老师在《说话的力量》一书中告诉大家要让自己的发言引人入胜并具有说服力是有方法和技巧的，并且是通过训练能提升的。让我们一起拆起来，看看究竟如何做吧？","level":"TF1-2","duration":30,"status":0,"type":1,"chaishujia":{"username":"喜羊羊","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":null,"ratings_count":0,"texts":[],"created_at":1458270700000,"updated_at":1458270700000},{"id":138,"topic":"说话的力量","learn_goal":"说话的力量","remark":"每个人每天从睁开眼到工作、娱乐、日常生活，都离不开说话，离不开表达。你是否有过眉飞色舞讲了半小时，对方仍然云里雾里的尴尬？你又是否有唾沫讲干对方却无法正确理解你意思的郁闷？或者，跟下属交待工作要求数次对方却还没能领悟的焦虑？成功的表达不但让你的工作生活更加顺畅，效率提升，更能提高自己的影响力，有更多成功的机会。“影响力是演出来的”，来跟我一起学学如何在表达过程中善用道具吧！","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"喜羊羊","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"大家好，我是新手拆书家许曼，去年辞职创业经营高端水果。\r\n拆书：大家刚听到拆书的时候，会不会在第一时间脑海里会浮现出撕书的画面呢？事实上，拆书并非如此，并不是把一本书拆掉。而是一种学习方法论，提倡的就是拆为已用。比如我是个阅读强迫症患者，阅读的习惯是从前言、目录再到正文到结尾逐字逐句看，于是遇到的最大问题就是阅读的效率非常低，而且一旦碰到一两句比较生涩的内容就会看不下去。所以我觉得拆书这种学习方法论非常适合我，也是非常适合成人学习的一种学习方法。\r\n说到拆书就不得不提到拆书帮，拆书帮听上去有一些江湖，事实上，他是一个社群，是一群拆书方法论的爱好者自发组织起来的一个公益的社群，每周固定在一个场所，就像今天这样我们一起分享一起学习。拆书分为个人学习的拆书法和组织学习的拆书法。个人学习的应用是便签法，组织学习的应用就像我们今天这样，由拆书家组织现场学习，引导和促进大家一起把知识拆为已用。\r\n到拆书帮学习也有两种方式，一种是游客，可以纯粹来听拆书家的分享学习；另一种就是拆书家，按照成长手册的要求，一起来升级打怪，成长为专业的拆书家来指导带领大家一起学习。","ratings_count":0,"texts":[{"id":177,"quote":"我今天要为大家分享的这本书，是孙路弘的《说话的力量》，这本书也是年前我们群友推荐的一本实用书，我在过年期间完成了这本书的阅读。\r\n这是一本实用的说话训练手册，与我们之前所看过的同类书相比，不同的是，除了告诉我们说话的技巧以外，给到了很多案例和训练的练习题目。我认为这本书更好的学习方法是有一个群体一起来学习练习会更有效果。\r\n这本书主要讲的是说话的方法、技巧和训练工具，我今天要分享的说话的方法中，表达的要点之一，作者认为成功表达有三个技巧：配合肢体语言、善用道具形式、巧用关键词和数字。我今天给大家展示的是善用道具形式这一技巧。首先请大家阅读这一片段，我用括号标记的部分，阅读完成的小伙伴请给我一个示意。\r\n拆页：善用道具形式\r\n2005年，李敖在北京大学进行了一场精彩的演讲。\r\n演讲中，他提到自己写了100多本书，其中有96本书被当地政府查禁。听众听到这里可能会觉得，被查禁90多本书是挺多的，但并没有一个直观的印象。李敖接着说，他把所有被查禁的书名，写作的年代、被查禁的理由都写在了一张纸上。说着他从 讲台底下掏出道具——一卷纸，然后像扯卫生纸似的扯啊扯啊，台下的观众都惊呆了，接着爆发出经久不息的掌声。李敖成功地通过道具，向听者传递了他想表达的信息。\r\n人们受到影响，是因为得到了信息。而要让人们得到这些信息，除了靠说话以外，还能借助的手段同中最重要的就是道具。","explains":"我们每天都会与不同的人进行很多的沟通，在沟通过程中，就是要通过自己的表达让对方接受我们的观点，这个过程中可能会用到一些肢体语言，或者用我们的语言的技巧，如何让对方更加容易接受我们给到的信息，认同我们的观点，从而提升我们的影响力。这个片段用了一个简单的案例告诉我们，除了通过语言的魅力，肢体语言以外，还有一个技巧，就是善用一些小工具，小道具。包括我们在案例中看到的李敖的这次演讲，本身的内容中已经运用到了很多的大数据，比较具有说服力，但是也许我们对数字没有一个直观的感觉，所以当他拿出这么一大卷纸出来的时候，那个效果会更加震撼。","interaction":"A1：自己的相关经验\r\n通过这个案例我也联想到我自己曾经的一些经验，这个经验可能不是用在与人沟通，说服别人，而是在孩子的教育方面。起因是我儿子五岁起学钢琴，当他学到高一级、两级音阶和低几级的音阶的时候，在认谱方面，就有了一些障碍，这个时候，我就得去帮助他，辅助他，最开始我如何表达呢？就是在纸上画五条线，然后把小蝌蚪一个个画上去，告诉他怎么爬楼梯，哆来米发嗦是在哪里，刚开始顺着爬还顺畅，但是一旦我跳着画给他，就出问题了，他又不知道了。后来我就想了一个办法，我给他制作了一个道具，像这样的一个道具，把他当下可能涉及到的大概五个音阶的小蝌蚪全都做出来，运用这个道具通过做游戏的方式来教他，这样的方式非常有效果，因为有了道具，他有参与感，而且会很有乐趣，这个学习过程中的障碍很快就跨过去了。那么这是我一个成功的经验。无论是我们日常的沟通中也好，还是工作中的沟通表达也好，都可以适当的运用一些工具，来增强说服力。\r\nA2：规划自己的运用\r\n通过这个成功的案例，和书中的讲解也给了我未来一些启发。我现在经营自己的水果店，很多时候我需要说服我的顾客，说服我的大客户，甚至还有供应商。我有一个计划，要做一个工作，把我经营一年多以来客户好评的微信截图、留言收集整理起来。包括我们做的会议拼盘留下的照片，客户的反馈。还有其他方面，比如精品水果诱人的照片和客户的反馈收集起来，将这些资料在店面做展示，以及在与大客户洽谈的时候，做一些展示，这样的方式，可能比我纯粹的跟他讲解会更有说服力。\r\n结语：我觉得运用道具这样一个技巧，不仅仅可以运用于我们工作沟通、培训方面，包括日常的沟通，比如说服家人去某地旅游、采购某一样大件或者是要试图说服领导做一个项目等等。那么我们现在也可以思考一下，最近是否有需要说服身边的人做某一件事，达成某一个愿意，准备用什么样的道具，去为自己的表达给一些助力。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1456403715000,"updated_at":1465053218000,"ria":true}]};